window.MATTHEW_DATA={"title":"The Gospel According to Matthew","source":"User-supplied text","chapterCount":28,"verseCount":1067,"sentenceCount":1710,"chapters":[{"chapter":1,"verses":[{"chapter":1,"verse":1,"reference":"Matthew 1:1","text":"This is a record of the ancestors of Jesus the Messiah, a descendant of David and of Abraham:","sentences":[{"id":"mt-1-1-1","chapter":1,"verse":1,"sentence":1,"reference":"Matthew 1:1","text":"This is a record of the ancestors of Jesus the Messiah, a descendant of David and of Abraham:"}]},{"chapter":1,"verse":2,"reference":"Matthew 1:2","text":"Abraham was the father of Isaac. Isaac was the father of Jacob. Jacob was the father of Judah and his brothers.","sentences":[{"id":"mt-1-2-1","chapter":1,"verse":2,"sentence":1,"reference":"Matthew 1:2","text":"Abraham was the father of Isaac."},{"id":"mt-1-2-2","chapter":1,"verse":2,"sentence":2,"reference":"Matthew 1:2","text":"Isaac was the father of Jacob."},{"id":"mt-1-2-3","chapter":1,"verse":2,"sentence":3,"reference":"Matthew 1:2","text":"Jacob was the father of Judah and his brothers."}]},{"chapter":1,"verse":3,"reference":"Matthew 1:3","text":"Judah was the father of Perez and Zerah (whose mother was Tamar). Perez was the father of Hezron. Hezron was the father of Ram.","sentences":[{"id":"mt-1-3-1","chapter":1,"verse":3,"sentence":1,"reference":"Matthew 1:3","text":"Judah was the father of Perez and Zerah (whose mother was Tamar)."},{"id":"mt-1-3-2","chapter":1,"verse":3,"sentence":2,"reference":"Matthew 1:3","text":"Perez was the father of Hezron."},{"id":"mt-1-3-3","chapter":1,"verse":3,"sentence":3,"reference":"Matthew 1:3","text":"Hezron was the father of Ram."}]},{"chapter":1,"verse":4,"reference":"Matthew 1:4","text":"Ram was the father of Amminadab. Amminadab was the father of Nahshon. Nahshon was the father of Salmon.","sentences":[{"id":"mt-1-4-1","chapter":1,"verse":4,"sentence":1,"reference":"Matthew 1:4","text":"Ram was the father of Amminadab."},{"id":"mt-1-4-2","chapter":1,"verse":4,"sentence":2,"reference":"Matthew 1:4","text":"Amminadab was the father of Nahshon."},{"id":"mt-1-4-3","chapter":1,"verse":4,"sentence":3,"reference":"Matthew 1:4","text":"Nahshon was the father of Salmon."}]},{"chapter":1,"verse":5,"reference":"Matthew 1:5","text":"Salmon was the father of Boaz (whose mother was Rahab). Boaz was the father of Obed (whose mother was Ruth). Obed was the father of Jesse.","sentences":[{"id":"mt-1-5-1","chapter":1,"verse":5,"sentence":1,"reference":"Matthew 1:5","text":"Salmon was the father of Boaz (whose mother was Rahab)."},{"id":"mt-1-5-2","chapter":1,"verse":5,"sentence":2,"reference":"Matthew 1:5","text":"Boaz was the father of Obed (whose mother was Ruth)."},{"id":"mt-1-5-3","chapter":1,"verse":5,"sentence":3,"reference":"Matthew 1:5","text":"Obed was the father of Jesse."}]},{"chapter":1,"verse":6,"reference":"Matthew 1:6","text":"Jesse was the father of King David. David was the father of Solomon (whose mother was Bathsheba, the widow of Uriah).","sentences":[{"id":"mt-1-6-1","chapter":1,"verse":6,"sentence":1,"reference":"Matthew 1:6","text":"Jesse was the father of King David."},{"id":"mt-1-6-2","chapter":1,"verse":6,"sentence":2,"reference":"Matthew 1:6","text":"David was the father of Solomon (whose mother was Bathsheba, the widow of Uriah)."}]},{"chapter":1,"verse":7,"reference":"Matthew 1:7","text":"Solomon was the father of Rehoboam. Rehoboam was the father of Abijah. Abijah was the father of Asa.","sentences":[{"id":"mt-1-7-1","chapter":1,"verse":7,"sentence":1,"reference":"Matthew 1:7","text":"Solomon was the father of Rehoboam."},{"id":"mt-1-7-2","chapter":1,"verse":7,"sentence":2,"reference":"Matthew 1:7","text":"Rehoboam was the father of Abijah."},{"id":"mt-1-7-3","chapter":1,"verse":7,"sentence":3,"reference":"Matthew 1:7","text":"Abijah was the father of Asa."}]},{"chapter":1,"verse":8,"reference":"Matthew 1:8","text":"Asa was the father of Jehoshaphat. Jehoshaphat was the father of Jehoram. Jehoram was the father of Uzziah.","sentences":[{"id":"mt-1-8-1","chapter":1,"verse":8,"sentence":1,"reference":"Matthew 1:8","text":"Asa was the father of Jehoshaphat."},{"id":"mt-1-8-2","chapter":1,"verse":8,"sentence":2,"reference":"Matthew 1:8","text":"Jehoshaphat was the father of Jehoram."},{"id":"mt-1-8-3","chapter":1,"verse":8,"sentence":3,"reference":"Matthew 1:8","text":"Jehoram was the father of Uzziah."}]},{"chapter":1,"verse":9,"reference":"Matthew 1:9","text":"Uzziah was the father of Jotham. Jotham was the father of Ahaz. Ahaz was the father of Hezekiah.","sentences":[{"id":"mt-1-9-1","chapter":1,"verse":9,"sentence":1,"reference":"Matthew 1:9","text":"Uzziah was the father of Jotham."},{"id":"mt-1-9-2","chapter":1,"verse":9,"sentence":2,"reference":"Matthew 1:9","text":"Jotham was the father of Ahaz."},{"id":"mt-1-9-3","chapter":1,"verse":9,"sentence":3,"reference":"Matthew 1:9","text":"Ahaz was the father of Hezekiah."}]},{"chapter":1,"verse":10,"reference":"Matthew 1:10","text":"Hezekiah was the father of Manasseh. Manasseh was the father of Amon. Amon was the father of Josiah.","sentences":[{"id":"mt-1-10-1","chapter":1,"verse":10,"sentence":1,"reference":"Matthew 1:10","text":"Hezekiah was the father of Manasseh."},{"id":"mt-1-10-2","chapter":1,"verse":10,"sentence":2,"reference":"Matthew 1:10","text":"Manasseh was the father of Amon."},{"id":"mt-1-10-3","chapter":1,"verse":10,"sentence":3,"reference":"Matthew 1:10","text":"Amon was the father of Josiah."}]},{"chapter":1,"verse":11,"reference":"Matthew 1:11","text":"Josiah was the father of Jehoiachin and his brothers (born at the time of the exile to Babylon).","sentences":[{"id":"mt-1-11-1","chapter":1,"verse":11,"sentence":1,"reference":"Matthew 1:11","text":"Josiah was the father of Jehoiachin and his brothers (born at the time of the exile to Babylon)."}]},{"chapter":1,"verse":12,"reference":"Matthew 1:12","text":"After the Babylonian exile: Jehoiachin was the father of Shealtiel. Shealtiel was the father of Zerubbabel.","sentences":[{"id":"mt-1-12-1","chapter":1,"verse":12,"sentence":1,"reference":"Matthew 1:12","text":"After the Babylonian exile: Jehoiachin was the father of Shealtiel."},{"id":"mt-1-12-2","chapter":1,"verse":12,"sentence":2,"reference":"Matthew 1:12","text":"Shealtiel was the father of Zerubbabel."}]},{"chapter":1,"verse":13,"reference":"Matthew 1:13","text":"Zerubbabel was the father of Abiud. Abiud was the father of Eliakim. Eliakim was the father of Azor.","sentences":[{"id":"mt-1-13-1","chapter":1,"verse":13,"sentence":1,"reference":"Matthew 1:13","text":"Zerubbabel was the father of Abiud."},{"id":"mt-1-13-2","chapter":1,"verse":13,"sentence":2,"reference":"Matthew 1:13","text":"Abiud was the father of Eliakim."},{"id":"mt-1-13-3","chapter":1,"verse":13,"sentence":3,"reference":"Matthew 1:13","text":"Eliakim was the father of Azor."}]},{"chapter":1,"verse":14,"reference":"Matthew 1:14","text":"Azor was the father of Zadok. Zadok was the father of Akim. Akim was the father of Eliud.","sentences":[{"id":"mt-1-14-1","chapter":1,"verse":14,"sentence":1,"reference":"Matthew 1:14","text":"Azor was the father of Zadok."},{"id":"mt-1-14-2","chapter":1,"verse":14,"sentence":2,"reference":"Matthew 1:14","text":"Zadok was the father of Akim."},{"id":"mt-1-14-3","chapter":1,"verse":14,"sentence":3,"reference":"Matthew 1:14","text":"Akim was the father of Eliud."}]},{"chapter":1,"verse":15,"reference":"Matthew 1:15","text":"Eliud was the father of Eleazar. Eleazar was the father of Matthan. Matthan was the father of Jacob.","sentences":[{"id":"mt-1-15-1","chapter":1,"verse":15,"sentence":1,"reference":"Matthew 1:15","text":"Eliud was the father of Eleazar."},{"id":"mt-1-15-2","chapter":1,"verse":15,"sentence":2,"reference":"Matthew 1:15","text":"Eleazar was the father of Matthan."},{"id":"mt-1-15-3","chapter":1,"verse":15,"sentence":3,"reference":"Matthew 1:15","text":"Matthan was the father of Jacob."}]},{"chapter":1,"verse":16,"reference":"Matthew 1:16","text":"Jacob was the father of Joseph, the husband of Mary. Mary gave birth to Jesus, who is called the Messiah.","sentences":[{"id":"mt-1-16-1","chapter":1,"verse":16,"sentence":1,"reference":"Matthew 1:16","text":"Jacob was the father of Joseph, the husband of Mary."},{"id":"mt-1-16-2","chapter":1,"verse":16,"sentence":2,"reference":"Matthew 1:16","text":"Mary gave birth to Jesus, who is called the Messiah."}]},{"chapter":1,"verse":17,"reference":"Matthew 1:17","text":"All those listed above include fourteen generations from Abraham to David, fourteen from David to the Babylonian exile, and fourteen from the Babylonian exile to the Messiah.","sentences":[{"id":"mt-1-17-1","chapter":1,"verse":17,"sentence":1,"reference":"Matthew 1:17","text":"All those listed above include fourteen generations from Abraham to David, fourteen from David to the Babylonian exile, and fourteen from the Babylonian exile to the Messiah."}]},{"chapter":1,"verse":18,"reference":"Matthew 1:18","text":"This is how Jesus the Messiah was born. His mother, Mary, was engaged to be married to Joseph. But before the marriage took place, while she was still a virgin, she became pregnant through the power of the Holy Spirit.","sentences":[{"id":"mt-1-18-1","chapter":1,"verse":18,"sentence":1,"reference":"Matthew 1:18","text":"This is how Jesus the Messiah was born."},{"id":"mt-1-18-2","chapter":1,"verse":18,"sentence":2,"reference":"Matthew 1:18","text":"His mother, Mary, was engaged to be married to Joseph."},{"id":"mt-1-18-3","chapter":1,"verse":18,"sentence":3,"reference":"Matthew 1:18","text":"But before the marriage took place, while she was still a virgin, she became pregnant through the power of the Holy Spirit."}]},{"chapter":1,"verse":19,"reference":"Matthew 1:19","text":"Joseph, to whom she was engaged, was a righteous man and did not want to disgrace her publicly, so he decided to break the engagement quietly.","sentences":[{"id":"mt-1-19-1","chapter":1,"verse":19,"sentence":1,"reference":"Matthew 1:19","text":"Joseph, to whom she was engaged, was a righteous man and did not want to disgrace her publicly, so he decided to break the engagement quietly."}]},{"chapter":1,"verse":20,"reference":"Matthew 1:20","text":"As he considered this, an angel of the Lord appeared to him in a dream. “Joseph, son of David,” the angel said, “do not be afraid to take Mary as your wife. For the child within her was conceived by the Holy Spirit.","sentences":[{"id":"mt-1-20-1","chapter":1,"verse":20,"sentence":1,"reference":"Matthew 1:20","text":"As he considered this, an angel of the Lord appeared to him in a dream."},{"id":"mt-1-20-2","chapter":1,"verse":20,"sentence":2,"reference":"Matthew 1:20","text":"“Joseph, son of David,” the angel said, “do not be afraid to take Mary as your wife."},{"id":"mt-1-20-3","chapter":1,"verse":20,"sentence":3,"reference":"Matthew 1:20","text":"For the child within her was conceived by the Holy Spirit."}]},{"chapter":1,"verse":21,"reference":"Matthew 1:21","text":"And she will have a son, and you are to name him Jesus, for he will save his people from their sins.”","sentences":[{"id":"mt-1-21-1","chapter":1,"verse":21,"sentence":1,"reference":"Matthew 1:21","text":"And she will have a son, and you are to name him Jesus, for he will save his people from their sins.”"}]},{"chapter":1,"verse":22,"reference":"Matthew 1:22","text":"All of this occurred to fulfill the Lord’s message through his prophet:","sentences":[{"id":"mt-1-22-1","chapter":1,"verse":22,"sentence":1,"reference":"Matthew 1:22","text":"All of this occurred to fulfill the Lord’s message through his prophet:"}]},{"chapter":1,"verse":23,"reference":"Matthew 1:23","text":"“Look! The virgin will conceive a child! She will give birth to a son, and they will call him Immanuel, which means ‘God is with us.’”","sentences":[{"id":"mt-1-23-1","chapter":1,"verse":23,"sentence":1,"reference":"Matthew 1:23","text":"“Look!"},{"id":"mt-1-23-2","chapter":1,"verse":23,"sentence":2,"reference":"Matthew 1:23","text":"The virgin will conceive a child!"},{"id":"mt-1-23-3","chapter":1,"verse":23,"sentence":3,"reference":"Matthew 1:23","text":"She will give birth to a son, and they will call him Immanuel, which means ‘God is with us.’”"}]},{"chapter":1,"verse":24,"reference":"Matthew 1:24","text":"When Joseph woke up, he did as the angel of the Lord commanded and took Mary as his wife.","sentences":[{"id":"mt-1-24-1","chapter":1,"verse":24,"sentence":1,"reference":"Matthew 1:24","text":"When Joseph woke up, he did as the angel of the Lord commanded and took Mary as his wife."}]},{"chapter":1,"verse":25,"reference":"Matthew 1:25","text":"But he did not have sexual relations with her until her son was born. And Joseph named him Jesus.","sentences":[{"id":"mt-1-25-1","chapter":1,"verse":25,"sentence":1,"reference":"Matthew 1:25","text":"But he did not have sexual relations with her until her son was born."},{"id":"mt-1-25-2","chapter":1,"verse":25,"sentence":2,"reference":"Matthew 1:25","text":"And Joseph named him Jesus."}]}]},{"chapter":2,"verses":[{"chapter":2,"verse":1,"reference":"Matthew 2:1","text":"Jesus was born in Bethlehem in Judea, during the reign of King Herod. About that time some wise men from eastern lands arrived in Jerusalem, asking,","sentences":[{"id":"mt-2-1-1","chapter":2,"verse":1,"sentence":1,"reference":"Matthew 2:1","text":"Jesus was born in Bethlehem in Judea, during the reign of King Herod."},{"id":"mt-2-1-2","chapter":2,"verse":1,"sentence":2,"reference":"Matthew 2:1","text":"About that time some wise men from eastern lands arrived in Jerusalem, asking,"}]},{"chapter":2,"verse":2,"reference":"Matthew 2:2","text":"“Where is the newborn king of the Jews? We saw his star as it rose, and we have come to worship him.”","sentences":[{"id":"mt-2-2-1","chapter":2,"verse":2,"sentence":1,"reference":"Matthew 2:2","text":"“Where is the newborn king of the Jews?"},{"id":"mt-2-2-2","chapter":2,"verse":2,"sentence":2,"reference":"Matthew 2:2","text":"We saw his star as it rose, and we have come to worship him.”"}]},{"chapter":2,"verse":3,"reference":"Matthew 2:3","text":"King Herod was deeply disturbed when he heard this, as was everyone in Jerusalem.","sentences":[{"id":"mt-2-3-1","chapter":2,"verse":3,"sentence":1,"reference":"Matthew 2:3","text":"King Herod was deeply disturbed when he heard this, as was everyone in Jerusalem."}]},{"chapter":2,"verse":4,"reference":"Matthew 2:4","text":"He called a meeting of the leading priests and teachers of religious law and asked, “Where is the Messiah supposed to be born?”","sentences":[{"id":"mt-2-4-1","chapter":2,"verse":4,"sentence":1,"reference":"Matthew 2:4","text":"He called a meeting of the leading priests and teachers of religious law and asked, “Where is the Messiah supposed to be born?”"}]},{"chapter":2,"verse":5,"reference":"Matthew 2:5","text":"“In Bethlehem in Judea,” they said, “for this is what the prophet wrote:","sentences":[{"id":"mt-2-5-1","chapter":2,"verse":5,"sentence":1,"reference":"Matthew 2:5","text":"“In Bethlehem in Judea,” they said, “for this is what the prophet wrote:"}]},{"chapter":2,"verse":6,"reference":"Matthew 2:6","text":"‘And you, O Bethlehem in the land of Judah, are not least among the ruling cities of Judah, for a ruler will come from you who will be the shepherd for my people Israel.’”","sentences":[{"id":"mt-2-6-1","chapter":2,"verse":6,"sentence":1,"reference":"Matthew 2:6","text":"‘And you, O Bethlehem in the land of Judah, are not least among the ruling cities of Judah, for a ruler will come from you who will be the shepherd for my people Israel.’”"}]},{"chapter":2,"verse":7,"reference":"Matthew 2:7","text":"Then Herod called for a private meeting with the wise men, and he learned from them the time when the star first appeared.","sentences":[{"id":"mt-2-7-1","chapter":2,"verse":7,"sentence":1,"reference":"Matthew 2:7","text":"Then Herod called for a private meeting with the wise men, and he learned from them the time when the star first appeared."}]},{"chapter":2,"verse":8,"reference":"Matthew 2:8","text":"Then he told them, “Go to Bethlehem and search carefully for the child. And when you find him, come back and tell me so that I can go and worship him, too!”","sentences":[{"id":"mt-2-8-1","chapter":2,"verse":8,"sentence":1,"reference":"Matthew 2:8","text":"Then he told them, “Go to Bethlehem and search carefully for the child."},{"id":"mt-2-8-2","chapter":2,"verse":8,"sentence":2,"reference":"Matthew 2:8","text":"And when you find him, come back and tell me so that I can go and worship him, too!”"}]},{"chapter":2,"verse":9,"reference":"Matthew 2:9","text":"After this interview the wise men went their way. And the star they had seen in the east guided them to Bethlehem. It went ahead of them and stopped over the place where the child was.","sentences":[{"id":"mt-2-9-1","chapter":2,"verse":9,"sentence":1,"reference":"Matthew 2:9","text":"After this interview the wise men went their way."},{"id":"mt-2-9-2","chapter":2,"verse":9,"sentence":2,"reference":"Matthew 2:9","text":"And the star they had seen in the east guided them to Bethlehem."},{"id":"mt-2-9-3","chapter":2,"verse":9,"sentence":3,"reference":"Matthew 2:9","text":"It went ahead of them and stopped over the place where the child was."}]},{"chapter":2,"verse":10,"reference":"Matthew 2:10","text":"When they saw the star, they were filled with joy!","sentences":[{"id":"mt-2-10-1","chapter":2,"verse":10,"sentence":1,"reference":"Matthew 2:10","text":"When they saw the star, they were filled with joy!"}]},{"chapter":2,"verse":11,"reference":"Matthew 2:11","text":"They entered the house and saw the child with his mother, Mary, and they bowed down and worshiped him. Then they opened their treasure chests and gave him gifts of gold, frankincense, and myrrh.","sentences":[{"id":"mt-2-11-1","chapter":2,"verse":11,"sentence":1,"reference":"Matthew 2:11","text":"They entered the house and saw the child with his mother, Mary, and they bowed down and worshiped him."},{"id":"mt-2-11-2","chapter":2,"verse":11,"sentence":2,"reference":"Matthew 2:11","text":"Then they opened their treasure chests and gave him gifts of gold, frankincense, and myrrh."}]},{"chapter":2,"verse":12,"reference":"Matthew 2:12","text":"When it was time to leave, they returned to their own country by another route, for God had warned them in a dream not to return to Herod.","sentences":[{"id":"mt-2-12-1","chapter":2,"verse":12,"sentence":1,"reference":"Matthew 2:12","text":"When it was time to leave, they returned to their own country by another route, for God had warned them in a dream not to return to Herod."}]},{"chapter":2,"verse":13,"reference":"Matthew 2:13","text":"After the wise men were gone, an angel of the Lord appeared to Joseph in a dream. “Get up! Flee to Egypt with the child and his mother,” the angel said. “Stay there until I tell you to return, because Herod is going to search for the child to kill him.”","sentences":[{"id":"mt-2-13-1","chapter":2,"verse":13,"sentence":1,"reference":"Matthew 2:13","text":"After the wise men were gone, an angel of the Lord appeared to Joseph in a dream."},{"id":"mt-2-13-2","chapter":2,"verse":13,"sentence":2,"reference":"Matthew 2:13","text":"“Get up!"},{"id":"mt-2-13-3","chapter":2,"verse":13,"sentence":3,"reference":"Matthew 2:13","text":"Flee to Egypt with the child and his mother,” the angel said."},{"id":"mt-2-13-4","chapter":2,"verse":13,"sentence":4,"reference":"Matthew 2:13","text":"“Stay there until I tell you to return, because Herod is going to search for the child to kill him.”"}]},{"chapter":2,"verse":14,"reference":"Matthew 2:14","text":"That night Joseph left for Egypt with the child and Mary, his mother,","sentences":[{"id":"mt-2-14-1","chapter":2,"verse":14,"sentence":1,"reference":"Matthew 2:14","text":"That night Joseph left for Egypt with the child and Mary, his mother,"}]},{"chapter":2,"verse":15,"reference":"Matthew 2:15","text":"and they stayed there until Herod’s death. This fulfilled what the Lord had spoken through the prophet: “I called my Son out of Egypt.”","sentences":[{"id":"mt-2-15-1","chapter":2,"verse":15,"sentence":1,"reference":"Matthew 2:15","text":"and they stayed there until Herod’s death."},{"id":"mt-2-15-2","chapter":2,"verse":15,"sentence":2,"reference":"Matthew 2:15","text":"This fulfilled what the Lord had spoken through the prophet: “I called my Son out of Egypt.”"}]},{"chapter":2,"verse":16,"reference":"Matthew 2:16","text":"Herod was furious when he realized that the wise men had outwitted him. He sent soldiers to kill all the boys in and around Bethlehem who were two years old and under, based on the wise men’s report of the star’s first appearance.","sentences":[{"id":"mt-2-16-1","chapter":2,"verse":16,"sentence":1,"reference":"Matthew 2:16","text":"Herod was furious when he realized that the wise men had outwitted him."},{"id":"mt-2-16-2","chapter":2,"verse":16,"sentence":2,"reference":"Matthew 2:16","text":"He sent soldiers to kill all the boys in and around Bethlehem who were two years old and under, based on the wise men’s report of the star’s first appearance."}]},{"chapter":2,"verse":17,"reference":"Matthew 2:17","text":"Herod’s brutal action fulfilled what God had spoken through the prophet Jeremiah:","sentences":[{"id":"mt-2-17-1","chapter":2,"verse":17,"sentence":1,"reference":"Matthew 2:17","text":"Herod’s brutal action fulfilled what God had spoken through the prophet Jeremiah:"}]},{"chapter":2,"verse":18,"reference":"Matthew 2:18","text":"“A cry was heard in Ramah— weeping and great mourning. Rachel weeps for her children, refusing to be comforted, for they are dead.”","sentences":[{"id":"mt-2-18-1","chapter":2,"verse":18,"sentence":1,"reference":"Matthew 2:18","text":"“A cry was heard in Ramah— weeping and great mourning."},{"id":"mt-2-18-2","chapter":2,"verse":18,"sentence":2,"reference":"Matthew 2:18","text":"Rachel weeps for her children, refusing to be comforted, for they are dead.”"}]},{"chapter":2,"verse":19,"reference":"Matthew 2:19","text":"When Herod died, an angel of the Lord appeared in a dream to Joseph in Egypt.","sentences":[{"id":"mt-2-19-1","chapter":2,"verse":19,"sentence":1,"reference":"Matthew 2:19","text":"When Herod died, an angel of the Lord appeared in a dream to Joseph in Egypt."}]},{"chapter":2,"verse":20,"reference":"Matthew 2:20","text":"“Get up!” the angel said. “Take the child and his mother back to the land of Israel, because those who were trying to kill the child are dead.”","sentences":[{"id":"mt-2-20-1","chapter":2,"verse":20,"sentence":1,"reference":"Matthew 2:20","text":"“Get up!”"},{"id":"mt-2-20-2","chapter":2,"verse":20,"sentence":2,"reference":"Matthew 2:20","text":"the angel said."},{"id":"mt-2-20-3","chapter":2,"verse":20,"sentence":3,"reference":"Matthew 2:20","text":"“Take the child and his mother back to the land of Israel, because those who were trying to kill the child are dead.”"}]},{"chapter":2,"verse":21,"reference":"Matthew 2:21","text":"So Joseph got up and returned to the land of Israel with Jesus and his mother.","sentences":[{"id":"mt-2-21-1","chapter":2,"verse":21,"sentence":1,"reference":"Matthew 2:21","text":"So Joseph got up and returned to the land of Israel with Jesus and his mother."}]},{"chapter":2,"verse":22,"reference":"Matthew 2:22","text":"But when he learned that the new ruler of Judea was Herod’s son Archelaus, he was afraid to go there. Then, after being warned in a dream, he left for the region of Galilee.","sentences":[{"id":"mt-2-22-1","chapter":2,"verse":22,"sentence":1,"reference":"Matthew 2:22","text":"But when he learned that the new ruler of Judea was Herod’s son Archelaus, he was afraid to go there."},{"id":"mt-2-22-2","chapter":2,"verse":22,"sentence":2,"reference":"Matthew 2:22","text":"Then, after being warned in a dream, he left for the region of Galilee."}]},{"chapter":2,"verse":23,"reference":"Matthew 2:23","text":"So the family went and lived in a town called Nazareth. This fulfilled what the prophets had said: “He will be called a Nazarene.”","sentences":[{"id":"mt-2-23-1","chapter":2,"verse":23,"sentence":1,"reference":"Matthew 2:23","text":"So the family went and lived in a town called Nazareth."},{"id":"mt-2-23-2","chapter":2,"verse":23,"sentence":2,"reference":"Matthew 2:23","text":"This fulfilled what the prophets had said: “He will be called a Nazarene.”"}]}]},{"chapter":3,"verses":[{"chapter":3,"verse":1,"reference":"Matthew 3:1","text":"In those days John the Baptist came to the Judean wilderness and began preaching. His message was,","sentences":[{"id":"mt-3-1-1","chapter":3,"verse":1,"sentence":1,"reference":"Matthew 3:1","text":"In those days John the Baptist came to the Judean wilderness and began preaching."},{"id":"mt-3-1-2","chapter":3,"verse":1,"sentence":2,"reference":"Matthew 3:1","text":"His message was,"}]},{"chapter":3,"verse":2,"reference":"Matthew 3:2","text":"“Repent of your sins and turn to God, for the Kingdom of Heaven is near.”","sentences":[{"id":"mt-3-2-1","chapter":3,"verse":2,"sentence":1,"reference":"Matthew 3:2","text":"“Repent of your sins and turn to God, for the Kingdom of Heaven is near.”"}]},{"chapter":3,"verse":3,"reference":"Matthew 3:3","text":"The prophet Isaiah was speaking about John when he said, “He is a voice shouting in the wilderness, ‘Prepare the way for the Lord’s coming! Clear the road for him!’”","sentences":[{"id":"mt-3-3-1","chapter":3,"verse":3,"sentence":1,"reference":"Matthew 3:3","text":"The prophet Isaiah was speaking about John when he said, “He is a voice shouting in the wilderness, ‘Prepare the way for the Lord’s coming!"},{"id":"mt-3-3-2","chapter":3,"verse":3,"sentence":2,"reference":"Matthew 3:3","text":"Clear the road for him!’”"}]},{"chapter":3,"verse":4,"reference":"Matthew 3:4","text":"John’s clothes were woven from coarse camel hair, and he wore a leather belt around his waist. For food he ate locusts and wild honey.","sentences":[{"id":"mt-3-4-1","chapter":3,"verse":4,"sentence":1,"reference":"Matthew 3:4","text":"John’s clothes were woven from coarse camel hair, and he wore a leather belt around his waist."},{"id":"mt-3-4-2","chapter":3,"verse":4,"sentence":2,"reference":"Matthew 3:4","text":"For food he ate locusts and wild honey."}]},{"chapter":3,"verse":5,"reference":"Matthew 3:5","text":"People from Jerusalem and from all of Judea and all over the Jordan Valley went out to see and hear John.","sentences":[{"id":"mt-3-5-1","chapter":3,"verse":5,"sentence":1,"reference":"Matthew 3:5","text":"People from Jerusalem and from all of Judea and all over the Jordan Valley went out to see and hear John."}]},{"chapter":3,"verse":6,"reference":"Matthew 3:6","text":"And when they confessed their sins, he baptized them in the Jordan River.","sentences":[{"id":"mt-3-6-1","chapter":3,"verse":6,"sentence":1,"reference":"Matthew 3:6","text":"And when they confessed their sins, he baptized them in the Jordan River."}]},{"chapter":3,"verse":7,"reference":"Matthew 3:7","text":"But when he saw many Pharisees and Sadducees coming to watch him baptize, he denounced them. “You brood of snakes!” he exclaimed. “Who warned you to flee the coming wrath?","sentences":[{"id":"mt-3-7-1","chapter":3,"verse":7,"sentence":1,"reference":"Matthew 3:7","text":"But when he saw many Pharisees and Sadducees coming to watch him baptize, he denounced them."},{"id":"mt-3-7-2","chapter":3,"verse":7,"sentence":2,"reference":"Matthew 3:7","text":"“You brood of snakes!”"},{"id":"mt-3-7-3","chapter":3,"verse":7,"sentence":3,"reference":"Matthew 3:7","text":"he exclaimed."},{"id":"mt-3-7-4","chapter":3,"verse":7,"sentence":4,"reference":"Matthew 3:7","text":"“Who warned you to flee the coming wrath?"}]},{"chapter":3,"verse":8,"reference":"Matthew 3:8","text":"Prove by the way you live that you have repented of your sins and turned to God.","sentences":[{"id":"mt-3-8-1","chapter":3,"verse":8,"sentence":1,"reference":"Matthew 3:8","text":"Prove by the way you live that you have repented of your sins and turned to God."}]},{"chapter":3,"verse":9,"reference":"Matthew 3:9","text":"Don’t just say to each other, ‘We’re safe, for we are descendants of Abraham.’ That means nothing, for I tell you, God can create children of Abraham from these very stones.","sentences":[{"id":"mt-3-9-1","chapter":3,"verse":9,"sentence":1,"reference":"Matthew 3:9","text":"Don’t just say to each other, ‘We’re safe, for we are descendants of Abraham.’"},{"id":"mt-3-9-2","chapter":3,"verse":9,"sentence":2,"reference":"Matthew 3:9","text":"That means nothing, for I tell you, God can create children of Abraham from these very stones."}]},{"chapter":3,"verse":10,"reference":"Matthew 3:10","text":"Even now the ax of God’s judgment is poised, ready to sever the roots of the trees. Yes, every tree that does not produce good fruit will be chopped down and thrown into the fire.","sentences":[{"id":"mt-3-10-1","chapter":3,"verse":10,"sentence":1,"reference":"Matthew 3:10","text":"Even now the ax of God’s judgment is poised, ready to sever the roots of the trees."},{"id":"mt-3-10-2","chapter":3,"verse":10,"sentence":2,"reference":"Matthew 3:10","text":"Yes, every tree that does not produce good fruit will be chopped down and thrown into the fire."}]},{"chapter":3,"verse":11,"reference":"Matthew 3:11","text":"“I baptize with water those who repent of their sins and turn to God. But someone is coming soon who is greater than I am—so much greater that I’m not worthy even to be his slave and carry his sandals. He will baptize you with the Holy Spirit and with fire.","sentences":[{"id":"mt-3-11-1","chapter":3,"verse":11,"sentence":1,"reference":"Matthew 3:11","text":"“I baptize with water those who repent of their sins and turn to God."},{"id":"mt-3-11-2","chapter":3,"verse":11,"sentence":2,"reference":"Matthew 3:11","text":"But someone is coming soon who is greater than I am—so much greater that I’m not worthy even to be his slave and carry his sandals."},{"id":"mt-3-11-3","chapter":3,"verse":11,"sentence":3,"reference":"Matthew 3:11","text":"He will baptize you with the Holy Spirit and with fire."}]},{"chapter":3,"verse":12,"reference":"Matthew 3:12","text":"He is ready to separate the chaff from the wheat with his winnowing fork. Then he will clean up the threshing area, gathering the wheat into his barn but burning the chaff with never-ending fire.”","sentences":[{"id":"mt-3-12-1","chapter":3,"verse":12,"sentence":1,"reference":"Matthew 3:12","text":"He is ready to separate the chaff from the wheat with his winnowing fork."},{"id":"mt-3-12-2","chapter":3,"verse":12,"sentence":2,"reference":"Matthew 3:12","text":"Then he will clean up the threshing area, gathering the wheat into his barn but burning the chaff with never-ending fire.”"}]},{"chapter":3,"verse":13,"reference":"Matthew 3:13","text":"Then Jesus went from Galilee to the Jordan River to be baptized by John.","sentences":[{"id":"mt-3-13-1","chapter":3,"verse":13,"sentence":1,"reference":"Matthew 3:13","text":"Then Jesus went from Galilee to the Jordan River to be baptized by John."}]},{"chapter":3,"verse":14,"reference":"Matthew 3:14","text":"But John tried to talk him out of it. “I am the one who needs to be baptized by you,” he said, “so why are you coming to me?”","sentences":[{"id":"mt-3-14-1","chapter":3,"verse":14,"sentence":1,"reference":"Matthew 3:14","text":"But John tried to talk him out of it."},{"id":"mt-3-14-2","chapter":3,"verse":14,"sentence":2,"reference":"Matthew 3:14","text":"“I am the one who needs to be baptized by you,” he said, “so why are you coming to me?”"}]},{"chapter":3,"verse":15,"reference":"Matthew 3:15","text":"But Jesus said, “It should be done, for we must carry out all that God requires.” So John agreed to baptize him.","sentences":[{"id":"mt-3-15-1","chapter":3,"verse":15,"sentence":1,"reference":"Matthew 3:15","text":"But Jesus said, “It should be done, for we must carry out all that God requires.”"},{"id":"mt-3-15-2","chapter":3,"verse":15,"sentence":2,"reference":"Matthew 3:15","text":"So John agreed to baptize him."}]},{"chapter":3,"verse":16,"reference":"Matthew 3:16","text":"After his baptism, as Jesus came up out of the water, the heavens were opened and he saw the Spirit of God descending like a dove and settling on him.","sentences":[{"id":"mt-3-16-1","chapter":3,"verse":16,"sentence":1,"reference":"Matthew 3:16","text":"After his baptism, as Jesus came up out of the water, the heavens were opened and he saw the Spirit of God descending like a dove and settling on him."}]},{"chapter":3,"verse":17,"reference":"Matthew 3:17","text":"And a voice from heaven said, “This is my dearly loved Son, who brings me great joy.”","sentences":[{"id":"mt-3-17-1","chapter":3,"verse":17,"sentence":1,"reference":"Matthew 3:17","text":"And a voice from heaven said, “This is my dearly loved Son, who brings me great joy.”"}]}]},{"chapter":4,"verses":[{"chapter":4,"verse":1,"reference":"Matthew 4:1","text":"Then Jesus was led by the Spirit into the wilderness to be tempted there by the devil.","sentences":[{"id":"mt-4-1-1","chapter":4,"verse":1,"sentence":1,"reference":"Matthew 4:1","text":"Then Jesus was led by the Spirit into the wilderness to be tempted there by the devil."}]},{"chapter":4,"verse":2,"reference":"Matthew 4:2","text":"For forty days and forty nights he fasted and became very hungry.","sentences":[{"id":"mt-4-2-1","chapter":4,"verse":2,"sentence":1,"reference":"Matthew 4:2","text":"For forty days and forty nights he fasted and became very hungry."}]},{"chapter":4,"verse":3,"reference":"Matthew 4:3","text":"During that time the devil came and said to him, “If you are the Son of God, tell these stones to become loaves of bread.”","sentences":[{"id":"mt-4-3-1","chapter":4,"verse":3,"sentence":1,"reference":"Matthew 4:3","text":"During that time the devil came and said to him, “If you are the Son of God, tell these stones to become loaves of bread.”"}]},{"chapter":4,"verse":4,"reference":"Matthew 4:4","text":"But Jesus told him, “No! The Scriptures say, ‘People do not live by bread alone, but by every word that comes from the mouth of God.’ ”","sentences":[{"id":"mt-4-4-1","chapter":4,"verse":4,"sentence":1,"reference":"Matthew 4:4","text":"But Jesus told him, “No!"},{"id":"mt-4-4-2","chapter":4,"verse":4,"sentence":2,"reference":"Matthew 4:4","text":"The Scriptures say, ‘People do not live by bread alone, but by every word that comes from the mouth of God.’"},{"id":"mt-4-4-3","chapter":4,"verse":4,"sentence":3,"reference":"Matthew 4:4","text":"”"}]},{"chapter":4,"verse":5,"reference":"Matthew 4:5","text":"Then the devil took him to the holy city, Jerusalem, to the highest point of the Temple,","sentences":[{"id":"mt-4-5-1","chapter":4,"verse":5,"sentence":1,"reference":"Matthew 4:5","text":"Then the devil took him to the holy city, Jerusalem, to the highest point of the Temple,"}]},{"chapter":4,"verse":6,"reference":"Matthew 4:6","text":"and said, “If you are the Son of God, jump off! For the Scriptures say, ‘He will order his angels to protect you. And they will hold you up with their hands so you won’t even hurt your foot on a stone.’”","sentences":[{"id":"mt-4-6-1","chapter":4,"verse":6,"sentence":1,"reference":"Matthew 4:6","text":"and said, “If you are the Son of God, jump off!"},{"id":"mt-4-6-2","chapter":4,"verse":6,"sentence":2,"reference":"Matthew 4:6","text":"For the Scriptures say, ‘He will order his angels to protect you."},{"id":"mt-4-6-3","chapter":4,"verse":6,"sentence":3,"reference":"Matthew 4:6","text":"And they will hold you up with their hands so you won’t even hurt your foot on a stone.’”"}]},{"chapter":4,"verse":7,"reference":"Matthew 4:7","text":"Jesus responded, “The Scriptures also say, ‘You must not test the Lord your God.’”","sentences":[{"id":"mt-4-7-1","chapter":4,"verse":7,"sentence":1,"reference":"Matthew 4:7","text":"Jesus responded, “The Scriptures also say, ‘You must not test the Lord your God.’”"}]},{"chapter":4,"verse":8,"reference":"Matthew 4:8","text":"Next the devil took him to the peak of a very high mountain and showed him all the kingdoms of the world and their glory.","sentences":[{"id":"mt-4-8-1","chapter":4,"verse":8,"sentence":1,"reference":"Matthew 4:8","text":"Next the devil took him to the peak of a very high mountain and showed him all the kingdoms of the world and their glory."}]},{"chapter":4,"verse":9,"reference":"Matthew 4:9","text":"“I will give it all to you,” he said, “if you will kneel down and worship me.”","sentences":[{"id":"mt-4-9-1","chapter":4,"verse":9,"sentence":1,"reference":"Matthew 4:9","text":"“I will give it all to you,” he said, “if you will kneel down and worship me.”"}]},{"chapter":4,"verse":10,"reference":"Matthew 4:10","text":"“Get out of here, Satan,” Jesus told him. “For the Scriptures say, ‘You must worship the Lord your God and serve only him.’ ”","sentences":[{"id":"mt-4-10-1","chapter":4,"verse":10,"sentence":1,"reference":"Matthew 4:10","text":"“Get out of here, Satan,” Jesus told him."},{"id":"mt-4-10-2","chapter":4,"verse":10,"sentence":2,"reference":"Matthew 4:10","text":"“For the Scriptures say, ‘You must worship the Lord your God and serve only him.’"},{"id":"mt-4-10-3","chapter":4,"verse":10,"sentence":3,"reference":"Matthew 4:10","text":"”"}]},{"chapter":4,"verse":11,"reference":"Matthew 4:11","text":"Then the devil went away, and angels came and took care of Jesus.","sentences":[{"id":"mt-4-11-1","chapter":4,"verse":11,"sentence":1,"reference":"Matthew 4:11","text":"Then the devil went away, and angels came and took care of Jesus."}]},{"chapter":4,"verse":12,"reference":"Matthew 4:12","text":"When Jesus heard that John had been arrested, he left Judea and returned to Galilee.","sentences":[{"id":"mt-4-12-1","chapter":4,"verse":12,"sentence":1,"reference":"Matthew 4:12","text":"When Jesus heard that John had been arrested, he left Judea and returned to Galilee."}]},{"chapter":4,"verse":13,"reference":"Matthew 4:13","text":"He went first to Nazareth, then left there and moved to Capernaum, beside the Sea of Galilee, in the region of Zebulun and Naphtali.","sentences":[{"id":"mt-4-13-1","chapter":4,"verse":13,"sentence":1,"reference":"Matthew 4:13","text":"He went first to Nazareth, then left there and moved to Capernaum, beside the Sea of Galilee, in the region of Zebulun and Naphtali."}]},{"chapter":4,"verse":14,"reference":"Matthew 4:14","text":"This fulfilled what God said through the prophet Isaiah:","sentences":[{"id":"mt-4-14-1","chapter":4,"verse":14,"sentence":1,"reference":"Matthew 4:14","text":"This fulfilled what God said through the prophet Isaiah:"}]},{"chapter":4,"verse":15,"reference":"Matthew 4:15","text":"“In the land of Zebulun and of Naphtali, beside the sea, beyond the Jordan River, in Galilee where so many Gentiles live,","sentences":[{"id":"mt-4-15-1","chapter":4,"verse":15,"sentence":1,"reference":"Matthew 4:15","text":"“In the land of Zebulun and of Naphtali, beside the sea, beyond the Jordan River, in Galilee where so many Gentiles live,"}]},{"chapter":4,"verse":16,"reference":"Matthew 4:16","text":"the people who sat in darkness have seen a great light. And for those who lived in the land where death casts its shadow, a light has shined.”","sentences":[{"id":"mt-4-16-1","chapter":4,"verse":16,"sentence":1,"reference":"Matthew 4:16","text":"the people who sat in darkness have seen a great light."},{"id":"mt-4-16-2","chapter":4,"verse":16,"sentence":2,"reference":"Matthew 4:16","text":"And for those who lived in the land where death casts its shadow, a light has shined.”"}]},{"chapter":4,"verse":17,"reference":"Matthew 4:17","text":"From then on Jesus began to preach, “Repent of your sins and turn to God, for the Kingdom of Heaven is near.”","sentences":[{"id":"mt-4-17-1","chapter":4,"verse":17,"sentence":1,"reference":"Matthew 4:17","text":"From then on Jesus began to preach, “Repent of your sins and turn to God, for the Kingdom of Heaven is near.”"}]},{"chapter":4,"verse":18,"reference":"Matthew 4:18","text":"One day as Jesus was walking along the shore of the Sea of Galilee, he saw two brothers—Simon, also called Peter, and Andrew—throwing a net into the water, for they fished for a living.","sentences":[{"id":"mt-4-18-1","chapter":4,"verse":18,"sentence":1,"reference":"Matthew 4:18","text":"One day as Jesus was walking along the shore of the Sea of Galilee, he saw two brothers—Simon, also called Peter, and Andrew—throwing a net into the water, for they fished for a living."}]},{"chapter":4,"verse":19,"reference":"Matthew 4:19","text":"Jesus called out to them, “Come, follow me, and I will show you how to fish for people!”","sentences":[{"id":"mt-4-19-1","chapter":4,"verse":19,"sentence":1,"reference":"Matthew 4:19","text":"Jesus called out to them, “Come, follow me, and I will show you how to fish for people!”"}]},{"chapter":4,"verse":20,"reference":"Matthew 4:20","text":"And they left their nets at once and followed him.","sentences":[{"id":"mt-4-20-1","chapter":4,"verse":20,"sentence":1,"reference":"Matthew 4:20","text":"And they left their nets at once and followed him."}]},{"chapter":4,"verse":21,"reference":"Matthew 4:21","text":"A little farther up the shore he saw two other brothers, James and John, sitting in a boat with their father, Zebedee, repairing their nets. And he called them to come, too.","sentences":[{"id":"mt-4-21-1","chapter":4,"verse":21,"sentence":1,"reference":"Matthew 4:21","text":"A little farther up the shore he saw two other brothers, James and John, sitting in a boat with their father, Zebedee, repairing their nets."},{"id":"mt-4-21-2","chapter":4,"verse":21,"sentence":2,"reference":"Matthew 4:21","text":"And he called them to come, too."}]},{"chapter":4,"verse":22,"reference":"Matthew 4:22","text":"They immediately followed him, leaving the boat and their father behind.","sentences":[{"id":"mt-4-22-1","chapter":4,"verse":22,"sentence":1,"reference":"Matthew 4:22","text":"They immediately followed him, leaving the boat and their father behind."}]},{"chapter":4,"verse":23,"reference":"Matthew 4:23","text":"Jesus traveled throughout the region of Galilee, teaching in the synagogues and announcing the Good News about the Kingdom. And he healed every kind of disease and illness.","sentences":[{"id":"mt-4-23-1","chapter":4,"verse":23,"sentence":1,"reference":"Matthew 4:23","text":"Jesus traveled throughout the region of Galilee, teaching in the synagogues and announcing the Good News about the Kingdom."},{"id":"mt-4-23-2","chapter":4,"verse":23,"sentence":2,"reference":"Matthew 4:23","text":"And he healed every kind of disease and illness."}]},{"chapter":4,"verse":24,"reference":"Matthew 4:24","text":"News about him spread as far as Syria, and people soon began bringing to him all who were sick. And whatever their sickness or disease, or if they were demon possessed or epileptic or paralyzed—he healed them all.","sentences":[{"id":"mt-4-24-1","chapter":4,"verse":24,"sentence":1,"reference":"Matthew 4:24","text":"News about him spread as far as Syria, and people soon began bringing to him all who were sick."},{"id":"mt-4-24-2","chapter":4,"verse":24,"sentence":2,"reference":"Matthew 4:24","text":"And whatever their sickness or disease, or if they were demon possessed or epileptic or paralyzed—he healed them all."}]},{"chapter":4,"verse":25,"reference":"Matthew 4:25","text":"Large crowds followed him wherever he went—people from Galilee, the Ten Towns, Jerusalem, from all over Judea, and from east of the Jordan River.","sentences":[{"id":"mt-4-25-1","chapter":4,"verse":25,"sentence":1,"reference":"Matthew 4:25","text":"Large crowds followed him wherever he went—people from Galilee, the Ten Towns, Jerusalem, from all over Judea, and from east of the Jordan River."}]}]},{"chapter":5,"verses":[{"chapter":5,"verse":1,"reference":"Matthew 5:1","text":"One day as he saw the crowds gathering, Jesus went up on the mountainside and sat down. His disciples gathered around him,","sentences":[{"id":"mt-5-1-1","chapter":5,"verse":1,"sentence":1,"reference":"Matthew 5:1","text":"One day as he saw the crowds gathering, Jesus went up on the mountainside and sat down."},{"id":"mt-5-1-2","chapter":5,"verse":1,"sentence":2,"reference":"Matthew 5:1","text":"His disciples gathered around him,"}]},{"chapter":5,"verse":2,"reference":"Matthew 5:2","text":"and he began to teach them.","sentences":[{"id":"mt-5-2-1","chapter":5,"verse":2,"sentence":1,"reference":"Matthew 5:2","text":"and he began to teach them."}]},{"chapter":5,"verse":3,"reference":"Matthew 5:3","text":"“God blesses those who are poor and realize their need for him, for the Kingdom of Heaven is theirs.","sentences":[{"id":"mt-5-3-1","chapter":5,"verse":3,"sentence":1,"reference":"Matthew 5:3","text":"“God blesses those who are poor and realize their need for him, for the Kingdom of Heaven is theirs."}]},{"chapter":5,"verse":4,"reference":"Matthew 5:4","text":"God blesses those who mourn, for they will be comforted.","sentences":[{"id":"mt-5-4-1","chapter":5,"verse":4,"sentence":1,"reference":"Matthew 5:4","text":"God blesses those who mourn, for they will be comforted."}]},{"chapter":5,"verse":5,"reference":"Matthew 5:5","text":"God blesses those who are humble, for they will inherit the whole earth.","sentences":[{"id":"mt-5-5-1","chapter":5,"verse":5,"sentence":1,"reference":"Matthew 5:5","text":"God blesses those who are humble, for they will inherit the whole earth."}]},{"chapter":5,"verse":6,"reference":"Matthew 5:6","text":"God blesses those who hunger and thirst for justice, for they will be satisfied.","sentences":[{"id":"mt-5-6-1","chapter":5,"verse":6,"sentence":1,"reference":"Matthew 5:6","text":"God blesses those who hunger and thirst for justice, for they will be satisfied."}]},{"chapter":5,"verse":7,"reference":"Matthew 5:7","text":"God blesses those who are merciful, for they will be shown mercy.","sentences":[{"id":"mt-5-7-1","chapter":5,"verse":7,"sentence":1,"reference":"Matthew 5:7","text":"God blesses those who are merciful, for they will be shown mercy."}]},{"chapter":5,"verse":8,"reference":"Matthew 5:8","text":"God blesses those whose hearts are pure, for they will see God.","sentences":[{"id":"mt-5-8-1","chapter":5,"verse":8,"sentence":1,"reference":"Matthew 5:8","text":"God blesses those whose hearts are pure, for they will see God."}]},{"chapter":5,"verse":9,"reference":"Matthew 5:9","text":"God blesses those who work for peace, for they will be called the children of God.","sentences":[{"id":"mt-5-9-1","chapter":5,"verse":9,"sentence":1,"reference":"Matthew 5:9","text":"God blesses those who work for peace, for they will be called the children of God."}]},{"chapter":5,"verse":10,"reference":"Matthew 5:10","text":"God blesses those who are persecuted for doing right, for the Kingdom of Heaven is theirs.","sentences":[{"id":"mt-5-10-1","chapter":5,"verse":10,"sentence":1,"reference":"Matthew 5:10","text":"God blesses those who are persecuted for doing right, for the Kingdom of Heaven is theirs."}]},{"chapter":5,"verse":11,"reference":"Matthew 5:11","text":"“God blesses you when people mock you and persecute you and lie about you and say all sorts of evil things against you because you are my followers.","sentences":[{"id":"mt-5-11-1","chapter":5,"verse":11,"sentence":1,"reference":"Matthew 5:11","text":"“God blesses you when people mock you and persecute you and lie about you and say all sorts of evil things against you because you are my followers."}]},{"chapter":5,"verse":12,"reference":"Matthew 5:12","text":"Be happy about it! Be very glad! For a great reward awaits you in heaven. And remember, the ancient prophets were persecuted in the same way.","sentences":[{"id":"mt-5-12-1","chapter":5,"verse":12,"sentence":1,"reference":"Matthew 5:12","text":"Be happy about it!"},{"id":"mt-5-12-2","chapter":5,"verse":12,"sentence":2,"reference":"Matthew 5:12","text":"Be very glad!"},{"id":"mt-5-12-3","chapter":5,"verse":12,"sentence":3,"reference":"Matthew 5:12","text":"For a great reward awaits you in heaven."},{"id":"mt-5-12-4","chapter":5,"verse":12,"sentence":4,"reference":"Matthew 5:12","text":"And remember, the ancient prophets were persecuted in the same way."}]},{"chapter":5,"verse":13,"reference":"Matthew 5:13","text":"“You are the salt of the earth. But what good is salt if it has lost its flavor? Can you make it salty again? It will be thrown out and trampled underfoot as worthless.","sentences":[{"id":"mt-5-13-1","chapter":5,"verse":13,"sentence":1,"reference":"Matthew 5:13","text":"“You are the salt of the earth."},{"id":"mt-5-13-2","chapter":5,"verse":13,"sentence":2,"reference":"Matthew 5:13","text":"But what good is salt if it has lost its flavor?"},{"id":"mt-5-13-3","chapter":5,"verse":13,"sentence":3,"reference":"Matthew 5:13","text":"Can you make it salty again?"},{"id":"mt-5-13-4","chapter":5,"verse":13,"sentence":4,"reference":"Matthew 5:13","text":"It will be thrown out and trampled underfoot as worthless."}]},{"chapter":5,"verse":14,"reference":"Matthew 5:14","text":"“You are the light of the world—like a city on a hilltop that cannot be hidden.","sentences":[{"id":"mt-5-14-1","chapter":5,"verse":14,"sentence":1,"reference":"Matthew 5:14","text":"“You are the light of the world—like a city on a hilltop that cannot be hidden."}]},{"chapter":5,"verse":15,"reference":"Matthew 5:15","text":"No one lights a lamp and then puts it under a basket. Instead, a lamp is placed on a stand, where it gives light to everyone in the house.","sentences":[{"id":"mt-5-15-1","chapter":5,"verse":15,"sentence":1,"reference":"Matthew 5:15","text":"No one lights a lamp and then puts it under a basket."},{"id":"mt-5-15-2","chapter":5,"verse":15,"sentence":2,"reference":"Matthew 5:15","text":"Instead, a lamp is placed on a stand, where it gives light to everyone in the house."}]},{"chapter":5,"verse":16,"reference":"Matthew 5:16","text":"In the same way, let your good deeds shine out for all to see, so that everyone will praise your heavenly Father.","sentences":[{"id":"mt-5-16-1","chapter":5,"verse":16,"sentence":1,"reference":"Matthew 5:16","text":"In the same way, let your good deeds shine out for all to see, so that everyone will praise your heavenly Father."}]},{"chapter":5,"verse":17,"reference":"Matthew 5:17","text":"“Don’t misunderstand why I have come. I did not come to abolish the law of Moses or the writings of the prophets. No, I came to accomplish their purpose.","sentences":[{"id":"mt-5-17-1","chapter":5,"verse":17,"sentence":1,"reference":"Matthew 5:17","text":"“Don’t misunderstand why I have come."},{"id":"mt-5-17-2","chapter":5,"verse":17,"sentence":2,"reference":"Matthew 5:17","text":"I did not come to abolish the law of Moses or the writings of the prophets."},{"id":"mt-5-17-3","chapter":5,"verse":17,"sentence":3,"reference":"Matthew 5:17","text":"No, I came to accomplish their purpose."}]},{"chapter":5,"verse":18,"reference":"Matthew 5:18","text":"I tell you the truth, until heaven and earth disappear, not even the smallest detail of God’s law will disappear until its purpose is achieved.","sentences":[{"id":"mt-5-18-1","chapter":5,"verse":18,"sentence":1,"reference":"Matthew 5:18","text":"I tell you the truth, until heaven and earth disappear, not even the smallest detail of God’s law will disappear until its purpose is achieved."}]},{"chapter":5,"verse":19,"reference":"Matthew 5:19","text":"So if you ignore the least commandment and teach others to do the same, you will be called the least in the Kingdom of Heaven. But anyone who obeys God’s laws and teaches them will be called great in the Kingdom of Heaven.","sentences":[{"id":"mt-5-19-1","chapter":5,"verse":19,"sentence":1,"reference":"Matthew 5:19","text":"So if you ignore the least commandment and teach others to do the same, you will be called the least in the Kingdom of Heaven."},{"id":"mt-5-19-2","chapter":5,"verse":19,"sentence":2,"reference":"Matthew 5:19","text":"But anyone who obeys God’s laws and teaches them will be called great in the Kingdom of Heaven."}]},{"chapter":5,"verse":20,"reference":"Matthew 5:20","text":"“But I warn you—unless your righteousness is better than the righteousness of the teachers of religious law and the Pharisees, you will never enter the Kingdom of Heaven!","sentences":[{"id":"mt-5-20-1","chapter":5,"verse":20,"sentence":1,"reference":"Matthew 5:20","text":"“But I warn you—unless your righteousness is better than the righteousness of the teachers of religious law and the Pharisees, you will never enter the Kingdom of Heaven!"}]},{"chapter":5,"verse":21,"reference":"Matthew 5:21","text":"“You have heard that our ancestors were told, ‘You must not murder. If you commit murder, you are subject to judgment.’","sentences":[{"id":"mt-5-21-1","chapter":5,"verse":21,"sentence":1,"reference":"Matthew 5:21","text":"“You have heard that our ancestors were told, ‘You must not murder."},{"id":"mt-5-21-2","chapter":5,"verse":21,"sentence":2,"reference":"Matthew 5:21","text":"If you commit murder, you are subject to judgment.’"}]},{"chapter":5,"verse":22,"reference":"Matthew 5:22","text":"But I say, if you are even angry with someone, you are subject to judgment! If you call someone an idiot, you are in danger of being brought before the court. And if you curse someone, you are in danger of the fires of hell.","sentences":[{"id":"mt-5-22-1","chapter":5,"verse":22,"sentence":1,"reference":"Matthew 5:22","text":"But I say, if you are even angry with someone, you are subject to judgment!"},{"id":"mt-5-22-2","chapter":5,"verse":22,"sentence":2,"reference":"Matthew 5:22","text":"If you call someone an idiot, you are in danger of being brought before the court."},{"id":"mt-5-22-3","chapter":5,"verse":22,"sentence":3,"reference":"Matthew 5:22","text":"And if you curse someone, you are in danger of the fires of hell."}]},{"chapter":5,"verse":23,"reference":"Matthew 5:23","text":"“So if you are presenting a sacrifice at the altar in the Temple and you suddenly remember that someone has something against you,","sentences":[{"id":"mt-5-23-1","chapter":5,"verse":23,"sentence":1,"reference":"Matthew 5:23","text":"“So if you are presenting a sacrifice at the altar in the Temple and you suddenly remember that someone has something against you,"}]},{"chapter":5,"verse":24,"reference":"Matthew 5:24","text":"leave your sacrifice there at the altar. Go and be reconciled to that person. Then come and offer your sacrifice to God.","sentences":[{"id":"mt-5-24-1","chapter":5,"verse":24,"sentence":1,"reference":"Matthew 5:24","text":"leave your sacrifice there at the altar."},{"id":"mt-5-24-2","chapter":5,"verse":24,"sentence":2,"reference":"Matthew 5:24","text":"Go and be reconciled to that person."},{"id":"mt-5-24-3","chapter":5,"verse":24,"sentence":3,"reference":"Matthew 5:24","text":"Then come and offer your sacrifice to God."}]},{"chapter":5,"verse":25,"reference":"Matthew 5:25","text":"“When you are on the way to court with your adversary, settle your differences quickly. Otherwise, your accuser may hand you over to the judge, who will hand you over to an officer, and you will be thrown into prison.","sentences":[{"id":"mt-5-25-1","chapter":5,"verse":25,"sentence":1,"reference":"Matthew 5:25","text":"“When you are on the way to court with your adversary, settle your differences quickly."},{"id":"mt-5-25-2","chapter":5,"verse":25,"sentence":2,"reference":"Matthew 5:25","text":"Otherwise, your accuser may hand you over to the judge, who will hand you over to an officer, and you will be thrown into prison."}]},{"chapter":5,"verse":26,"reference":"Matthew 5:26","text":"And if that happens, you surely won’t be free again until you have paid the last penny.","sentences":[{"id":"mt-5-26-1","chapter":5,"verse":26,"sentence":1,"reference":"Matthew 5:26","text":"And if that happens, you surely won’t be free again until you have paid the last penny."}]},{"chapter":5,"verse":27,"reference":"Matthew 5:27","text":"“You have heard the commandment that says, ‘You must not commit adultery.’","sentences":[{"id":"mt-5-27-1","chapter":5,"verse":27,"sentence":1,"reference":"Matthew 5:27","text":"“You have heard the commandment that says, ‘You must not commit adultery.’"}]},{"chapter":5,"verse":28,"reference":"Matthew 5:28","text":"But I say, anyone who even looks at a woman with lust has already committed adultery with her in his heart.","sentences":[{"id":"mt-5-28-1","chapter":5,"verse":28,"sentence":1,"reference":"Matthew 5:28","text":"But I say, anyone who even looks at a woman with lust has already committed adultery with her in his heart."}]},{"chapter":5,"verse":29,"reference":"Matthew 5:29","text":"So if your eye—even your good eye—causes you to lust, gouge it out and throw it away. It is better for you to lose one part of your body than for your whole body to be thrown into hell.","sentences":[{"id":"mt-5-29-1","chapter":5,"verse":29,"sentence":1,"reference":"Matthew 5:29","text":"So if your eye—even your good eye—causes you to lust, gouge it out and throw it away."},{"id":"mt-5-29-2","chapter":5,"verse":29,"sentence":2,"reference":"Matthew 5:29","text":"It is better for you to lose one part of your body than for your whole body to be thrown into hell."}]},{"chapter":5,"verse":30,"reference":"Matthew 5:30","text":"And if your hand—even your stronger hand—causes you to sin, cut it off and throw it away. It is better for you to lose one part of your body than for your whole body to be thrown into hell.","sentences":[{"id":"mt-5-30-1","chapter":5,"verse":30,"sentence":1,"reference":"Matthew 5:30","text":"And if your hand—even your stronger hand—causes you to sin, cut it off and throw it away."},{"id":"mt-5-30-2","chapter":5,"verse":30,"sentence":2,"reference":"Matthew 5:30","text":"It is better for you to lose one part of your body than for your whole body to be thrown into hell."}]},{"chapter":5,"verse":31,"reference":"Matthew 5:31","text":"“You have heard the law that says, ‘A man can divorce his wife by merely giving her a written notice of divorce.’","sentences":[{"id":"mt-5-31-1","chapter":5,"verse":31,"sentence":1,"reference":"Matthew 5:31","text":"“You have heard the law that says, ‘A man can divorce his wife by merely giving her a written notice of divorce.’"}]},{"chapter":5,"verse":32,"reference":"Matthew 5:32","text":"But I say that a man who divorces his wife, unless she has been unfaithful, causes her to commit adultery. And anyone who marries a divorced woman also commits adultery.","sentences":[{"id":"mt-5-32-1","chapter":5,"verse":32,"sentence":1,"reference":"Matthew 5:32","text":"But I say that a man who divorces his wife, unless she has been unfaithful, causes her to commit adultery."},{"id":"mt-5-32-2","chapter":5,"verse":32,"sentence":2,"reference":"Matthew 5:32","text":"And anyone who marries a divorced woman also commits adultery."}]},{"chapter":5,"verse":33,"reference":"Matthew 5:33","text":"“You have also heard that our ancestors were told, ‘You must not break your vows; you must carry out the vows you make to the Lord.’","sentences":[{"id":"mt-5-33-1","chapter":5,"verse":33,"sentence":1,"reference":"Matthew 5:33","text":"“You have also heard that our ancestors were told, ‘You must not break your vows; you must carry out the vows you make to the Lord.’"}]},{"chapter":5,"verse":34,"reference":"Matthew 5:34","text":"But I say, do not make any vows! Do not say, ‘By heaven!’ because heaven is God’s throne.","sentences":[{"id":"mt-5-34-1","chapter":5,"verse":34,"sentence":1,"reference":"Matthew 5:34","text":"But I say, do not make any vows!"},{"id":"mt-5-34-2","chapter":5,"verse":34,"sentence":2,"reference":"Matthew 5:34","text":"Do not say, ‘By heaven!’"},{"id":"mt-5-34-3","chapter":5,"verse":34,"sentence":3,"reference":"Matthew 5:34","text":"because heaven is God’s throne."}]},{"chapter":5,"verse":35,"reference":"Matthew 5:35","text":"And do not say, ‘By the earth!’ because the earth is his footstool. And do not say, ‘By Jerusalem!’ for Jerusalem is the city of the great King.","sentences":[{"id":"mt-5-35-1","chapter":5,"verse":35,"sentence":1,"reference":"Matthew 5:35","text":"And do not say, ‘By the earth!’"},{"id":"mt-5-35-2","chapter":5,"verse":35,"sentence":2,"reference":"Matthew 5:35","text":"because the earth is his footstool."},{"id":"mt-5-35-3","chapter":5,"verse":35,"sentence":3,"reference":"Matthew 5:35","text":"And do not say, ‘By Jerusalem!’"},{"id":"mt-5-35-4","chapter":5,"verse":35,"sentence":4,"reference":"Matthew 5:35","text":"for Jerusalem is the city of the great King."}]},{"chapter":5,"verse":36,"reference":"Matthew 5:36","text":"Do not even say, ‘By my head!’ for you can’t turn one hair white or black.","sentences":[{"id":"mt-5-36-1","chapter":5,"verse":36,"sentence":1,"reference":"Matthew 5:36","text":"Do not even say, ‘By my head!’"},{"id":"mt-5-36-2","chapter":5,"verse":36,"sentence":2,"reference":"Matthew 5:36","text":"for you can’t turn one hair white or black."}]},{"chapter":5,"verse":37,"reference":"Matthew 5:37","text":"Just say a simple, ‘Yes, I will,’ or ‘No, I won’t.’ Anything beyond this is from the evil one.","sentences":[{"id":"mt-5-37-1","chapter":5,"verse":37,"sentence":1,"reference":"Matthew 5:37","text":"Just say a simple, ‘Yes, I will,’ or ‘No, I won’t.’"},{"id":"mt-5-37-2","chapter":5,"verse":37,"sentence":2,"reference":"Matthew 5:37","text":"Anything beyond this is from the evil one."}]},{"chapter":5,"verse":38,"reference":"Matthew 5:38","text":"“You have heard the law that says the punishment must match the injury: ‘An eye for an eye, and a tooth for a tooth.’","sentences":[{"id":"mt-5-38-1","chapter":5,"verse":38,"sentence":1,"reference":"Matthew 5:38","text":"“You have heard the law that says the punishment must match the injury: ‘An eye for an eye, and a tooth for a tooth.’"}]},{"chapter":5,"verse":39,"reference":"Matthew 5:39","text":"But I say, do not resist an evil person! If someone slaps you on the right cheek, offer the other cheek also.","sentences":[{"id":"mt-5-39-1","chapter":5,"verse":39,"sentence":1,"reference":"Matthew 5:39","text":"But I say, do not resist an evil person!"},{"id":"mt-5-39-2","chapter":5,"verse":39,"sentence":2,"reference":"Matthew 5:39","text":"If someone slaps you on the right cheek, offer the other cheek also."}]},{"chapter":5,"verse":40,"reference":"Matthew 5:40","text":"If you are sued in court and your shirt is taken from you, give your coat, too.","sentences":[{"id":"mt-5-40-1","chapter":5,"verse":40,"sentence":1,"reference":"Matthew 5:40","text":"If you are sued in court and your shirt is taken from you, give your coat, too."}]},{"chapter":5,"verse":41,"reference":"Matthew 5:41","text":"If a soldier demands that you carry his gear for a mile, carry it two miles.","sentences":[{"id":"mt-5-41-1","chapter":5,"verse":41,"sentence":1,"reference":"Matthew 5:41","text":"If a soldier demands that you carry his gear for a mile, carry it two miles."}]},{"chapter":5,"verse":42,"reference":"Matthew 5:42","text":"Give to those who ask, and don’t turn away from those who want to borrow.","sentences":[{"id":"mt-5-42-1","chapter":5,"verse":42,"sentence":1,"reference":"Matthew 5:42","text":"Give to those who ask, and don’t turn away from those who want to borrow."}]},{"chapter":5,"verse":43,"reference":"Matthew 5:43","text":"“You have heard the law that says, ‘Love your neighbor’ and hate your enemy.","sentences":[{"id":"mt-5-43-1","chapter":5,"verse":43,"sentence":1,"reference":"Matthew 5:43","text":"“You have heard the law that says, ‘Love your neighbor’ and hate your enemy."}]},{"chapter":5,"verse":44,"reference":"Matthew 5:44","text":"But I say, love your enemies! Pray for those who persecute you!","sentences":[{"id":"mt-5-44-1","chapter":5,"verse":44,"sentence":1,"reference":"Matthew 5:44","text":"But I say, love your enemies!"},{"id":"mt-5-44-2","chapter":5,"verse":44,"sentence":2,"reference":"Matthew 5:44","text":"Pray for those who persecute you!"}]},{"chapter":5,"verse":45,"reference":"Matthew 5:45","text":"In that way, you will be acting as true children of your Father in heaven. For he gives his sunlight to both the evil and the good, and he sends rain on the just and the unjust alike.","sentences":[{"id":"mt-5-45-1","chapter":5,"verse":45,"sentence":1,"reference":"Matthew 5:45","text":"In that way, you will be acting as true children of your Father in heaven."},{"id":"mt-5-45-2","chapter":5,"verse":45,"sentence":2,"reference":"Matthew 5:45","text":"For he gives his sunlight to both the evil and the good, and he sends rain on the just and the unjust alike."}]},{"chapter":5,"verse":46,"reference":"Matthew 5:46","text":"If you love only those who love you, what reward is there for that? Even corrupt tax collectors do that much.","sentences":[{"id":"mt-5-46-1","chapter":5,"verse":46,"sentence":1,"reference":"Matthew 5:46","text":"If you love only those who love you, what reward is there for that?"},{"id":"mt-5-46-2","chapter":5,"verse":46,"sentence":2,"reference":"Matthew 5:46","text":"Even corrupt tax collectors do that much."}]},{"chapter":5,"verse":47,"reference":"Matthew 5:47","text":"If you are kind only to your friends, how are you different from anyone else? Even pagans do that.","sentences":[{"id":"mt-5-47-1","chapter":5,"verse":47,"sentence":1,"reference":"Matthew 5:47","text":"If you are kind only to your friends, how are you different from anyone else?"},{"id":"mt-5-47-2","chapter":5,"verse":47,"sentence":2,"reference":"Matthew 5:47","text":"Even pagans do that."}]},{"chapter":5,"verse":48,"reference":"Matthew 5:48","text":"But you are to be perfect, even as your Father in heaven is perfect.","sentences":[{"id":"mt-5-48-1","chapter":5,"verse":48,"sentence":1,"reference":"Matthew 5:48","text":"But you are to be perfect, even as your Father in heaven is perfect."}]}]},{"chapter":6,"verses":[{"chapter":6,"verse":1,"reference":"Matthew 6:1","text":"“Watch out! Don’t do your good deeds publicly, to be admired by others, for you will lose the reward from your Father in heaven.","sentences":[{"id":"mt-6-1-1","chapter":6,"verse":1,"sentence":1,"reference":"Matthew 6:1","text":"“Watch out!"},{"id":"mt-6-1-2","chapter":6,"verse":1,"sentence":2,"reference":"Matthew 6:1","text":"Don’t do your good deeds publicly, to be admired by others, for you will lose the reward from your Father in heaven."}]},{"chapter":6,"verse":2,"reference":"Matthew 6:2","text":"When you give to someone in need, don’t do as the hypocrites do—blowing trumpets in the synagogues and streets to call attention to their acts of charity! I tell you the truth, they have received all the reward they will ever get.","sentences":[{"id":"mt-6-2-1","chapter":6,"verse":2,"sentence":1,"reference":"Matthew 6:2","text":"When you give to someone in need, don’t do as the hypocrites do—blowing trumpets in the synagogues and streets to call attention to their acts of charity!"},{"id":"mt-6-2-2","chapter":6,"verse":2,"sentence":2,"reference":"Matthew 6:2","text":"I tell you the truth, they have received all the reward they will ever get."}]},{"chapter":6,"verse":3,"reference":"Matthew 6:3","text":"But when you give to someone in need, don’t let your left hand know what your right hand is doing.","sentences":[{"id":"mt-6-3-1","chapter":6,"verse":3,"sentence":1,"reference":"Matthew 6:3","text":"But when you give to someone in need, don’t let your left hand know what your right hand is doing."}]},{"chapter":6,"verse":4,"reference":"Matthew 6:4","text":"Give your gifts in private, and your Father, who sees everything, will reward you.","sentences":[{"id":"mt-6-4-1","chapter":6,"verse":4,"sentence":1,"reference":"Matthew 6:4","text":"Give your gifts in private, and your Father, who sees everything, will reward you."}]},{"chapter":6,"verse":5,"reference":"Matthew 6:5","text":"“When you pray, don’t be like the hypocrites who love to pray publicly on street corners and in the synagogues where everyone can see them. I tell you the truth, that is all the reward they will ever get.","sentences":[{"id":"mt-6-5-1","chapter":6,"verse":5,"sentence":1,"reference":"Matthew 6:5","text":"“When you pray, don’t be like the hypocrites who love to pray publicly on street corners and in the synagogues where everyone can see them."},{"id":"mt-6-5-2","chapter":6,"verse":5,"sentence":2,"reference":"Matthew 6:5","text":"I tell you the truth, that is all the reward they will ever get."}]},{"chapter":6,"verse":6,"reference":"Matthew 6:6","text":"But when you pray, go away by yourself, shut the door behind you, and pray to your Father in private. Then your Father, who sees everything, will reward you.","sentences":[{"id":"mt-6-6-1","chapter":6,"verse":6,"sentence":1,"reference":"Matthew 6:6","text":"But when you pray, go away by yourself, shut the door behind you, and pray to your Father in private."},{"id":"mt-6-6-2","chapter":6,"verse":6,"sentence":2,"reference":"Matthew 6:6","text":"Then your Father, who sees everything, will reward you."}]},{"chapter":6,"verse":7,"reference":"Matthew 6:7","text":"“When you pray, don’t babble on and on as the Gentiles do. They think their prayers are answered merely by repeating their words again and again.","sentences":[{"id":"mt-6-7-1","chapter":6,"verse":7,"sentence":1,"reference":"Matthew 6:7","text":"“When you pray, don’t babble on and on as the Gentiles do."},{"id":"mt-6-7-2","chapter":6,"verse":7,"sentence":2,"reference":"Matthew 6:7","text":"They think their prayers are answered merely by repeating their words again and again."}]},{"chapter":6,"verse":8,"reference":"Matthew 6:8","text":"Don’t be like them, for your Father knows exactly what you need even before you ask him!","sentences":[{"id":"mt-6-8-1","chapter":6,"verse":8,"sentence":1,"reference":"Matthew 6:8","text":"Don’t be like them, for your Father knows exactly what you need even before you ask him!"}]},{"chapter":6,"verse":9,"reference":"Matthew 6:9","text":"Pray like this: Our Father in heaven, may your name be kept holy.","sentences":[{"id":"mt-6-9-1","chapter":6,"verse":9,"sentence":1,"reference":"Matthew 6:9","text":"Pray like this: Our Father in heaven, may your name be kept holy."}]},{"chapter":6,"verse":10,"reference":"Matthew 6:10","text":"May your Kingdom come soon. May your will be done on earth, as it is in heaven.","sentences":[{"id":"mt-6-10-1","chapter":6,"verse":10,"sentence":1,"reference":"Matthew 6:10","text":"May your Kingdom come soon."},{"id":"mt-6-10-2","chapter":6,"verse":10,"sentence":2,"reference":"Matthew 6:10","text":"May your will be done on earth, as it is in heaven."}]},{"chapter":6,"verse":11,"reference":"Matthew 6:11","text":"Give us today the food we need,","sentences":[{"id":"mt-6-11-1","chapter":6,"verse":11,"sentence":1,"reference":"Matthew 6:11","text":"Give us today the food we need,"}]},{"chapter":6,"verse":12,"reference":"Matthew 6:12","text":"and forgive us our sins, as we have forgiven those who sin against us.","sentences":[{"id":"mt-6-12-1","chapter":6,"verse":12,"sentence":1,"reference":"Matthew 6:12","text":"and forgive us our sins, as we have forgiven those who sin against us."}]},{"chapter":6,"verse":13,"reference":"Matthew 6:13","text":"And don’t let us yield to temptation, but rescue us from the evil one.","sentences":[{"id":"mt-6-13-1","chapter":6,"verse":13,"sentence":1,"reference":"Matthew 6:13","text":"And don’t let us yield to temptation, but rescue us from the evil one."}]},{"chapter":6,"verse":14,"reference":"Matthew 6:14","text":"“If you forgive those who sin against you, your heavenly Father will forgive you.","sentences":[{"id":"mt-6-14-1","chapter":6,"verse":14,"sentence":1,"reference":"Matthew 6:14","text":"“If you forgive those who sin against you, your heavenly Father will forgive you."}]},{"chapter":6,"verse":15,"reference":"Matthew 6:15","text":"But if you refuse to forgive others, your Father will not forgive your sins.","sentences":[{"id":"mt-6-15-1","chapter":6,"verse":15,"sentence":1,"reference":"Matthew 6:15","text":"But if you refuse to forgive others, your Father will not forgive your sins."}]},{"chapter":6,"verse":16,"reference":"Matthew 6:16","text":"“And when you fast, don’t make it obvious, as the hypocrites do, for they try to look miserable and disheveled so people will admire them for their fasting. I tell you the truth, that is the only reward they will ever get.","sentences":[{"id":"mt-6-16-1","chapter":6,"verse":16,"sentence":1,"reference":"Matthew 6:16","text":"“And when you fast, don’t make it obvious, as the hypocrites do, for they try to look miserable and disheveled so people will admire them for their fasting."},{"id":"mt-6-16-2","chapter":6,"verse":16,"sentence":2,"reference":"Matthew 6:16","text":"I tell you the truth, that is the only reward they will ever get."}]},{"chapter":6,"verse":17,"reference":"Matthew 6:17","text":"But when you fast, comb your hair and wash your face.","sentences":[{"id":"mt-6-17-1","chapter":6,"verse":17,"sentence":1,"reference":"Matthew 6:17","text":"But when you fast, comb your hair and wash your face."}]},{"chapter":6,"verse":18,"reference":"Matthew 6:18","text":"Then no one will notice that you are fasting, except your Father, who knows what you do in private. And your Father, who sees everything, will reward you.","sentences":[{"id":"mt-6-18-1","chapter":6,"verse":18,"sentence":1,"reference":"Matthew 6:18","text":"Then no one will notice that you are fasting, except your Father, who knows what you do in private."},{"id":"mt-6-18-2","chapter":6,"verse":18,"sentence":2,"reference":"Matthew 6:18","text":"And your Father, who sees everything, will reward you."}]},{"chapter":6,"verse":19,"reference":"Matthew 6:19","text":"“Don’t store up treasures here on earth, where moths eat them and rust destroys them, and where thieves break in and steal.","sentences":[{"id":"mt-6-19-1","chapter":6,"verse":19,"sentence":1,"reference":"Matthew 6:19","text":"“Don’t store up treasures here on earth, where moths eat them and rust destroys them, and where thieves break in and steal."}]},{"chapter":6,"verse":20,"reference":"Matthew 6:20","text":"Store your treasures in heaven, where moths and rust cannot destroy, and thieves do not break in and steal.","sentences":[{"id":"mt-6-20-1","chapter":6,"verse":20,"sentence":1,"reference":"Matthew 6:20","text":"Store your treasures in heaven, where moths and rust cannot destroy, and thieves do not break in and steal."}]},{"chapter":6,"verse":21,"reference":"Matthew 6:21","text":"Wherever your treasure is, there the desires of your heart will also be.","sentences":[{"id":"mt-6-21-1","chapter":6,"verse":21,"sentence":1,"reference":"Matthew 6:21","text":"Wherever your treasure is, there the desires of your heart will also be."}]},{"chapter":6,"verse":22,"reference":"Matthew 6:22","text":"“Your eye is like a lamp that provides light for your body. When your eye is healthy, your whole body is filled with light.","sentences":[{"id":"mt-6-22-1","chapter":6,"verse":22,"sentence":1,"reference":"Matthew 6:22","text":"“Your eye is like a lamp that provides light for your body."},{"id":"mt-6-22-2","chapter":6,"verse":22,"sentence":2,"reference":"Matthew 6:22","text":"When your eye is healthy, your whole body is filled with light."}]},{"chapter":6,"verse":23,"reference":"Matthew 6:23","text":"But when your eye is unhealthy, your whole body is filled with darkness. And if the light you think you have is actually darkness, how deep that darkness is!","sentences":[{"id":"mt-6-23-1","chapter":6,"verse":23,"sentence":1,"reference":"Matthew 6:23","text":"But when your eye is unhealthy, your whole body is filled with darkness."},{"id":"mt-6-23-2","chapter":6,"verse":23,"sentence":2,"reference":"Matthew 6:23","text":"And if the light you think you have is actually darkness, how deep that darkness is!"}]},{"chapter":6,"verse":24,"reference":"Matthew 6:24","text":"“No one can serve two masters. For you will hate one and love the other; you will be devoted to one and despise the other. You cannot serve God and be enslaved to money.","sentences":[{"id":"mt-6-24-1","chapter":6,"verse":24,"sentence":1,"reference":"Matthew 6:24","text":"“No one can serve two masters."},{"id":"mt-6-24-2","chapter":6,"verse":24,"sentence":2,"reference":"Matthew 6:24","text":"For you will hate one and love the other; you will be devoted to one and despise the other."},{"id":"mt-6-24-3","chapter":6,"verse":24,"sentence":3,"reference":"Matthew 6:24","text":"You cannot serve God and be enslaved to money."}]},{"chapter":6,"verse":25,"reference":"Matthew 6:25","text":"“That is why I tell you not to worry about everyday life—whether you have enough food and drink, or enough clothes to wear. Isn’t life more than food, and your body more than clothing?","sentences":[{"id":"mt-6-25-1","chapter":6,"verse":25,"sentence":1,"reference":"Matthew 6:25","text":"“That is why I tell you not to worry about everyday life—whether you have enough food and drink, or enough clothes to wear."},{"id":"mt-6-25-2","chapter":6,"verse":25,"sentence":2,"reference":"Matthew 6:25","text":"Isn’t life more than food, and your body more than clothing?"}]},{"chapter":6,"verse":26,"reference":"Matthew 6:26","text":"Look at the birds. They don’t plant or harvest or store food in barns, for your heavenly Father feeds them. And aren’t you far more valuable to him than they are?","sentences":[{"id":"mt-6-26-1","chapter":6,"verse":26,"sentence":1,"reference":"Matthew 6:26","text":"Look at the birds."},{"id":"mt-6-26-2","chapter":6,"verse":26,"sentence":2,"reference":"Matthew 6:26","text":"They don’t plant or harvest or store food in barns, for your heavenly Father feeds them."},{"id":"mt-6-26-3","chapter":6,"verse":26,"sentence":3,"reference":"Matthew 6:26","text":"And aren’t you far more valuable to him than they are?"}]},{"chapter":6,"verse":27,"reference":"Matthew 6:27","text":"Can all your worries add a single moment to your life?","sentences":[{"id":"mt-6-27-1","chapter":6,"verse":27,"sentence":1,"reference":"Matthew 6:27","text":"Can all your worries add a single moment to your life?"}]},{"chapter":6,"verse":28,"reference":"Matthew 6:28","text":"“And why worry about your clothing? Look at the lilies of the field and how they grow. They don’t work or make their clothing,","sentences":[{"id":"mt-6-28-1","chapter":6,"verse":28,"sentence":1,"reference":"Matthew 6:28","text":"“And why worry about your clothing?"},{"id":"mt-6-28-2","chapter":6,"verse":28,"sentence":2,"reference":"Matthew 6:28","text":"Look at the lilies of the field and how they grow."},{"id":"mt-6-28-3","chapter":6,"verse":28,"sentence":3,"reference":"Matthew 6:28","text":"They don’t work or make their clothing,"}]},{"chapter":6,"verse":29,"reference":"Matthew 6:29","text":"yet Solomon in all his glory was not dressed as beautifully as they are.","sentences":[{"id":"mt-6-29-1","chapter":6,"verse":29,"sentence":1,"reference":"Matthew 6:29","text":"yet Solomon in all his glory was not dressed as beautifully as they are."}]},{"chapter":6,"verse":30,"reference":"Matthew 6:30","text":"And if God cares so wonderfully for wildflowers that are here today and thrown into the fire tomorrow, he will certainly care for you. Why do you have so little faith?","sentences":[{"id":"mt-6-30-1","chapter":6,"verse":30,"sentence":1,"reference":"Matthew 6:30","text":"And if God cares so wonderfully for wildflowers that are here today and thrown into the fire tomorrow, he will certainly care for you."},{"id":"mt-6-30-2","chapter":6,"verse":30,"sentence":2,"reference":"Matthew 6:30","text":"Why do you have so little faith?"}]},{"chapter":6,"verse":31,"reference":"Matthew 6:31","text":"“So don’t worry about these things, saying, ‘What will we eat? What will we drink? What will we wear?’","sentences":[{"id":"mt-6-31-1","chapter":6,"verse":31,"sentence":1,"reference":"Matthew 6:31","text":"“So don’t worry about these things, saying, ‘What will we eat?"},{"id":"mt-6-31-2","chapter":6,"verse":31,"sentence":2,"reference":"Matthew 6:31","text":"What will we drink?"},{"id":"mt-6-31-3","chapter":6,"verse":31,"sentence":3,"reference":"Matthew 6:31","text":"What will we wear?’"}]},{"chapter":6,"verse":32,"reference":"Matthew 6:32","text":"These things dominate the thoughts of unbelievers, but your heavenly Father already knows all your needs.","sentences":[{"id":"mt-6-32-1","chapter":6,"verse":32,"sentence":1,"reference":"Matthew 6:32","text":"These things dominate the thoughts of unbelievers, but your heavenly Father already knows all your needs."}]},{"chapter":6,"verse":33,"reference":"Matthew 6:33","text":"Seek the Kingdom of God above all else, and live righteously, and he will give you everything you need.","sentences":[{"id":"mt-6-33-1","chapter":6,"verse":33,"sentence":1,"reference":"Matthew 6:33","text":"Seek the Kingdom of God above all else, and live righteously, and he will give you everything you need."}]},{"chapter":6,"verse":34,"reference":"Matthew 6:34","text":"“So don’t worry about tomorrow, for tomorrow will bring its own worries. Today’s trouble is enough for today.","sentences":[{"id":"mt-6-34-1","chapter":6,"verse":34,"sentence":1,"reference":"Matthew 6:34","text":"“So don’t worry about tomorrow, for tomorrow will bring its own worries."},{"id":"mt-6-34-2","chapter":6,"verse":34,"sentence":2,"reference":"Matthew 6:34","text":"Today’s trouble is enough for today."}]}]},{"chapter":7,"verses":[{"chapter":7,"verse":1,"reference":"Matthew 7:1","text":"“Do not judge others, and you will not be judged.","sentences":[{"id":"mt-7-1-1","chapter":7,"verse":1,"sentence":1,"reference":"Matthew 7:1","text":"“Do not judge others, and you will not be judged."}]},{"chapter":7,"verse":2,"reference":"Matthew 7:2","text":"For you will be treated as you treat others. The standard you use in judging is the standard by which you will be judged.","sentences":[{"id":"mt-7-2-1","chapter":7,"verse":2,"sentence":1,"reference":"Matthew 7:2","text":"For you will be treated as you treat others."},{"id":"mt-7-2-2","chapter":7,"verse":2,"sentence":2,"reference":"Matthew 7:2","text":"The standard you use in judging is the standard by which you will be judged."}]},{"chapter":7,"verse":3,"reference":"Matthew 7:3","text":"“And why worry about a speck in your friend’s eye when you have a log in your own?","sentences":[{"id":"mt-7-3-1","chapter":7,"verse":3,"sentence":1,"reference":"Matthew 7:3","text":"“And why worry about a speck in your friend’s eye when you have a log in your own?"}]},{"chapter":7,"verse":4,"reference":"Matthew 7:4","text":"How can you think of saying to your friend, ‘Let me help you get rid of that speck in your eye,’ when you can’t see past the log in your own eye?","sentences":[{"id":"mt-7-4-1","chapter":7,"verse":4,"sentence":1,"reference":"Matthew 7:4","text":"How can you think of saying to your friend, ‘Let me help you get rid of that speck in your eye,’ when you can’t see past the log in your own eye?"}]},{"chapter":7,"verse":5,"reference":"Matthew 7:5","text":"Hypocrite! First get rid of the log in your own eye; then you will see well enough to deal with the speck in your friend’s eye.","sentences":[{"id":"mt-7-5-1","chapter":7,"verse":5,"sentence":1,"reference":"Matthew 7:5","text":"Hypocrite!"},{"id":"mt-7-5-2","chapter":7,"verse":5,"sentence":2,"reference":"Matthew 7:5","text":"First get rid of the log in your own eye; then you will see well enough to deal with the speck in your friend’s eye."}]},{"chapter":7,"verse":6,"reference":"Matthew 7:6","text":"“Don’t waste what is holy on people who are unholy. Don’t throw your pearls to pigs! They will trample the pearls, then turn and attack you.","sentences":[{"id":"mt-7-6-1","chapter":7,"verse":6,"sentence":1,"reference":"Matthew 7:6","text":"“Don’t waste what is holy on people who are unholy."},{"id":"mt-7-6-2","chapter":7,"verse":6,"sentence":2,"reference":"Matthew 7:6","text":"Don’t throw your pearls to pigs!"},{"id":"mt-7-6-3","chapter":7,"verse":6,"sentence":3,"reference":"Matthew 7:6","text":"They will trample the pearls, then turn and attack you."}]},{"chapter":7,"verse":7,"reference":"Matthew 7:7","text":"“Keep on asking, and you will receive what you ask for. Keep on seeking, and you will find. Keep on knocking, and the door will be opened to you.","sentences":[{"id":"mt-7-7-1","chapter":7,"verse":7,"sentence":1,"reference":"Matthew 7:7","text":"“Keep on asking, and you will receive what you ask for."},{"id":"mt-7-7-2","chapter":7,"verse":7,"sentence":2,"reference":"Matthew 7:7","text":"Keep on seeking, and you will find."},{"id":"mt-7-7-3","chapter":7,"verse":7,"sentence":3,"reference":"Matthew 7:7","text":"Keep on knocking, and the door will be opened to you."}]},{"chapter":7,"verse":8,"reference":"Matthew 7:8","text":"For everyone who asks, receives. Everyone who seeks, finds. And to everyone who knocks, the door will be opened.","sentences":[{"id":"mt-7-8-1","chapter":7,"verse":8,"sentence":1,"reference":"Matthew 7:8","text":"For everyone who asks, receives."},{"id":"mt-7-8-2","chapter":7,"verse":8,"sentence":2,"reference":"Matthew 7:8","text":"Everyone who seeks, finds."},{"id":"mt-7-8-3","chapter":7,"verse":8,"sentence":3,"reference":"Matthew 7:8","text":"And to everyone who knocks, the door will be opened."}]},{"chapter":7,"verse":9,"reference":"Matthew 7:9","text":"“You parents—if your children ask for a loaf of bread, do you give them a stone instead?","sentences":[{"id":"mt-7-9-1","chapter":7,"verse":9,"sentence":1,"reference":"Matthew 7:9","text":"“You parents—if your children ask for a loaf of bread, do you give them a stone instead?"}]},{"chapter":7,"verse":10,"reference":"Matthew 7:10","text":"Or if they ask for a fish, do you give them a snake? Of course not!","sentences":[{"id":"mt-7-10-1","chapter":7,"verse":10,"sentence":1,"reference":"Matthew 7:10","text":"Or if they ask for a fish, do you give them a snake?"},{"id":"mt-7-10-2","chapter":7,"verse":10,"sentence":2,"reference":"Matthew 7:10","text":"Of course not!"}]},{"chapter":7,"verse":11,"reference":"Matthew 7:11","text":"So if you sinful people know how to give good gifts to your children, how much more will your heavenly Father give good gifts to those who ask him.","sentences":[{"id":"mt-7-11-1","chapter":7,"verse":11,"sentence":1,"reference":"Matthew 7:11","text":"So if you sinful people know how to give good gifts to your children, how much more will your heavenly Father give good gifts to those who ask him."}]},{"chapter":7,"verse":12,"reference":"Matthew 7:12","text":"“Do to others whatever you would like them to do to you. This is the essence of all that is taught in the law and the prophets.","sentences":[{"id":"mt-7-12-1","chapter":7,"verse":12,"sentence":1,"reference":"Matthew 7:12","text":"“Do to others whatever you would like them to do to you."},{"id":"mt-7-12-2","chapter":7,"verse":12,"sentence":2,"reference":"Matthew 7:12","text":"This is the essence of all that is taught in the law and the prophets."}]},{"chapter":7,"verse":13,"reference":"Matthew 7:13","text":"“You can enter God’s Kingdom only through the narrow gate. The highway to hell is broad, and its gate is wide for the many who choose that way.","sentences":[{"id":"mt-7-13-1","chapter":7,"verse":13,"sentence":1,"reference":"Matthew 7:13","text":"“You can enter God’s Kingdom only through the narrow gate."},{"id":"mt-7-13-2","chapter":7,"verse":13,"sentence":2,"reference":"Matthew 7:13","text":"The highway to hell is broad, and its gate is wide for the many who choose that way."}]},{"chapter":7,"verse":14,"reference":"Matthew 7:14","text":"But the gateway to life is very narrow and the road is difficult, and only a few ever find it.","sentences":[{"id":"mt-7-14-1","chapter":7,"verse":14,"sentence":1,"reference":"Matthew 7:14","text":"But the gateway to life is very narrow and the road is difficult, and only a few ever find it."}]},{"chapter":7,"verse":15,"reference":"Matthew 7:15","text":"“Beware of false prophets who come disguised as harmless sheep but are really vicious wolves.","sentences":[{"id":"mt-7-15-1","chapter":7,"verse":15,"sentence":1,"reference":"Matthew 7:15","text":"“Beware of false prophets who come disguised as harmless sheep but are really vicious wolves."}]},{"chapter":7,"verse":16,"reference":"Matthew 7:16","text":"You can identify them by their fruit, that is, by the way they act. Can you pick grapes from thornbushes, or figs from thistles?","sentences":[{"id":"mt-7-16-1","chapter":7,"verse":16,"sentence":1,"reference":"Matthew 7:16","text":"You can identify them by their fruit, that is, by the way they act."},{"id":"mt-7-16-2","chapter":7,"verse":16,"sentence":2,"reference":"Matthew 7:16","text":"Can you pick grapes from thornbushes, or figs from thistles?"}]},{"chapter":7,"verse":17,"reference":"Matthew 7:17","text":"A good tree produces good fruit, and a bad tree produces bad fruit.","sentences":[{"id":"mt-7-17-1","chapter":7,"verse":17,"sentence":1,"reference":"Matthew 7:17","text":"A good tree produces good fruit, and a bad tree produces bad fruit."}]},{"chapter":7,"verse":18,"reference":"Matthew 7:18","text":"A good tree can’t produce bad fruit, and a bad tree can’t produce good fruit.","sentences":[{"id":"mt-7-18-1","chapter":7,"verse":18,"sentence":1,"reference":"Matthew 7:18","text":"A good tree can’t produce bad fruit, and a bad tree can’t produce good fruit."}]},{"chapter":7,"verse":19,"reference":"Matthew 7:19","text":"So every tree that does not produce good fruit is chopped down and thrown into the fire.","sentences":[{"id":"mt-7-19-1","chapter":7,"verse":19,"sentence":1,"reference":"Matthew 7:19","text":"So every tree that does not produce good fruit is chopped down and thrown into the fire."}]},{"chapter":7,"verse":20,"reference":"Matthew 7:20","text":"Yes, just as you can identify a tree by its fruit, so you can identify people by their actions.","sentences":[{"id":"mt-7-20-1","chapter":7,"verse":20,"sentence":1,"reference":"Matthew 7:20","text":"Yes, just as you can identify a tree by its fruit, so you can identify people by their actions."}]},{"chapter":7,"verse":21,"reference":"Matthew 7:21","text":"“Not everyone who calls out to me, ‘Lord! Lord!’ will enter the Kingdom of Heaven. Only those who actually do the will of my Father in heaven will enter.","sentences":[{"id":"mt-7-21-1","chapter":7,"verse":21,"sentence":1,"reference":"Matthew 7:21","text":"“Not everyone who calls out to me, ‘Lord!"},{"id":"mt-7-21-2","chapter":7,"verse":21,"sentence":2,"reference":"Matthew 7:21","text":"Lord!’"},{"id":"mt-7-21-3","chapter":7,"verse":21,"sentence":3,"reference":"Matthew 7:21","text":"will enter the Kingdom of Heaven."},{"id":"mt-7-21-4","chapter":7,"verse":21,"sentence":4,"reference":"Matthew 7:21","text":"Only those who actually do the will of my Father in heaven will enter."}]},{"chapter":7,"verse":22,"reference":"Matthew 7:22","text":"On judgment day many will say to me, ‘Lord! Lord! We prophesied in your name and cast out demons in your name and performed many miracles in your name.’","sentences":[{"id":"mt-7-22-1","chapter":7,"verse":22,"sentence":1,"reference":"Matthew 7:22","text":"On judgment day many will say to me, ‘Lord!"},{"id":"mt-7-22-2","chapter":7,"verse":22,"sentence":2,"reference":"Matthew 7:22","text":"Lord!"},{"id":"mt-7-22-3","chapter":7,"verse":22,"sentence":3,"reference":"Matthew 7:22","text":"We prophesied in your name and cast out demons in your name and performed many miracles in your name.’"}]},{"chapter":7,"verse":23,"reference":"Matthew 7:23","text":"But I will reply, ‘I never knew you. Get away from me, you who break God’s laws.’","sentences":[{"id":"mt-7-23-1","chapter":7,"verse":23,"sentence":1,"reference":"Matthew 7:23","text":"But I will reply, ‘I never knew you."},{"id":"mt-7-23-2","chapter":7,"verse":23,"sentence":2,"reference":"Matthew 7:23","text":"Get away from me, you who break God’s laws.’"}]},{"chapter":7,"verse":24,"reference":"Matthew 7:24","text":"“Anyone who listens to my teaching and follows it is wise, like a person who builds a house on solid rock.","sentences":[{"id":"mt-7-24-1","chapter":7,"verse":24,"sentence":1,"reference":"Matthew 7:24","text":"“Anyone who listens to my teaching and follows it is wise, like a person who builds a house on solid rock."}]},{"chapter":7,"verse":25,"reference":"Matthew 7:25","text":"Though the rain comes in torrents and the floodwaters rise and the winds beat against that house, it won’t collapse because it is built on bedrock.","sentences":[{"id":"mt-7-25-1","chapter":7,"verse":25,"sentence":1,"reference":"Matthew 7:25","text":"Though the rain comes in torrents and the floodwaters rise and the winds beat against that house, it won’t collapse because it is built on bedrock."}]},{"chapter":7,"verse":26,"reference":"Matthew 7:26","text":"But anyone who hears my teaching and doesn’t obey it is foolish, like a person who builds a house on sand.","sentences":[{"id":"mt-7-26-1","chapter":7,"verse":26,"sentence":1,"reference":"Matthew 7:26","text":"But anyone who hears my teaching and doesn’t obey it is foolish, like a person who builds a house on sand."}]},{"chapter":7,"verse":27,"reference":"Matthew 7:27","text":"When the rains and floods come and the winds beat against that house, it will collapse with a mighty crash.”","sentences":[{"id":"mt-7-27-1","chapter":7,"verse":27,"sentence":1,"reference":"Matthew 7:27","text":"When the rains and floods come and the winds beat against that house, it will collapse with a mighty crash.”"}]},{"chapter":7,"verse":28,"reference":"Matthew 7:28","text":"When Jesus had finished saying these things, the crowds were amazed at his teaching,","sentences":[{"id":"mt-7-28-1","chapter":7,"verse":28,"sentence":1,"reference":"Matthew 7:28","text":"When Jesus had finished saying these things, the crowds were amazed at his teaching,"}]},{"chapter":7,"verse":29,"reference":"Matthew 7:29","text":"for he taught with real authority—quite unlike their teachers of religious law.","sentences":[{"id":"mt-7-29-1","chapter":7,"verse":29,"sentence":1,"reference":"Matthew 7:29","text":"for he taught with real authority—quite unlike their teachers of religious law."}]}]},{"chapter":8,"verses":[{"chapter":8,"verse":1,"reference":"Matthew 8:1","text":"Large crowds followed Jesus as he came down the mountainside.","sentences":[{"id":"mt-8-1-1","chapter":8,"verse":1,"sentence":1,"reference":"Matthew 8:1","text":"Large crowds followed Jesus as he came down the mountainside."}]},{"chapter":8,"verse":2,"reference":"Matthew 8:2","text":"Suddenly, a man with leprosy approached him and knelt before him. “Lord,” the man said, “if you are willing, you can heal me and make me clean.”","sentences":[{"id":"mt-8-2-1","chapter":8,"verse":2,"sentence":1,"reference":"Matthew 8:2","text":"Suddenly, a man with leprosy approached him and knelt before him."},{"id":"mt-8-2-2","chapter":8,"verse":2,"sentence":2,"reference":"Matthew 8:2","text":"“Lord,” the man said, “if you are willing, you can heal me and make me clean.”"}]},{"chapter":8,"verse":3,"reference":"Matthew 8:3","text":"Jesus reached out and touched him. “I am willing,” he said. “Be healed!” And instantly the leprosy disappeared.","sentences":[{"id":"mt-8-3-1","chapter":8,"verse":3,"sentence":1,"reference":"Matthew 8:3","text":"Jesus reached out and touched him."},{"id":"mt-8-3-2","chapter":8,"verse":3,"sentence":2,"reference":"Matthew 8:3","text":"“I am willing,” he said."},{"id":"mt-8-3-3","chapter":8,"verse":3,"sentence":3,"reference":"Matthew 8:3","text":"“Be healed!”"},{"id":"mt-8-3-4","chapter":8,"verse":3,"sentence":4,"reference":"Matthew 8:3","text":"And instantly the leprosy disappeared."}]},{"chapter":8,"verse":4,"reference":"Matthew 8:4","text":"Then Jesus said to him, “Don’t tell anyone about this. Instead, go to the priest and let him examine you. Take along the offering required in the law of Moses for those who have been healed of leprosy. This will be a public testimony that you have been cleansed.”","sentences":[{"id":"mt-8-4-1","chapter":8,"verse":4,"sentence":1,"reference":"Matthew 8:4","text":"Then Jesus said to him, “Don’t tell anyone about this."},{"id":"mt-8-4-2","chapter":8,"verse":4,"sentence":2,"reference":"Matthew 8:4","text":"Instead, go to the priest and let him examine you."},{"id":"mt-8-4-3","chapter":8,"verse":4,"sentence":3,"reference":"Matthew 8:4","text":"Take along the offering required in the law of Moses for those who have been healed of leprosy."},{"id":"mt-8-4-4","chapter":8,"verse":4,"sentence":4,"reference":"Matthew 8:4","text":"This will be a public testimony that you have been cleansed.”"}]},{"chapter":8,"verse":5,"reference":"Matthew 8:5","text":"When Jesus returned to Capernaum, a Roman officer came and pleaded with him,","sentences":[{"id":"mt-8-5-1","chapter":8,"verse":5,"sentence":1,"reference":"Matthew 8:5","text":"When Jesus returned to Capernaum, a Roman officer came and pleaded with him,"}]},{"chapter":8,"verse":6,"reference":"Matthew 8:6","text":"“Lord, my young servant lies in bed, paralyzed and in terrible pain.”","sentences":[{"id":"mt-8-6-1","chapter":8,"verse":6,"sentence":1,"reference":"Matthew 8:6","text":"“Lord, my young servant lies in bed, paralyzed and in terrible pain.”"}]},{"chapter":8,"verse":7,"reference":"Matthew 8:7","text":"Jesus said, “I will come and heal him.”","sentences":[{"id":"mt-8-7-1","chapter":8,"verse":7,"sentence":1,"reference":"Matthew 8:7","text":"Jesus said, “I will come and heal him.”"}]},{"chapter":8,"verse":8,"reference":"Matthew 8:8","text":"But the officer said, “Lord, I am not worthy to have you come into my home. Just say the word from where you are, and my servant will be healed.","sentences":[{"id":"mt-8-8-1","chapter":8,"verse":8,"sentence":1,"reference":"Matthew 8:8","text":"But the officer said, “Lord, I am not worthy to have you come into my home."},{"id":"mt-8-8-2","chapter":8,"verse":8,"sentence":2,"reference":"Matthew 8:8","text":"Just say the word from where you are, and my servant will be healed."}]},{"chapter":8,"verse":9,"reference":"Matthew 8:9","text":"I know this because I am under the authority of my superior officers, and I have authority over my soldiers. I only need to say, ‘Go,’ and they go, or ‘Come,’ and they come. And if I say to my slaves, ‘Do this,’ they do it.”","sentences":[{"id":"mt-8-9-1","chapter":8,"verse":9,"sentence":1,"reference":"Matthew 8:9","text":"I know this because I am under the authority of my superior officers, and I have authority over my soldiers."},{"id":"mt-8-9-2","chapter":8,"verse":9,"sentence":2,"reference":"Matthew 8:9","text":"I only need to say, ‘Go,’ and they go, or ‘Come,’ and they come."},{"id":"mt-8-9-3","chapter":8,"verse":9,"sentence":3,"reference":"Matthew 8:9","text":"And if I say to my slaves, ‘Do this,’ they do it.”"}]},{"chapter":8,"verse":10,"reference":"Matthew 8:10","text":"When Jesus heard this, he was amazed. Turning to those who were following him, he said, “I tell you the truth, I haven’t seen faith like this in all Israel!","sentences":[{"id":"mt-8-10-1","chapter":8,"verse":10,"sentence":1,"reference":"Matthew 8:10","text":"When Jesus heard this, he was amazed."},{"id":"mt-8-10-2","chapter":8,"verse":10,"sentence":2,"reference":"Matthew 8:10","text":"Turning to those who were following him, he said, “I tell you the truth, I haven’t seen faith like this in all Israel!"}]},{"chapter":8,"verse":11,"reference":"Matthew 8:11","text":"And I tell you this, that many Gentiles will come from all over the world—from east and west—and sit down with Abraham, Isaac, and Jacob at the feast in the Kingdom of Heaven.","sentences":[{"id":"mt-8-11-1","chapter":8,"verse":11,"sentence":1,"reference":"Matthew 8:11","text":"And I tell you this, that many Gentiles will come from all over the world—from east and west—and sit down with Abraham, Isaac, and Jacob at the feast in the Kingdom of Heaven."}]},{"chapter":8,"verse":12,"reference":"Matthew 8:12","text":"But many Israelites—those for whom the Kingdom was prepared—will be thrown into outer darkness, where there will be weeping and gnashing of teeth.”","sentences":[{"id":"mt-8-12-1","chapter":8,"verse":12,"sentence":1,"reference":"Matthew 8:12","text":"But many Israelites—those for whom the Kingdom was prepared—will be thrown into outer darkness, where there will be weeping and gnashing of teeth.”"}]},{"chapter":8,"verse":13,"reference":"Matthew 8:13","text":"Then Jesus said to the Roman officer, “Go back home. Because you believed, it has happened.” And the young servant was healed that same hour.","sentences":[{"id":"mt-8-13-1","chapter":8,"verse":13,"sentence":1,"reference":"Matthew 8:13","text":"Then Jesus said to the Roman officer, “Go back home."},{"id":"mt-8-13-2","chapter":8,"verse":13,"sentence":2,"reference":"Matthew 8:13","text":"Because you believed, it has happened.”"},{"id":"mt-8-13-3","chapter":8,"verse":13,"sentence":3,"reference":"Matthew 8:13","text":"And the young servant was healed that same hour."}]},{"chapter":8,"verse":14,"reference":"Matthew 8:14","text":"When Jesus arrived at Peter’s house, Peter’s mother-in-law was sick in bed with a high fever.","sentences":[{"id":"mt-8-14-1","chapter":8,"verse":14,"sentence":1,"reference":"Matthew 8:14","text":"When Jesus arrived at Peter’s house, Peter’s mother-in-law was sick in bed with a high fever."}]},{"chapter":8,"verse":15,"reference":"Matthew 8:15","text":"But when Jesus touched her hand, the fever left her. Then she got up and prepared a meal for him.","sentences":[{"id":"mt-8-15-1","chapter":8,"verse":15,"sentence":1,"reference":"Matthew 8:15","text":"But when Jesus touched her hand, the fever left her."},{"id":"mt-8-15-2","chapter":8,"verse":15,"sentence":2,"reference":"Matthew 8:15","text":"Then she got up and prepared a meal for him."}]},{"chapter":8,"verse":16,"reference":"Matthew 8:16","text":"That evening many demon-possessed people were brought to Jesus. He cast out the evil spirits with a simple command, and he healed all the sick.","sentences":[{"id":"mt-8-16-1","chapter":8,"verse":16,"sentence":1,"reference":"Matthew 8:16","text":"That evening many demon-possessed people were brought to Jesus."},{"id":"mt-8-16-2","chapter":8,"verse":16,"sentence":2,"reference":"Matthew 8:16","text":"He cast out the evil spirits with a simple command, and he healed all the sick."}]},{"chapter":8,"verse":17,"reference":"Matthew 8:17","text":"This fulfilled the word of the Lord through the prophet Isaiah, who said, “He took our sicknesses and removed our diseases.”","sentences":[{"id":"mt-8-17-1","chapter":8,"verse":17,"sentence":1,"reference":"Matthew 8:17","text":"This fulfilled the word of the Lord through the prophet Isaiah, who said, “He took our sicknesses and removed our diseases.”"}]},{"chapter":8,"verse":18,"reference":"Matthew 8:18","text":"When Jesus saw the crowd around him, he instructed his disciples to cross to the other side of the lake.","sentences":[{"id":"mt-8-18-1","chapter":8,"verse":18,"sentence":1,"reference":"Matthew 8:18","text":"When Jesus saw the crowd around him, he instructed his disciples to cross to the other side of the lake."}]},{"chapter":8,"verse":19,"reference":"Matthew 8:19","text":"Then one of the teachers of religious law said to him, “Teacher, I will follow you wherever you go.”","sentences":[{"id":"mt-8-19-1","chapter":8,"verse":19,"sentence":1,"reference":"Matthew 8:19","text":"Then one of the teachers of religious law said to him, “Teacher, I will follow you wherever you go.”"}]},{"chapter":8,"verse":20,"reference":"Matthew 8:20","text":"But Jesus replied, “Foxes have dens to live in, and birds have nests, but the Son of Man has no place even to lay his head.”","sentences":[{"id":"mt-8-20-1","chapter":8,"verse":20,"sentence":1,"reference":"Matthew 8:20","text":"But Jesus replied, “Foxes have dens to live in, and birds have nests, but the Son of Man has no place even to lay his head.”"}]},{"chapter":8,"verse":21,"reference":"Matthew 8:21","text":"Another of his disciples said, “Lord, first let me return home and bury my father.”","sentences":[{"id":"mt-8-21-1","chapter":8,"verse":21,"sentence":1,"reference":"Matthew 8:21","text":"Another of his disciples said, “Lord, first let me return home and bury my father.”"}]},{"chapter":8,"verse":22,"reference":"Matthew 8:22","text":"But Jesus told him, “Follow me now. Let the spiritually dead bury their own dead.”","sentences":[{"id":"mt-8-22-1","chapter":8,"verse":22,"sentence":1,"reference":"Matthew 8:22","text":"But Jesus told him, “Follow me now."},{"id":"mt-8-22-2","chapter":8,"verse":22,"sentence":2,"reference":"Matthew 8:22","text":"Let the spiritually dead bury their own dead.”"}]},{"chapter":8,"verse":23,"reference":"Matthew 8:23","text":"Then Jesus got into the boat and started across the lake with his disciples.","sentences":[{"id":"mt-8-23-1","chapter":8,"verse":23,"sentence":1,"reference":"Matthew 8:23","text":"Then Jesus got into the boat and started across the lake with his disciples."}]},{"chapter":8,"verse":24,"reference":"Matthew 8:24","text":"Suddenly, a fierce storm struck the lake, with waves breaking into the boat. But Jesus was sleeping.","sentences":[{"id":"mt-8-24-1","chapter":8,"verse":24,"sentence":1,"reference":"Matthew 8:24","text":"Suddenly, a fierce storm struck the lake, with waves breaking into the boat."},{"id":"mt-8-24-2","chapter":8,"verse":24,"sentence":2,"reference":"Matthew 8:24","text":"But Jesus was sleeping."}]},{"chapter":8,"verse":25,"reference":"Matthew 8:25","text":"The disciples went and woke him up, shouting, “Lord, save us! We’re going to drown!”","sentences":[{"id":"mt-8-25-1","chapter":8,"verse":25,"sentence":1,"reference":"Matthew 8:25","text":"The disciples went and woke him up, shouting, “Lord, save us!"},{"id":"mt-8-25-2","chapter":8,"verse":25,"sentence":2,"reference":"Matthew 8:25","text":"We’re going to drown!”"}]},{"chapter":8,"verse":26,"reference":"Matthew 8:26","text":"Jesus responded, “Why are you afraid? You have so little faith!” Then he got up and rebuked the wind and waves, and suddenly there was a great calm.","sentences":[{"id":"mt-8-26-1","chapter":8,"verse":26,"sentence":1,"reference":"Matthew 8:26","text":"Jesus responded, “Why are you afraid?"},{"id":"mt-8-26-2","chapter":8,"verse":26,"sentence":2,"reference":"Matthew 8:26","text":"You have so little faith!”"},{"id":"mt-8-26-3","chapter":8,"verse":26,"sentence":3,"reference":"Matthew 8:26","text":"Then he got up and rebuked the wind and waves, and suddenly there was a great calm."}]},{"chapter":8,"verse":27,"reference":"Matthew 8:27","text":"The disciples were amazed. “Who is this man?” they asked. “Even the winds and waves obey him!”","sentences":[{"id":"mt-8-27-1","chapter":8,"verse":27,"sentence":1,"reference":"Matthew 8:27","text":"The disciples were amazed."},{"id":"mt-8-27-2","chapter":8,"verse":27,"sentence":2,"reference":"Matthew 8:27","text":"“Who is this man?”"},{"id":"mt-8-27-3","chapter":8,"verse":27,"sentence":3,"reference":"Matthew 8:27","text":"they asked."},{"id":"mt-8-27-4","chapter":8,"verse":27,"sentence":4,"reference":"Matthew 8:27","text":"“Even the winds and waves obey him!”"}]},{"chapter":8,"verse":28,"reference":"Matthew 8:28","text":"When Jesus arrived on the other side of the lake, in the region of the Gadarenes, two men who were possessed by demons met him. They came out of the tombs and were so violent that no one could go through that area.","sentences":[{"id":"mt-8-28-1","chapter":8,"verse":28,"sentence":1,"reference":"Matthew 8:28","text":"When Jesus arrived on the other side of the lake, in the region of the Gadarenes, two men who were possessed by demons met him."},{"id":"mt-8-28-2","chapter":8,"verse":28,"sentence":2,"reference":"Matthew 8:28","text":"They came out of the tombs and were so violent that no one could go through that area."}]},{"chapter":8,"verse":29,"reference":"Matthew 8:29","text":"They began screaming at him, “Why are you interfering with us, Son of God? Have you come here to torture us before God’s appointed time?”","sentences":[{"id":"mt-8-29-1","chapter":8,"verse":29,"sentence":1,"reference":"Matthew 8:29","text":"They began screaming at him, “Why are you interfering with us, Son of God?"},{"id":"mt-8-29-2","chapter":8,"verse":29,"sentence":2,"reference":"Matthew 8:29","text":"Have you come here to torture us before God’s appointed time?”"}]},{"chapter":8,"verse":30,"reference":"Matthew 8:30","text":"There happened to be a large herd of pigs feeding in the distance.","sentences":[{"id":"mt-8-30-1","chapter":8,"verse":30,"sentence":1,"reference":"Matthew 8:30","text":"There happened to be a large herd of pigs feeding in the distance."}]},{"chapter":8,"verse":31,"reference":"Matthew 8:31","text":"So the demons begged, “If you cast us out, send us into that herd of pigs.”","sentences":[{"id":"mt-8-31-1","chapter":8,"verse":31,"sentence":1,"reference":"Matthew 8:31","text":"So the demons begged, “If you cast us out, send us into that herd of pigs.”"}]},{"chapter":8,"verse":32,"reference":"Matthew 8:32","text":"“All right, go!” Jesus commanded them. So the demons came out of the men and entered the pigs, and the whole herd plunged down the steep hillside into the lake and drowned in the water.","sentences":[{"id":"mt-8-32-1","chapter":8,"verse":32,"sentence":1,"reference":"Matthew 8:32","text":"“All right, go!”"},{"id":"mt-8-32-2","chapter":8,"verse":32,"sentence":2,"reference":"Matthew 8:32","text":"Jesus commanded them."},{"id":"mt-8-32-3","chapter":8,"verse":32,"sentence":3,"reference":"Matthew 8:32","text":"So the demons came out of the men and entered the pigs, and the whole herd plunged down the steep hillside into the lake and drowned in the water."}]},{"chapter":8,"verse":33,"reference":"Matthew 8:33","text":"The herdsmen fled to the nearby town, telling everyone what happened to the demon-possessed men.","sentences":[{"id":"mt-8-33-1","chapter":8,"verse":33,"sentence":1,"reference":"Matthew 8:33","text":"The herdsmen fled to the nearby town, telling everyone what happened to the demon-possessed men."}]},{"chapter":8,"verse":34,"reference":"Matthew 8:34","text":"Then the entire town came out to meet Jesus, but they begged him to go away and leave them alone.","sentences":[{"id":"mt-8-34-1","chapter":8,"verse":34,"sentence":1,"reference":"Matthew 8:34","text":"Then the entire town came out to meet Jesus, but they begged him to go away and leave them alone."}]}]},{"chapter":9,"verses":[{"chapter":9,"verse":1,"reference":"Matthew 9:1","text":"Jesus climbed into a boat and went back across the lake to his own town.","sentences":[{"id":"mt-9-1-1","chapter":9,"verse":1,"sentence":1,"reference":"Matthew 9:1","text":"Jesus climbed into a boat and went back across the lake to his own town."}]},{"chapter":9,"verse":2,"reference":"Matthew 9:2","text":"Some people brought to him a paralyzed man on a mat. Seeing their faith, Jesus said to the paralyzed man, “Be encouraged, my child! Your sins are forgiven.”","sentences":[{"id":"mt-9-2-1","chapter":9,"verse":2,"sentence":1,"reference":"Matthew 9:2","text":"Some people brought to him a paralyzed man on a mat."},{"id":"mt-9-2-2","chapter":9,"verse":2,"sentence":2,"reference":"Matthew 9:2","text":"Seeing their faith, Jesus said to the paralyzed man, “Be encouraged, my child!"},{"id":"mt-9-2-3","chapter":9,"verse":2,"sentence":3,"reference":"Matthew 9:2","text":"Your sins are forgiven.”"}]},{"chapter":9,"verse":3,"reference":"Matthew 9:3","text":"But some of the teachers of religious law said to themselves, “That’s blasphemy! Does he think he’s God?”","sentences":[{"id":"mt-9-3-1","chapter":9,"verse":3,"sentence":1,"reference":"Matthew 9:3","text":"But some of the teachers of religious law said to themselves, “That’s blasphemy!"},{"id":"mt-9-3-2","chapter":9,"verse":3,"sentence":2,"reference":"Matthew 9:3","text":"Does he think he’s God?”"}]},{"chapter":9,"verse":4,"reference":"Matthew 9:4","text":"Jesus knew what they were thinking, so he asked them, “Why do you have such evil thoughts in your hearts?","sentences":[{"id":"mt-9-4-1","chapter":9,"verse":4,"sentence":1,"reference":"Matthew 9:4","text":"Jesus knew what they were thinking, so he asked them, “Why do you have such evil thoughts in your hearts?"}]},{"chapter":9,"verse":5,"reference":"Matthew 9:5","text":"Is it easier to say ‘Your sins are forgiven,’ or ‘Stand up and walk’?","sentences":[{"id":"mt-9-5-1","chapter":9,"verse":5,"sentence":1,"reference":"Matthew 9:5","text":"Is it easier to say ‘Your sins are forgiven,’ or ‘Stand up and walk’?"}]},{"chapter":9,"verse":6,"reference":"Matthew 9:6","text":"So I will prove to you that the Son of Man has the authority on earth to forgive sins.” Then Jesus turned to the paralyzed man and said, “Stand up, pick up your mat, and go home!”","sentences":[{"id":"mt-9-6-1","chapter":9,"verse":6,"sentence":1,"reference":"Matthew 9:6","text":"So I will prove to you that the Son of Man has the authority on earth to forgive sins.”"},{"id":"mt-9-6-2","chapter":9,"verse":6,"sentence":2,"reference":"Matthew 9:6","text":"Then Jesus turned to the paralyzed man and said, “Stand up, pick up your mat, and go home!”"}]},{"chapter":9,"verse":7,"reference":"Matthew 9:7","text":"And the man jumped up and went home!","sentences":[{"id":"mt-9-7-1","chapter":9,"verse":7,"sentence":1,"reference":"Matthew 9:7","text":"And the man jumped up and went home!"}]},{"chapter":9,"verse":8,"reference":"Matthew 9:8","text":"Fear swept through the crowd as they saw this happen. And they praised God for giving humans such authority.","sentences":[{"id":"mt-9-8-1","chapter":9,"verse":8,"sentence":1,"reference":"Matthew 9:8","text":"Fear swept through the crowd as they saw this happen."},{"id":"mt-9-8-2","chapter":9,"verse":8,"sentence":2,"reference":"Matthew 9:8","text":"And they praised God for giving humans such authority."}]},{"chapter":9,"verse":9,"reference":"Matthew 9:9","text":"As Jesus was walking along, he saw a man named Matthew sitting at his tax collector’s booth. “Follow me and be my disciple,” Jesus said to him. So Matthew got up and followed him.","sentences":[{"id":"mt-9-9-1","chapter":9,"verse":9,"sentence":1,"reference":"Matthew 9:9","text":"As Jesus was walking along, he saw a man named Matthew sitting at his tax collector’s booth."},{"id":"mt-9-9-2","chapter":9,"verse":9,"sentence":2,"reference":"Matthew 9:9","text":"“Follow me and be my disciple,” Jesus said to him."},{"id":"mt-9-9-3","chapter":9,"verse":9,"sentence":3,"reference":"Matthew 9:9","text":"So Matthew got up and followed him."}]},{"chapter":9,"verse":10,"reference":"Matthew 9:10","text":"Later, Matthew invited Jesus and his disciples to his home as dinner guests, along with many tax collectors and other disreputable sinners.","sentences":[{"id":"mt-9-10-1","chapter":9,"verse":10,"sentence":1,"reference":"Matthew 9:10","text":"Later, Matthew invited Jesus and his disciples to his home as dinner guests, along with many tax collectors and other disreputable sinners."}]},{"chapter":9,"verse":11,"reference":"Matthew 9:11","text":"But when the Pharisees saw this, they asked his disciples, “Why does your teacher eat with such scum?”","sentences":[{"id":"mt-9-11-1","chapter":9,"verse":11,"sentence":1,"reference":"Matthew 9:11","text":"But when the Pharisees saw this, they asked his disciples, “Why does your teacher eat with such scum?”"}]},{"chapter":9,"verse":12,"reference":"Matthew 9:12","text":"When Jesus heard this, he said, “Healthy people don’t need a doctor—sick people do.”","sentences":[{"id":"mt-9-12-1","chapter":9,"verse":12,"sentence":1,"reference":"Matthew 9:12","text":"When Jesus heard this, he said, “Healthy people don’t need a doctor—sick people do.”"}]},{"chapter":9,"verse":13,"reference":"Matthew 9:13","text":"Then he added, “Now go and learn the meaning of this Scripture: ‘I want you to show mercy, not offer sacrifices.’ For I have come to call not those who think they are righteous, but those who know they are sinners.”","sentences":[{"id":"mt-9-13-1","chapter":9,"verse":13,"sentence":1,"reference":"Matthew 9:13","text":"Then he added, “Now go and learn the meaning of this Scripture: ‘I want you to show mercy, not offer sacrifices.’"},{"id":"mt-9-13-2","chapter":9,"verse":13,"sentence":2,"reference":"Matthew 9:13","text":"For I have come to call not those who think they are righteous, but those who know they are sinners.”"}]},{"chapter":9,"verse":14,"reference":"Matthew 9:14","text":"One day the disciples of John the Baptist came to Jesus and asked him, “Why don’t your disciples fast like we do and the Pharisees do?”","sentences":[{"id":"mt-9-14-1","chapter":9,"verse":14,"sentence":1,"reference":"Matthew 9:14","text":"One day the disciples of John the Baptist came to Jesus and asked him, “Why don’t your disciples fast like we do and the Pharisees do?”"}]},{"chapter":9,"verse":15,"reference":"Matthew 9:15","text":"Jesus replied, “Do wedding guests mourn while celebrating with the groom? Of course not. But someday the groom will be taken away from them, and then they will fast.","sentences":[{"id":"mt-9-15-1","chapter":9,"verse":15,"sentence":1,"reference":"Matthew 9:15","text":"Jesus replied, “Do wedding guests mourn while celebrating with the groom?"},{"id":"mt-9-15-2","chapter":9,"verse":15,"sentence":2,"reference":"Matthew 9:15","text":"Of course not."},{"id":"mt-9-15-3","chapter":9,"verse":15,"sentence":3,"reference":"Matthew 9:15","text":"But someday the groom will be taken away from them, and then they will fast."}]},{"chapter":9,"verse":16,"reference":"Matthew 9:16","text":"“Besides, who would patch old clothing with new cloth? For the new patch would shrink and rip away from the old cloth, leaving an even bigger tear than before.","sentences":[{"id":"mt-9-16-1","chapter":9,"verse":16,"sentence":1,"reference":"Matthew 9:16","text":"“Besides, who would patch old clothing with new cloth?"},{"id":"mt-9-16-2","chapter":9,"verse":16,"sentence":2,"reference":"Matthew 9:16","text":"For the new patch would shrink and rip away from the old cloth, leaving an even bigger tear than before."}]},{"chapter":9,"verse":17,"reference":"Matthew 9:17","text":"“And no one puts new wine into old wineskins. For the old skins would burst from the pressure, spilling the wine and ruining the skins. New wine is stored in new wineskins so that both are preserved.”","sentences":[{"id":"mt-9-17-1","chapter":9,"verse":17,"sentence":1,"reference":"Matthew 9:17","text":"“And no one puts new wine into old wineskins."},{"id":"mt-9-17-2","chapter":9,"verse":17,"sentence":2,"reference":"Matthew 9:17","text":"For the old skins would burst from the pressure, spilling the wine and ruining the skins."},{"id":"mt-9-17-3","chapter":9,"verse":17,"sentence":3,"reference":"Matthew 9:17","text":"New wine is stored in new wineskins so that both are preserved.”"}]},{"chapter":9,"verse":18,"reference":"Matthew 9:18","text":"As Jesus was saying this, the leader of a synagogue came and knelt before him. “My daughter has just died,” he said, “but you can bring her back to life again if you just come and lay your hand on her.”","sentences":[{"id":"mt-9-18-1","chapter":9,"verse":18,"sentence":1,"reference":"Matthew 9:18","text":"As Jesus was saying this, the leader of a synagogue came and knelt before him."},{"id":"mt-9-18-2","chapter":9,"verse":18,"sentence":2,"reference":"Matthew 9:18","text":"“My daughter has just died,” he said, “but you can bring her back to life again if you just come and lay your hand on her.”"}]},{"chapter":9,"verse":19,"reference":"Matthew 9:19","text":"So Jesus and his disciples got up and went with him.","sentences":[{"id":"mt-9-19-1","chapter":9,"verse":19,"sentence":1,"reference":"Matthew 9:19","text":"So Jesus and his disciples got up and went with him."}]},{"chapter":9,"verse":20,"reference":"Matthew 9:20","text":"Just then a woman who had suffered for twelve years with constant bleeding came up behind him. She touched the fringe of his robe,","sentences":[{"id":"mt-9-20-1","chapter":9,"verse":20,"sentence":1,"reference":"Matthew 9:20","text":"Just then a woman who had suffered for twelve years with constant bleeding came up behind him."},{"id":"mt-9-20-2","chapter":9,"verse":20,"sentence":2,"reference":"Matthew 9:20","text":"She touched the fringe of his robe,"}]},{"chapter":9,"verse":21,"reference":"Matthew 9:21","text":"for she thought, “If I can just touch his robe, I will be healed.”","sentences":[{"id":"mt-9-21-1","chapter":9,"verse":21,"sentence":1,"reference":"Matthew 9:21","text":"for she thought, “If I can just touch his robe, I will be healed.”"}]},{"chapter":9,"verse":22,"reference":"Matthew 9:22","text":"Jesus turned around, and when he saw her he said, “Daughter, be encouraged! Your faith has made you well.” And the woman was healed at that moment.","sentences":[{"id":"mt-9-22-1","chapter":9,"verse":22,"sentence":1,"reference":"Matthew 9:22","text":"Jesus turned around, and when he saw her he said, “Daughter, be encouraged!"},{"id":"mt-9-22-2","chapter":9,"verse":22,"sentence":2,"reference":"Matthew 9:22","text":"Your faith has made you well.”"},{"id":"mt-9-22-3","chapter":9,"verse":22,"sentence":3,"reference":"Matthew 9:22","text":"And the woman was healed at that moment."}]},{"chapter":9,"verse":23,"reference":"Matthew 9:23","text":"When Jesus arrived at the official’s home, he saw the noisy crowd and heard the funeral music.","sentences":[{"id":"mt-9-23-1","chapter":9,"verse":23,"sentence":1,"reference":"Matthew 9:23","text":"When Jesus arrived at the official’s home, he saw the noisy crowd and heard the funeral music."}]},{"chapter":9,"verse":24,"reference":"Matthew 9:24","text":"“Get out!” he told them. “The girl isn’t dead; she’s only asleep.” But the crowd laughed at him.","sentences":[{"id":"mt-9-24-1","chapter":9,"verse":24,"sentence":1,"reference":"Matthew 9:24","text":"“Get out!”"},{"id":"mt-9-24-2","chapter":9,"verse":24,"sentence":2,"reference":"Matthew 9:24","text":"he told them."},{"id":"mt-9-24-3","chapter":9,"verse":24,"sentence":3,"reference":"Matthew 9:24","text":"“The girl isn’t dead; she’s only asleep.”"},{"id":"mt-9-24-4","chapter":9,"verse":24,"sentence":4,"reference":"Matthew 9:24","text":"But the crowd laughed at him."}]},{"chapter":9,"verse":25,"reference":"Matthew 9:25","text":"After the crowd was put outside, however, Jesus went in and took the girl by the hand, and she stood up!","sentences":[{"id":"mt-9-25-1","chapter":9,"verse":25,"sentence":1,"reference":"Matthew 9:25","text":"After the crowd was put outside, however, Jesus went in and took the girl by the hand, and she stood up!"}]},{"chapter":9,"verse":26,"reference":"Matthew 9:26","text":"The report of this miracle swept through the entire countryside.","sentences":[{"id":"mt-9-26-1","chapter":9,"verse":26,"sentence":1,"reference":"Matthew 9:26","text":"The report of this miracle swept through the entire countryside."}]},{"chapter":9,"verse":27,"reference":"Matthew 9:27","text":"After Jesus left the girl’s home, two blind men followed along behind him, shouting, “Son of David, have mercy on us!”","sentences":[{"id":"mt-9-27-1","chapter":9,"verse":27,"sentence":1,"reference":"Matthew 9:27","text":"After Jesus left the girl’s home, two blind men followed along behind him, shouting, “Son of David, have mercy on us!”"}]},{"chapter":9,"verse":28,"reference":"Matthew 9:28","text":"They went right into the house where he was staying, and Jesus asked them, “Do you believe I can make you see?” “Yes, Lord,” they told him, “we do.”","sentences":[{"id":"mt-9-28-1","chapter":9,"verse":28,"sentence":1,"reference":"Matthew 9:28","text":"They went right into the house where he was staying, and Jesus asked them, “Do you believe I can make you see?”"},{"id":"mt-9-28-2","chapter":9,"verse":28,"sentence":2,"reference":"Matthew 9:28","text":"“Yes, Lord,” they told him, “we do.”"}]},{"chapter":9,"verse":29,"reference":"Matthew 9:29","text":"Then he touched their eyes and said, “Because of your faith, it will happen.”","sentences":[{"id":"mt-9-29-1","chapter":9,"verse":29,"sentence":1,"reference":"Matthew 9:29","text":"Then he touched their eyes and said, “Because of your faith, it will happen.”"}]},{"chapter":9,"verse":30,"reference":"Matthew 9:30","text":"Then their eyes were opened, and they could see! Jesus sternly warned them, “Don’t tell anyone about this.”","sentences":[{"id":"mt-9-30-1","chapter":9,"verse":30,"sentence":1,"reference":"Matthew 9:30","text":"Then their eyes were opened, and they could see!"},{"id":"mt-9-30-2","chapter":9,"verse":30,"sentence":2,"reference":"Matthew 9:30","text":"Jesus sternly warned them, “Don’t tell anyone about this.”"}]},{"chapter":9,"verse":31,"reference":"Matthew 9:31","text":"But instead, they went out and spread his fame all over the region.","sentences":[{"id":"mt-9-31-1","chapter":9,"verse":31,"sentence":1,"reference":"Matthew 9:31","text":"But instead, they went out and spread his fame all over the region."}]},{"chapter":9,"verse":32,"reference":"Matthew 9:32","text":"When they left, a demon-possessed man who couldn’t speak was brought to Jesus.","sentences":[{"id":"mt-9-32-1","chapter":9,"verse":32,"sentence":1,"reference":"Matthew 9:32","text":"When they left, a demon-possessed man who couldn’t speak was brought to Jesus."}]},{"chapter":9,"verse":33,"reference":"Matthew 9:33","text":"So Jesus cast out the demon, and then the man began to speak. The crowds were amazed. “Nothing like this has ever happened in Israel!” they exclaimed.","sentences":[{"id":"mt-9-33-1","chapter":9,"verse":33,"sentence":1,"reference":"Matthew 9:33","text":"So Jesus cast out the demon, and then the man began to speak."},{"id":"mt-9-33-2","chapter":9,"verse":33,"sentence":2,"reference":"Matthew 9:33","text":"The crowds were amazed."},{"id":"mt-9-33-3","chapter":9,"verse":33,"sentence":3,"reference":"Matthew 9:33","text":"“Nothing like this has ever happened in Israel!”"},{"id":"mt-9-33-4","chapter":9,"verse":33,"sentence":4,"reference":"Matthew 9:33","text":"they exclaimed."}]},{"chapter":9,"verse":34,"reference":"Matthew 9:34","text":"But the Pharisees said, “He can cast out demons because he is empowered by the prince of demons.”","sentences":[{"id":"mt-9-34-1","chapter":9,"verse":34,"sentence":1,"reference":"Matthew 9:34","text":"But the Pharisees said, “He can cast out demons because he is empowered by the prince of demons.”"}]},{"chapter":9,"verse":35,"reference":"Matthew 9:35","text":"Jesus traveled through all the towns and villages of that area, teaching in the synagogues and announcing the Good News about the Kingdom. And he healed every kind of disease and illness.","sentences":[{"id":"mt-9-35-1","chapter":9,"verse":35,"sentence":1,"reference":"Matthew 9:35","text":"Jesus traveled through all the towns and villages of that area, teaching in the synagogues and announcing the Good News about the Kingdom."},{"id":"mt-9-35-2","chapter":9,"verse":35,"sentence":2,"reference":"Matthew 9:35","text":"And he healed every kind of disease and illness."}]},{"chapter":9,"verse":36,"reference":"Matthew 9:36","text":"When he saw the crowds, he had compassion on them because they were confused and helpless, like sheep without a shepherd.","sentences":[{"id":"mt-9-36-1","chapter":9,"verse":36,"sentence":1,"reference":"Matthew 9:36","text":"When he saw the crowds, he had compassion on them because they were confused and helpless, like sheep without a shepherd."}]},{"chapter":9,"verse":37,"reference":"Matthew 9:37","text":"He said to his disciples, “The harvest is great, but the workers are few.","sentences":[{"id":"mt-9-37-1","chapter":9,"verse":37,"sentence":1,"reference":"Matthew 9:37","text":"He said to his disciples, “The harvest is great, but the workers are few."}]},{"chapter":9,"verse":38,"reference":"Matthew 9:38","text":"So pray to the Lord who is in charge of the harvest; ask him to send more workers into his fields.”","sentences":[{"id":"mt-9-38-1","chapter":9,"verse":38,"sentence":1,"reference":"Matthew 9:38","text":"So pray to the Lord who is in charge of the harvest; ask him to send more workers into his fields.”"}]}]},{"chapter":10,"verses":[{"chapter":10,"verse":1,"reference":"Matthew 10:1","text":"Jesus called his twelve disciples together and gave them authority to cast out evil spirits and to heal every kind of disease and illness.","sentences":[{"id":"mt-10-1-1","chapter":10,"verse":1,"sentence":1,"reference":"Matthew 10:1","text":"Jesus called his twelve disciples together and gave them authority to cast out evil spirits and to heal every kind of disease and illness."}]},{"chapter":10,"verse":2,"reference":"Matthew 10:2","text":"Here are the names of the twelve apostles: first, Simon (also called Peter), then Andrew (Peter’s brother), James (son of Zebedee), John (James’s brother),","sentences":[{"id":"mt-10-2-1","chapter":10,"verse":2,"sentence":1,"reference":"Matthew 10:2","text":"Here are the names of the twelve apostles: first, Simon (also called Peter), then Andrew (Peter’s brother), James (son of Zebedee), John (James’s brother),"}]},{"chapter":10,"verse":3,"reference":"Matthew 10:3","text":"Philip, Bartholomew, Thomas, Matthew (the tax collector), James (son of Alphaeus), Thaddaeus,","sentences":[{"id":"mt-10-3-1","chapter":10,"verse":3,"sentence":1,"reference":"Matthew 10:3","text":"Philip, Bartholomew, Thomas, Matthew (the tax collector), James (son of Alphaeus), Thaddaeus,"}]},{"chapter":10,"verse":4,"reference":"Matthew 10:4","text":"Simon (the zealot), Judas Iscariot (who later betrayed him).","sentences":[{"id":"mt-10-4-1","chapter":10,"verse":4,"sentence":1,"reference":"Matthew 10:4","text":"Simon (the zealot), Judas Iscariot (who later betrayed him)."}]},{"chapter":10,"verse":5,"reference":"Matthew 10:5","text":"Jesus sent out the twelve apostles with these instructions: “Don’t go to the Gentiles or the Samaritans,","sentences":[{"id":"mt-10-5-1","chapter":10,"verse":5,"sentence":1,"reference":"Matthew 10:5","text":"Jesus sent out the twelve apostles with these instructions: “Don’t go to the Gentiles or the Samaritans,"}]},{"chapter":10,"verse":6,"reference":"Matthew 10:6","text":"but only to the people of Israel—God’s lost sheep.","sentences":[{"id":"mt-10-6-1","chapter":10,"verse":6,"sentence":1,"reference":"Matthew 10:6","text":"but only to the people of Israel—God’s lost sheep."}]},{"chapter":10,"verse":7,"reference":"Matthew 10:7","text":"Go and announce to them that the Kingdom of Heaven is near.","sentences":[{"id":"mt-10-7-1","chapter":10,"verse":7,"sentence":1,"reference":"Matthew 10:7","text":"Go and announce to them that the Kingdom of Heaven is near."}]},{"chapter":10,"verse":8,"reference":"Matthew 10:8","text":"Heal the sick, raise the dead, cure those with leprosy, and cast out demons. Give as freely as you have received!","sentences":[{"id":"mt-10-8-1","chapter":10,"verse":8,"sentence":1,"reference":"Matthew 10:8","text":"Heal the sick, raise the dead, cure those with leprosy, and cast out demons."},{"id":"mt-10-8-2","chapter":10,"verse":8,"sentence":2,"reference":"Matthew 10:8","text":"Give as freely as you have received!"}]},{"chapter":10,"verse":9,"reference":"Matthew 10:9","text":"“Don’t take any money in your money belts—no gold, silver, or even copper coins.","sentences":[{"id":"mt-10-9-1","chapter":10,"verse":9,"sentence":1,"reference":"Matthew 10:9","text":"“Don’t take any money in your money belts—no gold, silver, or even copper coins."}]},{"chapter":10,"verse":10,"reference":"Matthew 10:10","text":"Don’t carry a traveler’s bag with a change of clothes and sandals or even a walking stick. Don’t hesitate to accept hospitality, because those who work deserve to be fed.","sentences":[{"id":"mt-10-10-1","chapter":10,"verse":10,"sentence":1,"reference":"Matthew 10:10","text":"Don’t carry a traveler’s bag with a change of clothes and sandals or even a walking stick."},{"id":"mt-10-10-2","chapter":10,"verse":10,"sentence":2,"reference":"Matthew 10:10","text":"Don’t hesitate to accept hospitality, because those who work deserve to be fed."}]},{"chapter":10,"verse":11,"reference":"Matthew 10:11","text":"“Whenever you enter a city or village, search for a worthy person and stay in his home until you leave town.","sentences":[{"id":"mt-10-11-1","chapter":10,"verse":11,"sentence":1,"reference":"Matthew 10:11","text":"“Whenever you enter a city or village, search for a worthy person and stay in his home until you leave town."}]},{"chapter":10,"verse":12,"reference":"Matthew 10:12","text":"When you enter the home, give it your blessing.","sentences":[{"id":"mt-10-12-1","chapter":10,"verse":12,"sentence":1,"reference":"Matthew 10:12","text":"When you enter the home, give it your blessing."}]},{"chapter":10,"verse":13,"reference":"Matthew 10:13","text":"If it turns out to be a worthy home, let your blessing stand; if it is not, take back the blessing.","sentences":[{"id":"mt-10-13-1","chapter":10,"verse":13,"sentence":1,"reference":"Matthew 10:13","text":"If it turns out to be a worthy home, let your blessing stand; if it is not, take back the blessing."}]},{"chapter":10,"verse":14,"reference":"Matthew 10:14","text":"If any household or town refuses to welcome you or listen to your message, shake its dust from your feet as you leave.","sentences":[{"id":"mt-10-14-1","chapter":10,"verse":14,"sentence":1,"reference":"Matthew 10:14","text":"If any household or town refuses to welcome you or listen to your message, shake its dust from your feet as you leave."}]},{"chapter":10,"verse":15,"reference":"Matthew 10:15","text":"I tell you the truth, the wicked cities of Sodom and Gomorrah will be better off than such a town on the judgment day.","sentences":[{"id":"mt-10-15-1","chapter":10,"verse":15,"sentence":1,"reference":"Matthew 10:15","text":"I tell you the truth, the wicked cities of Sodom and Gomorrah will be better off than such a town on the judgment day."}]},{"chapter":10,"verse":16,"reference":"Matthew 10:16","text":"“Look, I am sending you out as sheep among wolves. So be as shrewd as snakes and harmless as doves.","sentences":[{"id":"mt-10-16-1","chapter":10,"verse":16,"sentence":1,"reference":"Matthew 10:16","text":"“Look, I am sending you out as sheep among wolves."},{"id":"mt-10-16-2","chapter":10,"verse":16,"sentence":2,"reference":"Matthew 10:16","text":"So be as shrewd as snakes and harmless as doves."}]},{"chapter":10,"verse":17,"reference":"Matthew 10:17","text":"But beware! For you will be handed over to the courts and will be flogged with whips in the synagogues.","sentences":[{"id":"mt-10-17-1","chapter":10,"verse":17,"sentence":1,"reference":"Matthew 10:17","text":"But beware!"},{"id":"mt-10-17-2","chapter":10,"verse":17,"sentence":2,"reference":"Matthew 10:17","text":"For you will be handed over to the courts and will be flogged with whips in the synagogues."}]},{"chapter":10,"verse":18,"reference":"Matthew 10:18","text":"You will stand trial before governors and kings because you are my followers. But this will be your opportunity to tell the rulers and other unbelievers about me.","sentences":[{"id":"mt-10-18-1","chapter":10,"verse":18,"sentence":1,"reference":"Matthew 10:18","text":"You will stand trial before governors and kings because you are my followers."},{"id":"mt-10-18-2","chapter":10,"verse":18,"sentence":2,"reference":"Matthew 10:18","text":"But this will be your opportunity to tell the rulers and other unbelievers about me."}]},{"chapter":10,"verse":19,"reference":"Matthew 10:19","text":"When you are arrested, don’t worry about how to respond or what to say. God will give you the right words at the right time.","sentences":[{"id":"mt-10-19-1","chapter":10,"verse":19,"sentence":1,"reference":"Matthew 10:19","text":"When you are arrested, don’t worry about how to respond or what to say."},{"id":"mt-10-19-2","chapter":10,"verse":19,"sentence":2,"reference":"Matthew 10:19","text":"God will give you the right words at the right time."}]},{"chapter":10,"verse":20,"reference":"Matthew 10:20","text":"For it is not you who will be speaking—it will be the Spirit of your Father speaking through you.","sentences":[{"id":"mt-10-20-1","chapter":10,"verse":20,"sentence":1,"reference":"Matthew 10:20","text":"For it is not you who will be speaking—it will be the Spirit of your Father speaking through you."}]},{"chapter":10,"verse":21,"reference":"Matthew 10:21","text":"“A brother will betray his brother to death, a father will betray his own child, and children will rebel against their parents and cause them to be killed.","sentences":[{"id":"mt-10-21-1","chapter":10,"verse":21,"sentence":1,"reference":"Matthew 10:21","text":"“A brother will betray his brother to death, a father will betray his own child, and children will rebel against their parents and cause them to be killed."}]},{"chapter":10,"verse":22,"reference":"Matthew 10:22","text":"And all nations will hate you because you are my followers. But everyone who endures to the end will be saved.","sentences":[{"id":"mt-10-22-1","chapter":10,"verse":22,"sentence":1,"reference":"Matthew 10:22","text":"And all nations will hate you because you are my followers."},{"id":"mt-10-22-2","chapter":10,"verse":22,"sentence":2,"reference":"Matthew 10:22","text":"But everyone who endures to the end will be saved."}]},{"chapter":10,"verse":23,"reference":"Matthew 10:23","text":"When you are persecuted in one town, flee to the next. I tell you the truth, the Son of Man will return before you have reached all the towns of Israel.","sentences":[{"id":"mt-10-23-1","chapter":10,"verse":23,"sentence":1,"reference":"Matthew 10:23","text":"When you are persecuted in one town, flee to the next."},{"id":"mt-10-23-2","chapter":10,"verse":23,"sentence":2,"reference":"Matthew 10:23","text":"I tell you the truth, the Son of Man will return before you have reached all the towns of Israel."}]},{"chapter":10,"verse":24,"reference":"Matthew 10:24","text":"“Students are not greater than their teacher, and slaves are not greater than their master.","sentences":[{"id":"mt-10-24-1","chapter":10,"verse":24,"sentence":1,"reference":"Matthew 10:24","text":"“Students are not greater than their teacher, and slaves are not greater than their master."}]},{"chapter":10,"verse":25,"reference":"Matthew 10:25","text":"Students are to be like their teacher, and slaves are to be like their master. And since I, the master of the household, have been called the prince of demons, the members of my household will be called by even worse names!","sentences":[{"id":"mt-10-25-1","chapter":10,"verse":25,"sentence":1,"reference":"Matthew 10:25","text":"Students are to be like their teacher, and slaves are to be like their master."},{"id":"mt-10-25-2","chapter":10,"verse":25,"sentence":2,"reference":"Matthew 10:25","text":"And since I, the master of the household, have been called the prince of demons, the members of my household will be called by even worse names!"}]},{"chapter":10,"verse":26,"reference":"Matthew 10:26","text":"“But don’t be afraid of those who threaten you. For the time is coming when everything that is covered will be revealed, and all that is secret will be made known to all.","sentences":[{"id":"mt-10-26-1","chapter":10,"verse":26,"sentence":1,"reference":"Matthew 10:26","text":"“But don’t be afraid of those who threaten you."},{"id":"mt-10-26-2","chapter":10,"verse":26,"sentence":2,"reference":"Matthew 10:26","text":"For the time is coming when everything that is covered will be revealed, and all that is secret will be made known to all."}]},{"chapter":10,"verse":27,"reference":"Matthew 10:27","text":"What I tell you now in the darkness, shout abroad when daybreak comes. What I whisper in your ear, shout from the housetops for all to hear!","sentences":[{"id":"mt-10-27-1","chapter":10,"verse":27,"sentence":1,"reference":"Matthew 10:27","text":"What I tell you now in the darkness, shout abroad when daybreak comes."},{"id":"mt-10-27-2","chapter":10,"verse":27,"sentence":2,"reference":"Matthew 10:27","text":"What I whisper in your ear, shout from the housetops for all to hear!"}]},{"chapter":10,"verse":28,"reference":"Matthew 10:28","text":"“Don’t be afraid of those who want to kill your body; they cannot touch your soul. Fear only God, who can destroy both soul and body in hell.","sentences":[{"id":"mt-10-28-1","chapter":10,"verse":28,"sentence":1,"reference":"Matthew 10:28","text":"“Don’t be afraid of those who want to kill your body; they cannot touch your soul."},{"id":"mt-10-28-2","chapter":10,"verse":28,"sentence":2,"reference":"Matthew 10:28","text":"Fear only God, who can destroy both soul and body in hell."}]},{"chapter":10,"verse":29,"reference":"Matthew 10:29","text":"What is the price of two sparrows—one copper coin? But not a single sparrow can fall to the ground without your Father knowing it.","sentences":[{"id":"mt-10-29-1","chapter":10,"verse":29,"sentence":1,"reference":"Matthew 10:29","text":"What is the price of two sparrows—one copper coin?"},{"id":"mt-10-29-2","chapter":10,"verse":29,"sentence":2,"reference":"Matthew 10:29","text":"But not a single sparrow can fall to the ground without your Father knowing it."}]},{"chapter":10,"verse":30,"reference":"Matthew 10:30","text":"And the very hairs on your head are all numbered.","sentences":[{"id":"mt-10-30-1","chapter":10,"verse":30,"sentence":1,"reference":"Matthew 10:30","text":"And the very hairs on your head are all numbered."}]},{"chapter":10,"verse":31,"reference":"Matthew 10:31","text":"So don’t be afraid; you are more valuable to God than a whole flock of sparrows.","sentences":[{"id":"mt-10-31-1","chapter":10,"verse":31,"sentence":1,"reference":"Matthew 10:31","text":"So don’t be afraid; you are more valuable to God than a whole flock of sparrows."}]},{"chapter":10,"verse":32,"reference":"Matthew 10:32","text":"“Everyone who acknowledges me publicly here on earth, I will also acknowledge before my Father in heaven.","sentences":[{"id":"mt-10-32-1","chapter":10,"verse":32,"sentence":1,"reference":"Matthew 10:32","text":"“Everyone who acknowledges me publicly here on earth, I will also acknowledge before my Father in heaven."}]},{"chapter":10,"verse":33,"reference":"Matthew 10:33","text":"But everyone who denies me here on earth, I will also deny before my Father in heaven.","sentences":[{"id":"mt-10-33-1","chapter":10,"verse":33,"sentence":1,"reference":"Matthew 10:33","text":"But everyone who denies me here on earth, I will also deny before my Father in heaven."}]},{"chapter":10,"verse":34,"reference":"Matthew 10:34","text":"“Don’t imagine that I came to bring peace to the earth! I came not to bring peace, but a sword.","sentences":[{"id":"mt-10-34-1","chapter":10,"verse":34,"sentence":1,"reference":"Matthew 10:34","text":"“Don’t imagine that I came to bring peace to the earth!"},{"id":"mt-10-34-2","chapter":10,"verse":34,"sentence":2,"reference":"Matthew 10:34","text":"I came not to bring peace, but a sword."}]},{"chapter":10,"verse":35,"reference":"Matthew 10:35","text":"‘I have come to set a man against his father, a daughter against her mother, and a daughter-in-law against her mother-in-law.","sentences":[{"id":"mt-10-35-1","chapter":10,"verse":35,"sentence":1,"reference":"Matthew 10:35","text":"‘I have come to set a man against his father, a daughter against her mother, and a daughter-in-law against her mother-in-law."}]},{"chapter":10,"verse":36,"reference":"Matthew 10:36","text":"Your enemies will be right in your own household!’","sentences":[{"id":"mt-10-36-1","chapter":10,"verse":36,"sentence":1,"reference":"Matthew 10:36","text":"Your enemies will be right in your own household!’"}]},{"chapter":10,"verse":37,"reference":"Matthew 10:37","text":"“If you love your father or mother more than you love me, you are not worthy of being mine; or if you love your son or daughter more than me, you are not worthy of being mine.","sentences":[{"id":"mt-10-37-1","chapter":10,"verse":37,"sentence":1,"reference":"Matthew 10:37","text":"“If you love your father or mother more than you love me, you are not worthy of being mine; or if you love your son or daughter more than me, you are not worthy of being mine."}]},{"chapter":10,"verse":38,"reference":"Matthew 10:38","text":"If you refuse to take up your cross and follow me, you are not worthy of being mine.","sentences":[{"id":"mt-10-38-1","chapter":10,"verse":38,"sentence":1,"reference":"Matthew 10:38","text":"If you refuse to take up your cross and follow me, you are not worthy of being mine."}]},{"chapter":10,"verse":39,"reference":"Matthew 10:39","text":"If you cling to your life, you will lose it; but if you give up your life for me, you will find it.","sentences":[{"id":"mt-10-39-1","chapter":10,"verse":39,"sentence":1,"reference":"Matthew 10:39","text":"If you cling to your life, you will lose it; but if you give up your life for me, you will find it."}]},{"chapter":10,"verse":40,"reference":"Matthew 10:40","text":"“Anyone who receives you receives me, and anyone who receives me receives the Father who sent me.","sentences":[{"id":"mt-10-40-1","chapter":10,"verse":40,"sentence":1,"reference":"Matthew 10:40","text":"“Anyone who receives you receives me, and anyone who receives me receives the Father who sent me."}]},{"chapter":10,"verse":41,"reference":"Matthew 10:41","text":"If you receive a prophet as one who speaks for God, you will be given the same reward as a prophet. And if you receive righteous people because of their righteousness, you will be given a reward like theirs.","sentences":[{"id":"mt-10-41-1","chapter":10,"verse":41,"sentence":1,"reference":"Matthew 10:41","text":"If you receive a prophet as one who speaks for God, you will be given the same reward as a prophet."},{"id":"mt-10-41-2","chapter":10,"verse":41,"sentence":2,"reference":"Matthew 10:41","text":"And if you receive righteous people because of their righteousness, you will be given a reward like theirs."}]},{"chapter":10,"verse":42,"reference":"Matthew 10:42","text":"And if you give even a cup of cold water to one of the least of my followers, you will surely be rewarded.”","sentences":[{"id":"mt-10-42-1","chapter":10,"verse":42,"sentence":1,"reference":"Matthew 10:42","text":"And if you give even a cup of cold water to one of the least of my followers, you will surely be rewarded.”"}]}]},{"chapter":11,"verses":[{"chapter":11,"verse":1,"reference":"Matthew 11:1","text":"When Jesus had finished giving these instructions to his twelve disciples, he went out to teach and preach in towns throughout the region.","sentences":[{"id":"mt-11-1-1","chapter":11,"verse":1,"sentence":1,"reference":"Matthew 11:1","text":"When Jesus had finished giving these instructions to his twelve disciples, he went out to teach and preach in towns throughout the region."}]},{"chapter":11,"verse":2,"reference":"Matthew 11:2","text":"John the Baptist, who was in prison, heard about all the things the Messiah was doing. So he sent his disciples to ask Jesus,","sentences":[{"id":"mt-11-2-1","chapter":11,"verse":2,"sentence":1,"reference":"Matthew 11:2","text":"John the Baptist, who was in prison, heard about all the things the Messiah was doing."},{"id":"mt-11-2-2","chapter":11,"verse":2,"sentence":2,"reference":"Matthew 11:2","text":"So he sent his disciples to ask Jesus,"}]},{"chapter":11,"verse":3,"reference":"Matthew 11:3","text":"“Are you the Messiah we’ve been expecting, or should we keep looking for someone else?”","sentences":[{"id":"mt-11-3-1","chapter":11,"verse":3,"sentence":1,"reference":"Matthew 11:3","text":"“Are you the Messiah we’ve been expecting, or should we keep looking for someone else?”"}]},{"chapter":11,"verse":4,"reference":"Matthew 11:4","text":"Jesus told them, “Go back to John and tell him what you have heard and seen—","sentences":[{"id":"mt-11-4-1","chapter":11,"verse":4,"sentence":1,"reference":"Matthew 11:4","text":"Jesus told them, “Go back to John and tell him what you have heard and seen—"}]},{"chapter":11,"verse":5,"reference":"Matthew 11:5","text":"the blind see, the lame walk, those with leprosy are cured, the deaf hear, the dead are raised to life, and the Good News is being preached to the poor.”","sentences":[{"id":"mt-11-5-1","chapter":11,"verse":5,"sentence":1,"reference":"Matthew 11:5","text":"the blind see, the lame walk, those with leprosy are cured, the deaf hear, the dead are raised to life, and the Good News is being preached to the poor.”"}]},{"chapter":11,"verse":6,"reference":"Matthew 11:6","text":"And he added, “God blesses those who do not fall away because of me.”","sentences":[{"id":"mt-11-6-1","chapter":11,"verse":6,"sentence":1,"reference":"Matthew 11:6","text":"And he added, “God blesses those who do not fall away because of me.”"}]},{"chapter":11,"verse":7,"reference":"Matthew 11:7","text":"As John’s disciples were leaving, Jesus began talking about him to the crowds. “What kind of man did you go into the wilderness to see? Was he a weak reed, swayed by every breath of wind?","sentences":[{"id":"mt-11-7-1","chapter":11,"verse":7,"sentence":1,"reference":"Matthew 11:7","text":"As John’s disciples were leaving, Jesus began talking about him to the crowds."},{"id":"mt-11-7-2","chapter":11,"verse":7,"sentence":2,"reference":"Matthew 11:7","text":"“What kind of man did you go into the wilderness to see?"},{"id":"mt-11-7-3","chapter":11,"verse":7,"sentence":3,"reference":"Matthew 11:7","text":"Was he a weak reed, swayed by every breath of wind?"}]},{"chapter":11,"verse":8,"reference":"Matthew 11:8","text":"Or were you expecting to see a man dressed in expensive clothes? No, people with expensive clothes live in palaces.","sentences":[{"id":"mt-11-8-1","chapter":11,"verse":8,"sentence":1,"reference":"Matthew 11:8","text":"Or were you expecting to see a man dressed in expensive clothes?"},{"id":"mt-11-8-2","chapter":11,"verse":8,"sentence":2,"reference":"Matthew 11:8","text":"No, people with expensive clothes live in palaces."}]},{"chapter":11,"verse":9,"reference":"Matthew 11:9","text":"Were you looking for a prophet? Yes, and he is more than a prophet.","sentences":[{"id":"mt-11-9-1","chapter":11,"verse":9,"sentence":1,"reference":"Matthew 11:9","text":"Were you looking for a prophet?"},{"id":"mt-11-9-2","chapter":11,"verse":9,"sentence":2,"reference":"Matthew 11:9","text":"Yes, and he is more than a prophet."}]},{"chapter":11,"verse":10,"reference":"Matthew 11:10","text":"John is the man to whom the Scriptures refer when they say, ‘Look, I am sending my messenger ahead of you, and he will prepare your way before you.’","sentences":[{"id":"mt-11-10-1","chapter":11,"verse":10,"sentence":1,"reference":"Matthew 11:10","text":"John is the man to whom the Scriptures refer when they say, ‘Look, I am sending my messenger ahead of you, and he will prepare your way before you.’"}]},{"chapter":11,"verse":11,"reference":"Matthew 11:11","text":"“I tell you the truth, of all who have ever lived, none is greater than John the Baptist. Yet even the least person in the Kingdom of Heaven is greater than he is!","sentences":[{"id":"mt-11-11-1","chapter":11,"verse":11,"sentence":1,"reference":"Matthew 11:11","text":"“I tell you the truth, of all who have ever lived, none is greater than John the Baptist."},{"id":"mt-11-11-2","chapter":11,"verse":11,"sentence":2,"reference":"Matthew 11:11","text":"Yet even the least person in the Kingdom of Heaven is greater than he is!"}]},{"chapter":11,"verse":12,"reference":"Matthew 11:12","text":"And from the time John the Baptist began preaching until now, the Kingdom of Heaven has been forcefully advancing, and violent people are attacking it.","sentences":[{"id":"mt-11-12-1","chapter":11,"verse":12,"sentence":1,"reference":"Matthew 11:12","text":"And from the time John the Baptist began preaching until now, the Kingdom of Heaven has been forcefully advancing, and violent people are attacking it."}]},{"chapter":11,"verse":13,"reference":"Matthew 11:13","text":"For before John came, all the prophets and the law of Moses looked forward to this present time.","sentences":[{"id":"mt-11-13-1","chapter":11,"verse":13,"sentence":1,"reference":"Matthew 11:13","text":"For before John came, all the prophets and the law of Moses looked forward to this present time."}]},{"chapter":11,"verse":14,"reference":"Matthew 11:14","text":"And if you are willing to accept what I say, he is Elijah, the one the prophets said would come.","sentences":[{"id":"mt-11-14-1","chapter":11,"verse":14,"sentence":1,"reference":"Matthew 11:14","text":"And if you are willing to accept what I say, he is Elijah, the one the prophets said would come."}]},{"chapter":11,"verse":15,"reference":"Matthew 11:15","text":"Anyone with ears to hear should listen and understand!","sentences":[{"id":"mt-11-15-1","chapter":11,"verse":15,"sentence":1,"reference":"Matthew 11:15","text":"Anyone with ears to hear should listen and understand!"}]},{"chapter":11,"verse":16,"reference":"Matthew 11:16","text":"“To what can I compare this generation? It is like children playing a game in the public square. They complain to their friends,","sentences":[{"id":"mt-11-16-1","chapter":11,"verse":16,"sentence":1,"reference":"Matthew 11:16","text":"“To what can I compare this generation?"},{"id":"mt-11-16-2","chapter":11,"verse":16,"sentence":2,"reference":"Matthew 11:16","text":"It is like children playing a game in the public square."},{"id":"mt-11-16-3","chapter":11,"verse":16,"sentence":3,"reference":"Matthew 11:16","text":"They complain to their friends,"}]},{"chapter":11,"verse":17,"reference":"Matthew 11:17","text":"‘We played wedding songs, and you didn’t dance, so we played funeral songs, and you didn’t mourn.’","sentences":[{"id":"mt-11-17-1","chapter":11,"verse":17,"sentence":1,"reference":"Matthew 11:17","text":"‘We played wedding songs, and you didn’t dance, so we played funeral songs, and you didn’t mourn.’"}]},{"chapter":11,"verse":18,"reference":"Matthew 11:18","text":"For John didn’t spend his time eating and drinking, and you say, ‘He’s possessed by a demon.’","sentences":[{"id":"mt-11-18-1","chapter":11,"verse":18,"sentence":1,"reference":"Matthew 11:18","text":"For John didn’t spend his time eating and drinking, and you say, ‘He’s possessed by a demon.’"}]},{"chapter":11,"verse":19,"reference":"Matthew 11:19","text":"The Son of Man, on the other hand, feasts and drinks, and you say, ‘He’s a glutton and a drunkard, and a friend of tax collectors and other sinners!’ But wisdom is shown to be right by its results.”","sentences":[{"id":"mt-11-19-1","chapter":11,"verse":19,"sentence":1,"reference":"Matthew 11:19","text":"The Son of Man, on the other hand, feasts and drinks, and you say, ‘He’s a glutton and a drunkard, and a friend of tax collectors and other sinners!’"},{"id":"mt-11-19-2","chapter":11,"verse":19,"sentence":2,"reference":"Matthew 11:19","text":"But wisdom is shown to be right by its results.”"}]},{"chapter":11,"verse":20,"reference":"Matthew 11:20","text":"Then Jesus began to denounce the towns where he had done so many of his miracles, because they hadn’t repented of their sins and turned to God.","sentences":[{"id":"mt-11-20-1","chapter":11,"verse":20,"sentence":1,"reference":"Matthew 11:20","text":"Then Jesus began to denounce the towns where he had done so many of his miracles, because they hadn’t repented of their sins and turned to God."}]},{"chapter":11,"verse":21,"reference":"Matthew 11:21","text":"“What sorrow awaits you, Korazin and Bethsaida! For if the miracles I did in you had been done in wicked Tyre and Sidon, their people would have repented of their sins long ago, clothing themselves in burlap and throwing ashes on their heads to show their remorse.","sentences":[{"id":"mt-11-21-1","chapter":11,"verse":21,"sentence":1,"reference":"Matthew 11:21","text":"“What sorrow awaits you, Korazin and Bethsaida!"},{"id":"mt-11-21-2","chapter":11,"verse":21,"sentence":2,"reference":"Matthew 11:21","text":"For if the miracles I did in you had been done in wicked Tyre and Sidon, their people would have repented of their sins long ago, clothing themselves in burlap and throwing ashes on their heads to show their remorse."}]},{"chapter":11,"verse":22,"reference":"Matthew 11:22","text":"I tell you, Tyre and Sidon will be better off on judgment day than you.","sentences":[{"id":"mt-11-22-1","chapter":11,"verse":22,"sentence":1,"reference":"Matthew 11:22","text":"I tell you, Tyre and Sidon will be better off on judgment day than you."}]},{"chapter":11,"verse":23,"reference":"Matthew 11:23","text":"“And you people of Capernaum, will you be honored in heaven? No, you will go down to the place of the dead. For if the miracles I did for you had been done in wicked Sodom, it would still be here today.","sentences":[{"id":"mt-11-23-1","chapter":11,"verse":23,"sentence":1,"reference":"Matthew 11:23","text":"“And you people of Capernaum, will you be honored in heaven?"},{"id":"mt-11-23-2","chapter":11,"verse":23,"sentence":2,"reference":"Matthew 11:23","text":"No, you will go down to the place of the dead."},{"id":"mt-11-23-3","chapter":11,"verse":23,"sentence":3,"reference":"Matthew 11:23","text":"For if the miracles I did for you had been done in wicked Sodom, it would still be here today."}]},{"chapter":11,"verse":24,"reference":"Matthew 11:24","text":"I tell you, even Sodom will be better off on judgment day than you.”","sentences":[{"id":"mt-11-24-1","chapter":11,"verse":24,"sentence":1,"reference":"Matthew 11:24","text":"I tell you, even Sodom will be better off on judgment day than you.”"}]},{"chapter":11,"verse":25,"reference":"Matthew 11:25","text":"At that time Jesus prayed this prayer: “O Father, Lord of heaven and earth, thank you for hiding these things from those who think themselves wise and clever, and for revealing them to the childlike.","sentences":[{"id":"mt-11-25-1","chapter":11,"verse":25,"sentence":1,"reference":"Matthew 11:25","text":"At that time Jesus prayed this prayer: “O Father, Lord of heaven and earth, thank you for hiding these things from those who think themselves wise and clever, and for revealing them to the childlike."}]},{"chapter":11,"verse":26,"reference":"Matthew 11:26","text":"Yes, Father, it pleased you to do it this way!","sentences":[{"id":"mt-11-26-1","chapter":11,"verse":26,"sentence":1,"reference":"Matthew 11:26","text":"Yes, Father, it pleased you to do it this way!"}]},{"chapter":11,"verse":27,"reference":"Matthew 11:27","text":"“My Father has entrusted everything to me. No one truly knows the Son except the Father, and no one truly knows the Father except the Son and those to whom the Son chooses to reveal him.”","sentences":[{"id":"mt-11-27-1","chapter":11,"verse":27,"sentence":1,"reference":"Matthew 11:27","text":"“My Father has entrusted everything to me."},{"id":"mt-11-27-2","chapter":11,"verse":27,"sentence":2,"reference":"Matthew 11:27","text":"No one truly knows the Son except the Father, and no one truly knows the Father except the Son and those to whom the Son chooses to reveal him.”"}]},{"chapter":11,"verse":28,"reference":"Matthew 11:28","text":"Then Jesus said, “Come to me, all of you who are weary and carry heavy burdens, and I will give you rest.","sentences":[{"id":"mt-11-28-1","chapter":11,"verse":28,"sentence":1,"reference":"Matthew 11:28","text":"Then Jesus said, “Come to me, all of you who are weary and carry heavy burdens, and I will give you rest."}]},{"chapter":11,"verse":29,"reference":"Matthew 11:29","text":"Take my yoke upon you. Let me teach you, because I am humble and gentle at heart, and you will find rest for your souls.","sentences":[{"id":"mt-11-29-1","chapter":11,"verse":29,"sentence":1,"reference":"Matthew 11:29","text":"Take my yoke upon you."},{"id":"mt-11-29-2","chapter":11,"verse":29,"sentence":2,"reference":"Matthew 11:29","text":"Let me teach you, because I am humble and gentle at heart, and you will find rest for your souls."}]},{"chapter":11,"verse":30,"reference":"Matthew 11:30","text":"For my yoke is easy to bear, and the burden I give you is light.”","sentences":[{"id":"mt-11-30-1","chapter":11,"verse":30,"sentence":1,"reference":"Matthew 11:30","text":"For my yoke is easy to bear, and the burden I give you is light.”"}]}]},{"chapter":12,"verses":[{"chapter":12,"verse":1,"reference":"Matthew 12:1","text":"At about that time Jesus was walking through some grainfields on the Sabbath. His disciples were hungry, so they began breaking off some heads of grain and eating them.","sentences":[{"id":"mt-12-1-1","chapter":12,"verse":1,"sentence":1,"reference":"Matthew 12:1","text":"At about that time Jesus was walking through some grainfields on the Sabbath."},{"id":"mt-12-1-2","chapter":12,"verse":1,"sentence":2,"reference":"Matthew 12:1","text":"His disciples were hungry, so they began breaking off some heads of grain and eating them."}]},{"chapter":12,"verse":2,"reference":"Matthew 12:2","text":"But some Pharisees saw them do it and protested, “Look, your disciples are breaking the law by harvesting grain on the Sabbath.”","sentences":[{"id":"mt-12-2-1","chapter":12,"verse":2,"sentence":1,"reference":"Matthew 12:2","text":"But some Pharisees saw them do it and protested, “Look, your disciples are breaking the law by harvesting grain on the Sabbath.”"}]},{"chapter":12,"verse":3,"reference":"Matthew 12:3","text":"Jesus said to them, “Haven’t you read in the Scriptures what David did when he and his companions were hungry?","sentences":[{"id":"mt-12-3-1","chapter":12,"verse":3,"sentence":1,"reference":"Matthew 12:3","text":"Jesus said to them, “Haven’t you read in the Scriptures what David did when he and his companions were hungry?"}]},{"chapter":12,"verse":4,"reference":"Matthew 12:4","text":"He went into the house of God, and he and his companions broke the law by eating the sacred loaves of bread that only the priests are allowed to eat.","sentences":[{"id":"mt-12-4-1","chapter":12,"verse":4,"sentence":1,"reference":"Matthew 12:4","text":"He went into the house of God, and he and his companions broke the law by eating the sacred loaves of bread that only the priests are allowed to eat."}]},{"chapter":12,"verse":5,"reference":"Matthew 12:5","text":"And haven’t you read in the law of Moses that the priests on duty in the Temple may work on the Sabbath?","sentences":[{"id":"mt-12-5-1","chapter":12,"verse":5,"sentence":1,"reference":"Matthew 12:5","text":"And haven’t you read in the law of Moses that the priests on duty in the Temple may work on the Sabbath?"}]},{"chapter":12,"verse":6,"reference":"Matthew 12:6","text":"I tell you, there is one here who is even greater than the Temple!","sentences":[{"id":"mt-12-6-1","chapter":12,"verse":6,"sentence":1,"reference":"Matthew 12:6","text":"I tell you, there is one here who is even greater than the Temple!"}]},{"chapter":12,"verse":7,"reference":"Matthew 12:7","text":"But you would not have condemned my innocent disciples if you knew the meaning of this Scripture: ‘I want you to show mercy, not offer sacrifices.’","sentences":[{"id":"mt-12-7-1","chapter":12,"verse":7,"sentence":1,"reference":"Matthew 12:7","text":"But you would not have condemned my innocent disciples if you knew the meaning of this Scripture: ‘I want you to show mercy, not offer sacrifices.’"}]},{"chapter":12,"verse":8,"reference":"Matthew 12:8","text":"For the Son of Man is Lord, even over the Sabbath!”","sentences":[{"id":"mt-12-8-1","chapter":12,"verse":8,"sentence":1,"reference":"Matthew 12:8","text":"For the Son of Man is Lord, even over the Sabbath!”"}]},{"chapter":12,"verse":9,"reference":"Matthew 12:9","text":"Then Jesus went over to their synagogue,","sentences":[{"id":"mt-12-9-1","chapter":12,"verse":9,"sentence":1,"reference":"Matthew 12:9","text":"Then Jesus went over to their synagogue,"}]},{"chapter":12,"verse":10,"reference":"Matthew 12:10","text":"where he noticed a man with a deformed hand. The Pharisees asked Jesus, “Does the law permit a person to work by healing on the Sabbath?” (They were hoping he would say yes, so they could bring charges against him.)","sentences":[{"id":"mt-12-10-1","chapter":12,"verse":10,"sentence":1,"reference":"Matthew 12:10","text":"where he noticed a man with a deformed hand."},{"id":"mt-12-10-2","chapter":12,"verse":10,"sentence":2,"reference":"Matthew 12:10","text":"The Pharisees asked Jesus, “Does the law permit a person to work by healing on the Sabbath?”"},{"id":"mt-12-10-3","chapter":12,"verse":10,"sentence":3,"reference":"Matthew 12:10","text":"(They were hoping he would say yes, so they could bring charges against him.)"}]},{"chapter":12,"verse":11,"reference":"Matthew 12:11","text":"And he answered, “If you had a sheep that fell into a well on the Sabbath, wouldn’t you work to pull it out? Of course you would.","sentences":[{"id":"mt-12-11-1","chapter":12,"verse":11,"sentence":1,"reference":"Matthew 12:11","text":"And he answered, “If you had a sheep that fell into a well on the Sabbath, wouldn’t you work to pull it out?"},{"id":"mt-12-11-2","chapter":12,"verse":11,"sentence":2,"reference":"Matthew 12:11","text":"Of course you would."}]},{"chapter":12,"verse":12,"reference":"Matthew 12:12","text":"And how much more valuable is a person than a sheep! Yes, the law permits a person to do good on the Sabbath.”","sentences":[{"id":"mt-12-12-1","chapter":12,"verse":12,"sentence":1,"reference":"Matthew 12:12","text":"And how much more valuable is a person than a sheep!"},{"id":"mt-12-12-2","chapter":12,"verse":12,"sentence":2,"reference":"Matthew 12:12","text":"Yes, the law permits a person to do good on the Sabbath.”"}]},{"chapter":12,"verse":13,"reference":"Matthew 12:13","text":"Then he said to the man, “Hold out your hand.” So the man held out his hand, and it was restored, just like the other one!","sentences":[{"id":"mt-12-13-1","chapter":12,"verse":13,"sentence":1,"reference":"Matthew 12:13","text":"Then he said to the man, “Hold out your hand.”"},{"id":"mt-12-13-2","chapter":12,"verse":13,"sentence":2,"reference":"Matthew 12:13","text":"So the man held out his hand, and it was restored, just like the other one!"}]},{"chapter":12,"verse":14,"reference":"Matthew 12:14","text":"Then the Pharisees called a meeting to plot how to kill Jesus.","sentences":[{"id":"mt-12-14-1","chapter":12,"verse":14,"sentence":1,"reference":"Matthew 12:14","text":"Then the Pharisees called a meeting to plot how to kill Jesus."}]},{"chapter":12,"verse":15,"reference":"Matthew 12:15","text":"But Jesus knew what they were planning. So he left that area, and many people followed him. He healed all the sick among them,","sentences":[{"id":"mt-12-15-1","chapter":12,"verse":15,"sentence":1,"reference":"Matthew 12:15","text":"But Jesus knew what they were planning."},{"id":"mt-12-15-2","chapter":12,"verse":15,"sentence":2,"reference":"Matthew 12:15","text":"So he left that area, and many people followed him."},{"id":"mt-12-15-3","chapter":12,"verse":15,"sentence":3,"reference":"Matthew 12:15","text":"He healed all the sick among them,"}]},{"chapter":12,"verse":16,"reference":"Matthew 12:16","text":"but he warned them not to reveal who he was.","sentences":[{"id":"mt-12-16-1","chapter":12,"verse":16,"sentence":1,"reference":"Matthew 12:16","text":"but he warned them not to reveal who he was."}]},{"chapter":12,"verse":17,"reference":"Matthew 12:17","text":"This fulfilled the prophecy of Isaiah concerning him:","sentences":[{"id":"mt-12-17-1","chapter":12,"verse":17,"sentence":1,"reference":"Matthew 12:17","text":"This fulfilled the prophecy of Isaiah concerning him:"}]},{"chapter":12,"verse":18,"reference":"Matthew 12:18","text":"“Look at my Servant, whom I have chosen. He is my Beloved, who pleases me. I will put my Spirit upon him, and he will proclaim justice to the nations.","sentences":[{"id":"mt-12-18-1","chapter":12,"verse":18,"sentence":1,"reference":"Matthew 12:18","text":"“Look at my Servant, whom I have chosen."},{"id":"mt-12-18-2","chapter":12,"verse":18,"sentence":2,"reference":"Matthew 12:18","text":"He is my Beloved, who pleases me."},{"id":"mt-12-18-3","chapter":12,"verse":18,"sentence":3,"reference":"Matthew 12:18","text":"I will put my Spirit upon him, and he will proclaim justice to the nations."}]},{"chapter":12,"verse":19,"reference":"Matthew 12:19","text":"He will not fight or shout or raise his voice in public.","sentences":[{"id":"mt-12-19-1","chapter":12,"verse":19,"sentence":1,"reference":"Matthew 12:19","text":"He will not fight or shout or raise his voice in public."}]},{"chapter":12,"verse":20,"reference":"Matthew 12:20","text":"He will not crush the weakest reed or put out a flickering candle. Finally he will cause justice to be victorious.","sentences":[{"id":"mt-12-20-1","chapter":12,"verse":20,"sentence":1,"reference":"Matthew 12:20","text":"He will not crush the weakest reed or put out a flickering candle."},{"id":"mt-12-20-2","chapter":12,"verse":20,"sentence":2,"reference":"Matthew 12:20","text":"Finally he will cause justice to be victorious."}]},{"chapter":12,"verse":21,"reference":"Matthew 12:21","text":"And his name will be the hope of all the world.”","sentences":[{"id":"mt-12-21-1","chapter":12,"verse":21,"sentence":1,"reference":"Matthew 12:21","text":"And his name will be the hope of all the world.”"}]},{"chapter":12,"verse":22,"reference":"Matthew 12:22","text":"Then a demon-possessed man, who was blind and couldn’t speak, was brought to Jesus. He healed the man so that he could both speak and see.","sentences":[{"id":"mt-12-22-1","chapter":12,"verse":22,"sentence":1,"reference":"Matthew 12:22","text":"Then a demon-possessed man, who was blind and couldn’t speak, was brought to Jesus."},{"id":"mt-12-22-2","chapter":12,"verse":22,"sentence":2,"reference":"Matthew 12:22","text":"He healed the man so that he could both speak and see."}]},{"chapter":12,"verse":23,"reference":"Matthew 12:23","text":"The crowd was amazed and asked, “Could it be that Jesus is the Son of David, the Messiah?”","sentences":[{"id":"mt-12-23-1","chapter":12,"verse":23,"sentence":1,"reference":"Matthew 12:23","text":"The crowd was amazed and asked, “Could it be that Jesus is the Son of David, the Messiah?”"}]},{"chapter":12,"verse":24,"reference":"Matthew 12:24","text":"But when the Pharisees heard about the miracle, they said, “No wonder he can cast out demons. He gets his power from Satan, the prince of demons.”","sentences":[{"id":"mt-12-24-1","chapter":12,"verse":24,"sentence":1,"reference":"Matthew 12:24","text":"But when the Pharisees heard about the miracle, they said, “No wonder he can cast out demons."},{"id":"mt-12-24-2","chapter":12,"verse":24,"sentence":2,"reference":"Matthew 12:24","text":"He gets his power from Satan, the prince of demons.”"}]},{"chapter":12,"verse":25,"reference":"Matthew 12:25","text":"Jesus knew their thoughts and replied, “Any kingdom divided by civil war is doomed. A town or family splintered by feuding will fall apart.","sentences":[{"id":"mt-12-25-1","chapter":12,"verse":25,"sentence":1,"reference":"Matthew 12:25","text":"Jesus knew their thoughts and replied, “Any kingdom divided by civil war is doomed."},{"id":"mt-12-25-2","chapter":12,"verse":25,"sentence":2,"reference":"Matthew 12:25","text":"A town or family splintered by feuding will fall apart."}]},{"chapter":12,"verse":26,"reference":"Matthew 12:26","text":"And if Satan is casting out Satan, he is divided and fighting against himself. His own kingdom will not survive.","sentences":[{"id":"mt-12-26-1","chapter":12,"verse":26,"sentence":1,"reference":"Matthew 12:26","text":"And if Satan is casting out Satan, he is divided and fighting against himself."},{"id":"mt-12-26-2","chapter":12,"verse":26,"sentence":2,"reference":"Matthew 12:26","text":"His own kingdom will not survive."}]},{"chapter":12,"verse":27,"reference":"Matthew 12:27","text":"And if I am empowered by Satan, what about your own exorcists? They cast out demons, too, so they will condemn you for what you have said.","sentences":[{"id":"mt-12-27-1","chapter":12,"verse":27,"sentence":1,"reference":"Matthew 12:27","text":"And if I am empowered by Satan, what about your own exorcists?"},{"id":"mt-12-27-2","chapter":12,"verse":27,"sentence":2,"reference":"Matthew 12:27","text":"They cast out demons, too, so they will condemn you for what you have said."}]},{"chapter":12,"verse":28,"reference":"Matthew 12:28","text":"But if I am casting out demons by the Spirit of God, then the Kingdom of God has arrived among you.","sentences":[{"id":"mt-12-28-1","chapter":12,"verse":28,"sentence":1,"reference":"Matthew 12:28","text":"But if I am casting out demons by the Spirit of God, then the Kingdom of God has arrived among you."}]},{"chapter":12,"verse":29,"reference":"Matthew 12:29","text":"For who is powerful enough to enter the house of a strong man and plunder his goods? Only someone even stronger—someone who could tie him up and then plunder his house.","sentences":[{"id":"mt-12-29-1","chapter":12,"verse":29,"sentence":1,"reference":"Matthew 12:29","text":"For who is powerful enough to enter the house of a strong man and plunder his goods?"},{"id":"mt-12-29-2","chapter":12,"verse":29,"sentence":2,"reference":"Matthew 12:29","text":"Only someone even stronger—someone who could tie him up and then plunder his house."}]},{"chapter":12,"verse":30,"reference":"Matthew 12:30","text":"“Anyone who isn’t with me opposes me, and anyone who isn’t working with me is actually working against me.","sentences":[{"id":"mt-12-30-1","chapter":12,"verse":30,"sentence":1,"reference":"Matthew 12:30","text":"“Anyone who isn’t with me opposes me, and anyone who isn’t working with me is actually working against me."}]},{"chapter":12,"verse":31,"reference":"Matthew 12:31","text":"“So I tell you, every sin and blasphemy can be forgiven—except blasphemy against the Holy Spirit, which will never be forgiven.","sentences":[{"id":"mt-12-31-1","chapter":12,"verse":31,"sentence":1,"reference":"Matthew 12:31","text":"“So I tell you, every sin and blasphemy can be forgiven—except blasphemy against the Holy Spirit, which will never be forgiven."}]},{"chapter":12,"verse":32,"reference":"Matthew 12:32","text":"Anyone who speaks against the Son of Man can be forgiven, but anyone who speaks against the Holy Spirit will never be forgiven, either in this world or in the world to come.","sentences":[{"id":"mt-12-32-1","chapter":12,"verse":32,"sentence":1,"reference":"Matthew 12:32","text":"Anyone who speaks against the Son of Man can be forgiven, but anyone who speaks against the Holy Spirit will never be forgiven, either in this world or in the world to come."}]},{"chapter":12,"verse":33,"reference":"Matthew 12:33","text":"“A tree is identified by its fruit. If a tree is good, its fruit will be good. If a tree is bad, its fruit will be bad.","sentences":[{"id":"mt-12-33-1","chapter":12,"verse":33,"sentence":1,"reference":"Matthew 12:33","text":"“A tree is identified by its fruit."},{"id":"mt-12-33-2","chapter":12,"verse":33,"sentence":2,"reference":"Matthew 12:33","text":"If a tree is good, its fruit will be good."},{"id":"mt-12-33-3","chapter":12,"verse":33,"sentence":3,"reference":"Matthew 12:33","text":"If a tree is bad, its fruit will be bad."}]},{"chapter":12,"verse":34,"reference":"Matthew 12:34","text":"You brood of snakes! How could evil men like you speak what is good and right? For whatever is in your heart determines what you say.","sentences":[{"id":"mt-12-34-1","chapter":12,"verse":34,"sentence":1,"reference":"Matthew 12:34","text":"You brood of snakes!"},{"id":"mt-12-34-2","chapter":12,"verse":34,"sentence":2,"reference":"Matthew 12:34","text":"How could evil men like you speak what is good and right?"},{"id":"mt-12-34-3","chapter":12,"verse":34,"sentence":3,"reference":"Matthew 12:34","text":"For whatever is in your heart determines what you say."}]},{"chapter":12,"verse":35,"reference":"Matthew 12:35","text":"A good person produces good things from the treasury of a good heart, and an evil person produces evil things from the treasury of an evil heart.","sentences":[{"id":"mt-12-35-1","chapter":12,"verse":35,"sentence":1,"reference":"Matthew 12:35","text":"A good person produces good things from the treasury of a good heart, and an evil person produces evil things from the treasury of an evil heart."}]},{"chapter":12,"verse":36,"reference":"Matthew 12:36","text":"And I tell you this, you must give an account on judgment day for every idle word you speak.","sentences":[{"id":"mt-12-36-1","chapter":12,"verse":36,"sentence":1,"reference":"Matthew 12:36","text":"And I tell you this, you must give an account on judgment day for every idle word you speak."}]},{"chapter":12,"verse":37,"reference":"Matthew 12:37","text":"The words you say will either acquit you or condemn you.”","sentences":[{"id":"mt-12-37-1","chapter":12,"verse":37,"sentence":1,"reference":"Matthew 12:37","text":"The words you say will either acquit you or condemn you.”"}]},{"chapter":12,"verse":38,"reference":"Matthew 12:38","text":"One day some teachers of religious law and Pharisees came to Jesus and said, “Teacher, we want you to show us a miraculous sign to prove your authority.”","sentences":[{"id":"mt-12-38-1","chapter":12,"verse":38,"sentence":1,"reference":"Matthew 12:38","text":"One day some teachers of religious law and Pharisees came to Jesus and said, “Teacher, we want you to show us a miraculous sign to prove your authority.”"}]},{"chapter":12,"verse":39,"reference":"Matthew 12:39","text":"But Jesus replied, “Only an evil, adulterous generation would demand a miraculous sign; but the only sign I will give them is the sign of the prophet Jonah.","sentences":[{"id":"mt-12-39-1","chapter":12,"verse":39,"sentence":1,"reference":"Matthew 12:39","text":"But Jesus replied, “Only an evil, adulterous generation would demand a miraculous sign; but the only sign I will give them is the sign of the prophet Jonah."}]},{"chapter":12,"verse":40,"reference":"Matthew 12:40","text":"For as Jonah was in the belly of the great fish for three days and three nights, so will the Son of Man be in the heart of the earth for three days and three nights.","sentences":[{"id":"mt-12-40-1","chapter":12,"verse":40,"sentence":1,"reference":"Matthew 12:40","text":"For as Jonah was in the belly of the great fish for three days and three nights, so will the Son of Man be in the heart of the earth for three days and three nights."}]},{"chapter":12,"verse":41,"reference":"Matthew 12:41","text":"“The people of Nineveh will stand up against this generation on judgment day and condemn it, for they repented of their sins at the preaching of Jonah. Now someone greater than Jonah is here—but you refuse to repent.","sentences":[{"id":"mt-12-41-1","chapter":12,"verse":41,"sentence":1,"reference":"Matthew 12:41","text":"“The people of Nineveh will stand up against this generation on judgment day and condemn it, for they repented of their sins at the preaching of Jonah."},{"id":"mt-12-41-2","chapter":12,"verse":41,"sentence":2,"reference":"Matthew 12:41","text":"Now someone greater than Jonah is here—but you refuse to repent."}]},{"chapter":12,"verse":42,"reference":"Matthew 12:42","text":"The queen of Sheba will also stand up against this generation on judgment day and condemn it, for she came from a distant land to hear the wisdom of Solomon. Now someone greater than Solomon is here—but you refuse to listen.","sentences":[{"id":"mt-12-42-1","chapter":12,"verse":42,"sentence":1,"reference":"Matthew 12:42","text":"The queen of Sheba will also stand up against this generation on judgment day and condemn it, for she came from a distant land to hear the wisdom of Solomon."},{"id":"mt-12-42-2","chapter":12,"verse":42,"sentence":2,"reference":"Matthew 12:42","text":"Now someone greater than Solomon is here—but you refuse to listen."}]},{"chapter":12,"verse":43,"reference":"Matthew 12:43","text":"“When an evil spirit leaves a person, it goes into the desert, seeking rest but finding none.","sentences":[{"id":"mt-12-43-1","chapter":12,"verse":43,"sentence":1,"reference":"Matthew 12:43","text":"“When an evil spirit leaves a person, it goes into the desert, seeking rest but finding none."}]},{"chapter":12,"verse":44,"reference":"Matthew 12:44","text":"Then it says, ‘I will return to the person I came from.’ So it returns and finds its former home empty, swept, and in order.","sentences":[{"id":"mt-12-44-1","chapter":12,"verse":44,"sentence":1,"reference":"Matthew 12:44","text":"Then it says, ‘I will return to the person I came from.’"},{"id":"mt-12-44-2","chapter":12,"verse":44,"sentence":2,"reference":"Matthew 12:44","text":"So it returns and finds its former home empty, swept, and in order."}]},{"chapter":12,"verse":45,"reference":"Matthew 12:45","text":"Then the spirit finds seven other spirits more evil than itself, and they all enter the person and live there. And so that person is worse off than before. That will be the experience of this evil generation.”","sentences":[{"id":"mt-12-45-1","chapter":12,"verse":45,"sentence":1,"reference":"Matthew 12:45","text":"Then the spirit finds seven other spirits more evil than itself, and they all enter the person and live there."},{"id":"mt-12-45-2","chapter":12,"verse":45,"sentence":2,"reference":"Matthew 12:45","text":"And so that person is worse off than before."},{"id":"mt-12-45-3","chapter":12,"verse":45,"sentence":3,"reference":"Matthew 12:45","text":"That will be the experience of this evil generation.”"}]},{"chapter":12,"verse":46,"reference":"Matthew 12:46","text":"As Jesus was speaking to the crowd, his mother and brothers stood outside, asking to speak to him.","sentences":[{"id":"mt-12-46-1","chapter":12,"verse":46,"sentence":1,"reference":"Matthew 12:46","text":"As Jesus was speaking to the crowd, his mother and brothers stood outside, asking to speak to him."}]},{"chapter":12,"verse":47,"reference":"Matthew 12:47","text":"Someone told Jesus, “Your mother and your brothers are standing outside, and they want to speak to you.”","sentences":[{"id":"mt-12-47-1","chapter":12,"verse":47,"sentence":1,"reference":"Matthew 12:47","text":"Someone told Jesus, “Your mother and your brothers are standing outside, and they want to speak to you.”"}]},{"chapter":12,"verse":48,"reference":"Matthew 12:48","text":"Jesus asked, “Who is my mother? Who are my brothers?”","sentences":[{"id":"mt-12-48-1","chapter":12,"verse":48,"sentence":1,"reference":"Matthew 12:48","text":"Jesus asked, “Who is my mother?"},{"id":"mt-12-48-2","chapter":12,"verse":48,"sentence":2,"reference":"Matthew 12:48","text":"Who are my brothers?”"}]},{"chapter":12,"verse":49,"reference":"Matthew 12:49","text":"Then he pointed to his disciples and said, “Look, these are my mother and brothers.","sentences":[{"id":"mt-12-49-1","chapter":12,"verse":49,"sentence":1,"reference":"Matthew 12:49","text":"Then he pointed to his disciples and said, “Look, these are my mother and brothers."}]},{"chapter":12,"verse":50,"reference":"Matthew 12:50","text":"Anyone who does the will of my Father in heaven is my brother and sister and mother!”","sentences":[{"id":"mt-12-50-1","chapter":12,"verse":50,"sentence":1,"reference":"Matthew 12:50","text":"Anyone who does the will of my Father in heaven is my brother and sister and mother!”"}]}]},{"chapter":13,"verses":[{"chapter":13,"verse":1,"reference":"Matthew 13:1","text":"Later that same day Jesus left the house and sat beside the lake.","sentences":[{"id":"mt-13-1-1","chapter":13,"verse":1,"sentence":1,"reference":"Matthew 13:1","text":"Later that same day Jesus left the house and sat beside the lake."}]},{"chapter":13,"verse":2,"reference":"Matthew 13:2","text":"A large crowd soon gathered around him, so he got into a boat. Then he sat there and taught as the people stood on the shore.","sentences":[{"id":"mt-13-2-1","chapter":13,"verse":2,"sentence":1,"reference":"Matthew 13:2","text":"A large crowd soon gathered around him, so he got into a boat."},{"id":"mt-13-2-2","chapter":13,"verse":2,"sentence":2,"reference":"Matthew 13:2","text":"Then he sat there and taught as the people stood on the shore."}]},{"chapter":13,"verse":3,"reference":"Matthew 13:3","text":"He told many stories in the form of parables, such as this one: “Listen! A farmer went out to plant some seeds.","sentences":[{"id":"mt-13-3-1","chapter":13,"verse":3,"sentence":1,"reference":"Matthew 13:3","text":"He told many stories in the form of parables, such as this one: “Listen!"},{"id":"mt-13-3-2","chapter":13,"verse":3,"sentence":2,"reference":"Matthew 13:3","text":"A farmer went out to plant some seeds."}]},{"chapter":13,"verse":4,"reference":"Matthew 13:4","text":"As he scattered them across his field, some seeds fell on a footpath, and the birds came and ate them.","sentences":[{"id":"mt-13-4-1","chapter":13,"verse":4,"sentence":1,"reference":"Matthew 13:4","text":"As he scattered them across his field, some seeds fell on a footpath, and the birds came and ate them."}]},{"chapter":13,"verse":5,"reference":"Matthew 13:5","text":"Other seeds fell on shallow soil with underlying rock. The seeds sprouted quickly because the soil was shallow.","sentences":[{"id":"mt-13-5-1","chapter":13,"verse":5,"sentence":1,"reference":"Matthew 13:5","text":"Other seeds fell on shallow soil with underlying rock."},{"id":"mt-13-5-2","chapter":13,"verse":5,"sentence":2,"reference":"Matthew 13:5","text":"The seeds sprouted quickly because the soil was shallow."}]},{"chapter":13,"verse":6,"reference":"Matthew 13:6","text":"But the plants soon wilted under the hot sun, and since they didn’t have deep roots, they died.","sentences":[{"id":"mt-13-6-1","chapter":13,"verse":6,"sentence":1,"reference":"Matthew 13:6","text":"But the plants soon wilted under the hot sun, and since they didn’t have deep roots, they died."}]},{"chapter":13,"verse":7,"reference":"Matthew 13:7","text":"Other seeds fell among thorns that grew up and choked out the tender plants.","sentences":[{"id":"mt-13-7-1","chapter":13,"verse":7,"sentence":1,"reference":"Matthew 13:7","text":"Other seeds fell among thorns that grew up and choked out the tender plants."}]},{"chapter":13,"verse":8,"reference":"Matthew 13:8","text":"Still other seeds fell on fertile soil, and they produced a crop that was thirty, sixty, and even a hundred times as much as had been planted!","sentences":[{"id":"mt-13-8-1","chapter":13,"verse":8,"sentence":1,"reference":"Matthew 13:8","text":"Still other seeds fell on fertile soil, and they produced a crop that was thirty, sixty, and even a hundred times as much as had been planted!"}]},{"chapter":13,"verse":9,"reference":"Matthew 13:9","text":"Anyone with ears to hear should listen and understand.”","sentences":[{"id":"mt-13-9-1","chapter":13,"verse":9,"sentence":1,"reference":"Matthew 13:9","text":"Anyone with ears to hear should listen and understand.”"}]},{"chapter":13,"verse":10,"reference":"Matthew 13:10","text":"His disciples came and asked him, “Why do you use parables when you talk to the people?”","sentences":[{"id":"mt-13-10-1","chapter":13,"verse":10,"sentence":1,"reference":"Matthew 13:10","text":"His disciples came and asked him, “Why do you use parables when you talk to the people?”"}]},{"chapter":13,"verse":11,"reference":"Matthew 13:11","text":"He replied, “You are permitted to understand the secrets of the Kingdom of Heaven, but others are not.","sentences":[{"id":"mt-13-11-1","chapter":13,"verse":11,"sentence":1,"reference":"Matthew 13:11","text":"He replied, “You are permitted to understand the secrets of the Kingdom of Heaven, but others are not."}]},{"chapter":13,"verse":12,"reference":"Matthew 13:12","text":"To those who listen to my teaching, more understanding will be given, and they will have an abundance of knowledge. But for those who are not listening, even what little understanding they have will be taken away from them.","sentences":[{"id":"mt-13-12-1","chapter":13,"verse":12,"sentence":1,"reference":"Matthew 13:12","text":"To those who listen to my teaching, more understanding will be given, and they will have an abundance of knowledge."},{"id":"mt-13-12-2","chapter":13,"verse":12,"sentence":2,"reference":"Matthew 13:12","text":"But for those who are not listening, even what little understanding they have will be taken away from them."}]},{"chapter":13,"verse":13,"reference":"Matthew 13:13","text":"That is why I use these parables, For they look, but they don’t really see. They hear, but they don’t really listen or understand.","sentences":[{"id":"mt-13-13-1","chapter":13,"verse":13,"sentence":1,"reference":"Matthew 13:13","text":"That is why I use these parables, For they look, but they don’t really see."},{"id":"mt-13-13-2","chapter":13,"verse":13,"sentence":2,"reference":"Matthew 13:13","text":"They hear, but they don’t really listen or understand."}]},{"chapter":13,"verse":14,"reference":"Matthew 13:14","text":"This fulfills the prophecy of Isaiah that says, ‘When you hear what I say, you will not understand. When you see what I do, you will not comprehend.","sentences":[{"id":"mt-13-14-1","chapter":13,"verse":14,"sentence":1,"reference":"Matthew 13:14","text":"This fulfills the prophecy of Isaiah that says, ‘When you hear what I say, you will not understand."},{"id":"mt-13-14-2","chapter":13,"verse":14,"sentence":2,"reference":"Matthew 13:14","text":"When you see what I do, you will not comprehend."}]},{"chapter":13,"verse":15,"reference":"Matthew 13:15","text":"For the hearts of these people are hardened, and their ears cannot hear, and they have closed their eyes— so their eyes cannot see, and their ears cannot hear, and their hearts cannot understand, and they cannot turn to me and let me heal them.’","sentences":[{"id":"mt-13-15-1","chapter":13,"verse":15,"sentence":1,"reference":"Matthew 13:15","text":"For the hearts of these people are hardened, and their ears cannot hear, and they have closed their eyes— so their eyes cannot see, and their ears cannot hear, and their hearts cannot understand, and they cannot turn to me and let me heal them.’"}]},{"chapter":13,"verse":16,"reference":"Matthew 13:16","text":"“But blessed are your eyes, because they see; and your ears, because they hear.","sentences":[{"id":"mt-13-16-1","chapter":13,"verse":16,"sentence":1,"reference":"Matthew 13:16","text":"“But blessed are your eyes, because they see; and your ears, because they hear."}]},{"chapter":13,"verse":17,"reference":"Matthew 13:17","text":"I tell you the truth, many prophets and righteous people longed to see what you see, but they didn’t see it. And they longed to hear what you hear, but they didn’t hear it.","sentences":[{"id":"mt-13-17-1","chapter":13,"verse":17,"sentence":1,"reference":"Matthew 13:17","text":"I tell you the truth, many prophets and righteous people longed to see what you see, but they didn’t see it."},{"id":"mt-13-17-2","chapter":13,"verse":17,"sentence":2,"reference":"Matthew 13:17","text":"And they longed to hear what you hear, but they didn’t hear it."}]},{"chapter":13,"verse":18,"reference":"Matthew 13:18","text":"“Now listen to the explanation of the parable about the farmer planting seeds:","sentences":[{"id":"mt-13-18-1","chapter":13,"verse":18,"sentence":1,"reference":"Matthew 13:18","text":"“Now listen to the explanation of the parable about the farmer planting seeds:"}]},{"chapter":13,"verse":19,"reference":"Matthew 13:19","text":"The seed that fell on the footpath represents those who hear the message about the Kingdom and don’t understand it. Then the evil one comes and snatches away the seed that was planted in their hearts.","sentences":[{"id":"mt-13-19-1","chapter":13,"verse":19,"sentence":1,"reference":"Matthew 13:19","text":"The seed that fell on the footpath represents those who hear the message about the Kingdom and don’t understand it."},{"id":"mt-13-19-2","chapter":13,"verse":19,"sentence":2,"reference":"Matthew 13:19","text":"Then the evil one comes and snatches away the seed that was planted in their hearts."}]},{"chapter":13,"verse":20,"reference":"Matthew 13:20","text":"The seed on the rocky soil represents those who hear the message and immediately receive it with joy.","sentences":[{"id":"mt-13-20-1","chapter":13,"verse":20,"sentence":1,"reference":"Matthew 13:20","text":"The seed on the rocky soil represents those who hear the message and immediately receive it with joy."}]},{"chapter":13,"verse":21,"reference":"Matthew 13:21","text":"But since they don’t have deep roots, they don’t last long. They fall away as soon as they have problems or are persecuted for believing God’s word.","sentences":[{"id":"mt-13-21-1","chapter":13,"verse":21,"sentence":1,"reference":"Matthew 13:21","text":"But since they don’t have deep roots, they don’t last long."},{"id":"mt-13-21-2","chapter":13,"verse":21,"sentence":2,"reference":"Matthew 13:21","text":"They fall away as soon as they have problems or are persecuted for believing God’s word."}]},{"chapter":13,"verse":22,"reference":"Matthew 13:22","text":"The seed that fell among the thorns represents those who hear God’s word, but all too quickly the message is crowded out by the worries of this life and the lure of wealth, so no fruit is produced.","sentences":[{"id":"mt-13-22-1","chapter":13,"verse":22,"sentence":1,"reference":"Matthew 13:22","text":"The seed that fell among the thorns represents those who hear God’s word, but all too quickly the message is crowded out by the worries of this life and the lure of wealth, so no fruit is produced."}]},{"chapter":13,"verse":23,"reference":"Matthew 13:23","text":"The seed that fell on good soil represents those who truly hear and understand God’s word and produce a harvest of thirty, sixty, or even a hundred times as much as had been planted!”","sentences":[{"id":"mt-13-23-1","chapter":13,"verse":23,"sentence":1,"reference":"Matthew 13:23","text":"The seed that fell on good soil represents those who truly hear and understand God’s word and produce a harvest of thirty, sixty, or even a hundred times as much as had been planted!”"}]},{"chapter":13,"verse":24,"reference":"Matthew 13:24","text":"Here is another story Jesus told: “The Kingdom of Heaven is like a farmer who planted good seed in his field.","sentences":[{"id":"mt-13-24-1","chapter":13,"verse":24,"sentence":1,"reference":"Matthew 13:24","text":"Here is another story Jesus told: “The Kingdom of Heaven is like a farmer who planted good seed in his field."}]},{"chapter":13,"verse":25,"reference":"Matthew 13:25","text":"But that night as the workers slept, his enemy came and planted weeds among the wheat, then slipped away.","sentences":[{"id":"mt-13-25-1","chapter":13,"verse":25,"sentence":1,"reference":"Matthew 13:25","text":"But that night as the workers slept, his enemy came and planted weeds among the wheat, then slipped away."}]},{"chapter":13,"verse":26,"reference":"Matthew 13:26","text":"When the crop began to grow and produce grain, the weeds also grew.","sentences":[{"id":"mt-13-26-1","chapter":13,"verse":26,"sentence":1,"reference":"Matthew 13:26","text":"When the crop began to grow and produce grain, the weeds also grew."}]},{"chapter":13,"verse":27,"reference":"Matthew 13:27","text":"“The farmer’s workers went to him and said, ‘Sir, the field where you planted that good seed is full of weeds! Where did they come from?’","sentences":[{"id":"mt-13-27-1","chapter":13,"verse":27,"sentence":1,"reference":"Matthew 13:27","text":"“The farmer’s workers went to him and said, ‘Sir, the field where you planted that good seed is full of weeds!"},{"id":"mt-13-27-2","chapter":13,"verse":27,"sentence":2,"reference":"Matthew 13:27","text":"Where did they come from?’"}]},{"chapter":13,"verse":28,"reference":"Matthew 13:28","text":"“‘An enemy has done this!’ the farmer exclaimed. “‘Should we pull out the weeds?’ they asked.","sentences":[{"id":"mt-13-28-1","chapter":13,"verse":28,"sentence":1,"reference":"Matthew 13:28","text":"“‘An enemy has done this!’"},{"id":"mt-13-28-2","chapter":13,"verse":28,"sentence":2,"reference":"Matthew 13:28","text":"the farmer exclaimed."},{"id":"mt-13-28-3","chapter":13,"verse":28,"sentence":3,"reference":"Matthew 13:28","text":"“‘Should we pull out the weeds?’"},{"id":"mt-13-28-4","chapter":13,"verse":28,"sentence":4,"reference":"Matthew 13:28","text":"they asked."}]},{"chapter":13,"verse":29,"reference":"Matthew 13:29","text":"“‘No,’ he replied, ‘you’ll uproot the wheat if you do.","sentences":[{"id":"mt-13-29-1","chapter":13,"verse":29,"sentence":1,"reference":"Matthew 13:29","text":"“‘No,’ he replied, ‘you’ll uproot the wheat if you do."}]},{"chapter":13,"verse":30,"reference":"Matthew 13:30","text":"Let both grow together until the harvest. Then I will tell the harvesters to sort out the weeds, tie them into bundles, and burn them, and to put the wheat in the barn.’”","sentences":[{"id":"mt-13-30-1","chapter":13,"verse":30,"sentence":1,"reference":"Matthew 13:30","text":"Let both grow together until the harvest."},{"id":"mt-13-30-2","chapter":13,"verse":30,"sentence":2,"reference":"Matthew 13:30","text":"Then I will tell the harvesters to sort out the weeds, tie them into bundles, and burn them, and to put the wheat in the barn.’”"}]},{"chapter":13,"verse":31,"reference":"Matthew 13:31","text":"Here is another illustration Jesus used: “The Kingdom of Heaven is like a mustard seed planted in a field.","sentences":[{"id":"mt-13-31-1","chapter":13,"verse":31,"sentence":1,"reference":"Matthew 13:31","text":"Here is another illustration Jesus used: “The Kingdom of Heaven is like a mustard seed planted in a field."}]},{"chapter":13,"verse":32,"reference":"Matthew 13:32","text":"It is the smallest of all seeds, but it becomes the largest of garden plants; it grows into a tree, and birds come and make nests in its branches.”","sentences":[{"id":"mt-13-32-1","chapter":13,"verse":32,"sentence":1,"reference":"Matthew 13:32","text":"It is the smallest of all seeds, but it becomes the largest of garden plants; it grows into a tree, and birds come and make nests in its branches.”"}]},{"chapter":13,"verse":33,"reference":"Matthew 13:33","text":"Jesus also used this illustration: “The Kingdom of Heaven is like the yeast a woman used in making bread. Even though she put only a little yeast in three measures of flour, it permeated every part of the dough.”","sentences":[{"id":"mt-13-33-1","chapter":13,"verse":33,"sentence":1,"reference":"Matthew 13:33","text":"Jesus also used this illustration: “The Kingdom of Heaven is like the yeast a woman used in making bread."},{"id":"mt-13-33-2","chapter":13,"verse":33,"sentence":2,"reference":"Matthew 13:33","text":"Even though she put only a little yeast in three measures of flour, it permeated every part of the dough.”"}]},{"chapter":13,"verse":34,"reference":"Matthew 13:34","text":"Jesus always used stories and illustrations like these when speaking to the crowds. In fact, he never spoke to them without using such parables.","sentences":[{"id":"mt-13-34-1","chapter":13,"verse":34,"sentence":1,"reference":"Matthew 13:34","text":"Jesus always used stories and illustrations like these when speaking to the crowds."},{"id":"mt-13-34-2","chapter":13,"verse":34,"sentence":2,"reference":"Matthew 13:34","text":"In fact, he never spoke to them without using such parables."}]},{"chapter":13,"verse":35,"reference":"Matthew 13:35","text":"This fulfilled what God had spoken through the prophet: “I will speak to you in parables. I will explain things hidden since the creation of the world.”","sentences":[{"id":"mt-13-35-1","chapter":13,"verse":35,"sentence":1,"reference":"Matthew 13:35","text":"This fulfilled what God had spoken through the prophet: “I will speak to you in parables."},{"id":"mt-13-35-2","chapter":13,"verse":35,"sentence":2,"reference":"Matthew 13:35","text":"I will explain things hidden since the creation of the world.”"}]},{"chapter":13,"verse":36,"reference":"Matthew 13:36","text":"Then, leaving the crowds outside, Jesus went into the house. His disciples said, “Please explain to us the story of the weeds in the field.”","sentences":[{"id":"mt-13-36-1","chapter":13,"verse":36,"sentence":1,"reference":"Matthew 13:36","text":"Then, leaving the crowds outside, Jesus went into the house."},{"id":"mt-13-36-2","chapter":13,"verse":36,"sentence":2,"reference":"Matthew 13:36","text":"His disciples said, “Please explain to us the story of the weeds in the field.”"}]},{"chapter":13,"verse":37,"reference":"Matthew 13:37","text":"Jesus replied, “The Son of Man is the farmer who plants the good seed.","sentences":[{"id":"mt-13-37-1","chapter":13,"verse":37,"sentence":1,"reference":"Matthew 13:37","text":"Jesus replied, “The Son of Man is the farmer who plants the good seed."}]},{"chapter":13,"verse":38,"reference":"Matthew 13:38","text":"The field is the world, and the good seed represents the people of the Kingdom. The weeds are the people who belong to the evil one.","sentences":[{"id":"mt-13-38-1","chapter":13,"verse":38,"sentence":1,"reference":"Matthew 13:38","text":"The field is the world, and the good seed represents the people of the Kingdom."},{"id":"mt-13-38-2","chapter":13,"verse":38,"sentence":2,"reference":"Matthew 13:38","text":"The weeds are the people who belong to the evil one."}]},{"chapter":13,"verse":39,"reference":"Matthew 13:39","text":"The enemy who planted the weeds among the wheat is the devil. The harvest is the end of the world, and the harvesters are the angels.","sentences":[{"id":"mt-13-39-1","chapter":13,"verse":39,"sentence":1,"reference":"Matthew 13:39","text":"The enemy who planted the weeds among the wheat is the devil."},{"id":"mt-13-39-2","chapter":13,"verse":39,"sentence":2,"reference":"Matthew 13:39","text":"The harvest is the end of the world, and the harvesters are the angels."}]},{"chapter":13,"verse":40,"reference":"Matthew 13:40","text":"“Just as the weeds are sorted out and burned in the fire, so it will be at the end of the world.","sentences":[{"id":"mt-13-40-1","chapter":13,"verse":40,"sentence":1,"reference":"Matthew 13:40","text":"“Just as the weeds are sorted out and burned in the fire, so it will be at the end of the world."}]},{"chapter":13,"verse":41,"reference":"Matthew 13:41","text":"The Son of Man will send his angels, and they will remove from his Kingdom everything that causes sin and all who do evil.","sentences":[{"id":"mt-13-41-1","chapter":13,"verse":41,"sentence":1,"reference":"Matthew 13:41","text":"The Son of Man will send his angels, and they will remove from his Kingdom everything that causes sin and all who do evil."}]},{"chapter":13,"verse":42,"reference":"Matthew 13:42","text":"And the angels will throw them into the fiery furnace, where there will be weeping and gnashing of teeth.","sentences":[{"id":"mt-13-42-1","chapter":13,"verse":42,"sentence":1,"reference":"Matthew 13:42","text":"And the angels will throw them into the fiery furnace, where there will be weeping and gnashing of teeth."}]},{"chapter":13,"verse":43,"reference":"Matthew 13:43","text":"Then the righteous will shine like the sun in their Father’s Kingdom. Anyone with ears to hear should listen and understand!","sentences":[{"id":"mt-13-43-1","chapter":13,"verse":43,"sentence":1,"reference":"Matthew 13:43","text":"Then the righteous will shine like the sun in their Father’s Kingdom."},{"id":"mt-13-43-2","chapter":13,"verse":43,"sentence":2,"reference":"Matthew 13:43","text":"Anyone with ears to hear should listen and understand!"}]},{"chapter":13,"verse":44,"reference":"Matthew 13:44","text":"“The Kingdom of Heaven is like a treasure that a man discovered hidden in a field. In his excitement, he hid it again and sold everything he owned to get enough money to buy the field.","sentences":[{"id":"mt-13-44-1","chapter":13,"verse":44,"sentence":1,"reference":"Matthew 13:44","text":"“The Kingdom of Heaven is like a treasure that a man discovered hidden in a field."},{"id":"mt-13-44-2","chapter":13,"verse":44,"sentence":2,"reference":"Matthew 13:44","text":"In his excitement, he hid it again and sold everything he owned to get enough money to buy the field."}]},{"chapter":13,"verse":45,"reference":"Matthew 13:45","text":"“Again, the Kingdom of Heaven is like a merchant on the lookout for choice pearls.","sentences":[{"id":"mt-13-45-1","chapter":13,"verse":45,"sentence":1,"reference":"Matthew 13:45","text":"“Again, the Kingdom of Heaven is like a merchant on the lookout for choice pearls."}]},{"chapter":13,"verse":46,"reference":"Matthew 13:46","text":"When he discovered a pearl of great value, he sold everything he owned and bought it!","sentences":[{"id":"mt-13-46-1","chapter":13,"verse":46,"sentence":1,"reference":"Matthew 13:46","text":"When he discovered a pearl of great value, he sold everything he owned and bought it!"}]},{"chapter":13,"verse":47,"reference":"Matthew 13:47","text":"“Again, the Kingdom of Heaven is like a fishing net that was thrown into the water and caught fish of every kind.","sentences":[{"id":"mt-13-47-1","chapter":13,"verse":47,"sentence":1,"reference":"Matthew 13:47","text":"“Again, the Kingdom of Heaven is like a fishing net that was thrown into the water and caught fish of every kind."}]},{"chapter":13,"verse":48,"reference":"Matthew 13:48","text":"When the net was full, they dragged it up onto the shore, sat down, and sorted the good fish into crates, but threw the bad ones away.","sentences":[{"id":"mt-13-48-1","chapter":13,"verse":48,"sentence":1,"reference":"Matthew 13:48","text":"When the net was full, they dragged it up onto the shore, sat down, and sorted the good fish into crates, but threw the bad ones away."}]},{"chapter":13,"verse":49,"reference":"Matthew 13:49","text":"That is the way it will be at the end of the world. The angels will come and separate the wicked people from the righteous,","sentences":[{"id":"mt-13-49-1","chapter":13,"verse":49,"sentence":1,"reference":"Matthew 13:49","text":"That is the way it will be at the end of the world."},{"id":"mt-13-49-2","chapter":13,"verse":49,"sentence":2,"reference":"Matthew 13:49","text":"The angels will come and separate the wicked people from the righteous,"}]},{"chapter":13,"verse":50,"reference":"Matthew 13:50","text":"throwing the wicked into the fiery furnace, where there will be weeping and gnashing of teeth.","sentences":[{"id":"mt-13-50-1","chapter":13,"verse":50,"sentence":1,"reference":"Matthew 13:50","text":"throwing the wicked into the fiery furnace, where there will be weeping and gnashing of teeth."}]},{"chapter":13,"verse":51,"reference":"Matthew 13:51","text":"Do you understand all these things?” “Yes,” they said, “we do.”","sentences":[{"id":"mt-13-51-1","chapter":13,"verse":51,"sentence":1,"reference":"Matthew 13:51","text":"Do you understand all these things?”"},{"id":"mt-13-51-2","chapter":13,"verse":51,"sentence":2,"reference":"Matthew 13:51","text":"“Yes,” they said, “we do.”"}]},{"chapter":13,"verse":52,"reference":"Matthew 13:52","text":"Then he added, “Every teacher of religious law who becomes a disciple in the Kingdom of Heaven is like a homeowner who brings from his storeroom new gems of truth as well as old.”","sentences":[{"id":"mt-13-52-1","chapter":13,"verse":52,"sentence":1,"reference":"Matthew 13:52","text":"Then he added, “Every teacher of religious law who becomes a disciple in the Kingdom of Heaven is like a homeowner who brings from his storeroom new gems of truth as well as old.”"}]},{"chapter":13,"verse":53,"reference":"Matthew 13:53","text":"When Jesus had finished telling these stories and illustrations, he left that part of the country.","sentences":[{"id":"mt-13-53-1","chapter":13,"verse":53,"sentence":1,"reference":"Matthew 13:53","text":"When Jesus had finished telling these stories and illustrations, he left that part of the country."}]},{"chapter":13,"verse":54,"reference":"Matthew 13:54","text":"He returned to Nazareth, his hometown. When he taught there in the synagogue, everyone was amazed and said, “Where does he get this wisdom and the power to do miracles?”","sentences":[{"id":"mt-13-54-1","chapter":13,"verse":54,"sentence":1,"reference":"Matthew 13:54","text":"He returned to Nazareth, his hometown."},{"id":"mt-13-54-2","chapter":13,"verse":54,"sentence":2,"reference":"Matthew 13:54","text":"When he taught there in the synagogue, everyone was amazed and said, “Where does he get this wisdom and the power to do miracles?”"}]},{"chapter":13,"verse":55,"reference":"Matthew 13:55","text":"Then they scoffed, “He’s just the carpenter’s son, and we know Mary, his mother, and his brothers—James, Joseph, Simon, and Judas.","sentences":[{"id":"mt-13-55-1","chapter":13,"verse":55,"sentence":1,"reference":"Matthew 13:55","text":"Then they scoffed, “He’s just the carpenter’s son, and we know Mary, his mother, and his brothers—James, Joseph, Simon, and Judas."}]},{"chapter":13,"verse":56,"reference":"Matthew 13:56","text":"All his sisters live right here among us. Where did he learn all these things?”","sentences":[{"id":"mt-13-56-1","chapter":13,"verse":56,"sentence":1,"reference":"Matthew 13:56","text":"All his sisters live right here among us."},{"id":"mt-13-56-2","chapter":13,"verse":56,"sentence":2,"reference":"Matthew 13:56","text":"Where did he learn all these things?”"}]},{"chapter":13,"verse":57,"reference":"Matthew 13:57","text":"And they were deeply offended and refused to believe in him. Then Jesus told them, “A prophet is honored everywhere except in his own hometown and among his own family.”","sentences":[{"id":"mt-13-57-1","chapter":13,"verse":57,"sentence":1,"reference":"Matthew 13:57","text":"And they were deeply offended and refused to believe in him."},{"id":"mt-13-57-2","chapter":13,"verse":57,"sentence":2,"reference":"Matthew 13:57","text":"Then Jesus told them, “A prophet is honored everywhere except in his own hometown and among his own family.”"}]},{"chapter":13,"verse":58,"reference":"Matthew 13:58","text":"And so he did only a few miracles there because of their unbelief.","sentences":[{"id":"mt-13-58-1","chapter":13,"verse":58,"sentence":1,"reference":"Matthew 13:58","text":"And so he did only a few miracles there because of their unbelief."}]}]},{"chapter":14,"verses":[{"chapter":14,"verse":1,"reference":"Matthew 14:1","text":"When Herod Antipas, the ruler of Galilee, heard about Jesus,","sentences":[{"id":"mt-14-1-1","chapter":14,"verse":1,"sentence":1,"reference":"Matthew 14:1","text":"When Herod Antipas, the ruler of Galilee, heard about Jesus,"}]},{"chapter":14,"verse":2,"reference":"Matthew 14:2","text":"he said to his advisers, “This must be John the Baptist raised from the dead! That is why he can do such miracles.”","sentences":[{"id":"mt-14-2-1","chapter":14,"verse":2,"sentence":1,"reference":"Matthew 14:2","text":"he said to his advisers, “This must be John the Baptist raised from the dead!"},{"id":"mt-14-2-2","chapter":14,"verse":2,"sentence":2,"reference":"Matthew 14:2","text":"That is why he can do such miracles.”"}]},{"chapter":14,"verse":3,"reference":"Matthew 14:3","text":"For Herod had arrested and imprisoned John as a favor to his wife Herodias (the former wife of Herod’s brother Philip).","sentences":[{"id":"mt-14-3-1","chapter":14,"verse":3,"sentence":1,"reference":"Matthew 14:3","text":"For Herod had arrested and imprisoned John as a favor to his wife Herodias (the former wife of Herod’s brother Philip)."}]},{"chapter":14,"verse":4,"reference":"Matthew 14:4","text":"John had been telling Herod, “It is against God’s law for you to marry her.”","sentences":[{"id":"mt-14-4-1","chapter":14,"verse":4,"sentence":1,"reference":"Matthew 14:4","text":"John had been telling Herod, “It is against God’s law for you to marry her.”"}]},{"chapter":14,"verse":5,"reference":"Matthew 14:5","text":"Herod wanted to kill John, but he was afraid of a riot, because all the people believed John was a prophet.","sentences":[{"id":"mt-14-5-1","chapter":14,"verse":5,"sentence":1,"reference":"Matthew 14:5","text":"Herod wanted to kill John, but he was afraid of a riot, because all the people believed John was a prophet."}]},{"chapter":14,"verse":6,"reference":"Matthew 14:6","text":"But at a birthday party for Herod, Herodias’s daughter performed a dance that greatly pleased him,","sentences":[{"id":"mt-14-6-1","chapter":14,"verse":6,"sentence":1,"reference":"Matthew 14:6","text":"But at a birthday party for Herod, Herodias’s daughter performed a dance that greatly pleased him,"}]},{"chapter":14,"verse":7,"reference":"Matthew 14:7","text":"so he promised with a vow to give her anything she wanted.","sentences":[{"id":"mt-14-7-1","chapter":14,"verse":7,"sentence":1,"reference":"Matthew 14:7","text":"so he promised with a vow to give her anything she wanted."}]},{"chapter":14,"verse":8,"reference":"Matthew 14:8","text":"At her mother’s urging, the girl said, “I want the head of John the Baptist on a tray!”","sentences":[{"id":"mt-14-8-1","chapter":14,"verse":8,"sentence":1,"reference":"Matthew 14:8","text":"At her mother’s urging, the girl said, “I want the head of John the Baptist on a tray!”"}]},{"chapter":14,"verse":9,"reference":"Matthew 14:9","text":"Then the king regretted what he had said; but because of the vow he had made in front of his guests, he issued the necessary orders.","sentences":[{"id":"mt-14-9-1","chapter":14,"verse":9,"sentence":1,"reference":"Matthew 14:9","text":"Then the king regretted what he had said; but because of the vow he had made in front of his guests, he issued the necessary orders."}]},{"chapter":14,"verse":10,"reference":"Matthew 14:10","text":"So John was beheaded in the prison,","sentences":[{"id":"mt-14-10-1","chapter":14,"verse":10,"sentence":1,"reference":"Matthew 14:10","text":"So John was beheaded in the prison,"}]},{"chapter":14,"verse":11,"reference":"Matthew 14:11","text":"and his head was brought on a tray and given to the girl, who took it to her mother.","sentences":[{"id":"mt-14-11-1","chapter":14,"verse":11,"sentence":1,"reference":"Matthew 14:11","text":"and his head was brought on a tray and given to the girl, who took it to her mother."}]},{"chapter":14,"verse":12,"reference":"Matthew 14:12","text":"Later, John’s disciples came for his body and buried it. Then they went and told Jesus what had happened.","sentences":[{"id":"mt-14-12-1","chapter":14,"verse":12,"sentence":1,"reference":"Matthew 14:12","text":"Later, John’s disciples came for his body and buried it."},{"id":"mt-14-12-2","chapter":14,"verse":12,"sentence":2,"reference":"Matthew 14:12","text":"Then they went and told Jesus what had happened."}]},{"chapter":14,"verse":13,"reference":"Matthew 14:13","text":"As soon as Jesus heard the news, he left in a boat to a remote area to be alone. But the crowds heard where he was headed and followed on foot from many towns.","sentences":[{"id":"mt-14-13-1","chapter":14,"verse":13,"sentence":1,"reference":"Matthew 14:13","text":"As soon as Jesus heard the news, he left in a boat to a remote area to be alone."},{"id":"mt-14-13-2","chapter":14,"verse":13,"sentence":2,"reference":"Matthew 14:13","text":"But the crowds heard where he was headed and followed on foot from many towns."}]},{"chapter":14,"verse":14,"reference":"Matthew 14:14","text":"Jesus saw the huge crowd as he stepped from the boat, and he had compassion on them and healed their sick.","sentences":[{"id":"mt-14-14-1","chapter":14,"verse":14,"sentence":1,"reference":"Matthew 14:14","text":"Jesus saw the huge crowd as he stepped from the boat, and he had compassion on them and healed their sick."}]},{"chapter":14,"verse":15,"reference":"Matthew 14:15","text":"That evening the disciples came to him and said, “This is a remote place, and it’s already getting late. Send the crowds away so they can go to the villages and buy food for themselves.”","sentences":[{"id":"mt-14-15-1","chapter":14,"verse":15,"sentence":1,"reference":"Matthew 14:15","text":"That evening the disciples came to him and said, “This is a remote place, and it’s already getting late."},{"id":"mt-14-15-2","chapter":14,"verse":15,"sentence":2,"reference":"Matthew 14:15","text":"Send the crowds away so they can go to the villages and buy food for themselves.”"}]},{"chapter":14,"verse":16,"reference":"Matthew 14:16","text":"But Jesus said, “That isn’t necessary—you feed them.”","sentences":[{"id":"mt-14-16-1","chapter":14,"verse":16,"sentence":1,"reference":"Matthew 14:16","text":"But Jesus said, “That isn’t necessary—you feed them.”"}]},{"chapter":14,"verse":17,"reference":"Matthew 14:17","text":"“But we have only five loaves of bread and two fish!” they answered.","sentences":[{"id":"mt-14-17-1","chapter":14,"verse":17,"sentence":1,"reference":"Matthew 14:17","text":"“But we have only five loaves of bread and two fish!”"},{"id":"mt-14-17-2","chapter":14,"verse":17,"sentence":2,"reference":"Matthew 14:17","text":"they answered."}]},{"chapter":14,"verse":18,"reference":"Matthew 14:18","text":"“Bring them here,” he said.","sentences":[{"id":"mt-14-18-1","chapter":14,"verse":18,"sentence":1,"reference":"Matthew 14:18","text":"“Bring them here,” he said."}]},{"chapter":14,"verse":19,"reference":"Matthew 14:19","text":"Then he told the people to sit down on the grass. Jesus took the five loaves and two fish, looked up toward heaven, and blessed them. Then, breaking the loaves into pieces, he gave the bread to the disciples, who distributed it to the people.","sentences":[{"id":"mt-14-19-1","chapter":14,"verse":19,"sentence":1,"reference":"Matthew 14:19","text":"Then he told the people to sit down on the grass."},{"id":"mt-14-19-2","chapter":14,"verse":19,"sentence":2,"reference":"Matthew 14:19","text":"Jesus took the five loaves and two fish, looked up toward heaven, and blessed them."},{"id":"mt-14-19-3","chapter":14,"verse":19,"sentence":3,"reference":"Matthew 14:19","text":"Then, breaking the loaves into pieces, he gave the bread to the disciples, who distributed it to the people."}]},{"chapter":14,"verse":20,"reference":"Matthew 14:20","text":"They all ate as much as they wanted, and afterward, the disciples picked up twelve baskets of leftovers.","sentences":[{"id":"mt-14-20-1","chapter":14,"verse":20,"sentence":1,"reference":"Matthew 14:20","text":"They all ate as much as they wanted, and afterward, the disciples picked up twelve baskets of leftovers."}]},{"chapter":14,"verse":21,"reference":"Matthew 14:21","text":"About 5,000 men were fed that day, in addition to all the women and children!","sentences":[{"id":"mt-14-21-1","chapter":14,"verse":21,"sentence":1,"reference":"Matthew 14:21","text":"About 5,000 men were fed that day, in addition to all the women and children!"}]},{"chapter":14,"verse":22,"reference":"Matthew 14:22","text":"Immediately after this, Jesus insisted that his disciples get back into the boat and cross to the other side of the lake, while he sent the people home.","sentences":[{"id":"mt-14-22-1","chapter":14,"verse":22,"sentence":1,"reference":"Matthew 14:22","text":"Immediately after this, Jesus insisted that his disciples get back into the boat and cross to the other side of the lake, while he sent the people home."}]},{"chapter":14,"verse":23,"reference":"Matthew 14:23","text":"After sending them home, he went up into the hills by himself to pray. Night fell while he was there alone.","sentences":[{"id":"mt-14-23-1","chapter":14,"verse":23,"sentence":1,"reference":"Matthew 14:23","text":"After sending them home, he went up into the hills by himself to pray."},{"id":"mt-14-23-2","chapter":14,"verse":23,"sentence":2,"reference":"Matthew 14:23","text":"Night fell while he was there alone."}]},{"chapter":14,"verse":24,"reference":"Matthew 14:24","text":"Meanwhile, the disciples were in trouble far away from land, for a strong wind had risen, and they were fighting heavy waves.","sentences":[{"id":"mt-14-24-1","chapter":14,"verse":24,"sentence":1,"reference":"Matthew 14:24","text":"Meanwhile, the disciples were in trouble far away from land, for a strong wind had risen, and they were fighting heavy waves."}]},{"chapter":14,"verse":25,"reference":"Matthew 14:25","text":"About three o’clock in the morning Jesus came toward them, walking on the water.","sentences":[{"id":"mt-14-25-1","chapter":14,"verse":25,"sentence":1,"reference":"Matthew 14:25","text":"About three o’clock in the morning Jesus came toward them, walking on the water."}]},{"chapter":14,"verse":26,"reference":"Matthew 14:26","text":"When the disciples saw him walking on the water, they were terrified. In their fear, they cried out, “It’s a ghost!”","sentences":[{"id":"mt-14-26-1","chapter":14,"verse":26,"sentence":1,"reference":"Matthew 14:26","text":"When the disciples saw him walking on the water, they were terrified."},{"id":"mt-14-26-2","chapter":14,"verse":26,"sentence":2,"reference":"Matthew 14:26","text":"In their fear, they cried out, “It’s a ghost!”"}]},{"chapter":14,"verse":27,"reference":"Matthew 14:27","text":"But Jesus spoke to them at once. “Don’t be afraid,” he said. “Take courage. I am here!”","sentences":[{"id":"mt-14-27-1","chapter":14,"verse":27,"sentence":1,"reference":"Matthew 14:27","text":"But Jesus spoke to them at once."},{"id":"mt-14-27-2","chapter":14,"verse":27,"sentence":2,"reference":"Matthew 14:27","text":"“Don’t be afraid,” he said."},{"id":"mt-14-27-3","chapter":14,"verse":27,"sentence":3,"reference":"Matthew 14:27","text":"“Take courage."},{"id":"mt-14-27-4","chapter":14,"verse":27,"sentence":4,"reference":"Matthew 14:27","text":"I am here!”"}]},{"chapter":14,"verse":28,"reference":"Matthew 14:28","text":"Then Peter called to him, “Lord, if it’s really you, tell me to come to you, walking on the water.”","sentences":[{"id":"mt-14-28-1","chapter":14,"verse":28,"sentence":1,"reference":"Matthew 14:28","text":"Then Peter called to him, “Lord, if it’s really you, tell me to come to you, walking on the water.”"}]},{"chapter":14,"verse":29,"reference":"Matthew 14:29","text":"“Yes, come,” Jesus said. So Peter went over the side of the boat and walked on the water toward Jesus.","sentences":[{"id":"mt-14-29-1","chapter":14,"verse":29,"sentence":1,"reference":"Matthew 14:29","text":"“Yes, come,” Jesus said."},{"id":"mt-14-29-2","chapter":14,"verse":29,"sentence":2,"reference":"Matthew 14:29","text":"So Peter went over the side of the boat and walked on the water toward Jesus."}]},{"chapter":14,"verse":30,"reference":"Matthew 14:30","text":"But when he saw the strong wind and the waves, he was terrified and began to sink. “Save me, Lord!” he shouted.","sentences":[{"id":"mt-14-30-1","chapter":14,"verse":30,"sentence":1,"reference":"Matthew 14:30","text":"But when he saw the strong wind and the waves, he was terrified and began to sink."},{"id":"mt-14-30-2","chapter":14,"verse":30,"sentence":2,"reference":"Matthew 14:30","text":"“Save me, Lord!”"},{"id":"mt-14-30-3","chapter":14,"verse":30,"sentence":3,"reference":"Matthew 14:30","text":"he shouted."}]},{"chapter":14,"verse":31,"reference":"Matthew 14:31","text":"Jesus immediately reached out and grabbed him. “You have so little faith,” Jesus said. “Why did you doubt me?”","sentences":[{"id":"mt-14-31-1","chapter":14,"verse":31,"sentence":1,"reference":"Matthew 14:31","text":"Jesus immediately reached out and grabbed him."},{"id":"mt-14-31-2","chapter":14,"verse":31,"sentence":2,"reference":"Matthew 14:31","text":"“You have so little faith,” Jesus said."},{"id":"mt-14-31-3","chapter":14,"verse":31,"sentence":3,"reference":"Matthew 14:31","text":"“Why did you doubt me?”"}]},{"chapter":14,"verse":32,"reference":"Matthew 14:32","text":"When they climbed back into the boat, the wind stopped.","sentences":[{"id":"mt-14-32-1","chapter":14,"verse":32,"sentence":1,"reference":"Matthew 14:32","text":"When they climbed back into the boat, the wind stopped."}]},{"chapter":14,"verse":33,"reference":"Matthew 14:33","text":"Then the disciples worshiped him. “You really are the Son of God!” they exclaimed.","sentences":[{"id":"mt-14-33-1","chapter":14,"verse":33,"sentence":1,"reference":"Matthew 14:33","text":"Then the disciples worshiped him."},{"id":"mt-14-33-2","chapter":14,"verse":33,"sentence":2,"reference":"Matthew 14:33","text":"“You really are the Son of God!”"},{"id":"mt-14-33-3","chapter":14,"verse":33,"sentence":3,"reference":"Matthew 14:33","text":"they exclaimed."}]},{"chapter":14,"verse":34,"reference":"Matthew 14:34","text":"After they had crossed the lake, they landed at Gennesaret.","sentences":[{"id":"mt-14-34-1","chapter":14,"verse":34,"sentence":1,"reference":"Matthew 14:34","text":"After they had crossed the lake, they landed at Gennesaret."}]},{"chapter":14,"verse":35,"reference":"Matthew 14:35","text":"When the people recognized Jesus, the news of his arrival spread quickly throughout the whole area, and soon people were bringing all their sick to be healed.","sentences":[{"id":"mt-14-35-1","chapter":14,"verse":35,"sentence":1,"reference":"Matthew 14:35","text":"When the people recognized Jesus, the news of his arrival spread quickly throughout the whole area, and soon people were bringing all their sick to be healed."}]},{"chapter":14,"verse":36,"reference":"Matthew 14:36","text":"They begged him to let the sick touch at least the fringe of his robe, and all who touched him were healed.","sentences":[{"id":"mt-14-36-1","chapter":14,"verse":36,"sentence":1,"reference":"Matthew 14:36","text":"They begged him to let the sick touch at least the fringe of his robe, and all who touched him were healed."}]}]},{"chapter":15,"verses":[{"chapter":15,"verse":1,"reference":"Matthew 15:1","text":"Some Pharisees and teachers of religious law now arrived from Jerusalem to see Jesus. They asked him,","sentences":[{"id":"mt-15-1-1","chapter":15,"verse":1,"sentence":1,"reference":"Matthew 15:1","text":"Some Pharisees and teachers of religious law now arrived from Jerusalem to see Jesus."},{"id":"mt-15-1-2","chapter":15,"verse":1,"sentence":2,"reference":"Matthew 15:1","text":"They asked him,"}]},{"chapter":15,"verse":2,"reference":"Matthew 15:2","text":"“Why do your disciples disobey our age-old tradition? For they ignore our tradition of ceremonial hand washing before they eat.”","sentences":[{"id":"mt-15-2-1","chapter":15,"verse":2,"sentence":1,"reference":"Matthew 15:2","text":"“Why do your disciples disobey our age-old tradition?"},{"id":"mt-15-2-2","chapter":15,"verse":2,"sentence":2,"reference":"Matthew 15:2","text":"For they ignore our tradition of ceremonial hand washing before they eat.”"}]},{"chapter":15,"verse":3,"reference":"Matthew 15:3","text":"Jesus replied, “And why do you, by your traditions, violate the direct commandments of God?","sentences":[{"id":"mt-15-3-1","chapter":15,"verse":3,"sentence":1,"reference":"Matthew 15:3","text":"Jesus replied, “And why do you, by your traditions, violate the direct commandments of God?"}]},{"chapter":15,"verse":4,"reference":"Matthew 15:4","text":"For instance, God says, ‘Honor your father and mother,’ and ‘Anyone who speaks disrespectfully of father or mother must be put to death.’","sentences":[{"id":"mt-15-4-1","chapter":15,"verse":4,"sentence":1,"reference":"Matthew 15:4","text":"For instance, God says, ‘Honor your father and mother,’ and ‘Anyone who speaks disrespectfully of father or mother must be put to death.’"}]},{"chapter":15,"verse":5,"reference":"Matthew 15:5","text":"But you say it is all right for people to say to their parents, ‘Sorry, I can’t help you. For I have vowed to give to God what I would have given to you.’","sentences":[{"id":"mt-15-5-1","chapter":15,"verse":5,"sentence":1,"reference":"Matthew 15:5","text":"But you say it is all right for people to say to their parents, ‘Sorry, I can’t help you."},{"id":"mt-15-5-2","chapter":15,"verse":5,"sentence":2,"reference":"Matthew 15:5","text":"For I have vowed to give to God what I would have given to you.’"}]},{"chapter":15,"verse":6,"reference":"Matthew 15:6","text":"In this way, you say they don’t need to honor their parents. And so you cancel the word of God for the sake of your own tradition.","sentences":[{"id":"mt-15-6-1","chapter":15,"verse":6,"sentence":1,"reference":"Matthew 15:6","text":"In this way, you say they don’t need to honor their parents."},{"id":"mt-15-6-2","chapter":15,"verse":6,"sentence":2,"reference":"Matthew 15:6","text":"And so you cancel the word of God for the sake of your own tradition."}]},{"chapter":15,"verse":7,"reference":"Matthew 15:7","text":"You hypocrites! Isaiah was right when he prophesied about you, for he wrote,","sentences":[{"id":"mt-15-7-1","chapter":15,"verse":7,"sentence":1,"reference":"Matthew 15:7","text":"You hypocrites!"},{"id":"mt-15-7-2","chapter":15,"verse":7,"sentence":2,"reference":"Matthew 15:7","text":"Isaiah was right when he prophesied about you, for he wrote,"}]},{"chapter":15,"verse":8,"reference":"Matthew 15:8","text":"‘These people honor me with their lips, but their hearts are far from me.","sentences":[{"id":"mt-15-8-1","chapter":15,"verse":8,"sentence":1,"reference":"Matthew 15:8","text":"‘These people honor me with their lips, but their hearts are far from me."}]},{"chapter":15,"verse":9,"reference":"Matthew 15:9","text":"Their worship is a farce, for they teach man-made ideas as commands from God.’ ”","sentences":[{"id":"mt-15-9-1","chapter":15,"verse":9,"sentence":1,"reference":"Matthew 15:9","text":"Their worship is a farce, for they teach man-made ideas as commands from God.’"},{"id":"mt-15-9-2","chapter":15,"verse":9,"sentence":2,"reference":"Matthew 15:9","text":"”"}]},{"chapter":15,"verse":10,"reference":"Matthew 15:10","text":"Then Jesus called to the crowd to come and hear. “Listen,” he said, “and try to understand.","sentences":[{"id":"mt-15-10-1","chapter":15,"verse":10,"sentence":1,"reference":"Matthew 15:10","text":"Then Jesus called to the crowd to come and hear."},{"id":"mt-15-10-2","chapter":15,"verse":10,"sentence":2,"reference":"Matthew 15:10","text":"“Listen,” he said, “and try to understand."}]},{"chapter":15,"verse":11,"reference":"Matthew 15:11","text":"It’s not what goes into your mouth that defiles you; you are defiled by the words that come out of your mouth.”","sentences":[{"id":"mt-15-11-1","chapter":15,"verse":11,"sentence":1,"reference":"Matthew 15:11","text":"It’s not what goes into your mouth that defiles you; you are defiled by the words that come out of your mouth.”"}]},{"chapter":15,"verse":12,"reference":"Matthew 15:12","text":"Then the disciples came to him and asked, “Do you realize you offended the Pharisees by what you just said?”","sentences":[{"id":"mt-15-12-1","chapter":15,"verse":12,"sentence":1,"reference":"Matthew 15:12","text":"Then the disciples came to him and asked, “Do you realize you offended the Pharisees by what you just said?”"}]},{"chapter":15,"verse":13,"reference":"Matthew 15:13","text":"Jesus replied, “Every plant not planted by my heavenly Father will be uprooted,","sentences":[{"id":"mt-15-13-1","chapter":15,"verse":13,"sentence":1,"reference":"Matthew 15:13","text":"Jesus replied, “Every plant not planted by my heavenly Father will be uprooted,"}]},{"chapter":15,"verse":14,"reference":"Matthew 15:14","text":"so ignore them. They are blind guides leading the blind, and if one blind person guides another, they will both fall into a ditch.”","sentences":[{"id":"mt-15-14-1","chapter":15,"verse":14,"sentence":1,"reference":"Matthew 15:14","text":"so ignore them."},{"id":"mt-15-14-2","chapter":15,"verse":14,"sentence":2,"reference":"Matthew 15:14","text":"They are blind guides leading the blind, and if one blind person guides another, they will both fall into a ditch.”"}]},{"chapter":15,"verse":15,"reference":"Matthew 15:15","text":"Then Peter said to Jesus, “Explain to us the parable that says people aren’t defiled by what they eat.”","sentences":[{"id":"mt-15-15-1","chapter":15,"verse":15,"sentence":1,"reference":"Matthew 15:15","text":"Then Peter said to Jesus, “Explain to us the parable that says people aren’t defiled by what they eat.”"}]},{"chapter":15,"verse":16,"reference":"Matthew 15:16","text":"“Don’t you understand yet?” Jesus asked.","sentences":[{"id":"mt-15-16-1","chapter":15,"verse":16,"sentence":1,"reference":"Matthew 15:16","text":"“Don’t you understand yet?”"},{"id":"mt-15-16-2","chapter":15,"verse":16,"sentence":2,"reference":"Matthew 15:16","text":"Jesus asked."}]},{"chapter":15,"verse":17,"reference":"Matthew 15:17","text":"“Anything you eat passes through the stomach and then goes into the sewer.","sentences":[{"id":"mt-15-17-1","chapter":15,"verse":17,"sentence":1,"reference":"Matthew 15:17","text":"“Anything you eat passes through the stomach and then goes into the sewer."}]},{"chapter":15,"verse":18,"reference":"Matthew 15:18","text":"But the words you speak come from the heart—that’s what defiles you.","sentences":[{"id":"mt-15-18-1","chapter":15,"verse":18,"sentence":1,"reference":"Matthew 15:18","text":"But the words you speak come from the heart—that’s what defiles you."}]},{"chapter":15,"verse":19,"reference":"Matthew 15:19","text":"For from the heart come evil thoughts, murder, adultery, all sexual immorality, theft, lying, and slander.","sentences":[{"id":"mt-15-19-1","chapter":15,"verse":19,"sentence":1,"reference":"Matthew 15:19","text":"For from the heart come evil thoughts, murder, adultery, all sexual immorality, theft, lying, and slander."}]},{"chapter":15,"verse":20,"reference":"Matthew 15:20","text":"These are what defile you. Eating with unwashed hands will never defile you.”","sentences":[{"id":"mt-15-20-1","chapter":15,"verse":20,"sentence":1,"reference":"Matthew 15:20","text":"These are what defile you."},{"id":"mt-15-20-2","chapter":15,"verse":20,"sentence":2,"reference":"Matthew 15:20","text":"Eating with unwashed hands will never defile you.”"}]},{"chapter":15,"verse":21,"reference":"Matthew 15:21","text":"Then Jesus left Galilee and went north to the region of Tyre and Sidon.","sentences":[{"id":"mt-15-21-1","chapter":15,"verse":21,"sentence":1,"reference":"Matthew 15:21","text":"Then Jesus left Galilee and went north to the region of Tyre and Sidon."}]},{"chapter":15,"verse":22,"reference":"Matthew 15:22","text":"A Gentile woman who lived there came to him, pleading, “Have mercy on me, O Lord, Son of David! For my daughter is possessed by a demon that torments her severely.”","sentences":[{"id":"mt-15-22-1","chapter":15,"verse":22,"sentence":1,"reference":"Matthew 15:22","text":"A Gentile woman who lived there came to him, pleading, “Have mercy on me, O Lord, Son of David!"},{"id":"mt-15-22-2","chapter":15,"verse":22,"sentence":2,"reference":"Matthew 15:22","text":"For my daughter is possessed by a demon that torments her severely.”"}]},{"chapter":15,"verse":23,"reference":"Matthew 15:23","text":"But Jesus gave her no reply, not even a word. Then his disciples urged him to send her away. “Tell her to go away,” they said. “She is bothering us with all her begging.”","sentences":[{"id":"mt-15-23-1","chapter":15,"verse":23,"sentence":1,"reference":"Matthew 15:23","text":"But Jesus gave her no reply, not even a word."},{"id":"mt-15-23-2","chapter":15,"verse":23,"sentence":2,"reference":"Matthew 15:23","text":"Then his disciples urged him to send her away."},{"id":"mt-15-23-3","chapter":15,"verse":23,"sentence":3,"reference":"Matthew 15:23","text":"“Tell her to go away,” they said."},{"id":"mt-15-23-4","chapter":15,"verse":23,"sentence":4,"reference":"Matthew 15:23","text":"“She is bothering us with all her begging.”"}]},{"chapter":15,"verse":24,"reference":"Matthew 15:24","text":"Then Jesus said to the woman, “I was sent only to help God’s lost sheep—the people of Israel.”","sentences":[{"id":"mt-15-24-1","chapter":15,"verse":24,"sentence":1,"reference":"Matthew 15:24","text":"Then Jesus said to the woman, “I was sent only to help God’s lost sheep—the people of Israel.”"}]},{"chapter":15,"verse":25,"reference":"Matthew 15:25","text":"But she came and worshiped him, pleading again, “Lord, help me!”","sentences":[{"id":"mt-15-25-1","chapter":15,"verse":25,"sentence":1,"reference":"Matthew 15:25","text":"But she came and worshiped him, pleading again, “Lord, help me!”"}]},{"chapter":15,"verse":26,"reference":"Matthew 15:26","text":"Jesus responded, “It isn’t right to take food from the children and throw it to the dogs.”","sentences":[{"id":"mt-15-26-1","chapter":15,"verse":26,"sentence":1,"reference":"Matthew 15:26","text":"Jesus responded, “It isn’t right to take food from the children and throw it to the dogs.”"}]},{"chapter":15,"verse":27,"reference":"Matthew 15:27","text":"She replied, “That’s true, Lord, but even dogs are allowed to eat the scraps that fall beneath their masters’ table.”","sentences":[{"id":"mt-15-27-1","chapter":15,"verse":27,"sentence":1,"reference":"Matthew 15:27","text":"She replied, “That’s true, Lord, but even dogs are allowed to eat the scraps that fall beneath their masters’ table.”"}]},{"chapter":15,"verse":28,"reference":"Matthew 15:28","text":"“Dear woman,” Jesus said to her, “your faith is great. Your request is granted.” And her daughter was instantly healed.","sentences":[{"id":"mt-15-28-1","chapter":15,"verse":28,"sentence":1,"reference":"Matthew 15:28","text":"“Dear woman,” Jesus said to her, “your faith is great."},{"id":"mt-15-28-2","chapter":15,"verse":28,"sentence":2,"reference":"Matthew 15:28","text":"Your request is granted.”"},{"id":"mt-15-28-3","chapter":15,"verse":28,"sentence":3,"reference":"Matthew 15:28","text":"And her daughter was instantly healed."}]},{"chapter":15,"verse":29,"reference":"Matthew 15:29","text":"Jesus returned to the Sea of Galilee and climbed a hill and sat down.","sentences":[{"id":"mt-15-29-1","chapter":15,"verse":29,"sentence":1,"reference":"Matthew 15:29","text":"Jesus returned to the Sea of Galilee and climbed a hill and sat down."}]},{"chapter":15,"verse":30,"reference":"Matthew 15:30","text":"A vast crowd brought to him people who were lame, blind, crippled, those who couldn’t speak, and many others. They laid them before Jesus, and he healed them all.","sentences":[{"id":"mt-15-30-1","chapter":15,"verse":30,"sentence":1,"reference":"Matthew 15:30","text":"A vast crowd brought to him people who were lame, blind, crippled, those who couldn’t speak, and many others."},{"id":"mt-15-30-2","chapter":15,"verse":30,"sentence":2,"reference":"Matthew 15:30","text":"They laid them before Jesus, and he healed them all."}]},{"chapter":15,"verse":31,"reference":"Matthew 15:31","text":"The crowd was amazed! Those who hadn’t been able to speak were talking, the crippled were made well, the lame were walking, and the blind could see again! And they praised the God of Israel.","sentences":[{"id":"mt-15-31-1","chapter":15,"verse":31,"sentence":1,"reference":"Matthew 15:31","text":"The crowd was amazed!"},{"id":"mt-15-31-2","chapter":15,"verse":31,"sentence":2,"reference":"Matthew 15:31","text":"Those who hadn’t been able to speak were talking, the crippled were made well, the lame were walking, and the blind could see again!"},{"id":"mt-15-31-3","chapter":15,"verse":31,"sentence":3,"reference":"Matthew 15:31","text":"And they praised the God of Israel."}]},{"chapter":15,"verse":32,"reference":"Matthew 15:32","text":"Then Jesus called his disciples and told them, “I feel sorry for these people. They have been here with me for three days, and they have nothing left to eat. I don’t want to send them away hungry, or they will faint along the way.”","sentences":[{"id":"mt-15-32-1","chapter":15,"verse":32,"sentence":1,"reference":"Matthew 15:32","text":"Then Jesus called his disciples and told them, “I feel sorry for these people."},{"id":"mt-15-32-2","chapter":15,"verse":32,"sentence":2,"reference":"Matthew 15:32","text":"They have been here with me for three days, and they have nothing left to eat."},{"id":"mt-15-32-3","chapter":15,"verse":32,"sentence":3,"reference":"Matthew 15:32","text":"I don’t want to send them away hungry, or they will faint along the way.”"}]},{"chapter":15,"verse":33,"reference":"Matthew 15:33","text":"The disciples replied, “Where would we get enough food here in the wilderness for such a huge crowd?”","sentences":[{"id":"mt-15-33-1","chapter":15,"verse":33,"sentence":1,"reference":"Matthew 15:33","text":"The disciples replied, “Where would we get enough food here in the wilderness for such a huge crowd?”"}]},{"chapter":15,"verse":34,"reference":"Matthew 15:34","text":"Jesus asked, “How much bread do you have?” They replied, “Seven loaves, and a few small fish.”","sentences":[{"id":"mt-15-34-1","chapter":15,"verse":34,"sentence":1,"reference":"Matthew 15:34","text":"Jesus asked, “How much bread do you have?”"},{"id":"mt-15-34-2","chapter":15,"verse":34,"sentence":2,"reference":"Matthew 15:34","text":"They replied, “Seven loaves, and a few small fish.”"}]},{"chapter":15,"verse":35,"reference":"Matthew 15:35","text":"So Jesus told all the people to sit down on the ground.","sentences":[{"id":"mt-15-35-1","chapter":15,"verse":35,"sentence":1,"reference":"Matthew 15:35","text":"So Jesus told all the people to sit down on the ground."}]},{"chapter":15,"verse":36,"reference":"Matthew 15:36","text":"Then he took the seven loaves and the fish, thanked God for them, and broke them into pieces. He gave them to the disciples, who distributed the food to the crowd.","sentences":[{"id":"mt-15-36-1","chapter":15,"verse":36,"sentence":1,"reference":"Matthew 15:36","text":"Then he took the seven loaves and the fish, thanked God for them, and broke them into pieces."},{"id":"mt-15-36-2","chapter":15,"verse":36,"sentence":2,"reference":"Matthew 15:36","text":"He gave them to the disciples, who distributed the food to the crowd."}]},{"chapter":15,"verse":37,"reference":"Matthew 15:37","text":"They all ate as much as they wanted. Afterward, the disciples picked up seven large baskets of leftover food.","sentences":[{"id":"mt-15-37-1","chapter":15,"verse":37,"sentence":1,"reference":"Matthew 15:37","text":"They all ate as much as they wanted."},{"id":"mt-15-37-2","chapter":15,"verse":37,"sentence":2,"reference":"Matthew 15:37","text":"Afterward, the disciples picked up seven large baskets of leftover food."}]},{"chapter":15,"verse":38,"reference":"Matthew 15:38","text":"There were 4,000 men who were fed that day, in addition to all the women and children.","sentences":[{"id":"mt-15-38-1","chapter":15,"verse":38,"sentence":1,"reference":"Matthew 15:38","text":"There were 4,000 men who were fed that day, in addition to all the women and children."}]},{"chapter":15,"verse":39,"reference":"Matthew 15:39","text":"Then Jesus sent the people home, and he got into a boat and crossed over to the region of Magadan.","sentences":[{"id":"mt-15-39-1","chapter":15,"verse":39,"sentence":1,"reference":"Matthew 15:39","text":"Then Jesus sent the people home, and he got into a boat and crossed over to the region of Magadan."}]}]},{"chapter":16,"verses":[{"chapter":16,"verse":1,"reference":"Matthew 16:1","text":"One day the Pharisees and Sadducees came to test Jesus, demanding that he show them a miraculous sign from heaven to prove his authority.","sentences":[{"id":"mt-16-1-1","chapter":16,"verse":1,"sentence":1,"reference":"Matthew 16:1","text":"One day the Pharisees and Sadducees came to test Jesus, demanding that he show them a miraculous sign from heaven to prove his authority."}]},{"chapter":16,"verse":2,"reference":"Matthew 16:2","text":"He replied, “You know the saying, ‘Red sky at night means fair weather tomorrow;","sentences":[{"id":"mt-16-2-1","chapter":16,"verse":2,"sentence":1,"reference":"Matthew 16:2","text":"He replied, “You know the saying, ‘Red sky at night means fair weather tomorrow;"}]},{"chapter":16,"verse":3,"reference":"Matthew 16:3","text":"red sky in the morning means foul weather all day.’ You know how to interpret the weather signs in the sky, but you don’t know how to interpret the signs of the times!","sentences":[{"id":"mt-16-3-1","chapter":16,"verse":3,"sentence":1,"reference":"Matthew 16:3","text":"red sky in the morning means foul weather all day.’"},{"id":"mt-16-3-2","chapter":16,"verse":3,"sentence":2,"reference":"Matthew 16:3","text":"You know how to interpret the weather signs in the sky, but you don’t know how to interpret the signs of the times!"}]},{"chapter":16,"verse":4,"reference":"Matthew 16:4","text":"Only an evil, adulterous generation would demand a miraculous sign, but the only sign I will give them is the sign of the prophet Jonah.” Then Jesus left them and went away.","sentences":[{"id":"mt-16-4-1","chapter":16,"verse":4,"sentence":1,"reference":"Matthew 16:4","text":"Only an evil, adulterous generation would demand a miraculous sign, but the only sign I will give them is the sign of the prophet Jonah.”"},{"id":"mt-16-4-2","chapter":16,"verse":4,"sentence":2,"reference":"Matthew 16:4","text":"Then Jesus left them and went away."}]},{"chapter":16,"verse":5,"reference":"Matthew 16:5","text":"Later, after they crossed to the other side of the lake, the disciples discovered they had forgotten to bring any bread.","sentences":[{"id":"mt-16-5-1","chapter":16,"verse":5,"sentence":1,"reference":"Matthew 16:5","text":"Later, after they crossed to the other side of the lake, the disciples discovered they had forgotten to bring any bread."}]},{"chapter":16,"verse":6,"reference":"Matthew 16:6","text":"“Watch out!” Jesus warned them. “Beware of the yeast of the Pharisees and Sadducees.”","sentences":[{"id":"mt-16-6-1","chapter":16,"verse":6,"sentence":1,"reference":"Matthew 16:6","text":"“Watch out!”"},{"id":"mt-16-6-2","chapter":16,"verse":6,"sentence":2,"reference":"Matthew 16:6","text":"Jesus warned them."},{"id":"mt-16-6-3","chapter":16,"verse":6,"sentence":3,"reference":"Matthew 16:6","text":"“Beware of the yeast of the Pharisees and Sadducees.”"}]},{"chapter":16,"verse":7,"reference":"Matthew 16:7","text":"At this they began to argue with each other because they hadn’t brought any bread.","sentences":[{"id":"mt-16-7-1","chapter":16,"verse":7,"sentence":1,"reference":"Matthew 16:7","text":"At this they began to argue with each other because they hadn’t brought any bread."}]},{"chapter":16,"verse":8,"reference":"Matthew 16:8","text":"Jesus knew what they were saying, so he said, “You have so little faith! Why are you arguing with each other about having no bread?","sentences":[{"id":"mt-16-8-1","chapter":16,"verse":8,"sentence":1,"reference":"Matthew 16:8","text":"Jesus knew what they were saying, so he said, “You have so little faith!"},{"id":"mt-16-8-2","chapter":16,"verse":8,"sentence":2,"reference":"Matthew 16:8","text":"Why are you arguing with each other about having no bread?"}]},{"chapter":16,"verse":9,"reference":"Matthew 16:9","text":"Don’t you understand even yet? Don’t you remember the 5,000 I fed with five loaves, and the baskets of leftovers you picked up?","sentences":[{"id":"mt-16-9-1","chapter":16,"verse":9,"sentence":1,"reference":"Matthew 16:9","text":"Don’t you understand even yet?"},{"id":"mt-16-9-2","chapter":16,"verse":9,"sentence":2,"reference":"Matthew 16:9","text":"Don’t you remember the 5,000 I fed with five loaves, and the baskets of leftovers you picked up?"}]},{"chapter":16,"verse":10,"reference":"Matthew 16:10","text":"Or the 4,000 I fed with seven loaves, and the large baskets of leftovers you picked up?","sentences":[{"id":"mt-16-10-1","chapter":16,"verse":10,"sentence":1,"reference":"Matthew 16:10","text":"Or the 4,000 I fed with seven loaves, and the large baskets of leftovers you picked up?"}]},{"chapter":16,"verse":11,"reference":"Matthew 16:11","text":"Why can’t you understand that I’m not talking about bread? So again I say, ‘Beware of the yeast of the Pharisees and Sadducees.’”","sentences":[{"id":"mt-16-11-1","chapter":16,"verse":11,"sentence":1,"reference":"Matthew 16:11","text":"Why can’t you understand that I’m not talking about bread?"},{"id":"mt-16-11-2","chapter":16,"verse":11,"sentence":2,"reference":"Matthew 16:11","text":"So again I say, ‘Beware of the yeast of the Pharisees and Sadducees.’”"}]},{"chapter":16,"verse":12,"reference":"Matthew 16:12","text":"Then at last they understood that he wasn’t speaking about the yeast in bread, but about the deceptive teaching of the Pharisees and Sadducees.","sentences":[{"id":"mt-16-12-1","chapter":16,"verse":12,"sentence":1,"reference":"Matthew 16:12","text":"Then at last they understood that he wasn’t speaking about the yeast in bread, but about the deceptive teaching of the Pharisees and Sadducees."}]},{"chapter":16,"verse":13,"reference":"Matthew 16:13","text":"When Jesus came to the region of Caesarea Philippi, he asked his disciples, “Who do people say that the Son of Man is?”","sentences":[{"id":"mt-16-13-1","chapter":16,"verse":13,"sentence":1,"reference":"Matthew 16:13","text":"When Jesus came to the region of Caesarea Philippi, he asked his disciples, “Who do people say that the Son of Man is?”"}]},{"chapter":16,"verse":14,"reference":"Matthew 16:14","text":"“Well,” they replied, “some say John the Baptist, some say Elijah, and others say Jeremiah or one of the other prophets.”","sentences":[{"id":"mt-16-14-1","chapter":16,"verse":14,"sentence":1,"reference":"Matthew 16:14","text":"“Well,” they replied, “some say John the Baptist, some say Elijah, and others say Jeremiah or one of the other prophets.”"}]},{"chapter":16,"verse":15,"reference":"Matthew 16:15","text":"Then he asked them, “But who do you say I am?”","sentences":[{"id":"mt-16-15-1","chapter":16,"verse":15,"sentence":1,"reference":"Matthew 16:15","text":"Then he asked them, “But who do you say I am?”"}]},{"chapter":16,"verse":16,"reference":"Matthew 16:16","text":"Simon Peter answered, “You are the Messiah, the Son of the living God.”","sentences":[{"id":"mt-16-16-1","chapter":16,"verse":16,"sentence":1,"reference":"Matthew 16:16","text":"Simon Peter answered, “You are the Messiah, the Son of the living God.”"}]},{"chapter":16,"verse":17,"reference":"Matthew 16:17","text":"Jesus replied, “You are blessed, Simon son of John, because my Father in heaven has revealed this to you. You did not learn this from any human being.","sentences":[{"id":"mt-16-17-1","chapter":16,"verse":17,"sentence":1,"reference":"Matthew 16:17","text":"Jesus replied, “You are blessed, Simon son of John, because my Father in heaven has revealed this to you."},{"id":"mt-16-17-2","chapter":16,"verse":17,"sentence":2,"reference":"Matthew 16:17","text":"You did not learn this from any human being."}]},{"chapter":16,"verse":18,"reference":"Matthew 16:18","text":"Now I say to you that you are Peter (which means ‘rock’), and upon this rock I will build my church, and all the powers of hell will not conquer it.","sentences":[{"id":"mt-16-18-1","chapter":16,"verse":18,"sentence":1,"reference":"Matthew 16:18","text":"Now I say to you that you are Peter (which means ‘rock’), and upon this rock I will build my church, and all the powers of hell will not conquer it."}]},{"chapter":16,"verse":19,"reference":"Matthew 16:19","text":"And I will give you the keys of the Kingdom of Heaven. Whatever you forbid on earth will be forbidden in heaven, and whatever you permit on earth will be permitted in heaven.”","sentences":[{"id":"mt-16-19-1","chapter":16,"verse":19,"sentence":1,"reference":"Matthew 16:19","text":"And I will give you the keys of the Kingdom of Heaven."},{"id":"mt-16-19-2","chapter":16,"verse":19,"sentence":2,"reference":"Matthew 16:19","text":"Whatever you forbid on earth will be forbidden in heaven, and whatever you permit on earth will be permitted in heaven.”"}]},{"chapter":16,"verse":20,"reference":"Matthew 16:20","text":"Then he sternly warned the disciples not to tell anyone that he was the Messiah.","sentences":[{"id":"mt-16-20-1","chapter":16,"verse":20,"sentence":1,"reference":"Matthew 16:20","text":"Then he sternly warned the disciples not to tell anyone that he was the Messiah."}]},{"chapter":16,"verse":21,"reference":"Matthew 16:21","text":"From then on Jesus began to tell his disciples plainly that it was necessary for him to go to Jerusalem, and that he would suffer many terrible things at the hands of the elders, the leading priests, and the teachers of religious law. He would be killed, but on the third day he would be raised from the dead.","sentences":[{"id":"mt-16-21-1","chapter":16,"verse":21,"sentence":1,"reference":"Matthew 16:21","text":"From then on Jesus began to tell his disciples plainly that it was necessary for him to go to Jerusalem, and that he would suffer many terrible things at the hands of the elders, the leading priests, and the teachers of religious law."},{"id":"mt-16-21-2","chapter":16,"verse":21,"sentence":2,"reference":"Matthew 16:21","text":"He would be killed, but on the third day he would be raised from the dead."}]},{"chapter":16,"verse":22,"reference":"Matthew 16:22","text":"But Peter took him aside and began to reprimand him for saying such things. “Heaven forbid, Lord,” he said. “This will never happen to you!”","sentences":[{"id":"mt-16-22-1","chapter":16,"verse":22,"sentence":1,"reference":"Matthew 16:22","text":"But Peter took him aside and began to reprimand him for saying such things."},{"id":"mt-16-22-2","chapter":16,"verse":22,"sentence":2,"reference":"Matthew 16:22","text":"“Heaven forbid, Lord,” he said."},{"id":"mt-16-22-3","chapter":16,"verse":22,"sentence":3,"reference":"Matthew 16:22","text":"“This will never happen to you!”"}]},{"chapter":16,"verse":23,"reference":"Matthew 16:23","text":"Jesus turned to Peter and said, “Get away from me, Satan! You are a dangerous trap to me. You are seeing things merely from a human point of view, not from God’s.”","sentences":[{"id":"mt-16-23-1","chapter":16,"verse":23,"sentence":1,"reference":"Matthew 16:23","text":"Jesus turned to Peter and said, “Get away from me, Satan!"},{"id":"mt-16-23-2","chapter":16,"verse":23,"sentence":2,"reference":"Matthew 16:23","text":"You are a dangerous trap to me."},{"id":"mt-16-23-3","chapter":16,"verse":23,"sentence":3,"reference":"Matthew 16:23","text":"You are seeing things merely from a human point of view, not from God’s.”"}]},{"chapter":16,"verse":24,"reference":"Matthew 16:24","text":"Then Jesus said to his disciples, “If any of you wants to be my follower, you must give up your own way, take up your cross, and follow me.","sentences":[{"id":"mt-16-24-1","chapter":16,"verse":24,"sentence":1,"reference":"Matthew 16:24","text":"Then Jesus said to his disciples, “If any of you wants to be my follower, you must give up your own way, take up your cross, and follow me."}]},{"chapter":16,"verse":25,"reference":"Matthew 16:25","text":"If you try to hang on to your life, you will lose it. But if you give up your life for my sake, you will save it.","sentences":[{"id":"mt-16-25-1","chapter":16,"verse":25,"sentence":1,"reference":"Matthew 16:25","text":"If you try to hang on to your life, you will lose it."},{"id":"mt-16-25-2","chapter":16,"verse":25,"sentence":2,"reference":"Matthew 16:25","text":"But if you give up your life for my sake, you will save it."}]},{"chapter":16,"verse":26,"reference":"Matthew 16:26","text":"And what do you benefit if you gain the whole world but lose your own soul? Is anything worth more than your soul?","sentences":[{"id":"mt-16-26-1","chapter":16,"verse":26,"sentence":1,"reference":"Matthew 16:26","text":"And what do you benefit if you gain the whole world but lose your own soul?"},{"id":"mt-16-26-2","chapter":16,"verse":26,"sentence":2,"reference":"Matthew 16:26","text":"Is anything worth more than your soul?"}]},{"chapter":16,"verse":27,"reference":"Matthew 16:27","text":"For the Son of Man will come with his angels in the glory of his Father and will judge all people according to their deeds.","sentences":[{"id":"mt-16-27-1","chapter":16,"verse":27,"sentence":1,"reference":"Matthew 16:27","text":"For the Son of Man will come with his angels in the glory of his Father and will judge all people according to their deeds."}]},{"chapter":16,"verse":28,"reference":"Matthew 16:28","text":"And I tell you the truth, some standing here right now will not die before they see the Son of Man coming in his Kingdom.”","sentences":[{"id":"mt-16-28-1","chapter":16,"verse":28,"sentence":1,"reference":"Matthew 16:28","text":"And I tell you the truth, some standing here right now will not die before they see the Son of Man coming in his Kingdom.”"}]}]},{"chapter":17,"verses":[{"chapter":17,"verse":1,"reference":"Matthew 17:1","text":"Six days later Jesus took Peter and the two brothers, James and John, and led them up a high mountain to be alone.","sentences":[{"id":"mt-17-1-1","chapter":17,"verse":1,"sentence":1,"reference":"Matthew 17:1","text":"Six days later Jesus took Peter and the two brothers, James and John, and led them up a high mountain to be alone."}]},{"chapter":17,"verse":2,"reference":"Matthew 17:2","text":"As the men watched, Jesus’ appearance was transformed so that his face shone like the sun, and his clothes became as white as light.","sentences":[{"id":"mt-17-2-1","chapter":17,"verse":2,"sentence":1,"reference":"Matthew 17:2","text":"As the men watched, Jesus’ appearance was transformed so that his face shone like the sun, and his clothes became as white as light."}]},{"chapter":17,"verse":3,"reference":"Matthew 17:3","text":"Suddenly, Moses and Elijah appeared and began talking with Jesus.","sentences":[{"id":"mt-17-3-1","chapter":17,"verse":3,"sentence":1,"reference":"Matthew 17:3","text":"Suddenly, Moses and Elijah appeared and began talking with Jesus."}]},{"chapter":17,"verse":4,"reference":"Matthew 17:4","text":"Peter exclaimed, “Lord, it’s wonderful for us to be here! If you want, I’ll make three shelters as memorials—one for you, one for Moses, and one for Elijah.”","sentences":[{"id":"mt-17-4-1","chapter":17,"verse":4,"sentence":1,"reference":"Matthew 17:4","text":"Peter exclaimed, “Lord, it’s wonderful for us to be here!"},{"id":"mt-17-4-2","chapter":17,"verse":4,"sentence":2,"reference":"Matthew 17:4","text":"If you want, I’ll make three shelters as memorials—one for you, one for Moses, and one for Elijah.”"}]},{"chapter":17,"verse":5,"reference":"Matthew 17:5","text":"But even as he spoke, a bright cloud overshadowed them, and a voice from the cloud said, “This is my dearly loved Son, who brings me great joy. Listen to him.”","sentences":[{"id":"mt-17-5-1","chapter":17,"verse":5,"sentence":1,"reference":"Matthew 17:5","text":"But even as he spoke, a bright cloud overshadowed them, and a voice from the cloud said, “This is my dearly loved Son, who brings me great joy."},{"id":"mt-17-5-2","chapter":17,"verse":5,"sentence":2,"reference":"Matthew 17:5","text":"Listen to him.”"}]},{"chapter":17,"verse":6,"reference":"Matthew 17:6","text":"The disciples were terrified and fell face down on the ground.","sentences":[{"id":"mt-17-6-1","chapter":17,"verse":6,"sentence":1,"reference":"Matthew 17:6","text":"The disciples were terrified and fell face down on the ground."}]},{"chapter":17,"verse":7,"reference":"Matthew 17:7","text":"Then Jesus came over and touched them. “Get up,” he said. “Don’t be afraid.”","sentences":[{"id":"mt-17-7-1","chapter":17,"verse":7,"sentence":1,"reference":"Matthew 17:7","text":"Then Jesus came over and touched them."},{"id":"mt-17-7-2","chapter":17,"verse":7,"sentence":2,"reference":"Matthew 17:7","text":"“Get up,” he said."},{"id":"mt-17-7-3","chapter":17,"verse":7,"sentence":3,"reference":"Matthew 17:7","text":"“Don’t be afraid.”"}]},{"chapter":17,"verse":8,"reference":"Matthew 17:8","text":"And when they looked up, Moses and Elijah were gone, and they saw only Jesus.","sentences":[{"id":"mt-17-8-1","chapter":17,"verse":8,"sentence":1,"reference":"Matthew 17:8","text":"And when they looked up, Moses and Elijah were gone, and they saw only Jesus."}]},{"chapter":17,"verse":9,"reference":"Matthew 17:9","text":"As they went back down the mountain, Jesus commanded them, “Don’t tell anyone what you have seen until the Son of Man has been raised from the dead.”","sentences":[{"id":"mt-17-9-1","chapter":17,"verse":9,"sentence":1,"reference":"Matthew 17:9","text":"As they went back down the mountain, Jesus commanded them, “Don’t tell anyone what you have seen until the Son of Man has been raised from the dead.”"}]},{"chapter":17,"verse":10,"reference":"Matthew 17:10","text":"Then his disciples asked him, “Why do the teachers of religious law insist that Elijah must return before the Messiah comes?”","sentences":[{"id":"mt-17-10-1","chapter":17,"verse":10,"sentence":1,"reference":"Matthew 17:10","text":"Then his disciples asked him, “Why do the teachers of religious law insist that Elijah must return before the Messiah comes?”"}]},{"chapter":17,"verse":11,"reference":"Matthew 17:11","text":"Jesus replied, “Elijah is indeed coming first to get everything ready.","sentences":[{"id":"mt-17-11-1","chapter":17,"verse":11,"sentence":1,"reference":"Matthew 17:11","text":"Jesus replied, “Elijah is indeed coming first to get everything ready."}]},{"chapter":17,"verse":12,"reference":"Matthew 17:12","text":"But I tell you, Elijah has already come, but he wasn’t recognized, and they chose to abuse him. And in the same way they will also make the Son of Man suffer.”","sentences":[{"id":"mt-17-12-1","chapter":17,"verse":12,"sentence":1,"reference":"Matthew 17:12","text":"But I tell you, Elijah has already come, but he wasn’t recognized, and they chose to abuse him."},{"id":"mt-17-12-2","chapter":17,"verse":12,"sentence":2,"reference":"Matthew 17:12","text":"And in the same way they will also make the Son of Man suffer.”"}]},{"chapter":17,"verse":13,"reference":"Matthew 17:13","text":"Then the disciples realized he was talking about John the Baptist.","sentences":[{"id":"mt-17-13-1","chapter":17,"verse":13,"sentence":1,"reference":"Matthew 17:13","text":"Then the disciples realized he was talking about John the Baptist."}]},{"chapter":17,"verse":14,"reference":"Matthew 17:14","text":"At the foot of the mountain, a large crowd was waiting for them. A man came and knelt before Jesus and said,","sentences":[{"id":"mt-17-14-1","chapter":17,"verse":14,"sentence":1,"reference":"Matthew 17:14","text":"At the foot of the mountain, a large crowd was waiting for them."},{"id":"mt-17-14-2","chapter":17,"verse":14,"sentence":2,"reference":"Matthew 17:14","text":"A man came and knelt before Jesus and said,"}]},{"chapter":17,"verse":15,"reference":"Matthew 17:15","text":"“Lord, have mercy on my son. He has seizures and suffers terribly. He often falls into the fire or into the water.","sentences":[{"id":"mt-17-15-1","chapter":17,"verse":15,"sentence":1,"reference":"Matthew 17:15","text":"“Lord, have mercy on my son."},{"id":"mt-17-15-2","chapter":17,"verse":15,"sentence":2,"reference":"Matthew 17:15","text":"He has seizures and suffers terribly."},{"id":"mt-17-15-3","chapter":17,"verse":15,"sentence":3,"reference":"Matthew 17:15","text":"He often falls into the fire or into the water."}]},{"chapter":17,"verse":16,"reference":"Matthew 17:16","text":"So I brought him to your disciples, but they couldn’t heal him.”","sentences":[{"id":"mt-17-16-1","chapter":17,"verse":16,"sentence":1,"reference":"Matthew 17:16","text":"So I brought him to your disciples, but they couldn’t heal him.”"}]},{"chapter":17,"verse":17,"reference":"Matthew 17:17","text":"Jesus said, “You faithless and corrupt people! How long must I be with you? How long must I put up with you? Bring the boy here to me.”","sentences":[{"id":"mt-17-17-1","chapter":17,"verse":17,"sentence":1,"reference":"Matthew 17:17","text":"Jesus said, “You faithless and corrupt people!"},{"id":"mt-17-17-2","chapter":17,"verse":17,"sentence":2,"reference":"Matthew 17:17","text":"How long must I be with you?"},{"id":"mt-17-17-3","chapter":17,"verse":17,"sentence":3,"reference":"Matthew 17:17","text":"How long must I put up with you?"},{"id":"mt-17-17-4","chapter":17,"verse":17,"sentence":4,"reference":"Matthew 17:17","text":"Bring the boy here to me.”"}]},{"chapter":17,"verse":18,"reference":"Matthew 17:18","text":"Then Jesus rebuked the demon in the boy, and it left him. From that moment the boy was well.","sentences":[{"id":"mt-17-18-1","chapter":17,"verse":18,"sentence":1,"reference":"Matthew 17:18","text":"Then Jesus rebuked the demon in the boy, and it left him."},{"id":"mt-17-18-2","chapter":17,"verse":18,"sentence":2,"reference":"Matthew 17:18","text":"From that moment the boy was well."}]},{"chapter":17,"verse":19,"reference":"Matthew 17:19","text":"Afterward the disciples asked Jesus privately, “Why couldn’t we cast out that demon?”","sentences":[{"id":"mt-17-19-1","chapter":17,"verse":19,"sentence":1,"reference":"Matthew 17:19","text":"Afterward the disciples asked Jesus privately, “Why couldn’t we cast out that demon?”"}]},{"chapter":17,"verse":20,"reference":"Matthew 17:20","text":"“You don’t have enough faith,” Jesus told them. “I tell you the truth, if you had faith even as small as a mustard seed, you could say to this mountain, ‘Move from here to there,’ and it would move. Nothing would be impossible.”","sentences":[{"id":"mt-17-20-1","chapter":17,"verse":20,"sentence":1,"reference":"Matthew 17:20","text":"“You don’t have enough faith,” Jesus told them."},{"id":"mt-17-20-2","chapter":17,"verse":20,"sentence":2,"reference":"Matthew 17:20","text":"“I tell you the truth, if you had faith even as small as a mustard seed, you could say to this mountain, ‘Move from here to there,’ and it would move."},{"id":"mt-17-20-3","chapter":17,"verse":20,"sentence":3,"reference":"Matthew 17:20","text":"Nothing would be impossible.”"}]},{"chapter":17,"verse":22,"reference":"Matthew 17:22","text":"After they gathered again in Galilee, Jesus told them, “The Son of Man is going to be betrayed into the hands of his enemies.","sentences":[{"id":"mt-17-22-1","chapter":17,"verse":22,"sentence":1,"reference":"Matthew 17:22","text":"After they gathered again in Galilee, Jesus told them, “The Son of Man is going to be betrayed into the hands of his enemies."}]},{"chapter":17,"verse":23,"reference":"Matthew 17:23","text":"He will be killed, but on the third day he will be raised from the dead.” And the disciples were filled with grief.","sentences":[{"id":"mt-17-23-1","chapter":17,"verse":23,"sentence":1,"reference":"Matthew 17:23","text":"He will be killed, but on the third day he will be raised from the dead.”"},{"id":"mt-17-23-2","chapter":17,"verse":23,"sentence":2,"reference":"Matthew 17:23","text":"And the disciples were filled with grief."}]},{"chapter":17,"verse":24,"reference":"Matthew 17:24","text":"On their arrival in Capernaum, the collectors of the Temple tax came to Peter and asked him, “Doesn’t your teacher pay the Temple tax?”","sentences":[{"id":"mt-17-24-1","chapter":17,"verse":24,"sentence":1,"reference":"Matthew 17:24","text":"On their arrival in Capernaum, the collectors of the Temple tax came to Peter and asked him, “Doesn’t your teacher pay the Temple tax?”"}]},{"chapter":17,"verse":25,"reference":"Matthew 17:25","text":"“Yes, he does,” Peter replied. Then he went into the house. But before he had a chance to speak, Jesus asked him, “What do you think, Peter? Do kings tax their own people or the people they have conquered?”","sentences":[{"id":"mt-17-25-1","chapter":17,"verse":25,"sentence":1,"reference":"Matthew 17:25","text":"“Yes, he does,” Peter replied."},{"id":"mt-17-25-2","chapter":17,"verse":25,"sentence":2,"reference":"Matthew 17:25","text":"Then he went into the house."},{"id":"mt-17-25-3","chapter":17,"verse":25,"sentence":3,"reference":"Matthew 17:25","text":"But before he had a chance to speak, Jesus asked him, “What do you think, Peter?"},{"id":"mt-17-25-4","chapter":17,"verse":25,"sentence":4,"reference":"Matthew 17:25","text":"Do kings tax their own people or the people they have conquered?”"}]},{"chapter":17,"verse":26,"reference":"Matthew 17:26","text":"“They tax the people they have conquered,” Peter replied. “Well, then,” Jesus said, “the citizens are free!","sentences":[{"id":"mt-17-26-1","chapter":17,"verse":26,"sentence":1,"reference":"Matthew 17:26","text":"“They tax the people they have conquered,” Peter replied."},{"id":"mt-17-26-2","chapter":17,"verse":26,"sentence":2,"reference":"Matthew 17:26","text":"“Well, then,” Jesus said, “the citizens are free!"}]},{"chapter":17,"verse":27,"reference":"Matthew 17:27","text":"However, we don’t want to offend them, so go down to the lake and throw in a line. Open the mouth of the first fish you catch, and you will find a large silver coin. Take it and pay the tax for both of us.”","sentences":[{"id":"mt-17-27-1","chapter":17,"verse":27,"sentence":1,"reference":"Matthew 17:27","text":"However, we don’t want to offend them, so go down to the lake and throw in a line."},{"id":"mt-17-27-2","chapter":17,"verse":27,"sentence":2,"reference":"Matthew 17:27","text":"Open the mouth of the first fish you catch, and you will find a large silver coin."},{"id":"mt-17-27-3","chapter":17,"verse":27,"sentence":3,"reference":"Matthew 17:27","text":"Take it and pay the tax for both of us.”"}]}]},{"chapter":18,"verses":[{"chapter":18,"verse":1,"reference":"Matthew 18:1","text":"About that time the disciples came to Jesus and asked, “Who is greatest in the Kingdom of Heaven?”","sentences":[{"id":"mt-18-1-1","chapter":18,"verse":1,"sentence":1,"reference":"Matthew 18:1","text":"About that time the disciples came to Jesus and asked, “Who is greatest in the Kingdom of Heaven?”"}]},{"chapter":18,"verse":2,"reference":"Matthew 18:2","text":"Jesus called a little child to him and put the child among them.","sentences":[{"id":"mt-18-2-1","chapter":18,"verse":2,"sentence":1,"reference":"Matthew 18:2","text":"Jesus called a little child to him and put the child among them."}]},{"chapter":18,"verse":3,"reference":"Matthew 18:3","text":"Then he said, “I tell you the truth, unless you turn from your sins and become like little children, you will never get into the Kingdom of Heaven.","sentences":[{"id":"mt-18-3-1","chapter":18,"verse":3,"sentence":1,"reference":"Matthew 18:3","text":"Then he said, “I tell you the truth, unless you turn from your sins and become like little children, you will never get into the Kingdom of Heaven."}]},{"chapter":18,"verse":4,"reference":"Matthew 18:4","text":"So anyone who becomes as humble as this little child is the greatest in the Kingdom of Heaven.","sentences":[{"id":"mt-18-4-1","chapter":18,"verse":4,"sentence":1,"reference":"Matthew 18:4","text":"So anyone who becomes as humble as this little child is the greatest in the Kingdom of Heaven."}]},{"chapter":18,"verse":5,"reference":"Matthew 18:5","text":"“And anyone who welcomes a little child like this on my behalf is welcoming me.","sentences":[{"id":"mt-18-5-1","chapter":18,"verse":5,"sentence":1,"reference":"Matthew 18:5","text":"“And anyone who welcomes a little child like this on my behalf is welcoming me."}]},{"chapter":18,"verse":6,"reference":"Matthew 18:6","text":"But if you cause one of these little ones who trusts in me to fall into sin, it would be better for you to have a large millstone tied around your neck and be drowned in the depths of the sea.","sentences":[{"id":"mt-18-6-1","chapter":18,"verse":6,"sentence":1,"reference":"Matthew 18:6","text":"But if you cause one of these little ones who trusts in me to fall into sin, it would be better for you to have a large millstone tied around your neck and be drowned in the depths of the sea."}]},{"chapter":18,"verse":7,"reference":"Matthew 18:7","text":"“What sorrow awaits the world, because it tempts people to sin. Temptations are inevitable, but what sorrow awaits the person who does the tempting.","sentences":[{"id":"mt-18-7-1","chapter":18,"verse":7,"sentence":1,"reference":"Matthew 18:7","text":"“What sorrow awaits the world, because it tempts people to sin."},{"id":"mt-18-7-2","chapter":18,"verse":7,"sentence":2,"reference":"Matthew 18:7","text":"Temptations are inevitable, but what sorrow awaits the person who does the tempting."}]},{"chapter":18,"verse":8,"reference":"Matthew 18:8","text":"So if your hand or foot causes you to sin, cut it off and throw it away. It’s better to enter eternal life with only one hand or one foot than to be thrown into eternal fire with both of your hands and feet.","sentences":[{"id":"mt-18-8-1","chapter":18,"verse":8,"sentence":1,"reference":"Matthew 18:8","text":"So if your hand or foot causes you to sin, cut it off and throw it away."},{"id":"mt-18-8-2","chapter":18,"verse":8,"sentence":2,"reference":"Matthew 18:8","text":"It’s better to enter eternal life with only one hand or one foot than to be thrown into eternal fire with both of your hands and feet."}]},{"chapter":18,"verse":9,"reference":"Matthew 18:9","text":"And if your eye causes you to sin, gouge it out and throw it away. It’s better to enter eternal life with only one eye than to have two eyes and be thrown into the fire of hell.","sentences":[{"id":"mt-18-9-1","chapter":18,"verse":9,"sentence":1,"reference":"Matthew 18:9","text":"And if your eye causes you to sin, gouge it out and throw it away."},{"id":"mt-18-9-2","chapter":18,"verse":9,"sentence":2,"reference":"Matthew 18:9","text":"It’s better to enter eternal life with only one eye than to have two eyes and be thrown into the fire of hell."}]},{"chapter":18,"verse":10,"reference":"Matthew 18:10","text":"“Beware that you don’t look down on any of these little ones. For I tell you that in heaven their angels are always in the presence of my heavenly Father.","sentences":[{"id":"mt-18-10-1","chapter":18,"verse":10,"sentence":1,"reference":"Matthew 18:10","text":"“Beware that you don’t look down on any of these little ones."},{"id":"mt-18-10-2","chapter":18,"verse":10,"sentence":2,"reference":"Matthew 18:10","text":"For I tell you that in heaven their angels are always in the presence of my heavenly Father."}]},{"chapter":18,"verse":12,"reference":"Matthew 18:12","text":"“If a man has a hundred sheep and one of them wanders away, what will he do? Won’t he leave the ninety-nine others on the hills and go out to search for the one that is lost?","sentences":[{"id":"mt-18-12-1","chapter":18,"verse":12,"sentence":1,"reference":"Matthew 18:12","text":"“If a man has a hundred sheep and one of them wanders away, what will he do?"},{"id":"mt-18-12-2","chapter":18,"verse":12,"sentence":2,"reference":"Matthew 18:12","text":"Won’t he leave the ninety-nine others on the hills and go out to search for the one that is lost?"}]},{"chapter":18,"verse":13,"reference":"Matthew 18:13","text":"And if he finds it, I tell you the truth, he will rejoice over it more than over the ninety-nine that didn’t wander away!","sentences":[{"id":"mt-18-13-1","chapter":18,"verse":13,"sentence":1,"reference":"Matthew 18:13","text":"And if he finds it, I tell you the truth, he will rejoice over it more than over the ninety-nine that didn’t wander away!"}]},{"chapter":18,"verse":14,"reference":"Matthew 18:14","text":"In the same way, it is not my heavenly Father’s will that even one of these little ones should perish.","sentences":[{"id":"mt-18-14-1","chapter":18,"verse":14,"sentence":1,"reference":"Matthew 18:14","text":"In the same way, it is not my heavenly Father’s will that even one of these little ones should perish."}]},{"chapter":18,"verse":15,"reference":"Matthew 18:15","text":"“If another believer sins against you, go privately and point out the offense. If the other person listens and confesses it, you have won that person back.","sentences":[{"id":"mt-18-15-1","chapter":18,"verse":15,"sentence":1,"reference":"Matthew 18:15","text":"“If another believer sins against you, go privately and point out the offense."},{"id":"mt-18-15-2","chapter":18,"verse":15,"sentence":2,"reference":"Matthew 18:15","text":"If the other person listens and confesses it, you have won that person back."}]},{"chapter":18,"verse":16,"reference":"Matthew 18:16","text":"But if you are unsuccessful, take one or two others with you and go back again, so that everything you say may be confirmed by two or three witnesses.","sentences":[{"id":"mt-18-16-1","chapter":18,"verse":16,"sentence":1,"reference":"Matthew 18:16","text":"But if you are unsuccessful, take one or two others with you and go back again, so that everything you say may be confirmed by two or three witnesses."}]},{"chapter":18,"verse":17,"reference":"Matthew 18:17","text":"If the person still refuses to listen, take your case to the church. Then if he or she won’t accept the church’s decision, treat that person as a pagan or a corrupt tax collector.","sentences":[{"id":"mt-18-17-1","chapter":18,"verse":17,"sentence":1,"reference":"Matthew 18:17","text":"If the person still refuses to listen, take your case to the church."},{"id":"mt-18-17-2","chapter":18,"verse":17,"sentence":2,"reference":"Matthew 18:17","text":"Then if he or she won’t accept the church’s decision, treat that person as a pagan or a corrupt tax collector."}]},{"chapter":18,"verse":18,"reference":"Matthew 18:18","text":"“I tell you the truth, whatever you forbid on earth will be forbidden in heaven, and whatever you permit on earth will be permitted in heaven.","sentences":[{"id":"mt-18-18-1","chapter":18,"verse":18,"sentence":1,"reference":"Matthew 18:18","text":"“I tell you the truth, whatever you forbid on earth will be forbidden in heaven, and whatever you permit on earth will be permitted in heaven."}]},{"chapter":18,"verse":19,"reference":"Matthew 18:19","text":"“I also tell you this: If two of you agree here on earth concerning anything you ask, my Father in heaven will do it for you.","sentences":[{"id":"mt-18-19-1","chapter":18,"verse":19,"sentence":1,"reference":"Matthew 18:19","text":"“I also tell you this: If two of you agree here on earth concerning anything you ask, my Father in heaven will do it for you."}]},{"chapter":18,"verse":20,"reference":"Matthew 18:20","text":"For where two or three gather together as my followers, I am there among them.”","sentences":[{"id":"mt-18-20-1","chapter":18,"verse":20,"sentence":1,"reference":"Matthew 18:20","text":"For where two or three gather together as my followers, I am there among them.”"}]},{"chapter":18,"verse":21,"reference":"Matthew 18:21","text":"Then Peter came to him and asked, “Lord, how often should I forgive someone who sins against me? Seven times?”","sentences":[{"id":"mt-18-21-1","chapter":18,"verse":21,"sentence":1,"reference":"Matthew 18:21","text":"Then Peter came to him and asked, “Lord, how often should I forgive someone who sins against me?"},{"id":"mt-18-21-2","chapter":18,"verse":21,"sentence":2,"reference":"Matthew 18:21","text":"Seven times?”"}]},{"chapter":18,"verse":22,"reference":"Matthew 18:22","text":"“No, not seven times,” Jesus replied, “but seventy times seven!","sentences":[{"id":"mt-18-22-1","chapter":18,"verse":22,"sentence":1,"reference":"Matthew 18:22","text":"“No, not seven times,” Jesus replied, “but seventy times seven!"}]},{"chapter":18,"verse":23,"reference":"Matthew 18:23","text":"“Therefore, the Kingdom of Heaven can be compared to a king who decided to bring his accounts up to date with servants who had borrowed money from him.","sentences":[{"id":"mt-18-23-1","chapter":18,"verse":23,"sentence":1,"reference":"Matthew 18:23","text":"“Therefore, the Kingdom of Heaven can be compared to a king who decided to bring his accounts up to date with servants who had borrowed money from him."}]},{"chapter":18,"verse":24,"reference":"Matthew 18:24","text":"In the process, one of his debtors was brought in who owed him millions of dollars.","sentences":[{"id":"mt-18-24-1","chapter":18,"verse":24,"sentence":1,"reference":"Matthew 18:24","text":"In the process, one of his debtors was brought in who owed him millions of dollars."}]},{"chapter":18,"verse":25,"reference":"Matthew 18:25","text":"He couldn’t pay, so his master ordered that he be sold—along with his wife, his children, and everything he owned—to pay the debt.","sentences":[{"id":"mt-18-25-1","chapter":18,"verse":25,"sentence":1,"reference":"Matthew 18:25","text":"He couldn’t pay, so his master ordered that he be sold—along with his wife, his children, and everything he owned—to pay the debt."}]},{"chapter":18,"verse":26,"reference":"Matthew 18:26","text":"“But the man fell down before his master and begged him, ‘Please, be patient with me, and I will pay it all.’","sentences":[{"id":"mt-18-26-1","chapter":18,"verse":26,"sentence":1,"reference":"Matthew 18:26","text":"“But the man fell down before his master and begged him, ‘Please, be patient with me, and I will pay it all.’"}]},{"chapter":18,"verse":27,"reference":"Matthew 18:27","text":"Then his master was filled with pity for him, and he released him and forgave his debt.","sentences":[{"id":"mt-18-27-1","chapter":18,"verse":27,"sentence":1,"reference":"Matthew 18:27","text":"Then his master was filled with pity for him, and he released him and forgave his debt."}]},{"chapter":18,"verse":28,"reference":"Matthew 18:28","text":"“But when the man left the king, he went to a fellow servant who owed him a few thousand dollars. He grabbed him by the throat and demanded instant payment.","sentences":[{"id":"mt-18-28-1","chapter":18,"verse":28,"sentence":1,"reference":"Matthew 18:28","text":"“But when the man left the king, he went to a fellow servant who owed him a few thousand dollars."},{"id":"mt-18-28-2","chapter":18,"verse":28,"sentence":2,"reference":"Matthew 18:28","text":"He grabbed him by the throat and demanded instant payment."}]},{"chapter":18,"verse":29,"reference":"Matthew 18:29","text":"“His fellow servant fell down before him and begged for a little more time. ‘Be patient with me, and I will pay it,’ he pleaded.","sentences":[{"id":"mt-18-29-1","chapter":18,"verse":29,"sentence":1,"reference":"Matthew 18:29","text":"“His fellow servant fell down before him and begged for a little more time."},{"id":"mt-18-29-2","chapter":18,"verse":29,"sentence":2,"reference":"Matthew 18:29","text":"‘Be patient with me, and I will pay it,’ he pleaded."}]},{"chapter":18,"verse":30,"reference":"Matthew 18:30","text":"But his creditor wouldn’t wait. He had the man arrested and put in prison until the debt could be paid in full.","sentences":[{"id":"mt-18-30-1","chapter":18,"verse":30,"sentence":1,"reference":"Matthew 18:30","text":"But his creditor wouldn’t wait."},{"id":"mt-18-30-2","chapter":18,"verse":30,"sentence":2,"reference":"Matthew 18:30","text":"He had the man arrested and put in prison until the debt could be paid in full."}]},{"chapter":18,"verse":31,"reference":"Matthew 18:31","text":"“When some of the other servants saw this, they were very upset. They went to the king and told him everything that had happened.","sentences":[{"id":"mt-18-31-1","chapter":18,"verse":31,"sentence":1,"reference":"Matthew 18:31","text":"“When some of the other servants saw this, they were very upset."},{"id":"mt-18-31-2","chapter":18,"verse":31,"sentence":2,"reference":"Matthew 18:31","text":"They went to the king and told him everything that had happened."}]},{"chapter":18,"verse":32,"reference":"Matthew 18:32","text":"Then the king called in the man he had forgiven and said, ‘You evil servant! I forgave you that tremendous debt because you pleaded with me.","sentences":[{"id":"mt-18-32-1","chapter":18,"verse":32,"sentence":1,"reference":"Matthew 18:32","text":"Then the king called in the man he had forgiven and said, ‘You evil servant!"},{"id":"mt-18-32-2","chapter":18,"verse":32,"sentence":2,"reference":"Matthew 18:32","text":"I forgave you that tremendous debt because you pleaded with me."}]},{"chapter":18,"verse":33,"reference":"Matthew 18:33","text":"Shouldn’t you have mercy on your fellow servant, just as I had mercy on you?’","sentences":[{"id":"mt-18-33-1","chapter":18,"verse":33,"sentence":1,"reference":"Matthew 18:33","text":"Shouldn’t you have mercy on your fellow servant, just as I had mercy on you?’"}]},{"chapter":18,"verse":34,"reference":"Matthew 18:34","text":"Then the angry king sent the man to prison to be tortured until he had paid his entire debt.","sentences":[{"id":"mt-18-34-1","chapter":18,"verse":34,"sentence":1,"reference":"Matthew 18:34","text":"Then the angry king sent the man to prison to be tortured until he had paid his entire debt."}]},{"chapter":18,"verse":35,"reference":"Matthew 18:35","text":"“That’s what my heavenly Father will do to you if you refuse to forgive your brothers and sisters from your heart.”","sentences":[{"id":"mt-18-35-1","chapter":18,"verse":35,"sentence":1,"reference":"Matthew 18:35","text":"“That’s what my heavenly Father will do to you if you refuse to forgive your brothers and sisters from your heart.”"}]}]},{"chapter":19,"verses":[{"chapter":19,"verse":1,"reference":"Matthew 19:1","text":"When Jesus had finished saying these things, he left Galilee and went down to the region of Judea east of the Jordan River.","sentences":[{"id":"mt-19-1-1","chapter":19,"verse":1,"sentence":1,"reference":"Matthew 19:1","text":"When Jesus had finished saying these things, he left Galilee and went down to the region of Judea east of the Jordan River."}]},{"chapter":19,"verse":2,"reference":"Matthew 19:2","text":"Large crowds followed him there, and he healed their sick.","sentences":[{"id":"mt-19-2-1","chapter":19,"verse":2,"sentence":1,"reference":"Matthew 19:2","text":"Large crowds followed him there, and he healed their sick."}]},{"chapter":19,"verse":3,"reference":"Matthew 19:3","text":"Some Pharisees came and tried to trap him with this question: “Should a man be allowed to divorce his wife for just any reason?”","sentences":[{"id":"mt-19-3-1","chapter":19,"verse":3,"sentence":1,"reference":"Matthew 19:3","text":"Some Pharisees came and tried to trap him with this question: “Should a man be allowed to divorce his wife for just any reason?”"}]},{"chapter":19,"verse":4,"reference":"Matthew 19:4","text":"“Haven’t you read the Scriptures?” Jesus replied. “They record that from the beginning ‘God made them male and female.’”","sentences":[{"id":"mt-19-4-1","chapter":19,"verse":4,"sentence":1,"reference":"Matthew 19:4","text":"“Haven’t you read the Scriptures?”"},{"id":"mt-19-4-2","chapter":19,"verse":4,"sentence":2,"reference":"Matthew 19:4","text":"Jesus replied."},{"id":"mt-19-4-3","chapter":19,"verse":4,"sentence":3,"reference":"Matthew 19:4","text":"“They record that from the beginning ‘God made them male and female.’”"}]},{"chapter":19,"verse":5,"reference":"Matthew 19:5","text":"And he said, “‘This explains why a man leaves his father and mother and is joined to his wife, and the two are united into one.’","sentences":[{"id":"mt-19-5-1","chapter":19,"verse":5,"sentence":1,"reference":"Matthew 19:5","text":"And he said, “‘This explains why a man leaves his father and mother and is joined to his wife, and the two are united into one.’"}]},{"chapter":19,"verse":6,"reference":"Matthew 19:6","text":"Since they are no longer two but one, let no one split apart what God has joined together.”","sentences":[{"id":"mt-19-6-1","chapter":19,"verse":6,"sentence":1,"reference":"Matthew 19:6","text":"Since they are no longer two but one, let no one split apart what God has joined together.”"}]},{"chapter":19,"verse":7,"reference":"Matthew 19:7","text":"“Then why did Moses say in the law that a man could give his wife a written notice of divorce and send her away?” they asked.","sentences":[{"id":"mt-19-7-1","chapter":19,"verse":7,"sentence":1,"reference":"Matthew 19:7","text":"“Then why did Moses say in the law that a man could give his wife a written notice of divorce and send her away?”"},{"id":"mt-19-7-2","chapter":19,"verse":7,"sentence":2,"reference":"Matthew 19:7","text":"they asked."}]},{"chapter":19,"verse":8,"reference":"Matthew 19:8","text":"Jesus replied, “Moses permitted divorce only as a concession to your hard hearts, but it was not what God had originally intended.","sentences":[{"id":"mt-19-8-1","chapter":19,"verse":8,"sentence":1,"reference":"Matthew 19:8","text":"Jesus replied, “Moses permitted divorce only as a concession to your hard hearts, but it was not what God had originally intended."}]},{"chapter":19,"verse":9,"reference":"Matthew 19:9","text":"And I tell you this, whoever divorces his wife and marries someone else commits adultery—unless his wife has been unfaithful.”","sentences":[{"id":"mt-19-9-1","chapter":19,"verse":9,"sentence":1,"reference":"Matthew 19:9","text":"And I tell you this, whoever divorces his wife and marries someone else commits adultery—unless his wife has been unfaithful.”"}]},{"chapter":19,"verse":10,"reference":"Matthew 19:10","text":"Jesus’ disciples then said to him, “If this is the case, it is better not to marry!”","sentences":[{"id":"mt-19-10-1","chapter":19,"verse":10,"sentence":1,"reference":"Matthew 19:10","text":"Jesus’ disciples then said to him, “If this is the case, it is better not to marry!”"}]},{"chapter":19,"verse":11,"reference":"Matthew 19:11","text":"“Not everyone can accept this statement,” Jesus said. “Only those whom God helps.","sentences":[{"id":"mt-19-11-1","chapter":19,"verse":11,"sentence":1,"reference":"Matthew 19:11","text":"“Not everyone can accept this statement,” Jesus said."},{"id":"mt-19-11-2","chapter":19,"verse":11,"sentence":2,"reference":"Matthew 19:11","text":"“Only those whom God helps."}]},{"chapter":19,"verse":12,"reference":"Matthew 19:12","text":"Some are born as eunuchs, some have been made eunuchs by others, and some choose not to marry for the sake of the Kingdom of Heaven. Let anyone accept this who can.”","sentences":[{"id":"mt-19-12-1","chapter":19,"verse":12,"sentence":1,"reference":"Matthew 19:12","text":"Some are born as eunuchs, some have been made eunuchs by others, and some choose not to marry for the sake of the Kingdom of Heaven."},{"id":"mt-19-12-2","chapter":19,"verse":12,"sentence":2,"reference":"Matthew 19:12","text":"Let anyone accept this who can.”"}]},{"chapter":19,"verse":13,"reference":"Matthew 19:13","text":"One day some parents brought their children to Jesus so he could lay his hands on them and pray for them. But the disciples scolded the parents for bothering him.","sentences":[{"id":"mt-19-13-1","chapter":19,"verse":13,"sentence":1,"reference":"Matthew 19:13","text":"One day some parents brought their children to Jesus so he could lay his hands on them and pray for them."},{"id":"mt-19-13-2","chapter":19,"verse":13,"sentence":2,"reference":"Matthew 19:13","text":"But the disciples scolded the parents for bothering him."}]},{"chapter":19,"verse":14,"reference":"Matthew 19:14","text":"But Jesus said, “Let the children come to me. Don’t stop them! For the Kingdom of Heaven belongs to those who are like these children.”","sentences":[{"id":"mt-19-14-1","chapter":19,"verse":14,"sentence":1,"reference":"Matthew 19:14","text":"But Jesus said, “Let the children come to me."},{"id":"mt-19-14-2","chapter":19,"verse":14,"sentence":2,"reference":"Matthew 19:14","text":"Don’t stop them!"},{"id":"mt-19-14-3","chapter":19,"verse":14,"sentence":3,"reference":"Matthew 19:14","text":"For the Kingdom of Heaven belongs to those who are like these children.”"}]},{"chapter":19,"verse":15,"reference":"Matthew 19:15","text":"And he placed his hands on their heads and blessed them before he left.","sentences":[{"id":"mt-19-15-1","chapter":19,"verse":15,"sentence":1,"reference":"Matthew 19:15","text":"And he placed his hands on their heads and blessed them before he left."}]},{"chapter":19,"verse":16,"reference":"Matthew 19:16","text":"Someone came to Jesus with this question: “Teacher, what good deed must I do to have eternal life?”","sentences":[{"id":"mt-19-16-1","chapter":19,"verse":16,"sentence":1,"reference":"Matthew 19:16","text":"Someone came to Jesus with this question: “Teacher, what good deed must I do to have eternal life?”"}]},{"chapter":19,"verse":17,"reference":"Matthew 19:17","text":"“Why ask me about what is good?” Jesus replied. “There is only One who is good. But to answer your question—if you want to receive eternal life, keep the commandments.”","sentences":[{"id":"mt-19-17-1","chapter":19,"verse":17,"sentence":1,"reference":"Matthew 19:17","text":"“Why ask me about what is good?”"},{"id":"mt-19-17-2","chapter":19,"verse":17,"sentence":2,"reference":"Matthew 19:17","text":"Jesus replied."},{"id":"mt-19-17-3","chapter":19,"verse":17,"sentence":3,"reference":"Matthew 19:17","text":"“There is only One who is good."},{"id":"mt-19-17-4","chapter":19,"verse":17,"sentence":4,"reference":"Matthew 19:17","text":"But to answer your question—if you want to receive eternal life, keep the commandments.”"}]},{"chapter":19,"verse":18,"reference":"Matthew 19:18","text":"“Which ones?” the man asked. And Jesus replied: “‘You must not murder. You must not commit adultery. You must not steal. You must not testify falsely.","sentences":[{"id":"mt-19-18-1","chapter":19,"verse":18,"sentence":1,"reference":"Matthew 19:18","text":"“Which ones?”"},{"id":"mt-19-18-2","chapter":19,"verse":18,"sentence":2,"reference":"Matthew 19:18","text":"the man asked."},{"id":"mt-19-18-3","chapter":19,"verse":18,"sentence":3,"reference":"Matthew 19:18","text":"And Jesus replied: “‘You must not murder."},{"id":"mt-19-18-4","chapter":19,"verse":18,"sentence":4,"reference":"Matthew 19:18","text":"You must not commit adultery."},{"id":"mt-19-18-5","chapter":19,"verse":18,"sentence":5,"reference":"Matthew 19:18","text":"You must not steal."},{"id":"mt-19-18-6","chapter":19,"verse":18,"sentence":6,"reference":"Matthew 19:18","text":"You must not testify falsely."}]},{"chapter":19,"verse":19,"reference":"Matthew 19:19","text":"Honor your father and mother. Love your neighbor as yourself.’”","sentences":[{"id":"mt-19-19-1","chapter":19,"verse":19,"sentence":1,"reference":"Matthew 19:19","text":"Honor your father and mother."},{"id":"mt-19-19-2","chapter":19,"verse":19,"sentence":2,"reference":"Matthew 19:19","text":"Love your neighbor as yourself.’”"}]},{"chapter":19,"verse":20,"reference":"Matthew 19:20","text":"“I’ve obeyed all these commandments,” the young man replied. “What else must I do?”","sentences":[{"id":"mt-19-20-1","chapter":19,"verse":20,"sentence":1,"reference":"Matthew 19:20","text":"“I’ve obeyed all these commandments,” the young man replied."},{"id":"mt-19-20-2","chapter":19,"verse":20,"sentence":2,"reference":"Matthew 19:20","text":"“What else must I do?”"}]},{"chapter":19,"verse":21,"reference":"Matthew 19:21","text":"Jesus told him, “If you want to be perfect, go and sell all your possessions and give the money to the poor, and you will have treasure in heaven. Then come, follow me.”","sentences":[{"id":"mt-19-21-1","chapter":19,"verse":21,"sentence":1,"reference":"Matthew 19:21","text":"Jesus told him, “If you want to be perfect, go and sell all your possessions and give the money to the poor, and you will have treasure in heaven."},{"id":"mt-19-21-2","chapter":19,"verse":21,"sentence":2,"reference":"Matthew 19:21","text":"Then come, follow me.”"}]},{"chapter":19,"verse":22,"reference":"Matthew 19:22","text":"But when the young man heard this, he went away sad, for he had many possessions.","sentences":[{"id":"mt-19-22-1","chapter":19,"verse":22,"sentence":1,"reference":"Matthew 19:22","text":"But when the young man heard this, he went away sad, for he had many possessions."}]},{"chapter":19,"verse":23,"reference":"Matthew 19:23","text":"Then Jesus said to his disciples, “I tell you the truth, it is very hard for a rich person to enter the Kingdom of Heaven.","sentences":[{"id":"mt-19-23-1","chapter":19,"verse":23,"sentence":1,"reference":"Matthew 19:23","text":"Then Jesus said to his disciples, “I tell you the truth, it is very hard for a rich person to enter the Kingdom of Heaven."}]},{"chapter":19,"verse":24,"reference":"Matthew 19:24","text":"I’ll say it again—it is easier for a camel to go through the eye of a needle than for a rich person to enter the Kingdom of God!”","sentences":[{"id":"mt-19-24-1","chapter":19,"verse":24,"sentence":1,"reference":"Matthew 19:24","text":"I’ll say it again—it is easier for a camel to go through the eye of a needle than for a rich person to enter the Kingdom of God!”"}]},{"chapter":19,"verse":25,"reference":"Matthew 19:25","text":"The disciples were astounded. “Then who in the world can be saved?” they asked.","sentences":[{"id":"mt-19-25-1","chapter":19,"verse":25,"sentence":1,"reference":"Matthew 19:25","text":"The disciples were astounded."},{"id":"mt-19-25-2","chapter":19,"verse":25,"sentence":2,"reference":"Matthew 19:25","text":"“Then who in the world can be saved?”"},{"id":"mt-19-25-3","chapter":19,"verse":25,"sentence":3,"reference":"Matthew 19:25","text":"they asked."}]},{"chapter":19,"verse":26,"reference":"Matthew 19:26","text":"Jesus looked at them intently and said, “Humanly speaking, it is impossible. But with God everything is possible.”","sentences":[{"id":"mt-19-26-1","chapter":19,"verse":26,"sentence":1,"reference":"Matthew 19:26","text":"Jesus looked at them intently and said, “Humanly speaking, it is impossible."},{"id":"mt-19-26-2","chapter":19,"verse":26,"sentence":2,"reference":"Matthew 19:26","text":"But with God everything is possible.”"}]},{"chapter":19,"verse":27,"reference":"Matthew 19:27","text":"Then Peter said to him, “We’ve given up everything to follow you. What will we get?”","sentences":[{"id":"mt-19-27-1","chapter":19,"verse":27,"sentence":1,"reference":"Matthew 19:27","text":"Then Peter said to him, “We’ve given up everything to follow you."},{"id":"mt-19-27-2","chapter":19,"verse":27,"sentence":2,"reference":"Matthew 19:27","text":"What will we get?”"}]},{"chapter":19,"verse":28,"reference":"Matthew 19:28","text":"Jesus replied, “I assure you that when the world is made new and the Son of Man sits upon his glorious throne, you who have been my followers will also sit on twelve thrones, judging the twelve tribes of Israel.","sentences":[{"id":"mt-19-28-1","chapter":19,"verse":28,"sentence":1,"reference":"Matthew 19:28","text":"Jesus replied, “I assure you that when the world is made new and the Son of Man sits upon his glorious throne, you who have been my followers will also sit on twelve thrones, judging the twelve tribes of Israel."}]},{"chapter":19,"verse":29,"reference":"Matthew 19:29","text":"And everyone who has given up houses or brothers or sisters or father or mother or children or property, for my sake, will receive a hundred times as much in return and will inherit eternal life.","sentences":[{"id":"mt-19-29-1","chapter":19,"verse":29,"sentence":1,"reference":"Matthew 19:29","text":"And everyone who has given up houses or brothers or sisters or father or mother or children or property, for my sake, will receive a hundred times as much in return and will inherit eternal life."}]},{"chapter":19,"verse":30,"reference":"Matthew 19:30","text":"But many who are the greatest now will be least important then, and those who seem least important now will be the greatest then.","sentences":[{"id":"mt-19-30-1","chapter":19,"verse":30,"sentence":1,"reference":"Matthew 19:30","text":"But many who are the greatest now will be least important then, and those who seem least important now will be the greatest then."}]}]},{"chapter":20,"verses":[{"chapter":20,"verse":1,"reference":"Matthew 20:1","text":"“For the Kingdom of Heaven is like the landowner who went out early one morning to hire workers for his vineyard.","sentences":[{"id":"mt-20-1-1","chapter":20,"verse":1,"sentence":1,"reference":"Matthew 20:1","text":"“For the Kingdom of Heaven is like the landowner who went out early one morning to hire workers for his vineyard."}]},{"chapter":20,"verse":2,"reference":"Matthew 20:2","text":"He agreed to pay the normal daily wage and sent them out to work.","sentences":[{"id":"mt-20-2-1","chapter":20,"verse":2,"sentence":1,"reference":"Matthew 20:2","text":"He agreed to pay the normal daily wage and sent them out to work."}]},{"chapter":20,"verse":3,"reference":"Matthew 20:3","text":"“At nine o’clock in the morning he was passing through the marketplace and saw some people standing around doing nothing.","sentences":[{"id":"mt-20-3-1","chapter":20,"verse":3,"sentence":1,"reference":"Matthew 20:3","text":"“At nine o’clock in the morning he was passing through the marketplace and saw some people standing around doing nothing."}]},{"chapter":20,"verse":4,"reference":"Matthew 20:4","text":"So he hired them, telling them he would pay them whatever was right at the end of the day.","sentences":[{"id":"mt-20-4-1","chapter":20,"verse":4,"sentence":1,"reference":"Matthew 20:4","text":"So he hired them, telling them he would pay them whatever was right at the end of the day."}]},{"chapter":20,"verse":5,"reference":"Matthew 20:5","text":"So they went to work in the vineyard. At noon and again at three o’clock he did the same thing.","sentences":[{"id":"mt-20-5-1","chapter":20,"verse":5,"sentence":1,"reference":"Matthew 20:5","text":"So they went to work in the vineyard."},{"id":"mt-20-5-2","chapter":20,"verse":5,"sentence":2,"reference":"Matthew 20:5","text":"At noon and again at three o’clock he did the same thing."}]},{"chapter":20,"verse":6,"reference":"Matthew 20:6","text":"“At five o’clock that afternoon he was in town again and saw some more people standing around. He asked them, ‘Why haven’t you been working today?’","sentences":[{"id":"mt-20-6-1","chapter":20,"verse":6,"sentence":1,"reference":"Matthew 20:6","text":"“At five o’clock that afternoon he was in town again and saw some more people standing around."},{"id":"mt-20-6-2","chapter":20,"verse":6,"sentence":2,"reference":"Matthew 20:6","text":"He asked them, ‘Why haven’t you been working today?’"}]},{"chapter":20,"verse":7,"reference":"Matthew 20:7","text":"“They replied, ‘Because no one hired us.’ “The landowner told them, ‘Then go out and join the others in my vineyard.’","sentences":[{"id":"mt-20-7-1","chapter":20,"verse":7,"sentence":1,"reference":"Matthew 20:7","text":"“They replied, ‘Because no one hired us.’"},{"id":"mt-20-7-2","chapter":20,"verse":7,"sentence":2,"reference":"Matthew 20:7","text":"“The landowner told them, ‘Then go out and join the others in my vineyard.’"}]},{"chapter":20,"verse":8,"reference":"Matthew 20:8","text":"“That evening he told the foreman to call the workers in and pay them, beginning with the last workers first.","sentences":[{"id":"mt-20-8-1","chapter":20,"verse":8,"sentence":1,"reference":"Matthew 20:8","text":"“That evening he told the foreman to call the workers in and pay them, beginning with the last workers first."}]},{"chapter":20,"verse":9,"reference":"Matthew 20:9","text":"When those hired at five o’clock were paid, each received a full day’s wage.","sentences":[{"id":"mt-20-9-1","chapter":20,"verse":9,"sentence":1,"reference":"Matthew 20:9","text":"When those hired at five o’clock were paid, each received a full day’s wage."}]},{"chapter":20,"verse":10,"reference":"Matthew 20:10","text":"When those hired first came to get their pay, they assumed they would receive more. But they, too, were paid a day’s wage.","sentences":[{"id":"mt-20-10-1","chapter":20,"verse":10,"sentence":1,"reference":"Matthew 20:10","text":"When those hired first came to get their pay, they assumed they would receive more."},{"id":"mt-20-10-2","chapter":20,"verse":10,"sentence":2,"reference":"Matthew 20:10","text":"But they, too, were paid a day’s wage."}]},{"chapter":20,"verse":11,"reference":"Matthew 20:11","text":"When they received their pay, they protested to the owner,","sentences":[{"id":"mt-20-11-1","chapter":20,"verse":11,"sentence":1,"reference":"Matthew 20:11","text":"When they received their pay, they protested to the owner,"}]},{"chapter":20,"verse":12,"reference":"Matthew 20:12","text":"‘Those people worked only one hour, and yet you’ve paid them just as much as you paid us who worked all day in the scorching heat.’","sentences":[{"id":"mt-20-12-1","chapter":20,"verse":12,"sentence":1,"reference":"Matthew 20:12","text":"‘Those people worked only one hour, and yet you’ve paid them just as much as you paid us who worked all day in the scorching heat.’"}]},{"chapter":20,"verse":13,"reference":"Matthew 20:13","text":"“He answered one of them, ‘Friend, I haven’t been unfair! Didn’t you agree to work all day for the usual wage?","sentences":[{"id":"mt-20-13-1","chapter":20,"verse":13,"sentence":1,"reference":"Matthew 20:13","text":"“He answered one of them, ‘Friend, I haven’t been unfair!"},{"id":"mt-20-13-2","chapter":20,"verse":13,"sentence":2,"reference":"Matthew 20:13","text":"Didn’t you agree to work all day for the usual wage?"}]},{"chapter":20,"verse":14,"reference":"Matthew 20:14","text":"Take your money and go. I wanted to pay this last worker the same as you.","sentences":[{"id":"mt-20-14-1","chapter":20,"verse":14,"sentence":1,"reference":"Matthew 20:14","text":"Take your money and go."},{"id":"mt-20-14-2","chapter":20,"verse":14,"sentence":2,"reference":"Matthew 20:14","text":"I wanted to pay this last worker the same as you."}]},{"chapter":20,"verse":15,"reference":"Matthew 20:15","text":"Is it against the law for me to do what I want with my money? Should you be jealous because I am kind to others?’","sentences":[{"id":"mt-20-15-1","chapter":20,"verse":15,"sentence":1,"reference":"Matthew 20:15","text":"Is it against the law for me to do what I want with my money?"},{"id":"mt-20-15-2","chapter":20,"verse":15,"sentence":2,"reference":"Matthew 20:15","text":"Should you be jealous because I am kind to others?’"}]},{"chapter":20,"verse":16,"reference":"Matthew 20:16","text":"“So those who are last now will be first then, and those who are first will be last.”","sentences":[{"id":"mt-20-16-1","chapter":20,"verse":16,"sentence":1,"reference":"Matthew 20:16","text":"“So those who are last now will be first then, and those who are first will be last.”"}]},{"chapter":20,"verse":17,"reference":"Matthew 20:17","text":"As Jesus was going up to Jerusalem, he took the twelve disciples aside privately and told them what was going to happen to him.","sentences":[{"id":"mt-20-17-1","chapter":20,"verse":17,"sentence":1,"reference":"Matthew 20:17","text":"As Jesus was going up to Jerusalem, he took the twelve disciples aside privately and told them what was going to happen to him."}]},{"chapter":20,"verse":18,"reference":"Matthew 20:18","text":"“Listen,” he said, “we’re going up to Jerusalem, where the Son of Man will be betrayed to the leading priests and the teachers of religious law. They will sentence him to die.","sentences":[{"id":"mt-20-18-1","chapter":20,"verse":18,"sentence":1,"reference":"Matthew 20:18","text":"“Listen,” he said, “we’re going up to Jerusalem, where the Son of Man will be betrayed to the leading priests and the teachers of religious law."},{"id":"mt-20-18-2","chapter":20,"verse":18,"sentence":2,"reference":"Matthew 20:18","text":"They will sentence him to die."}]},{"chapter":20,"verse":19,"reference":"Matthew 20:19","text":"Then they will hand him over to the Romans to be mocked, flogged with a whip, and crucified. But on the third day he will be raised from the dead.”","sentences":[{"id":"mt-20-19-1","chapter":20,"verse":19,"sentence":1,"reference":"Matthew 20:19","text":"Then they will hand him over to the Romans to be mocked, flogged with a whip, and crucified."},{"id":"mt-20-19-2","chapter":20,"verse":19,"sentence":2,"reference":"Matthew 20:19","text":"But on the third day he will be raised from the dead.”"}]},{"chapter":20,"verse":20,"reference":"Matthew 20:20","text":"Then the mother of James and John, the sons of Zebedee, came to Jesus with her sons. She knelt respectfully to ask a favor.","sentences":[{"id":"mt-20-20-1","chapter":20,"verse":20,"sentence":1,"reference":"Matthew 20:20","text":"Then the mother of James and John, the sons of Zebedee, came to Jesus with her sons."},{"id":"mt-20-20-2","chapter":20,"verse":20,"sentence":2,"reference":"Matthew 20:20","text":"She knelt respectfully to ask a favor."}]},{"chapter":20,"verse":21,"reference":"Matthew 20:21","text":"“What is your request?” he asked. She replied, “In your Kingdom, please let my two sons sit in places of honor next to you, one on your right and the other on your left.”","sentences":[{"id":"mt-20-21-1","chapter":20,"verse":21,"sentence":1,"reference":"Matthew 20:21","text":"“What is your request?”"},{"id":"mt-20-21-2","chapter":20,"verse":21,"sentence":2,"reference":"Matthew 20:21","text":"he asked."},{"id":"mt-20-21-3","chapter":20,"verse":21,"sentence":3,"reference":"Matthew 20:21","text":"She replied, “In your Kingdom, please let my two sons sit in places of honor next to you, one on your right and the other on your left.”"}]},{"chapter":20,"verse":22,"reference":"Matthew 20:22","text":"But Jesus answered by saying to them, “You don’t know what you are asking! Are you able to drink from the bitter cup of suffering I am about to drink?” “Oh yes,” they replied, “we are able!”","sentences":[{"id":"mt-20-22-1","chapter":20,"verse":22,"sentence":1,"reference":"Matthew 20:22","text":"But Jesus answered by saying to them, “You don’t know what you are asking!"},{"id":"mt-20-22-2","chapter":20,"verse":22,"sentence":2,"reference":"Matthew 20:22","text":"Are you able to drink from the bitter cup of suffering I am about to drink?”"},{"id":"mt-20-22-3","chapter":20,"verse":22,"sentence":3,"reference":"Matthew 20:22","text":"“Oh yes,” they replied, “we are able!”"}]},{"chapter":20,"verse":23,"reference":"Matthew 20:23","text":"Jesus told them, “You will indeed drink from my bitter cup. But I have no right to say who will sit on my right or my left. My Father has prepared those places for the ones he has chosen.”","sentences":[{"id":"mt-20-23-1","chapter":20,"verse":23,"sentence":1,"reference":"Matthew 20:23","text":"Jesus told them, “You will indeed drink from my bitter cup."},{"id":"mt-20-23-2","chapter":20,"verse":23,"sentence":2,"reference":"Matthew 20:23","text":"But I have no right to say who will sit on my right or my left."},{"id":"mt-20-23-3","chapter":20,"verse":23,"sentence":3,"reference":"Matthew 20:23","text":"My Father has prepared those places for the ones he has chosen.”"}]},{"chapter":20,"verse":24,"reference":"Matthew 20:24","text":"When the ten other disciples heard what James and John had asked, they were indignant.","sentences":[{"id":"mt-20-24-1","chapter":20,"verse":24,"sentence":1,"reference":"Matthew 20:24","text":"When the ten other disciples heard what James and John had asked, they were indignant."}]},{"chapter":20,"verse":25,"reference":"Matthew 20:25","text":"But Jesus called them together and said, “You know that the rulers in this world lord it over their people, and officials flaunt their authority over those under them.","sentences":[{"id":"mt-20-25-1","chapter":20,"verse":25,"sentence":1,"reference":"Matthew 20:25","text":"But Jesus called them together and said, “You know that the rulers in this world lord it over their people, and officials flaunt their authority over those under them."}]},{"chapter":20,"verse":26,"reference":"Matthew 20:26","text":"But among you it will be different. Whoever wants to be a leader among you must be your servant,","sentences":[{"id":"mt-20-26-1","chapter":20,"verse":26,"sentence":1,"reference":"Matthew 20:26","text":"But among you it will be different."},{"id":"mt-20-26-2","chapter":20,"verse":26,"sentence":2,"reference":"Matthew 20:26","text":"Whoever wants to be a leader among you must be your servant,"}]},{"chapter":20,"verse":27,"reference":"Matthew 20:27","text":"and whoever wants to be first among you must become your slave.","sentences":[{"id":"mt-20-27-1","chapter":20,"verse":27,"sentence":1,"reference":"Matthew 20:27","text":"and whoever wants to be first among you must become your slave."}]},{"chapter":20,"verse":28,"reference":"Matthew 20:28","text":"For even the Son of Man came not to be served but to serve others and to give his life as a ransom for many.”","sentences":[{"id":"mt-20-28-1","chapter":20,"verse":28,"sentence":1,"reference":"Matthew 20:28","text":"For even the Son of Man came not to be served but to serve others and to give his life as a ransom for many.”"}]},{"chapter":20,"verse":29,"reference":"Matthew 20:29","text":"As Jesus and the disciples left the town of Jericho, a large crowd followed behind.","sentences":[{"id":"mt-20-29-1","chapter":20,"verse":29,"sentence":1,"reference":"Matthew 20:29","text":"As Jesus and the disciples left the town of Jericho, a large crowd followed behind."}]},{"chapter":20,"verse":30,"reference":"Matthew 20:30","text":"Two blind men were sitting beside the road. When they heard that Jesus was coming that way, they began shouting, “Lord, Son of David, have mercy on us!”","sentences":[{"id":"mt-20-30-1","chapter":20,"verse":30,"sentence":1,"reference":"Matthew 20:30","text":"Two blind men were sitting beside the road."},{"id":"mt-20-30-2","chapter":20,"verse":30,"sentence":2,"reference":"Matthew 20:30","text":"When they heard that Jesus was coming that way, they began shouting, “Lord, Son of David, have mercy on us!”"}]},{"chapter":20,"verse":31,"reference":"Matthew 20:31","text":"“Be quiet!” the crowd yelled at them. But they only shouted louder, “Lord, Son of David, have mercy on us!”","sentences":[{"id":"mt-20-31-1","chapter":20,"verse":31,"sentence":1,"reference":"Matthew 20:31","text":"“Be quiet!”"},{"id":"mt-20-31-2","chapter":20,"verse":31,"sentence":2,"reference":"Matthew 20:31","text":"the crowd yelled at them."},{"id":"mt-20-31-3","chapter":20,"verse":31,"sentence":3,"reference":"Matthew 20:31","text":"But they only shouted louder, “Lord, Son of David, have mercy on us!”"}]},{"chapter":20,"verse":32,"reference":"Matthew 20:32","text":"When Jesus heard them, he stopped and called, “What do you want me to do for you?”","sentences":[{"id":"mt-20-32-1","chapter":20,"verse":32,"sentence":1,"reference":"Matthew 20:32","text":"When Jesus heard them, he stopped and called, “What do you want me to do for you?”"}]},{"chapter":20,"verse":33,"reference":"Matthew 20:33","text":"“Lord,” they said, “we want to see!”","sentences":[{"id":"mt-20-33-1","chapter":20,"verse":33,"sentence":1,"reference":"Matthew 20:33","text":"“Lord,” they said, “we want to see!”"}]},{"chapter":20,"verse":34,"reference":"Matthew 20:34","text":"Jesus felt sorry for them and touched their eyes. Instantly they could see! Then they followed him.","sentences":[{"id":"mt-20-34-1","chapter":20,"verse":34,"sentence":1,"reference":"Matthew 20:34","text":"Jesus felt sorry for them and touched their eyes."},{"id":"mt-20-34-2","chapter":20,"verse":34,"sentence":2,"reference":"Matthew 20:34","text":"Instantly they could see!"},{"id":"mt-20-34-3","chapter":20,"verse":34,"sentence":3,"reference":"Matthew 20:34","text":"Then they followed him."}]}]},{"chapter":21,"verses":[{"chapter":21,"verse":1,"reference":"Matthew 21:1","text":"As Jesus and the disciples approached Jerusalem, they came to the town of Bethphage on the Mount of Olives. Jesus sent two of them on ahead.","sentences":[{"id":"mt-21-1-1","chapter":21,"verse":1,"sentence":1,"reference":"Matthew 21:1","text":"As Jesus and the disciples approached Jerusalem, they came to the town of Bethphage on the Mount of Olives."},{"id":"mt-21-1-2","chapter":21,"verse":1,"sentence":2,"reference":"Matthew 21:1","text":"Jesus sent two of them on ahead."}]},{"chapter":21,"verse":2,"reference":"Matthew 21:2","text":"“Go into the village over there,” he said. “As soon as you enter it, you will see a donkey tied there, with its colt beside it. Untie them and bring them to me.","sentences":[{"id":"mt-21-2-1","chapter":21,"verse":2,"sentence":1,"reference":"Matthew 21:2","text":"“Go into the village over there,” he said."},{"id":"mt-21-2-2","chapter":21,"verse":2,"sentence":2,"reference":"Matthew 21:2","text":"“As soon as you enter it, you will see a donkey tied there, with its colt beside it."},{"id":"mt-21-2-3","chapter":21,"verse":2,"sentence":3,"reference":"Matthew 21:2","text":"Untie them and bring them to me."}]},{"chapter":21,"verse":3,"reference":"Matthew 21:3","text":"If anyone asks what you are doing, just say, ‘The Lord needs them,’ and he will immediately let you take them.”","sentences":[{"id":"mt-21-3-1","chapter":21,"verse":3,"sentence":1,"reference":"Matthew 21:3","text":"If anyone asks what you are doing, just say, ‘The Lord needs them,’ and he will immediately let you take them.”"}]},{"chapter":21,"verse":4,"reference":"Matthew 21:4","text":"This took place to fulfill the prophecy that said,","sentences":[{"id":"mt-21-4-1","chapter":21,"verse":4,"sentence":1,"reference":"Matthew 21:4","text":"This took place to fulfill the prophecy that said,"}]},{"chapter":21,"verse":5,"reference":"Matthew 21:5","text":"“Tell the people of Jerusalem, ‘Look, your King is coming to you. He is humble, riding on a donkey— riding on a donkey’s colt.’”","sentences":[{"id":"mt-21-5-1","chapter":21,"verse":5,"sentence":1,"reference":"Matthew 21:5","text":"“Tell the people of Jerusalem, ‘Look, your King is coming to you."},{"id":"mt-21-5-2","chapter":21,"verse":5,"sentence":2,"reference":"Matthew 21:5","text":"He is humble, riding on a donkey— riding on a donkey’s colt.’”"}]},{"chapter":21,"verse":6,"reference":"Matthew 21:6","text":"The two disciples did as Jesus commanded.","sentences":[{"id":"mt-21-6-1","chapter":21,"verse":6,"sentence":1,"reference":"Matthew 21:6","text":"The two disciples did as Jesus commanded."}]},{"chapter":21,"verse":7,"reference":"Matthew 21:7","text":"They brought the donkey and the colt to him and threw their garments over the colt, and he sat on it.","sentences":[{"id":"mt-21-7-1","chapter":21,"verse":7,"sentence":1,"reference":"Matthew 21:7","text":"They brought the donkey and the colt to him and threw their garments over the colt, and he sat on it."}]},{"chapter":21,"verse":8,"reference":"Matthew 21:8","text":"Most of the crowd spread their garments on the road ahead of him, and others cut branches from the trees and spread them on the road.","sentences":[{"id":"mt-21-8-1","chapter":21,"verse":8,"sentence":1,"reference":"Matthew 21:8","text":"Most of the crowd spread their garments on the road ahead of him, and others cut branches from the trees and spread them on the road."}]},{"chapter":21,"verse":9,"reference":"Matthew 21:9","text":"Jesus was in the center of the procession, and the people all around him were shouting, “Praise God for the Son of David! Blessings on the one who comes in the name of the Lord! Praise God in highest heaven!”","sentences":[{"id":"mt-21-9-1","chapter":21,"verse":9,"sentence":1,"reference":"Matthew 21:9","text":"Jesus was in the center of the procession, and the people all around him were shouting, “Praise God for the Son of David!"},{"id":"mt-21-9-2","chapter":21,"verse":9,"sentence":2,"reference":"Matthew 21:9","text":"Blessings on the one who comes in the name of the Lord!"},{"id":"mt-21-9-3","chapter":21,"verse":9,"sentence":3,"reference":"Matthew 21:9","text":"Praise God in highest heaven!”"}]},{"chapter":21,"verse":10,"reference":"Matthew 21:10","text":"The entire city of Jerusalem was in an uproar as he entered. “Who is this?” they asked.","sentences":[{"id":"mt-21-10-1","chapter":21,"verse":10,"sentence":1,"reference":"Matthew 21:10","text":"The entire city of Jerusalem was in an uproar as he entered."},{"id":"mt-21-10-2","chapter":21,"verse":10,"sentence":2,"reference":"Matthew 21:10","text":"“Who is this?”"},{"id":"mt-21-10-3","chapter":21,"verse":10,"sentence":3,"reference":"Matthew 21:10","text":"they asked."}]},{"chapter":21,"verse":11,"reference":"Matthew 21:11","text":"And the crowds replied, “It’s Jesus, the prophet from Nazareth in Galilee.”","sentences":[{"id":"mt-21-11-1","chapter":21,"verse":11,"sentence":1,"reference":"Matthew 21:11","text":"And the crowds replied, “It’s Jesus, the prophet from Nazareth in Galilee.”"}]},{"chapter":21,"verse":12,"reference":"Matthew 21:12","text":"Jesus entered the Temple and began to drive out all the people buying and selling animals for sacrifice. He knocked over the tables of the money changers and the chairs of those selling doves.","sentences":[{"id":"mt-21-12-1","chapter":21,"verse":12,"sentence":1,"reference":"Matthew 21:12","text":"Jesus entered the Temple and began to drive out all the people buying and selling animals for sacrifice."},{"id":"mt-21-12-2","chapter":21,"verse":12,"sentence":2,"reference":"Matthew 21:12","text":"He knocked over the tables of the money changers and the chairs of those selling doves."}]},{"chapter":21,"verse":13,"reference":"Matthew 21:13","text":"He said to them, “The Scriptures declare, ‘My Temple will be called a house of prayer,’ but you have turned it into a den of thieves!”","sentences":[{"id":"mt-21-13-1","chapter":21,"verse":13,"sentence":1,"reference":"Matthew 21:13","text":"He said to them, “The Scriptures declare, ‘My Temple will be called a house of prayer,’ but you have turned it into a den of thieves!”"}]},{"chapter":21,"verse":14,"reference":"Matthew 21:14","text":"The blind and the lame came to him in the Temple, and he healed them.","sentences":[{"id":"mt-21-14-1","chapter":21,"verse":14,"sentence":1,"reference":"Matthew 21:14","text":"The blind and the lame came to him in the Temple, and he healed them."}]},{"chapter":21,"verse":15,"reference":"Matthew 21:15","text":"The leading priests and the teachers of religious law saw these wonderful miracles and heard even the children in the Temple shouting, “Praise God for the Son of David.” But the leaders were indignant.","sentences":[{"id":"mt-21-15-1","chapter":21,"verse":15,"sentence":1,"reference":"Matthew 21:15","text":"The leading priests and the teachers of religious law saw these wonderful miracles and heard even the children in the Temple shouting, “Praise God for the Son of David.”"},{"id":"mt-21-15-2","chapter":21,"verse":15,"sentence":2,"reference":"Matthew 21:15","text":"But the leaders were indignant."}]},{"chapter":21,"verse":16,"reference":"Matthew 21:16","text":"They asked Jesus, “Do you hear what these children are saying?” “Yes,” Jesus replied. “Haven’t you ever read the Scriptures? For they say, ‘You have taught children and infants to give you praise.’”","sentences":[{"id":"mt-21-16-1","chapter":21,"verse":16,"sentence":1,"reference":"Matthew 21:16","text":"They asked Jesus, “Do you hear what these children are saying?”"},{"id":"mt-21-16-2","chapter":21,"verse":16,"sentence":2,"reference":"Matthew 21:16","text":"“Yes,” Jesus replied."},{"id":"mt-21-16-3","chapter":21,"verse":16,"sentence":3,"reference":"Matthew 21:16","text":"“Haven’t you ever read the Scriptures?"},{"id":"mt-21-16-4","chapter":21,"verse":16,"sentence":4,"reference":"Matthew 21:16","text":"For they say, ‘You have taught children and infants to give you praise.’”"}]},{"chapter":21,"verse":17,"reference":"Matthew 21:17","text":"Then he returned to Bethany, where he stayed overnight.","sentences":[{"id":"mt-21-17-1","chapter":21,"verse":17,"sentence":1,"reference":"Matthew 21:17","text":"Then he returned to Bethany, where he stayed overnight."}]},{"chapter":21,"verse":18,"reference":"Matthew 21:18","text":"In the morning, as Jesus was returning to Jerusalem, he was hungry,","sentences":[{"id":"mt-21-18-1","chapter":21,"verse":18,"sentence":1,"reference":"Matthew 21:18","text":"In the morning, as Jesus was returning to Jerusalem, he was hungry,"}]},{"chapter":21,"verse":19,"reference":"Matthew 21:19","text":"and he noticed a fig tree beside the road. He went over to see if there were any figs, but there were only leaves. Then he said to it, “May you never bear fruit again!” And immediately the fig tree withered up.","sentences":[{"id":"mt-21-19-1","chapter":21,"verse":19,"sentence":1,"reference":"Matthew 21:19","text":"and he noticed a fig tree beside the road."},{"id":"mt-21-19-2","chapter":21,"verse":19,"sentence":2,"reference":"Matthew 21:19","text":"He went over to see if there were any figs, but there were only leaves."},{"id":"mt-21-19-3","chapter":21,"verse":19,"sentence":3,"reference":"Matthew 21:19","text":"Then he said to it, “May you never bear fruit again!”"},{"id":"mt-21-19-4","chapter":21,"verse":19,"sentence":4,"reference":"Matthew 21:19","text":"And immediately the fig tree withered up."}]},{"chapter":21,"verse":20,"reference":"Matthew 21:20","text":"The disciples were amazed when they saw this and asked, “How did the fig tree wither so quickly?”","sentences":[{"id":"mt-21-20-1","chapter":21,"verse":20,"sentence":1,"reference":"Matthew 21:20","text":"The disciples were amazed when they saw this and asked, “How did the fig tree wither so quickly?”"}]},{"chapter":21,"verse":21,"reference":"Matthew 21:21","text":"Then Jesus told them, “I tell you the truth, if you have faith and don’t doubt, you can do things like this and much more. You can even say to this mountain, ‘May you be lifted up and thrown into the sea,’ and it will happen.","sentences":[{"id":"mt-21-21-1","chapter":21,"verse":21,"sentence":1,"reference":"Matthew 21:21","text":"Then Jesus told them, “I tell you the truth, if you have faith and don’t doubt, you can do things like this and much more."},{"id":"mt-21-21-2","chapter":21,"verse":21,"sentence":2,"reference":"Matthew 21:21","text":"You can even say to this mountain, ‘May you be lifted up and thrown into the sea,’ and it will happen."}]},{"chapter":21,"verse":22,"reference":"Matthew 21:22","text":"You can pray for anything, and if you have faith, you will receive it.”","sentences":[{"id":"mt-21-22-1","chapter":21,"verse":22,"sentence":1,"reference":"Matthew 21:22","text":"You can pray for anything, and if you have faith, you will receive it.”"}]},{"chapter":21,"verse":23,"reference":"Matthew 21:23","text":"When Jesus returned to the Temple and began teaching, the leading priests and elders came up to him. They demanded, “By what authority are you doing all these things? Who gave you the right?”","sentences":[{"id":"mt-21-23-1","chapter":21,"verse":23,"sentence":1,"reference":"Matthew 21:23","text":"When Jesus returned to the Temple and began teaching, the leading priests and elders came up to him."},{"id":"mt-21-23-2","chapter":21,"verse":23,"sentence":2,"reference":"Matthew 21:23","text":"They demanded, “By what authority are you doing all these things?"},{"id":"mt-21-23-3","chapter":21,"verse":23,"sentence":3,"reference":"Matthew 21:23","text":"Who gave you the right?”"}]},{"chapter":21,"verse":24,"reference":"Matthew 21:24","text":"“I’ll tell you by what authority I do these things if you answer one question,” Jesus replied.","sentences":[{"id":"mt-21-24-1","chapter":21,"verse":24,"sentence":1,"reference":"Matthew 21:24","text":"“I’ll tell you by what authority I do these things if you answer one question,” Jesus replied."}]},{"chapter":21,"verse":25,"reference":"Matthew 21:25","text":"“Did John’s authority to baptize come from heaven, or was it merely human?” They talked it over among themselves. “If we say it was from heaven, he will ask us why we didn’t believe John.","sentences":[{"id":"mt-21-25-1","chapter":21,"verse":25,"sentence":1,"reference":"Matthew 21:25","text":"“Did John’s authority to baptize come from heaven, or was it merely human?”"},{"id":"mt-21-25-2","chapter":21,"verse":25,"sentence":2,"reference":"Matthew 21:25","text":"They talked it over among themselves."},{"id":"mt-21-25-3","chapter":21,"verse":25,"sentence":3,"reference":"Matthew 21:25","text":"“If we say it was from heaven, he will ask us why we didn’t believe John."}]},{"chapter":21,"verse":26,"reference":"Matthew 21:26","text":"But if we say it was merely human, we’ll be mobbed because the people believe John was a prophet.”","sentences":[{"id":"mt-21-26-1","chapter":21,"verse":26,"sentence":1,"reference":"Matthew 21:26","text":"But if we say it was merely human, we’ll be mobbed because the people believe John was a prophet.”"}]},{"chapter":21,"verse":27,"reference":"Matthew 21:27","text":"So they finally replied, “We don’t know.” And Jesus responded, “Then I won’t tell you by what authority I do these things.","sentences":[{"id":"mt-21-27-1","chapter":21,"verse":27,"sentence":1,"reference":"Matthew 21:27","text":"So they finally replied, “We don’t know.”"},{"id":"mt-21-27-2","chapter":21,"verse":27,"sentence":2,"reference":"Matthew 21:27","text":"And Jesus responded, “Then I won’t tell you by what authority I do these things."}]},{"chapter":21,"verse":28,"reference":"Matthew 21:28","text":"“But what do you think about this? A man with two sons told the older boy, ‘Son, go out and work in the vineyard today.’","sentences":[{"id":"mt-21-28-1","chapter":21,"verse":28,"sentence":1,"reference":"Matthew 21:28","text":"“But what do you think about this?"},{"id":"mt-21-28-2","chapter":21,"verse":28,"sentence":2,"reference":"Matthew 21:28","text":"A man with two sons told the older boy, ‘Son, go out and work in the vineyard today.’"}]},{"chapter":21,"verse":29,"reference":"Matthew 21:29","text":"The son answered, ‘No, I won’t go,’ but later he changed his mind and went anyway.","sentences":[{"id":"mt-21-29-1","chapter":21,"verse":29,"sentence":1,"reference":"Matthew 21:29","text":"The son answered, ‘No, I won’t go,’ but later he changed his mind and went anyway."}]},{"chapter":21,"verse":30,"reference":"Matthew 21:30","text":"Then the father told the other son, ‘You go,’ and he said, ‘Yes, sir, I will.’ But he didn’t go.","sentences":[{"id":"mt-21-30-1","chapter":21,"verse":30,"sentence":1,"reference":"Matthew 21:30","text":"Then the father told the other son, ‘You go,’ and he said, ‘Yes, sir, I will.’"},{"id":"mt-21-30-2","chapter":21,"verse":30,"sentence":2,"reference":"Matthew 21:30","text":"But he didn’t go."}]},{"chapter":21,"verse":31,"reference":"Matthew 21:31","text":"“Which of the two obeyed his father?” They replied, “The first.” Then Jesus explained his meaning: “I tell you the truth, corrupt tax collectors and prostitutes will get into the Kingdom of God before you do.","sentences":[{"id":"mt-21-31-1","chapter":21,"verse":31,"sentence":1,"reference":"Matthew 21:31","text":"“Which of the two obeyed his father?”"},{"id":"mt-21-31-2","chapter":21,"verse":31,"sentence":2,"reference":"Matthew 21:31","text":"They replied, “The first.”"},{"id":"mt-21-31-3","chapter":21,"verse":31,"sentence":3,"reference":"Matthew 21:31","text":"Then Jesus explained his meaning: “I tell you the truth, corrupt tax collectors and prostitutes will get into the Kingdom of God before you do."}]},{"chapter":21,"verse":32,"reference":"Matthew 21:32","text":"For John the Baptist came and showed you the right way to live, but you didn’t believe him, while tax collectors and prostitutes did. And even when you saw this happening, you refused to believe him and repent of your sins.","sentences":[{"id":"mt-21-32-1","chapter":21,"verse":32,"sentence":1,"reference":"Matthew 21:32","text":"For John the Baptist came and showed you the right way to live, but you didn’t believe him, while tax collectors and prostitutes did."},{"id":"mt-21-32-2","chapter":21,"verse":32,"sentence":2,"reference":"Matthew 21:32","text":"And even when you saw this happening, you refused to believe him and repent of your sins."}]},{"chapter":21,"verse":33,"reference":"Matthew 21:33","text":"“Now listen to another story. A certain landowner planted a vineyard, built a wall around it, dug a pit for pressing out the grape juice, and built a lookout tower. Then he leased the vineyard to tenant farmers and moved to another country.","sentences":[{"id":"mt-21-33-1","chapter":21,"verse":33,"sentence":1,"reference":"Matthew 21:33","text":"“Now listen to another story."},{"id":"mt-21-33-2","chapter":21,"verse":33,"sentence":2,"reference":"Matthew 21:33","text":"A certain landowner planted a vineyard, built a wall around it, dug a pit for pressing out the grape juice, and built a lookout tower."},{"id":"mt-21-33-3","chapter":21,"verse":33,"sentence":3,"reference":"Matthew 21:33","text":"Then he leased the vineyard to tenant farmers and moved to another country."}]},{"chapter":21,"verse":34,"reference":"Matthew 21:34","text":"At the time of the grape harvest, he sent his servants to collect his share of the crop.","sentences":[{"id":"mt-21-34-1","chapter":21,"verse":34,"sentence":1,"reference":"Matthew 21:34","text":"At the time of the grape harvest, he sent his servants to collect his share of the crop."}]},{"chapter":21,"verse":35,"reference":"Matthew 21:35","text":"But the farmers grabbed his servants, beat one, killed one, and stoned another.","sentences":[{"id":"mt-21-35-1","chapter":21,"verse":35,"sentence":1,"reference":"Matthew 21:35","text":"But the farmers grabbed his servants, beat one, killed one, and stoned another."}]},{"chapter":21,"verse":36,"reference":"Matthew 21:36","text":"So the landowner sent a larger group of his servants to collect for him, but the results were the same.","sentences":[{"id":"mt-21-36-1","chapter":21,"verse":36,"sentence":1,"reference":"Matthew 21:36","text":"So the landowner sent a larger group of his servants to collect for him, but the results were the same."}]},{"chapter":21,"verse":37,"reference":"Matthew 21:37","text":"“Finally, the owner sent his son, thinking, ‘Surely they will respect my son.’","sentences":[{"id":"mt-21-37-1","chapter":21,"verse":37,"sentence":1,"reference":"Matthew 21:37","text":"“Finally, the owner sent his son, thinking, ‘Surely they will respect my son.’"}]},{"chapter":21,"verse":38,"reference":"Matthew 21:38","text":"“But when the tenant farmers saw his son coming, they said to one another, ‘Here comes the heir to this estate. Come on, let’s kill him and get the estate for ourselves!’","sentences":[{"id":"mt-21-38-1","chapter":21,"verse":38,"sentence":1,"reference":"Matthew 21:38","text":"“But when the tenant farmers saw his son coming, they said to one another, ‘Here comes the heir to this estate."},{"id":"mt-21-38-2","chapter":21,"verse":38,"sentence":2,"reference":"Matthew 21:38","text":"Come on, let’s kill him and get the estate for ourselves!’"}]},{"chapter":21,"verse":39,"reference":"Matthew 21:39","text":"So they grabbed him, dragged him out of the vineyard, and murdered him.","sentences":[{"id":"mt-21-39-1","chapter":21,"verse":39,"sentence":1,"reference":"Matthew 21:39","text":"So they grabbed him, dragged him out of the vineyard, and murdered him."}]},{"chapter":21,"verse":40,"reference":"Matthew 21:40","text":"“When the owner of the vineyard returns,” Jesus asked, “what do you think he will do to those farmers?”","sentences":[{"id":"mt-21-40-1","chapter":21,"verse":40,"sentence":1,"reference":"Matthew 21:40","text":"“When the owner of the vineyard returns,” Jesus asked, “what do you think he will do to those farmers?”"}]},{"chapter":21,"verse":41,"reference":"Matthew 21:41","text":"The religious leaders replied, “He will put the wicked men to a horrible death and lease the vineyard to others who will give him his share of the crop after each harvest.”","sentences":[{"id":"mt-21-41-1","chapter":21,"verse":41,"sentence":1,"reference":"Matthew 21:41","text":"The religious leaders replied, “He will put the wicked men to a horrible death and lease the vineyard to others who will give him his share of the crop after each harvest.”"}]},{"chapter":21,"verse":42,"reference":"Matthew 21:42","text":"Then Jesus asked them, “Didn’t you ever read this in the Scriptures? ‘The stone that the builders rejected has now become the cornerstone. This is the Lord’s doing, and it is wonderful to see.’","sentences":[{"id":"mt-21-42-1","chapter":21,"verse":42,"sentence":1,"reference":"Matthew 21:42","text":"Then Jesus asked them, “Didn’t you ever read this in the Scriptures?"},{"id":"mt-21-42-2","chapter":21,"verse":42,"sentence":2,"reference":"Matthew 21:42","text":"‘The stone that the builders rejected has now become the cornerstone."},{"id":"mt-21-42-3","chapter":21,"verse":42,"sentence":3,"reference":"Matthew 21:42","text":"This is the Lord’s doing, and it is wonderful to see.’"}]},{"chapter":21,"verse":43,"reference":"Matthew 21:43","text":"I tell you, the Kingdom of God will be taken away from you and given to a nation that will produce the proper fruit.","sentences":[{"id":"mt-21-43-1","chapter":21,"verse":43,"sentence":1,"reference":"Matthew 21:43","text":"I tell you, the Kingdom of God will be taken away from you and given to a nation that will produce the proper fruit."}]},{"chapter":21,"verse":44,"reference":"Matthew 21:44","text":"Anyone who stumbles over that stone will be broken to pieces, and it will crush anyone it falls on.”","sentences":[{"id":"mt-21-44-1","chapter":21,"verse":44,"sentence":1,"reference":"Matthew 21:44","text":"Anyone who stumbles over that stone will be broken to pieces, and it will crush anyone it falls on.”"}]},{"chapter":21,"verse":45,"reference":"Matthew 21:45","text":"When the leading priests and Pharisees heard this parable, they realized he was telling the story against them—they were the wicked farmers.","sentences":[{"id":"mt-21-45-1","chapter":21,"verse":45,"sentence":1,"reference":"Matthew 21:45","text":"When the leading priests and Pharisees heard this parable, they realized he was telling the story against them—they were the wicked farmers."}]},{"chapter":21,"verse":46,"reference":"Matthew 21:46","text":"They wanted to arrest him, but they were afraid of the crowds, who considered Jesus to be a prophet.","sentences":[{"id":"mt-21-46-1","chapter":21,"verse":46,"sentence":1,"reference":"Matthew 21:46","text":"They wanted to arrest him, but they were afraid of the crowds, who considered Jesus to be a prophet."}]}]},{"chapter":22,"verses":[{"chapter":22,"verse":1,"reference":"Matthew 22:1","text":"Jesus also told them other parables. He said,","sentences":[{"id":"mt-22-1-1","chapter":22,"verse":1,"sentence":1,"reference":"Matthew 22:1","text":"Jesus also told them other parables."},{"id":"mt-22-1-2","chapter":22,"verse":1,"sentence":2,"reference":"Matthew 22:1","text":"He said,"}]},{"chapter":22,"verse":2,"reference":"Matthew 22:2","text":"“The Kingdom of Heaven can be illustrated by the story of a king who prepared a great wedding feast for his son.","sentences":[{"id":"mt-22-2-1","chapter":22,"verse":2,"sentence":1,"reference":"Matthew 22:2","text":"“The Kingdom of Heaven can be illustrated by the story of a king who prepared a great wedding feast for his son."}]},{"chapter":22,"verse":3,"reference":"Matthew 22:3","text":"When the banquet was ready, he sent his servants to notify those who were invited. But they all refused to come!","sentences":[{"id":"mt-22-3-1","chapter":22,"verse":3,"sentence":1,"reference":"Matthew 22:3","text":"When the banquet was ready, he sent his servants to notify those who were invited."},{"id":"mt-22-3-2","chapter":22,"verse":3,"sentence":2,"reference":"Matthew 22:3","text":"But they all refused to come!"}]},{"chapter":22,"verse":4,"reference":"Matthew 22:4","text":"“So he sent other servants to tell them, ‘The feast has been prepared. The bulls and fattened cattle have been killed, and everything is ready. Come to the banquet!’","sentences":[{"id":"mt-22-4-1","chapter":22,"verse":4,"sentence":1,"reference":"Matthew 22:4","text":"“So he sent other servants to tell them, ‘The feast has been prepared."},{"id":"mt-22-4-2","chapter":22,"verse":4,"sentence":2,"reference":"Matthew 22:4","text":"The bulls and fattened cattle have been killed, and everything is ready."},{"id":"mt-22-4-3","chapter":22,"verse":4,"sentence":3,"reference":"Matthew 22:4","text":"Come to the banquet!’"}]},{"chapter":22,"verse":5,"reference":"Matthew 22:5","text":"But the guests he had invited ignored them and went their own way, one to his farm, another to his business.","sentences":[{"id":"mt-22-5-1","chapter":22,"verse":5,"sentence":1,"reference":"Matthew 22:5","text":"But the guests he had invited ignored them and went their own way, one to his farm, another to his business."}]},{"chapter":22,"verse":6,"reference":"Matthew 22:6","text":"Others seized his messengers and insulted them and killed them.","sentences":[{"id":"mt-22-6-1","chapter":22,"verse":6,"sentence":1,"reference":"Matthew 22:6","text":"Others seized his messengers and insulted them and killed them."}]},{"chapter":22,"verse":7,"reference":"Matthew 22:7","text":"“The king was furious, and he sent out his army to destroy the murderers and burn their town.","sentences":[{"id":"mt-22-7-1","chapter":22,"verse":7,"sentence":1,"reference":"Matthew 22:7","text":"“The king was furious, and he sent out his army to destroy the murderers and burn their town."}]},{"chapter":22,"verse":8,"reference":"Matthew 22:8","text":"And he said to his servants, ‘The wedding feast is ready, and the guests I invited aren’t worthy of the honor.","sentences":[{"id":"mt-22-8-1","chapter":22,"verse":8,"sentence":1,"reference":"Matthew 22:8","text":"And he said to his servants, ‘The wedding feast is ready, and the guests I invited aren’t worthy of the honor."}]},{"chapter":22,"verse":9,"reference":"Matthew 22:9","text":"Now go out to the street corners and invite everyone you see.’","sentences":[{"id":"mt-22-9-1","chapter":22,"verse":9,"sentence":1,"reference":"Matthew 22:9","text":"Now go out to the street corners and invite everyone you see.’"}]},{"chapter":22,"verse":10,"reference":"Matthew 22:10","text":"So the servants brought in everyone they could find, good and bad alike, and the banquet hall was filled with guests.","sentences":[{"id":"mt-22-10-1","chapter":22,"verse":10,"sentence":1,"reference":"Matthew 22:10","text":"So the servants brought in everyone they could find, good and bad alike, and the banquet hall was filled with guests."}]},{"chapter":22,"verse":11,"reference":"Matthew 22:11","text":"“But when the king came in to meet the guests, he noticed a man who wasn’t wearing the proper clothes for a wedding.","sentences":[{"id":"mt-22-11-1","chapter":22,"verse":11,"sentence":1,"reference":"Matthew 22:11","text":"“But when the king came in to meet the guests, he noticed a man who wasn’t wearing the proper clothes for a wedding."}]},{"chapter":22,"verse":12,"reference":"Matthew 22:12","text":"‘Friend,’ he asked, ‘how is it that you are here without wedding clothes?’ But the man had no reply.","sentences":[{"id":"mt-22-12-1","chapter":22,"verse":12,"sentence":1,"reference":"Matthew 22:12","text":"‘Friend,’ he asked, ‘how is it that you are here without wedding clothes?’"},{"id":"mt-22-12-2","chapter":22,"verse":12,"sentence":2,"reference":"Matthew 22:12","text":"But the man had no reply."}]},{"chapter":22,"verse":13,"reference":"Matthew 22:13","text":"Then the king said to his aides, ‘Bind his hands and feet and throw him into the outer darkness, where there will be weeping and gnashing of teeth.’","sentences":[{"id":"mt-22-13-1","chapter":22,"verse":13,"sentence":1,"reference":"Matthew 22:13","text":"Then the king said to his aides, ‘Bind his hands and feet and throw him into the outer darkness, where there will be weeping and gnashing of teeth.’"}]},{"chapter":22,"verse":14,"reference":"Matthew 22:14","text":"“For many are called, but few are chosen.”","sentences":[{"id":"mt-22-14-1","chapter":22,"verse":14,"sentence":1,"reference":"Matthew 22:14","text":"“For many are called, but few are chosen.”"}]},{"chapter":22,"verse":15,"reference":"Matthew 22:15","text":"Then the Pharisees met together to plot how to trap Jesus into saying something for which he could be arrested.","sentences":[{"id":"mt-22-15-1","chapter":22,"verse":15,"sentence":1,"reference":"Matthew 22:15","text":"Then the Pharisees met together to plot how to trap Jesus into saying something for which he could be arrested."}]},{"chapter":22,"verse":16,"reference":"Matthew 22:16","text":"They sent some of their disciples, along with the supporters of Herod, to meet with him. “Teacher,” they said, “we know how honest you are. You teach the way of God truthfully. You are impartial and don’t play favorites.","sentences":[{"id":"mt-22-16-1","chapter":22,"verse":16,"sentence":1,"reference":"Matthew 22:16","text":"They sent some of their disciples, along with the supporters of Herod, to meet with him."},{"id":"mt-22-16-2","chapter":22,"verse":16,"sentence":2,"reference":"Matthew 22:16","text":"“Teacher,” they said, “we know how honest you are."},{"id":"mt-22-16-3","chapter":22,"verse":16,"sentence":3,"reference":"Matthew 22:16","text":"You teach the way of God truthfully."},{"id":"mt-22-16-4","chapter":22,"verse":16,"sentence":4,"reference":"Matthew 22:16","text":"You are impartial and don’t play favorites."}]},{"chapter":22,"verse":17,"reference":"Matthew 22:17","text":"Now tell us what you think about this: Is it right to pay taxes to Caesar or not?”","sentences":[{"id":"mt-22-17-1","chapter":22,"verse":17,"sentence":1,"reference":"Matthew 22:17","text":"Now tell us what you think about this: Is it right to pay taxes to Caesar or not?”"}]},{"chapter":22,"verse":18,"reference":"Matthew 22:18","text":"But Jesus knew their evil motives. “You hypocrites!” he said. “Why are you trying to trap me?","sentences":[{"id":"mt-22-18-1","chapter":22,"verse":18,"sentence":1,"reference":"Matthew 22:18","text":"But Jesus knew their evil motives."},{"id":"mt-22-18-2","chapter":22,"verse":18,"sentence":2,"reference":"Matthew 22:18","text":"“You hypocrites!”"},{"id":"mt-22-18-3","chapter":22,"verse":18,"sentence":3,"reference":"Matthew 22:18","text":"he said."},{"id":"mt-22-18-4","chapter":22,"verse":18,"sentence":4,"reference":"Matthew 22:18","text":"“Why are you trying to trap me?"}]},{"chapter":22,"verse":19,"reference":"Matthew 22:19","text":"Here, show me the coin used for the tax.” When they handed him a Roman coin,","sentences":[{"id":"mt-22-19-1","chapter":22,"verse":19,"sentence":1,"reference":"Matthew 22:19","text":"Here, show me the coin used for the tax.”"},{"id":"mt-22-19-2","chapter":22,"verse":19,"sentence":2,"reference":"Matthew 22:19","text":"When they handed him a Roman coin,"}]},{"chapter":22,"verse":20,"reference":"Matthew 22:20","text":"he asked, “Whose picture and title are stamped on it?”","sentences":[{"id":"mt-22-20-1","chapter":22,"verse":20,"sentence":1,"reference":"Matthew 22:20","text":"he asked, “Whose picture and title are stamped on it?”"}]},{"chapter":22,"verse":21,"reference":"Matthew 22:21","text":"“Caesar’s,” they replied. “Well, then,” he said, “give to Caesar what belongs to Caesar, and give to God what belongs to God.”","sentences":[{"id":"mt-22-21-1","chapter":22,"verse":21,"sentence":1,"reference":"Matthew 22:21","text":"“Caesar’s,” they replied."},{"id":"mt-22-21-2","chapter":22,"verse":21,"sentence":2,"reference":"Matthew 22:21","text":"“Well, then,” he said, “give to Caesar what belongs to Caesar, and give to God what belongs to God.”"}]},{"chapter":22,"verse":22,"reference":"Matthew 22:22","text":"His reply amazed them, and they went away.","sentences":[{"id":"mt-22-22-1","chapter":22,"verse":22,"sentence":1,"reference":"Matthew 22:22","text":"His reply amazed them, and they went away."}]},{"chapter":22,"verse":23,"reference":"Matthew 22:23","text":"That same day Jesus was approached by some Sadducees—religious leaders who say there is no resurrection from the dead. They posed this question:","sentences":[{"id":"mt-22-23-1","chapter":22,"verse":23,"sentence":1,"reference":"Matthew 22:23","text":"That same day Jesus was approached by some Sadducees—religious leaders who say there is no resurrection from the dead."},{"id":"mt-22-23-2","chapter":22,"verse":23,"sentence":2,"reference":"Matthew 22:23","text":"They posed this question:"}]},{"chapter":22,"verse":24,"reference":"Matthew 22:24","text":"“Teacher, Moses said, ‘If a man dies without children, his brother should marry the widow and have a child who will carry on the brother’s name.’","sentences":[{"id":"mt-22-24-1","chapter":22,"verse":24,"sentence":1,"reference":"Matthew 22:24","text":"“Teacher, Moses said, ‘If a man dies without children, his brother should marry the widow and have a child who will carry on the brother’s name.’"}]},{"chapter":22,"verse":25,"reference":"Matthew 22:25","text":"Well, suppose there were seven brothers. The oldest one married and then died without children, so his brother married the widow.","sentences":[{"id":"mt-22-25-1","chapter":22,"verse":25,"sentence":1,"reference":"Matthew 22:25","text":"Well, suppose there were seven brothers."},{"id":"mt-22-25-2","chapter":22,"verse":25,"sentence":2,"reference":"Matthew 22:25","text":"The oldest one married and then died without children, so his brother married the widow."}]},{"chapter":22,"verse":26,"reference":"Matthew 22:26","text":"But the second brother also died, and the third brother married her. This continued with all seven of them.","sentences":[{"id":"mt-22-26-1","chapter":22,"verse":26,"sentence":1,"reference":"Matthew 22:26","text":"But the second brother also died, and the third brother married her."},{"id":"mt-22-26-2","chapter":22,"verse":26,"sentence":2,"reference":"Matthew 22:26","text":"This continued with all seven of them."}]},{"chapter":22,"verse":27,"reference":"Matthew 22:27","text":"Last of all, the woman also died.","sentences":[{"id":"mt-22-27-1","chapter":22,"verse":27,"sentence":1,"reference":"Matthew 22:27","text":"Last of all, the woman also died."}]},{"chapter":22,"verse":28,"reference":"Matthew 22:28","text":"So tell us, whose wife will she be in the resurrection? For all seven were married to her.”","sentences":[{"id":"mt-22-28-1","chapter":22,"verse":28,"sentence":1,"reference":"Matthew 22:28","text":"So tell us, whose wife will she be in the resurrection?"},{"id":"mt-22-28-2","chapter":22,"verse":28,"sentence":2,"reference":"Matthew 22:28","text":"For all seven were married to her.”"}]},{"chapter":22,"verse":29,"reference":"Matthew 22:29","text":"Jesus replied, “Your mistake is that you don’t know the Scriptures, and you don’t know the power of God.","sentences":[{"id":"mt-22-29-1","chapter":22,"verse":29,"sentence":1,"reference":"Matthew 22:29","text":"Jesus replied, “Your mistake is that you don’t know the Scriptures, and you don’t know the power of God."}]},{"chapter":22,"verse":30,"reference":"Matthew 22:30","text":"For when the dead rise, they will neither marry nor be given in marriage. In this respect they will be like the angels in heaven.","sentences":[{"id":"mt-22-30-1","chapter":22,"verse":30,"sentence":1,"reference":"Matthew 22:30","text":"For when the dead rise, they will neither marry nor be given in marriage."},{"id":"mt-22-30-2","chapter":22,"verse":30,"sentence":2,"reference":"Matthew 22:30","text":"In this respect they will be like the angels in heaven."}]},{"chapter":22,"verse":31,"reference":"Matthew 22:31","text":"“But now, as to whether there will be a resurrection of the dead—haven’t you ever read about this in the Scriptures? Long after Abraham, Isaac, and Jacob had died, God said,","sentences":[{"id":"mt-22-31-1","chapter":22,"verse":31,"sentence":1,"reference":"Matthew 22:31","text":"“But now, as to whether there will be a resurrection of the dead—haven’t you ever read about this in the Scriptures?"},{"id":"mt-22-31-2","chapter":22,"verse":31,"sentence":2,"reference":"Matthew 22:31","text":"Long after Abraham, Isaac, and Jacob had died, God said,"}]},{"chapter":22,"verse":32,"reference":"Matthew 22:32","text":"‘I am the God of Abraham, the God of Isaac, and the God of Jacob.’ So he is the God of the living, not the dead.”","sentences":[{"id":"mt-22-32-1","chapter":22,"verse":32,"sentence":1,"reference":"Matthew 22:32","text":"‘I am the God of Abraham, the God of Isaac, and the God of Jacob.’"},{"id":"mt-22-32-2","chapter":22,"verse":32,"sentence":2,"reference":"Matthew 22:32","text":"So he is the God of the living, not the dead.”"}]},{"chapter":22,"verse":33,"reference":"Matthew 22:33","text":"When the crowds heard him, they were astounded at his teaching.","sentences":[{"id":"mt-22-33-1","chapter":22,"verse":33,"sentence":1,"reference":"Matthew 22:33","text":"When the crowds heard him, they were astounded at his teaching."}]},{"chapter":22,"verse":34,"reference":"Matthew 22:34","text":"But when the Pharisees heard that he had silenced the Sadducees with his reply, they met together to question him again.","sentences":[{"id":"mt-22-34-1","chapter":22,"verse":34,"sentence":1,"reference":"Matthew 22:34","text":"But when the Pharisees heard that he had silenced the Sadducees with his reply, they met together to question him again."}]},{"chapter":22,"verse":35,"reference":"Matthew 22:35","text":"One of them, an expert in religious law, tried to trap him with this question:","sentences":[{"id":"mt-22-35-1","chapter":22,"verse":35,"sentence":1,"reference":"Matthew 22:35","text":"One of them, an expert in religious law, tried to trap him with this question:"}]},{"chapter":22,"verse":36,"reference":"Matthew 22:36","text":"“Teacher, which is the most important commandment in the law of Moses?”","sentences":[{"id":"mt-22-36-1","chapter":22,"verse":36,"sentence":1,"reference":"Matthew 22:36","text":"“Teacher, which is the most important commandment in the law of Moses?”"}]},{"chapter":22,"verse":37,"reference":"Matthew 22:37","text":"Jesus replied, “‘You must love the Lord your God with all your heart, all your soul, and all your mind.’","sentences":[{"id":"mt-22-37-1","chapter":22,"verse":37,"sentence":1,"reference":"Matthew 22:37","text":"Jesus replied, “‘You must love the Lord your God with all your heart, all your soul, and all your mind.’"}]},{"chapter":22,"verse":38,"reference":"Matthew 22:38","text":"This is the first and greatest commandment.","sentences":[{"id":"mt-22-38-1","chapter":22,"verse":38,"sentence":1,"reference":"Matthew 22:38","text":"This is the first and greatest commandment."}]},{"chapter":22,"verse":39,"reference":"Matthew 22:39","text":"A second is equally important: ‘Love your neighbor as yourself.’","sentences":[{"id":"mt-22-39-1","chapter":22,"verse":39,"sentence":1,"reference":"Matthew 22:39","text":"A second is equally important: ‘Love your neighbor as yourself.’"}]},{"chapter":22,"verse":40,"reference":"Matthew 22:40","text":"The entire law and all the demands of the prophets are based on these two commandments.”","sentences":[{"id":"mt-22-40-1","chapter":22,"verse":40,"sentence":1,"reference":"Matthew 22:40","text":"The entire law and all the demands of the prophets are based on these two commandments.”"}]},{"chapter":22,"verse":41,"reference":"Matthew 22:41","text":"Then, surrounded by the Pharisees, Jesus asked them a question:","sentences":[{"id":"mt-22-41-1","chapter":22,"verse":41,"sentence":1,"reference":"Matthew 22:41","text":"Then, surrounded by the Pharisees, Jesus asked them a question:"}]},{"chapter":22,"verse":42,"reference":"Matthew 22:42","text":"“What do you think about the Messiah? Whose son is he?” They replied, “He is the son of David.”","sentences":[{"id":"mt-22-42-1","chapter":22,"verse":42,"sentence":1,"reference":"Matthew 22:42","text":"“What do you think about the Messiah?"},{"id":"mt-22-42-2","chapter":22,"verse":42,"sentence":2,"reference":"Matthew 22:42","text":"Whose son is he?”"},{"id":"mt-22-42-3","chapter":22,"verse":42,"sentence":3,"reference":"Matthew 22:42","text":"They replied, “He is the son of David.”"}]},{"chapter":22,"verse":43,"reference":"Matthew 22:43","text":"Jesus responded, “Then why does David, speaking under the inspiration of the Spirit, call the Messiah ‘my Lord’? For David said,","sentences":[{"id":"mt-22-43-1","chapter":22,"verse":43,"sentence":1,"reference":"Matthew 22:43","text":"Jesus responded, “Then why does David, speaking under the inspiration of the Spirit, call the Messiah ‘my Lord’?"},{"id":"mt-22-43-2","chapter":22,"verse":43,"sentence":2,"reference":"Matthew 22:43","text":"For David said,"}]},{"chapter":22,"verse":44,"reference":"Matthew 22:44","text":"‘The Lord said to my Lord, Sit in the place of honor at my right hand until I humble your enemies beneath your feet.’","sentences":[{"id":"mt-22-44-1","chapter":22,"verse":44,"sentence":1,"reference":"Matthew 22:44","text":"‘The Lord said to my Lord, Sit in the place of honor at my right hand until I humble your enemies beneath your feet.’"}]},{"chapter":22,"verse":45,"reference":"Matthew 22:45","text":"Since David called the Messiah ‘my Lord,’ how can the Messiah be his son?”","sentences":[{"id":"mt-22-45-1","chapter":22,"verse":45,"sentence":1,"reference":"Matthew 22:45","text":"Since David called the Messiah ‘my Lord,’ how can the Messiah be his son?”"}]},{"chapter":22,"verse":46,"reference":"Matthew 22:46","text":"No one could answer him. And after that, no one dared to ask him any more questions.","sentences":[{"id":"mt-22-46-1","chapter":22,"verse":46,"sentence":1,"reference":"Matthew 22:46","text":"No one could answer him."},{"id":"mt-22-46-2","chapter":22,"verse":46,"sentence":2,"reference":"Matthew 22:46","text":"And after that, no one dared to ask him any more questions."}]}]},{"chapter":23,"verses":[{"chapter":23,"verse":1,"reference":"Matthew 23:1","text":"Then Jesus said to the crowds and to his disciples,","sentences":[{"id":"mt-23-1-1","chapter":23,"verse":1,"sentence":1,"reference":"Matthew 23:1","text":"Then Jesus said to the crowds and to his disciples,"}]},{"chapter":23,"verse":2,"reference":"Matthew 23:2","text":"“The teachers of religious law and the Pharisees are the official interpreters of the law of Moses.","sentences":[{"id":"mt-23-2-1","chapter":23,"verse":2,"sentence":1,"reference":"Matthew 23:2","text":"“The teachers of religious law and the Pharisees are the official interpreters of the law of Moses."}]},{"chapter":23,"verse":3,"reference":"Matthew 23:3","text":"So practice and obey whatever they tell you, but don’t follow their example. For they don’t practice what they teach.","sentences":[{"id":"mt-23-3-1","chapter":23,"verse":3,"sentence":1,"reference":"Matthew 23:3","text":"So practice and obey whatever they tell you, but don’t follow their example."},{"id":"mt-23-3-2","chapter":23,"verse":3,"sentence":2,"reference":"Matthew 23:3","text":"For they don’t practice what they teach."}]},{"chapter":23,"verse":4,"reference":"Matthew 23:4","text":"They crush people with unbearable religious demands and never lift a finger to ease the burden.","sentences":[{"id":"mt-23-4-1","chapter":23,"verse":4,"sentence":1,"reference":"Matthew 23:4","text":"They crush people with unbearable religious demands and never lift a finger to ease the burden."}]},{"chapter":23,"verse":5,"reference":"Matthew 23:5","text":"“Everything they do is for show. On their arms they wear extra wide prayer boxes with Scripture verses inside, and they wear robes with extra long tassels.","sentences":[{"id":"mt-23-5-1","chapter":23,"verse":5,"sentence":1,"reference":"Matthew 23:5","text":"“Everything they do is for show."},{"id":"mt-23-5-2","chapter":23,"verse":5,"sentence":2,"reference":"Matthew 23:5","text":"On their arms they wear extra wide prayer boxes with Scripture verses inside, and they wear robes with extra long tassels."}]},{"chapter":23,"verse":6,"reference":"Matthew 23:6","text":"And they love to sit at the head table at banquets and in the seats of honor in the synagogues.","sentences":[{"id":"mt-23-6-1","chapter":23,"verse":6,"sentence":1,"reference":"Matthew 23:6","text":"And they love to sit at the head table at banquets and in the seats of honor in the synagogues."}]},{"chapter":23,"verse":7,"reference":"Matthew 23:7","text":"They love to receive respectful greetings as they walk in the marketplaces, and to be called ‘Rabbi.’","sentences":[{"id":"mt-23-7-1","chapter":23,"verse":7,"sentence":1,"reference":"Matthew 23:7","text":"They love to receive respectful greetings as they walk in the marketplaces, and to be called ‘Rabbi.’"}]},{"chapter":23,"verse":8,"reference":"Matthew 23:8","text":"“Don’t let anyone call you ‘Rabbi,’ for you have only one teacher, and all of you are equal as brothers and sisters.","sentences":[{"id":"mt-23-8-1","chapter":23,"verse":8,"sentence":1,"reference":"Matthew 23:8","text":"“Don’t let anyone call you ‘Rabbi,’ for you have only one teacher, and all of you are equal as brothers and sisters."}]},{"chapter":23,"verse":9,"reference":"Matthew 23:9","text":"And don’t address anyone here on earth as ‘Father,’ for only God in heaven is your Father.","sentences":[{"id":"mt-23-9-1","chapter":23,"verse":9,"sentence":1,"reference":"Matthew 23:9","text":"And don’t address anyone here on earth as ‘Father,’ for only God in heaven is your Father."}]},{"chapter":23,"verse":10,"reference":"Matthew 23:10","text":"And don’t let anyone call you ‘Teacher,’ for you have only one teacher, the Messiah.","sentences":[{"id":"mt-23-10-1","chapter":23,"verse":10,"sentence":1,"reference":"Matthew 23:10","text":"And don’t let anyone call you ‘Teacher,’ for you have only one teacher, the Messiah."}]},{"chapter":23,"verse":11,"reference":"Matthew 23:11","text":"The greatest among you must be a servant.","sentences":[{"id":"mt-23-11-1","chapter":23,"verse":11,"sentence":1,"reference":"Matthew 23:11","text":"The greatest among you must be a servant."}]},{"chapter":23,"verse":12,"reference":"Matthew 23:12","text":"But those who exalt themselves will be humbled, and those who humble themselves will be exalted.","sentences":[{"id":"mt-23-12-1","chapter":23,"verse":12,"sentence":1,"reference":"Matthew 23:12","text":"But those who exalt themselves will be humbled, and those who humble themselves will be exalted."}]},{"chapter":23,"verse":13,"reference":"Matthew 23:13","text":"“What sorrow awaits you teachers of religious law and you Pharisees. Hypocrites! For you shut the door of the Kingdom of Heaven in people’s faces. You won’t go in yourselves, and you don’t let others enter either.","sentences":[{"id":"mt-23-13-1","chapter":23,"verse":13,"sentence":1,"reference":"Matthew 23:13","text":"“What sorrow awaits you teachers of religious law and you Pharisees."},{"id":"mt-23-13-2","chapter":23,"verse":13,"sentence":2,"reference":"Matthew 23:13","text":"Hypocrites!"},{"id":"mt-23-13-3","chapter":23,"verse":13,"sentence":3,"reference":"Matthew 23:13","text":"For you shut the door of the Kingdom of Heaven in people’s faces."},{"id":"mt-23-13-4","chapter":23,"verse":13,"sentence":4,"reference":"Matthew 23:13","text":"You won’t go in yourselves, and you don’t let others enter either."}]},{"chapter":23,"verse":15,"reference":"Matthew 23:15","text":"“What sorrow awaits you teachers of religious law and you Pharisees. Hypocrites! For you cross land and sea to make one convert, and then you turn that person into twice the child of hell you yourselves are!","sentences":[{"id":"mt-23-15-1","chapter":23,"verse":15,"sentence":1,"reference":"Matthew 23:15","text":"“What sorrow awaits you teachers of religious law and you Pharisees."},{"id":"mt-23-15-2","chapter":23,"verse":15,"sentence":2,"reference":"Matthew 23:15","text":"Hypocrites!"},{"id":"mt-23-15-3","chapter":23,"verse":15,"sentence":3,"reference":"Matthew 23:15","text":"For you cross land and sea to make one convert, and then you turn that person into twice the child of hell you yourselves are!"}]},{"chapter":23,"verse":16,"reference":"Matthew 23:16","text":"“Blind guides! What sorrow awaits you! For you say that it means nothing to swear ‘by God’s Temple,’ but that it is binding to swear ‘by the gold in the Temple.’","sentences":[{"id":"mt-23-16-1","chapter":23,"verse":16,"sentence":1,"reference":"Matthew 23:16","text":"“Blind guides!"},{"id":"mt-23-16-2","chapter":23,"verse":16,"sentence":2,"reference":"Matthew 23:16","text":"What sorrow awaits you!"},{"id":"mt-23-16-3","chapter":23,"verse":16,"sentence":3,"reference":"Matthew 23:16","text":"For you say that it means nothing to swear ‘by God’s Temple,’ but that it is binding to swear ‘by the gold in the Temple.’"}]},{"chapter":23,"verse":17,"reference":"Matthew 23:17","text":"Blind fools! Which is more important—the gold or the Temple that makes the gold sacred?","sentences":[{"id":"mt-23-17-1","chapter":23,"verse":17,"sentence":1,"reference":"Matthew 23:17","text":"Blind fools!"},{"id":"mt-23-17-2","chapter":23,"verse":17,"sentence":2,"reference":"Matthew 23:17","text":"Which is more important—the gold or the Temple that makes the gold sacred?"}]},{"chapter":23,"verse":18,"reference":"Matthew 23:18","text":"And you say that to swear ‘by the altar’ is not binding, but to swear ‘by the gifts on the altar’ is binding.","sentences":[{"id":"mt-23-18-1","chapter":23,"verse":18,"sentence":1,"reference":"Matthew 23:18","text":"And you say that to swear ‘by the altar’ is not binding, but to swear ‘by the gifts on the altar’ is binding."}]},{"chapter":23,"verse":19,"reference":"Matthew 23:19","text":"How blind! For which is more important—the gift on the altar or the altar that makes the gift sacred?","sentences":[{"id":"mt-23-19-1","chapter":23,"verse":19,"sentence":1,"reference":"Matthew 23:19","text":"How blind!"},{"id":"mt-23-19-2","chapter":23,"verse":19,"sentence":2,"reference":"Matthew 23:19","text":"For which is more important—the gift on the altar or the altar that makes the gift sacred?"}]},{"chapter":23,"verse":20,"reference":"Matthew 23:20","text":"When you swear ‘by the altar,’ you are swearing by it and by everything on it.","sentences":[{"id":"mt-23-20-1","chapter":23,"verse":20,"sentence":1,"reference":"Matthew 23:20","text":"When you swear ‘by the altar,’ you are swearing by it and by everything on it."}]},{"chapter":23,"verse":21,"reference":"Matthew 23:21","text":"And when you swear ‘by the Temple,’ you are swearing by it and by God, who lives in it.","sentences":[{"id":"mt-23-21-1","chapter":23,"verse":21,"sentence":1,"reference":"Matthew 23:21","text":"And when you swear ‘by the Temple,’ you are swearing by it and by God, who lives in it."}]},{"chapter":23,"verse":22,"reference":"Matthew 23:22","text":"And when you swear ‘by heaven,’ you are swearing by the throne of God and by God, who sits on the throne.","sentences":[{"id":"mt-23-22-1","chapter":23,"verse":22,"sentence":1,"reference":"Matthew 23:22","text":"And when you swear ‘by heaven,’ you are swearing by the throne of God and by God, who sits on the throne."}]},{"chapter":23,"verse":23,"reference":"Matthew 23:23","text":"“What sorrow awaits you teachers of religious law and you Pharisees. Hypocrites! For you are careful to tithe even the tiniest income from your herb gardens, but you ignore the more important aspects of the law—justice, mercy, and faith. You should tithe, yes, but do not neglect the more important things.","sentences":[{"id":"mt-23-23-1","chapter":23,"verse":23,"sentence":1,"reference":"Matthew 23:23","text":"“What sorrow awaits you teachers of religious law and you Pharisees."},{"id":"mt-23-23-2","chapter":23,"verse":23,"sentence":2,"reference":"Matthew 23:23","text":"Hypocrites!"},{"id":"mt-23-23-3","chapter":23,"verse":23,"sentence":3,"reference":"Matthew 23:23","text":"For you are careful to tithe even the tiniest income from your herb gardens, but you ignore the more important aspects of the law—justice, mercy, and faith."},{"id":"mt-23-23-4","chapter":23,"verse":23,"sentence":4,"reference":"Matthew 23:23","text":"You should tithe, yes, but do not neglect the more important things."}]},{"chapter":23,"verse":24,"reference":"Matthew 23:24","text":"Blind guides! You strain your water so you won’t accidentally swallow a gnat, but you swallow a camel!","sentences":[{"id":"mt-23-24-1","chapter":23,"verse":24,"sentence":1,"reference":"Matthew 23:24","text":"Blind guides!"},{"id":"mt-23-24-2","chapter":23,"verse":24,"sentence":2,"reference":"Matthew 23:24","text":"You strain your water so you won’t accidentally swallow a gnat, but you swallow a camel!"}]},{"chapter":23,"verse":25,"reference":"Matthew 23:25","text":"“What sorrow awaits you teachers of religious law and you Pharisees. Hypocrites! For you are so careful to clean the outside of the cup and the dish, but inside you are filthy—full of greed and self-indulgence!","sentences":[{"id":"mt-23-25-1","chapter":23,"verse":25,"sentence":1,"reference":"Matthew 23:25","text":"“What sorrow awaits you teachers of religious law and you Pharisees."},{"id":"mt-23-25-2","chapter":23,"verse":25,"sentence":2,"reference":"Matthew 23:25","text":"Hypocrites!"},{"id":"mt-23-25-3","chapter":23,"verse":25,"sentence":3,"reference":"Matthew 23:25","text":"For you are so careful to clean the outside of the cup and the dish, but inside you are filthy—full of greed and self-indulgence!"}]},{"chapter":23,"verse":26,"reference":"Matthew 23:26","text":"You blind Pharisee! First wash the inside of the cup and the dish, and then the outside will become clean, too.","sentences":[{"id":"mt-23-26-1","chapter":23,"verse":26,"sentence":1,"reference":"Matthew 23:26","text":"You blind Pharisee!"},{"id":"mt-23-26-2","chapter":23,"verse":26,"sentence":2,"reference":"Matthew 23:26","text":"First wash the inside of the cup and the dish, and then the outside will become clean, too."}]},{"chapter":23,"verse":27,"reference":"Matthew 23:27","text":"“What sorrow awaits you teachers of religious law and you Pharisees. Hypocrites! For you are like whitewashed tombs—beautiful on the outside but filled on the inside with dead people’s bones and all sorts of impurity.","sentences":[{"id":"mt-23-27-1","chapter":23,"verse":27,"sentence":1,"reference":"Matthew 23:27","text":"“What sorrow awaits you teachers of religious law and you Pharisees."},{"id":"mt-23-27-2","chapter":23,"verse":27,"sentence":2,"reference":"Matthew 23:27","text":"Hypocrites!"},{"id":"mt-23-27-3","chapter":23,"verse":27,"sentence":3,"reference":"Matthew 23:27","text":"For you are like whitewashed tombs—beautiful on the outside but filled on the inside with dead people’s bones and all sorts of impurity."}]},{"chapter":23,"verse":28,"reference":"Matthew 23:28","text":"Outwardly you look like righteous people, but inwardly your hearts are filled with hypocrisy and lawlessness.","sentences":[{"id":"mt-23-28-1","chapter":23,"verse":28,"sentence":1,"reference":"Matthew 23:28","text":"Outwardly you look like righteous people, but inwardly your hearts are filled with hypocrisy and lawlessness."}]},{"chapter":23,"verse":29,"reference":"Matthew 23:29","text":"“What sorrow awaits you teachers of religious law and you Pharisees. Hypocrites! For you build tombs for the prophets your ancestors killed, and you decorate the monuments of the godly people your ancestors destroyed.","sentences":[{"id":"mt-23-29-1","chapter":23,"verse":29,"sentence":1,"reference":"Matthew 23:29","text":"“What sorrow awaits you teachers of religious law and you Pharisees."},{"id":"mt-23-29-2","chapter":23,"verse":29,"sentence":2,"reference":"Matthew 23:29","text":"Hypocrites!"},{"id":"mt-23-29-3","chapter":23,"verse":29,"sentence":3,"reference":"Matthew 23:29","text":"For you build tombs for the prophets your ancestors killed, and you decorate the monuments of the godly people your ancestors destroyed."}]},{"chapter":23,"verse":30,"reference":"Matthew 23:30","text":"Then you say, ‘If we had lived in the days of our ancestors, we would never have joined them in killing the prophets.’","sentences":[{"id":"mt-23-30-1","chapter":23,"verse":30,"sentence":1,"reference":"Matthew 23:30","text":"Then you say, ‘If we had lived in the days of our ancestors, we would never have joined them in killing the prophets.’"}]},{"chapter":23,"verse":31,"reference":"Matthew 23:31","text":"“But in saying that, you testify against yourselves that you are indeed the descendants of those who murdered the prophets.","sentences":[{"id":"mt-23-31-1","chapter":23,"verse":31,"sentence":1,"reference":"Matthew 23:31","text":"“But in saying that, you testify against yourselves that you are indeed the descendants of those who murdered the prophets."}]},{"chapter":23,"verse":32,"reference":"Matthew 23:32","text":"Go ahead and finish what your ancestors started.","sentences":[{"id":"mt-23-32-1","chapter":23,"verse":32,"sentence":1,"reference":"Matthew 23:32","text":"Go ahead and finish what your ancestors started."}]},{"chapter":23,"verse":33,"reference":"Matthew 23:33","text":"Snakes! Sons of vipers! How will you escape the judgment of hell?","sentences":[{"id":"mt-23-33-1","chapter":23,"verse":33,"sentence":1,"reference":"Matthew 23:33","text":"Snakes!"},{"id":"mt-23-33-2","chapter":23,"verse":33,"sentence":2,"reference":"Matthew 23:33","text":"Sons of vipers!"},{"id":"mt-23-33-3","chapter":23,"verse":33,"sentence":3,"reference":"Matthew 23:33","text":"How will you escape the judgment of hell?"}]},{"chapter":23,"verse":34,"reference":"Matthew 23:34","text":"“Therefore, I am sending you prophets and wise men and teachers of religious law. But you will kill some by crucifixion, and you will flog others with whips in your synagogues, chasing them from city to city.","sentences":[{"id":"mt-23-34-1","chapter":23,"verse":34,"sentence":1,"reference":"Matthew 23:34","text":"“Therefore, I am sending you prophets and wise men and teachers of religious law."},{"id":"mt-23-34-2","chapter":23,"verse":34,"sentence":2,"reference":"Matthew 23:34","text":"But you will kill some by crucifixion, and you will flog others with whips in your synagogues, chasing them from city to city."}]},{"chapter":23,"verse":35,"reference":"Matthew 23:35","text":"As a result, you will be held responsible for the murder of all godly people of all time—from the murder of righteous Abel to the murder of Zechariah son of Berekiah, whom you killed in the Temple between the sanctuary and the altar.","sentences":[{"id":"mt-23-35-1","chapter":23,"verse":35,"sentence":1,"reference":"Matthew 23:35","text":"As a result, you will be held responsible for the murder of all godly people of all time—from the murder of righteous Abel to the murder of Zechariah son of Berekiah, whom you killed in the Temple between the sanctuary and the altar."}]},{"chapter":23,"verse":36,"reference":"Matthew 23:36","text":"I tell you the truth, this judgment will fall on this very generation.","sentences":[{"id":"mt-23-36-1","chapter":23,"verse":36,"sentence":1,"reference":"Matthew 23:36","text":"I tell you the truth, this judgment will fall on this very generation."}]},{"chapter":23,"verse":37,"reference":"Matthew 23:37","text":"“O Jerusalem, Jerusalem, the city that kills the prophets and stones God’s messengers! How often I have wanted to gather your children together as a hen protects her chicks beneath her wings, but you wouldn’t let me.","sentences":[{"id":"mt-23-37-1","chapter":23,"verse":37,"sentence":1,"reference":"Matthew 23:37","text":"“O Jerusalem, Jerusalem, the city that kills the prophets and stones God’s messengers!"},{"id":"mt-23-37-2","chapter":23,"verse":37,"sentence":2,"reference":"Matthew 23:37","text":"How often I have wanted to gather your children together as a hen protects her chicks beneath her wings, but you wouldn’t let me."}]},{"chapter":23,"verse":38,"reference":"Matthew 23:38","text":"And now, look, your house is abandoned and desolate.","sentences":[{"id":"mt-23-38-1","chapter":23,"verse":38,"sentence":1,"reference":"Matthew 23:38","text":"And now, look, your house is abandoned and desolate."}]},{"chapter":23,"verse":39,"reference":"Matthew 23:39","text":"For I tell you this, you will never see me again until you say, ‘Blessings on the one who comes in the name of the Lord!’”","sentences":[{"id":"mt-23-39-1","chapter":23,"verse":39,"sentence":1,"reference":"Matthew 23:39","text":"For I tell you this, you will never see me again until you say, ‘Blessings on the one who comes in the name of the Lord!’”"}]}]},{"chapter":24,"verses":[{"chapter":24,"verse":1,"reference":"Matthew 24:1","text":"As Jesus was leaving the Temple grounds, his disciples pointed out to him the various Temple buildings.","sentences":[{"id":"mt-24-1-1","chapter":24,"verse":1,"sentence":1,"reference":"Matthew 24:1","text":"As Jesus was leaving the Temple grounds, his disciples pointed out to him the various Temple buildings."}]},{"chapter":24,"verse":2,"reference":"Matthew 24:2","text":"But he responded, “Do you see all these buildings? I tell you the truth, they will be completely demolished. Not one stone will be left on top of another!”","sentences":[{"id":"mt-24-2-1","chapter":24,"verse":2,"sentence":1,"reference":"Matthew 24:2","text":"But he responded, “Do you see all these buildings?"},{"id":"mt-24-2-2","chapter":24,"verse":2,"sentence":2,"reference":"Matthew 24:2","text":"I tell you the truth, they will be completely demolished."},{"id":"mt-24-2-3","chapter":24,"verse":2,"sentence":3,"reference":"Matthew 24:2","text":"Not one stone will be left on top of another!”"}]},{"chapter":24,"verse":3,"reference":"Matthew 24:3","text":"Later, Jesus sat on the Mount of Olives. His disciples came to him privately and said, “Tell us, when will all this happen? What sign will signal your return and the end of the world?”","sentences":[{"id":"mt-24-3-1","chapter":24,"verse":3,"sentence":1,"reference":"Matthew 24:3","text":"Later, Jesus sat on the Mount of Olives."},{"id":"mt-24-3-2","chapter":24,"verse":3,"sentence":2,"reference":"Matthew 24:3","text":"His disciples came to him privately and said, “Tell us, when will all this happen?"},{"id":"mt-24-3-3","chapter":24,"verse":3,"sentence":3,"reference":"Matthew 24:3","text":"What sign will signal your return and the end of the world?”"}]},{"chapter":24,"verse":4,"reference":"Matthew 24:4","text":"Jesus told them, “Don’t let anyone mislead you,","sentences":[{"id":"mt-24-4-1","chapter":24,"verse":4,"sentence":1,"reference":"Matthew 24:4","text":"Jesus told them, “Don’t let anyone mislead you,"}]},{"chapter":24,"verse":5,"reference":"Matthew 24:5","text":"for many will come in my name, claiming, ‘I am the Messiah.’ They will deceive many.","sentences":[{"id":"mt-24-5-1","chapter":24,"verse":5,"sentence":1,"reference":"Matthew 24:5","text":"for many will come in my name, claiming, ‘I am the Messiah.’"},{"id":"mt-24-5-2","chapter":24,"verse":5,"sentence":2,"reference":"Matthew 24:5","text":"They will deceive many."}]},{"chapter":24,"verse":6,"reference":"Matthew 24:6","text":"And you will hear of wars and threats of wars, but don’t panic. Yes, these things must take place, but the end won’t follow immediately.","sentences":[{"id":"mt-24-6-1","chapter":24,"verse":6,"sentence":1,"reference":"Matthew 24:6","text":"And you will hear of wars and threats of wars, but don’t panic."},{"id":"mt-24-6-2","chapter":24,"verse":6,"sentence":2,"reference":"Matthew 24:6","text":"Yes, these things must take place, but the end won’t follow immediately."}]},{"chapter":24,"verse":7,"reference":"Matthew 24:7","text":"Nation will go to war against nation, and kingdom against kingdom. There will be famines and earthquakes in many parts of the world.","sentences":[{"id":"mt-24-7-1","chapter":24,"verse":7,"sentence":1,"reference":"Matthew 24:7","text":"Nation will go to war against nation, and kingdom against kingdom."},{"id":"mt-24-7-2","chapter":24,"verse":7,"sentence":2,"reference":"Matthew 24:7","text":"There will be famines and earthquakes in many parts of the world."}]},{"chapter":24,"verse":8,"reference":"Matthew 24:8","text":"But all this is only the first of the birth pains, with more to come.","sentences":[{"id":"mt-24-8-1","chapter":24,"verse":8,"sentence":1,"reference":"Matthew 24:8","text":"But all this is only the first of the birth pains, with more to come."}]},{"chapter":24,"verse":9,"reference":"Matthew 24:9","text":"“Then you will be arrested, persecuted, and killed. You will be hated all over the world because you are my followers.","sentences":[{"id":"mt-24-9-1","chapter":24,"verse":9,"sentence":1,"reference":"Matthew 24:9","text":"“Then you will be arrested, persecuted, and killed."},{"id":"mt-24-9-2","chapter":24,"verse":9,"sentence":2,"reference":"Matthew 24:9","text":"You will be hated all over the world because you are my followers."}]},{"chapter":24,"verse":10,"reference":"Matthew 24:10","text":"And many will turn away from me and betray and hate each other.","sentences":[{"id":"mt-24-10-1","chapter":24,"verse":10,"sentence":1,"reference":"Matthew 24:10","text":"And many will turn away from me and betray and hate each other."}]},{"chapter":24,"verse":11,"reference":"Matthew 24:11","text":"And many false prophets will appear and will deceive many people.","sentences":[{"id":"mt-24-11-1","chapter":24,"verse":11,"sentence":1,"reference":"Matthew 24:11","text":"And many false prophets will appear and will deceive many people."}]},{"chapter":24,"verse":12,"reference":"Matthew 24:12","text":"Sin will be rampant everywhere, and the love of many will grow cold.","sentences":[{"id":"mt-24-12-1","chapter":24,"verse":12,"sentence":1,"reference":"Matthew 24:12","text":"Sin will be rampant everywhere, and the love of many will grow cold."}]},{"chapter":24,"verse":13,"reference":"Matthew 24:13","text":"But the one who endures to the end will be saved.","sentences":[{"id":"mt-24-13-1","chapter":24,"verse":13,"sentence":1,"reference":"Matthew 24:13","text":"But the one who endures to the end will be saved."}]},{"chapter":24,"verse":14,"reference":"Matthew 24:14","text":"And the Good News about the Kingdom will be preached throughout the whole world, so that all nations will hear it; and then the end will come.","sentences":[{"id":"mt-24-14-1","chapter":24,"verse":14,"sentence":1,"reference":"Matthew 24:14","text":"And the Good News about the Kingdom will be preached throughout the whole world, so that all nations will hear it; and then the end will come."}]},{"chapter":24,"verse":15,"reference":"Matthew 24:15","text":"“The day is coming when you will see what Daniel the prophet spoke about—the sacrilegious object that causes desecration standing in the Holy Place.” (Reader, pay attention!)","sentences":[{"id":"mt-24-15-1","chapter":24,"verse":15,"sentence":1,"reference":"Matthew 24:15","text":"“The day is coming when you will see what Daniel the prophet spoke about—the sacrilegious object that causes desecration standing in the Holy Place.”"},{"id":"mt-24-15-2","chapter":24,"verse":15,"sentence":2,"reference":"Matthew 24:15","text":"(Reader, pay attention!)"}]},{"chapter":24,"verse":16,"reference":"Matthew 24:16","text":"“Then those in Judea must flee to the hills.","sentences":[{"id":"mt-24-16-1","chapter":24,"verse":16,"sentence":1,"reference":"Matthew 24:16","text":"“Then those in Judea must flee to the hills."}]},{"chapter":24,"verse":17,"reference":"Matthew 24:17","text":"A person out on the deck of a roof must not go down into the house to pack.","sentences":[{"id":"mt-24-17-1","chapter":24,"verse":17,"sentence":1,"reference":"Matthew 24:17","text":"A person out on the deck of a roof must not go down into the house to pack."}]},{"chapter":24,"verse":18,"reference":"Matthew 24:18","text":"A person out in the field must not return even to get a coat.","sentences":[{"id":"mt-24-18-1","chapter":24,"verse":18,"sentence":1,"reference":"Matthew 24:18","text":"A person out in the field must not return even to get a coat."}]},{"chapter":24,"verse":19,"reference":"Matthew 24:19","text":"How terrible it will be for pregnant women and for nursing mothers in those days.","sentences":[{"id":"mt-24-19-1","chapter":24,"verse":19,"sentence":1,"reference":"Matthew 24:19","text":"How terrible it will be for pregnant women and for nursing mothers in those days."}]},{"chapter":24,"verse":20,"reference":"Matthew 24:20","text":"And pray that your flight will not be in winter or on the Sabbath.","sentences":[{"id":"mt-24-20-1","chapter":24,"verse":20,"sentence":1,"reference":"Matthew 24:20","text":"And pray that your flight will not be in winter or on the Sabbath."}]},{"chapter":24,"verse":21,"reference":"Matthew 24:21","text":"For there will be greater anguish than at any time since the world began. And it will never be so great again.","sentences":[{"id":"mt-24-21-1","chapter":24,"verse":21,"sentence":1,"reference":"Matthew 24:21","text":"For there will be greater anguish than at any time since the world began."},{"id":"mt-24-21-2","chapter":24,"verse":21,"sentence":2,"reference":"Matthew 24:21","text":"And it will never be so great again."}]},{"chapter":24,"verse":22,"reference":"Matthew 24:22","text":"In fact, unless that time of calamity is shortened, not a single person will survive. But it will be shortened for the sake of God’s chosen ones.","sentences":[{"id":"mt-24-22-1","chapter":24,"verse":22,"sentence":1,"reference":"Matthew 24:22","text":"In fact, unless that time of calamity is shortened, not a single person will survive."},{"id":"mt-24-22-2","chapter":24,"verse":22,"sentence":2,"reference":"Matthew 24:22","text":"But it will be shortened for the sake of God’s chosen ones."}]},{"chapter":24,"verse":23,"reference":"Matthew 24:23","text":"“Then if anyone tells you, ‘Look, here is the Messiah,’ or ‘There he is,’ don’t believe it.","sentences":[{"id":"mt-24-23-1","chapter":24,"verse":23,"sentence":1,"reference":"Matthew 24:23","text":"“Then if anyone tells you, ‘Look, here is the Messiah,’ or ‘There he is,’ don’t believe it."}]},{"chapter":24,"verse":24,"reference":"Matthew 24:24","text":"For false messiahs and false prophets will rise up and perform great signs and wonders so as to deceive, if possible, even God’s chosen ones.","sentences":[{"id":"mt-24-24-1","chapter":24,"verse":24,"sentence":1,"reference":"Matthew 24:24","text":"For false messiahs and false prophets will rise up and perform great signs and wonders so as to deceive, if possible, even God’s chosen ones."}]},{"chapter":24,"verse":25,"reference":"Matthew 24:25","text":"See, I have warned you about this ahead of time.","sentences":[{"id":"mt-24-25-1","chapter":24,"verse":25,"sentence":1,"reference":"Matthew 24:25","text":"See, I have warned you about this ahead of time."}]},{"chapter":24,"verse":26,"reference":"Matthew 24:26","text":"“So if someone tells you, ‘Look, the Messiah is out in the desert,’ don’t bother to go and look. Or, ‘Look, he is hiding here,’ don’t believe it!","sentences":[{"id":"mt-24-26-1","chapter":24,"verse":26,"sentence":1,"reference":"Matthew 24:26","text":"“So if someone tells you, ‘Look, the Messiah is out in the desert,’ don’t bother to go and look."},{"id":"mt-24-26-2","chapter":24,"verse":26,"sentence":2,"reference":"Matthew 24:26","text":"Or, ‘Look, he is hiding here,’ don’t believe it!"}]},{"chapter":24,"verse":27,"reference":"Matthew 24:27","text":"For as the lightning flashes in the east and shines to the west, so it will be when the Son of Man comes.","sentences":[{"id":"mt-24-27-1","chapter":24,"verse":27,"sentence":1,"reference":"Matthew 24:27","text":"For as the lightning flashes in the east and shines to the west, so it will be when the Son of Man comes."}]},{"chapter":24,"verse":28,"reference":"Matthew 24:28","text":"Just as the gathering of vultures shows there is a carcass nearby, so these signs indicate that the end is near.","sentences":[{"id":"mt-24-28-1","chapter":24,"verse":28,"sentence":1,"reference":"Matthew 24:28","text":"Just as the gathering of vultures shows there is a carcass nearby, so these signs indicate that the end is near."}]},{"chapter":24,"verse":29,"reference":"Matthew 24:29","text":"“Immediately after the anguish of those days, the sun will be darkened, the moon will give no light, the stars will fall from the sky, and the powers in the heavens will be shaken.","sentences":[{"id":"mt-24-29-1","chapter":24,"verse":29,"sentence":1,"reference":"Matthew 24:29","text":"“Immediately after the anguish of those days, the sun will be darkened, the moon will give no light, the stars will fall from the sky, and the powers in the heavens will be shaken."}]},{"chapter":24,"verse":30,"reference":"Matthew 24:30","text":"And then at last, the sign that the Son of Man is coming will appear in the heavens, and there will be deep mourning among all the peoples of the earth. And they will see the Son of Man coming on the clouds of heaven with power and great glory.","sentences":[{"id":"mt-24-30-1","chapter":24,"verse":30,"sentence":1,"reference":"Matthew 24:30","text":"And then at last, the sign that the Son of Man is coming will appear in the heavens, and there will be deep mourning among all the peoples of the earth."},{"id":"mt-24-30-2","chapter":24,"verse":30,"sentence":2,"reference":"Matthew 24:30","text":"And they will see the Son of Man coming on the clouds of heaven with power and great glory."}]},{"chapter":24,"verse":31,"reference":"Matthew 24:31","text":"And he will send out his angels with the mighty blast of a trumpet, and they will gather his chosen ones from all over the world—from the farthest ends of the earth and heaven.","sentences":[{"id":"mt-24-31-1","chapter":24,"verse":31,"sentence":1,"reference":"Matthew 24:31","text":"And he will send out his angels with the mighty blast of a trumpet, and they will gather his chosen ones from all over the world—from the farthest ends of the earth and heaven."}]},{"chapter":24,"verse":32,"reference":"Matthew 24:32","text":"“Now learn a lesson from the fig tree. When its branches bud and its leaves begin to sprout, you know that summer is near.","sentences":[{"id":"mt-24-32-1","chapter":24,"verse":32,"sentence":1,"reference":"Matthew 24:32","text":"“Now learn a lesson from the fig tree."},{"id":"mt-24-32-2","chapter":24,"verse":32,"sentence":2,"reference":"Matthew 24:32","text":"When its branches bud and its leaves begin to sprout, you know that summer is near."}]},{"chapter":24,"verse":33,"reference":"Matthew 24:33","text":"In the same way, when you see all these things, you can know his return is very near, right at the door.","sentences":[{"id":"mt-24-33-1","chapter":24,"verse":33,"sentence":1,"reference":"Matthew 24:33","text":"In the same way, when you see all these things, you can know his return is very near, right at the door."}]},{"chapter":24,"verse":34,"reference":"Matthew 24:34","text":"I tell you the truth, this generation will not pass from the scene until all these things take place.","sentences":[{"id":"mt-24-34-1","chapter":24,"verse":34,"sentence":1,"reference":"Matthew 24:34","text":"I tell you the truth, this generation will not pass from the scene until all these things take place."}]},{"chapter":24,"verse":35,"reference":"Matthew 24:35","text":"Heaven and earth will disappear, but my words will never disappear.","sentences":[{"id":"mt-24-35-1","chapter":24,"verse":35,"sentence":1,"reference":"Matthew 24:35","text":"Heaven and earth will disappear, but my words will never disappear."}]},{"chapter":24,"verse":36,"reference":"Matthew 24:36","text":"“However, no one knows the day or hour when these things will happen, not even the angels in heaven or the Son himself. Only the Father knows.","sentences":[{"id":"mt-24-36-1","chapter":24,"verse":36,"sentence":1,"reference":"Matthew 24:36","text":"“However, no one knows the day or hour when these things will happen, not even the angels in heaven or the Son himself."},{"id":"mt-24-36-2","chapter":24,"verse":36,"sentence":2,"reference":"Matthew 24:36","text":"Only the Father knows."}]},{"chapter":24,"verse":37,"reference":"Matthew 24:37","text":"“When the Son of Man returns, it will be like it was in Noah’s day.","sentences":[{"id":"mt-24-37-1","chapter":24,"verse":37,"sentence":1,"reference":"Matthew 24:37","text":"“When the Son of Man returns, it will be like it was in Noah’s day."}]},{"chapter":24,"verse":38,"reference":"Matthew 24:38","text":"In those days before the flood, the people were enjoying banquets and parties and weddings right up to the time Noah entered his boat.","sentences":[{"id":"mt-24-38-1","chapter":24,"verse":38,"sentence":1,"reference":"Matthew 24:38","text":"In those days before the flood, the people were enjoying banquets and parties and weddings right up to the time Noah entered his boat."}]},{"chapter":24,"verse":39,"reference":"Matthew 24:39","text":"People didn’t realize what was going to happen until the flood came and swept them all away. That is the way it will be when the Son of Man comes.","sentences":[{"id":"mt-24-39-1","chapter":24,"verse":39,"sentence":1,"reference":"Matthew 24:39","text":"People didn’t realize what was going to happen until the flood came and swept them all away."},{"id":"mt-24-39-2","chapter":24,"verse":39,"sentence":2,"reference":"Matthew 24:39","text":"That is the way it will be when the Son of Man comes."}]},{"chapter":24,"verse":40,"reference":"Matthew 24:40","text":"“Two men will be working together in the field; one will be taken, the other left.","sentences":[{"id":"mt-24-40-1","chapter":24,"verse":40,"sentence":1,"reference":"Matthew 24:40","text":"“Two men will be working together in the field; one will be taken, the other left."}]},{"chapter":24,"verse":41,"reference":"Matthew 24:41","text":"Two women will be grinding flour at the mill; one will be taken, the other left.","sentences":[{"id":"mt-24-41-1","chapter":24,"verse":41,"sentence":1,"reference":"Matthew 24:41","text":"Two women will be grinding flour at the mill; one will be taken, the other left."}]},{"chapter":24,"verse":42,"reference":"Matthew 24:42","text":"“So you, too, must keep watch! For you don’t know what day your Lord is coming.","sentences":[{"id":"mt-24-42-1","chapter":24,"verse":42,"sentence":1,"reference":"Matthew 24:42","text":"“So you, too, must keep watch!"},{"id":"mt-24-42-2","chapter":24,"verse":42,"sentence":2,"reference":"Matthew 24:42","text":"For you don’t know what day your Lord is coming."}]},{"chapter":24,"verse":43,"reference":"Matthew 24:43","text":"Understand this: If a homeowner knew exactly when a burglar was coming, he would keep watch and not permit his house to be broken into.","sentences":[{"id":"mt-24-43-1","chapter":24,"verse":43,"sentence":1,"reference":"Matthew 24:43","text":"Understand this: If a homeowner knew exactly when a burglar was coming, he would keep watch and not permit his house to be broken into."}]},{"chapter":24,"verse":44,"reference":"Matthew 24:44","text":"You also must be ready all the time, for the Son of Man will come when least expected.","sentences":[{"id":"mt-24-44-1","chapter":24,"verse":44,"sentence":1,"reference":"Matthew 24:44","text":"You also must be ready all the time, for the Son of Man will come when least expected."}]},{"chapter":24,"verse":45,"reference":"Matthew 24:45","text":"“A faithful, sensible servant is one to whom the master can give the responsibility of managing his other household servants and feeding them.","sentences":[{"id":"mt-24-45-1","chapter":24,"verse":45,"sentence":1,"reference":"Matthew 24:45","text":"“A faithful, sensible servant is one to whom the master can give the responsibility of managing his other household servants and feeding them."}]},{"chapter":24,"verse":46,"reference":"Matthew 24:46","text":"If the master returns and finds that the servant has done a good job, there will be a reward.","sentences":[{"id":"mt-24-46-1","chapter":24,"verse":46,"sentence":1,"reference":"Matthew 24:46","text":"If the master returns and finds that the servant has done a good job, there will be a reward."}]},{"chapter":24,"verse":47,"reference":"Matthew 24:47","text":"I tell you the truth, the master will put that servant in charge of all he owns.","sentences":[{"id":"mt-24-47-1","chapter":24,"verse":47,"sentence":1,"reference":"Matthew 24:47","text":"I tell you the truth, the master will put that servant in charge of all he owns."}]},{"chapter":24,"verse":48,"reference":"Matthew 24:48","text":"But what if the servant is evil and thinks, ‘My master won’t be back for a while,’","sentences":[{"id":"mt-24-48-1","chapter":24,"verse":48,"sentence":1,"reference":"Matthew 24:48","text":"But what if the servant is evil and thinks, ‘My master won’t be back for a while,’"}]},{"chapter":24,"verse":49,"reference":"Matthew 24:49","text":"and he begins beating the other servants, partying, and getting drunk?","sentences":[{"id":"mt-24-49-1","chapter":24,"verse":49,"sentence":1,"reference":"Matthew 24:49","text":"and he begins beating the other servants, partying, and getting drunk?"}]},{"chapter":24,"verse":50,"reference":"Matthew 24:50","text":"The master will return unannounced and unexpected,","sentences":[{"id":"mt-24-50-1","chapter":24,"verse":50,"sentence":1,"reference":"Matthew 24:50","text":"The master will return unannounced and unexpected,"}]},{"chapter":24,"verse":51,"reference":"Matthew 24:51","text":"and he will cut the servant to pieces and assign him a place with the hypocrites. In that place there will be weeping and gnashing of teeth.","sentences":[{"id":"mt-24-51-1","chapter":24,"verse":51,"sentence":1,"reference":"Matthew 24:51","text":"and he will cut the servant to pieces and assign him a place with the hypocrites."},{"id":"mt-24-51-2","chapter":24,"verse":51,"sentence":2,"reference":"Matthew 24:51","text":"In that place there will be weeping and gnashing of teeth."}]}]},{"chapter":25,"verses":[{"chapter":25,"verse":1,"reference":"Matthew 25:1","text":"“Then the Kingdom of Heaven will be like ten bridesmaids who took their lamps and went to meet the bridegroom.","sentences":[{"id":"mt-25-1-1","chapter":25,"verse":1,"sentence":1,"reference":"Matthew 25:1","text":"“Then the Kingdom of Heaven will be like ten bridesmaids who took their lamps and went to meet the bridegroom."}]},{"chapter":25,"verse":2,"reference":"Matthew 25:2","text":"Five of them were foolish, and five were wise.","sentences":[{"id":"mt-25-2-1","chapter":25,"verse":2,"sentence":1,"reference":"Matthew 25:2","text":"Five of them were foolish, and five were wise."}]},{"chapter":25,"verse":3,"reference":"Matthew 25:3","text":"The five who were foolish didn’t take enough olive oil for their lamps,","sentences":[{"id":"mt-25-3-1","chapter":25,"verse":3,"sentence":1,"reference":"Matthew 25:3","text":"The five who were foolish didn’t take enough olive oil for their lamps,"}]},{"chapter":25,"verse":4,"reference":"Matthew 25:4","text":"but the other five were wise enough to take along extra oil.","sentences":[{"id":"mt-25-4-1","chapter":25,"verse":4,"sentence":1,"reference":"Matthew 25:4","text":"but the other five were wise enough to take along extra oil."}]},{"chapter":25,"verse":5,"reference":"Matthew 25:5","text":"When the bridegroom was delayed, they all became drowsy and fell asleep.","sentences":[{"id":"mt-25-5-1","chapter":25,"verse":5,"sentence":1,"reference":"Matthew 25:5","text":"When the bridegroom was delayed, they all became drowsy and fell asleep."}]},{"chapter":25,"verse":6,"reference":"Matthew 25:6","text":"“At midnight they were roused by the shout, ‘Look, the bridegroom is coming! Come out and meet him!’","sentences":[{"id":"mt-25-6-1","chapter":25,"verse":6,"sentence":1,"reference":"Matthew 25:6","text":"“At midnight they were roused by the shout, ‘Look, the bridegroom is coming!"},{"id":"mt-25-6-2","chapter":25,"verse":6,"sentence":2,"reference":"Matthew 25:6","text":"Come out and meet him!’"}]},{"chapter":25,"verse":7,"reference":"Matthew 25:7","text":"“All the bridesmaids got up and prepared their lamps.","sentences":[{"id":"mt-25-7-1","chapter":25,"verse":7,"sentence":1,"reference":"Matthew 25:7","text":"“All the bridesmaids got up and prepared their lamps."}]},{"chapter":25,"verse":8,"reference":"Matthew 25:8","text":"Then the five foolish ones asked the others, ‘Please give us some of your oil because our lamps are going out.’","sentences":[{"id":"mt-25-8-1","chapter":25,"verse":8,"sentence":1,"reference":"Matthew 25:8","text":"Then the five foolish ones asked the others, ‘Please give us some of your oil because our lamps are going out.’"}]},{"chapter":25,"verse":9,"reference":"Matthew 25:9","text":"“But the others replied, ‘We don’t have enough for all of us. Go to a shop and buy some for yourselves.’","sentences":[{"id":"mt-25-9-1","chapter":25,"verse":9,"sentence":1,"reference":"Matthew 25:9","text":"“But the others replied, ‘We don’t have enough for all of us."},{"id":"mt-25-9-2","chapter":25,"verse":9,"sentence":2,"reference":"Matthew 25:9","text":"Go to a shop and buy some for yourselves.’"}]},{"chapter":25,"verse":10,"reference":"Matthew 25:10","text":"“But while they were gone to buy oil, the bridegroom came. Then those who were ready went in with him to the marriage feast, and the door was locked.","sentences":[{"id":"mt-25-10-1","chapter":25,"verse":10,"sentence":1,"reference":"Matthew 25:10","text":"“But while they were gone to buy oil, the bridegroom came."},{"id":"mt-25-10-2","chapter":25,"verse":10,"sentence":2,"reference":"Matthew 25:10","text":"Then those who were ready went in with him to the marriage feast, and the door was locked."}]},{"chapter":25,"verse":11,"reference":"Matthew 25:11","text":"Later, when the other five bridesmaids returned, they stood outside, calling, ‘Lord! Lord! Open the door for us!’","sentences":[{"id":"mt-25-11-1","chapter":25,"verse":11,"sentence":1,"reference":"Matthew 25:11","text":"Later, when the other five bridesmaids returned, they stood outside, calling, ‘Lord!"},{"id":"mt-25-11-2","chapter":25,"verse":11,"sentence":2,"reference":"Matthew 25:11","text":"Lord!"},{"id":"mt-25-11-3","chapter":25,"verse":11,"sentence":3,"reference":"Matthew 25:11","text":"Open the door for us!’"}]},{"chapter":25,"verse":12,"reference":"Matthew 25:12","text":"“But he called back, ‘Believe me, I don’t know you!’","sentences":[{"id":"mt-25-12-1","chapter":25,"verse":12,"sentence":1,"reference":"Matthew 25:12","text":"“But he called back, ‘Believe me, I don’t know you!’"}]},{"chapter":25,"verse":13,"reference":"Matthew 25:13","text":"“So you, too, must keep watch! For you do not know the day or hour of my return.","sentences":[{"id":"mt-25-13-1","chapter":25,"verse":13,"sentence":1,"reference":"Matthew 25:13","text":"“So you, too, must keep watch!"},{"id":"mt-25-13-2","chapter":25,"verse":13,"sentence":2,"reference":"Matthew 25:13","text":"For you do not know the day or hour of my return."}]},{"chapter":25,"verse":14,"reference":"Matthew 25:14","text":"“Again, the Kingdom of Heaven can be illustrated by the story of a man going on a long trip. He called together his servants and entrusted his money to them while he was gone.","sentences":[{"id":"mt-25-14-1","chapter":25,"verse":14,"sentence":1,"reference":"Matthew 25:14","text":"“Again, the Kingdom of Heaven can be illustrated by the story of a man going on a long trip."},{"id":"mt-25-14-2","chapter":25,"verse":14,"sentence":2,"reference":"Matthew 25:14","text":"He called together his servants and entrusted his money to them while he was gone."}]},{"chapter":25,"verse":15,"reference":"Matthew 25:15","text":"He gave five bags of silver to one, two bags of silver to another, and one bag of silver to the last—dividing it in proportion to their abilities. He then left on his trip.","sentences":[{"id":"mt-25-15-1","chapter":25,"verse":15,"sentence":1,"reference":"Matthew 25:15","text":"He gave five bags of silver to one, two bags of silver to another, and one bag of silver to the last—dividing it in proportion to their abilities."},{"id":"mt-25-15-2","chapter":25,"verse":15,"sentence":2,"reference":"Matthew 25:15","text":"He then left on his trip."}]},{"chapter":25,"verse":16,"reference":"Matthew 25:16","text":"“The servant who received the five bags of silver began to invest the money and earned five more.","sentences":[{"id":"mt-25-16-1","chapter":25,"verse":16,"sentence":1,"reference":"Matthew 25:16","text":"“The servant who received the five bags of silver began to invest the money and earned five more."}]},{"chapter":25,"verse":17,"reference":"Matthew 25:17","text":"The servant with two bags of silver also went to work and earned two more.","sentences":[{"id":"mt-25-17-1","chapter":25,"verse":17,"sentence":1,"reference":"Matthew 25:17","text":"The servant with two bags of silver also went to work and earned two more."}]},{"chapter":25,"verse":18,"reference":"Matthew 25:18","text":"But the servant who received the one bag of silver dug a hole in the ground and hid the master’s money.","sentences":[{"id":"mt-25-18-1","chapter":25,"verse":18,"sentence":1,"reference":"Matthew 25:18","text":"But the servant who received the one bag of silver dug a hole in the ground and hid the master’s money."}]},{"chapter":25,"verse":19,"reference":"Matthew 25:19","text":"“After a long time their master returned from his trip and called them to give an account of how they had used his money.","sentences":[{"id":"mt-25-19-1","chapter":25,"verse":19,"sentence":1,"reference":"Matthew 25:19","text":"“After a long time their master returned from his trip and called them to give an account of how they had used his money."}]},{"chapter":25,"verse":20,"reference":"Matthew 25:20","text":"The servant to whom he had entrusted the five bags of silver came forward with five more and said, ‘Master, you gave me five bags of silver to invest, and I have earned five more.’","sentences":[{"id":"mt-25-20-1","chapter":25,"verse":20,"sentence":1,"reference":"Matthew 25:20","text":"The servant to whom he had entrusted the five bags of silver came forward with five more and said, ‘Master, you gave me five bags of silver to invest, and I have earned five more.’"}]},{"chapter":25,"verse":21,"reference":"Matthew 25:21","text":"“The master was full of praise. ‘Well done, my good and faithful servant. You have been faithful in handling this small amount, so now I will give you many more responsibilities. Let’s celebrate together! ’","sentences":[{"id":"mt-25-21-1","chapter":25,"verse":21,"sentence":1,"reference":"Matthew 25:21","text":"“The master was full of praise."},{"id":"mt-25-21-2","chapter":25,"verse":21,"sentence":2,"reference":"Matthew 25:21","text":"‘Well done, my good and faithful servant."},{"id":"mt-25-21-3","chapter":25,"verse":21,"sentence":3,"reference":"Matthew 25:21","text":"You have been faithful in handling this small amount, so now I will give you many more responsibilities."},{"id":"mt-25-21-4","chapter":25,"verse":21,"sentence":4,"reference":"Matthew 25:21","text":"Let’s celebrate together!"},{"id":"mt-25-21-5","chapter":25,"verse":21,"sentence":5,"reference":"Matthew 25:21","text":"’"}]},{"chapter":25,"verse":22,"reference":"Matthew 25:22","text":"“The servant who had received the two bags of silver came forward and said, ‘Master, you gave me two bags of silver to invest, and I have earned two more.’","sentences":[{"id":"mt-25-22-1","chapter":25,"verse":22,"sentence":1,"reference":"Matthew 25:22","text":"“The servant who had received the two bags of silver came forward and said, ‘Master, you gave me two bags of silver to invest, and I have earned two more.’"}]},{"chapter":25,"verse":23,"reference":"Matthew 25:23","text":"“The master said, ‘Well done, my good and faithful servant. You have been faithful in handling this small amount, so now I will give you many more responsibilities. Let’s celebrate together!’","sentences":[{"id":"mt-25-23-1","chapter":25,"verse":23,"sentence":1,"reference":"Matthew 25:23","text":"“The master said, ‘Well done, my good and faithful servant."},{"id":"mt-25-23-2","chapter":25,"verse":23,"sentence":2,"reference":"Matthew 25:23","text":"You have been faithful in handling this small amount, so now I will give you many more responsibilities."},{"id":"mt-25-23-3","chapter":25,"verse":23,"sentence":3,"reference":"Matthew 25:23","text":"Let’s celebrate together!’"}]},{"chapter":25,"verse":24,"reference":"Matthew 25:24","text":"“Then the servant with the one bag of silver came and said, ‘Master, I knew you were a harsh man, harvesting crops you didn’t plant and gathering crops you didn’t cultivate.","sentences":[{"id":"mt-25-24-1","chapter":25,"verse":24,"sentence":1,"reference":"Matthew 25:24","text":"“Then the servant with the one bag of silver came and said, ‘Master, I knew you were a harsh man, harvesting crops you didn’t plant and gathering crops you didn’t cultivate."}]},{"chapter":25,"verse":25,"reference":"Matthew 25:25","text":"I was afraid I would lose your money, so I hid it in the earth. Look, here is your money back.’","sentences":[{"id":"mt-25-25-1","chapter":25,"verse":25,"sentence":1,"reference":"Matthew 25:25","text":"I was afraid I would lose your money, so I hid it in the earth."},{"id":"mt-25-25-2","chapter":25,"verse":25,"sentence":2,"reference":"Matthew 25:25","text":"Look, here is your money back.’"}]},{"chapter":25,"verse":26,"reference":"Matthew 25:26","text":"“But the master replied, ‘You wicked and lazy servant! If you knew I harvested crops I didn’t plant and gathered crops I didn’t cultivate,","sentences":[{"id":"mt-25-26-1","chapter":25,"verse":26,"sentence":1,"reference":"Matthew 25:26","text":"“But the master replied, ‘You wicked and lazy servant!"},{"id":"mt-25-26-2","chapter":25,"verse":26,"sentence":2,"reference":"Matthew 25:26","text":"If you knew I harvested crops I didn’t plant and gathered crops I didn’t cultivate,"}]},{"chapter":25,"verse":27,"reference":"Matthew 25:27","text":"why didn’t you deposit my money in the bank? At least I could have gotten some interest on it.’","sentences":[{"id":"mt-25-27-1","chapter":25,"verse":27,"sentence":1,"reference":"Matthew 25:27","text":"why didn’t you deposit my money in the bank?"},{"id":"mt-25-27-2","chapter":25,"verse":27,"sentence":2,"reference":"Matthew 25:27","text":"At least I could have gotten some interest on it.’"}]},{"chapter":25,"verse":28,"reference":"Matthew 25:28","text":"“Then he ordered, ‘Take the money from this servant, and give it to the one with the ten bags of silver.","sentences":[{"id":"mt-25-28-1","chapter":25,"verse":28,"sentence":1,"reference":"Matthew 25:28","text":"“Then he ordered, ‘Take the money from this servant, and give it to the one with the ten bags of silver."}]},{"chapter":25,"verse":29,"reference":"Matthew 25:29","text":"To those who use well what they are given, even more will be given, and they will have an abundance. But from those who do nothing, even what little they have will be taken away.","sentences":[{"id":"mt-25-29-1","chapter":25,"verse":29,"sentence":1,"reference":"Matthew 25:29","text":"To those who use well what they are given, even more will be given, and they will have an abundance."},{"id":"mt-25-29-2","chapter":25,"verse":29,"sentence":2,"reference":"Matthew 25:29","text":"But from those who do nothing, even what little they have will be taken away."}]},{"chapter":25,"verse":30,"reference":"Matthew 25:30","text":"Now throw this useless servant into outer darkness, where there will be weeping and gnashing of teeth.’","sentences":[{"id":"mt-25-30-1","chapter":25,"verse":30,"sentence":1,"reference":"Matthew 25:30","text":"Now throw this useless servant into outer darkness, where there will be weeping and gnashing of teeth.’"}]},{"chapter":25,"verse":31,"reference":"Matthew 25:31","text":"“But when the Son of Man comes in his glory, and all the angels with him, then he will sit upon his glorious throne.","sentences":[{"id":"mt-25-31-1","chapter":25,"verse":31,"sentence":1,"reference":"Matthew 25:31","text":"“But when the Son of Man comes in his glory, and all the angels with him, then he will sit upon his glorious throne."}]},{"chapter":25,"verse":32,"reference":"Matthew 25:32","text":"All the nations will be gathered in his presence, and he will separate the people as a shepherd separates the sheep from the goats.","sentences":[{"id":"mt-25-32-1","chapter":25,"verse":32,"sentence":1,"reference":"Matthew 25:32","text":"All the nations will be gathered in his presence, and he will separate the people as a shepherd separates the sheep from the goats."}]},{"chapter":25,"verse":33,"reference":"Matthew 25:33","text":"He will place the sheep at his right hand and the goats at his left.","sentences":[{"id":"mt-25-33-1","chapter":25,"verse":33,"sentence":1,"reference":"Matthew 25:33","text":"He will place the sheep at his right hand and the goats at his left."}]},{"chapter":25,"verse":34,"reference":"Matthew 25:34","text":"“Then the King will say to those on his right, ‘Come, you who are blessed by my Father, inherit the Kingdom prepared for you from the creation of the world.","sentences":[{"id":"mt-25-34-1","chapter":25,"verse":34,"sentence":1,"reference":"Matthew 25:34","text":"“Then the King will say to those on his right, ‘Come, you who are blessed by my Father, inherit the Kingdom prepared for you from the creation of the world."}]},{"chapter":25,"verse":35,"reference":"Matthew 25:35","text":"For I was hungry, and you fed me. I was thirsty, and you gave me a drink. I was a stranger, and you invited me into your home.","sentences":[{"id":"mt-25-35-1","chapter":25,"verse":35,"sentence":1,"reference":"Matthew 25:35","text":"For I was hungry, and you fed me."},{"id":"mt-25-35-2","chapter":25,"verse":35,"sentence":2,"reference":"Matthew 25:35","text":"I was thirsty, and you gave me a drink."},{"id":"mt-25-35-3","chapter":25,"verse":35,"sentence":3,"reference":"Matthew 25:35","text":"I was a stranger, and you invited me into your home."}]},{"chapter":25,"verse":36,"reference":"Matthew 25:36","text":"I was naked, and you gave me clothing. I was sick, and you cared for me. I was in prison, and you visited me.’","sentences":[{"id":"mt-25-36-1","chapter":25,"verse":36,"sentence":1,"reference":"Matthew 25:36","text":"I was naked, and you gave me clothing."},{"id":"mt-25-36-2","chapter":25,"verse":36,"sentence":2,"reference":"Matthew 25:36","text":"I was sick, and you cared for me."},{"id":"mt-25-36-3","chapter":25,"verse":36,"sentence":3,"reference":"Matthew 25:36","text":"I was in prison, and you visited me.’"}]},{"chapter":25,"verse":37,"reference":"Matthew 25:37","text":"“Then these righteous ones will reply, ‘Lord, when did we ever see you hungry and feed you? Or thirsty and give you something to drink?","sentences":[{"id":"mt-25-37-1","chapter":25,"verse":37,"sentence":1,"reference":"Matthew 25:37","text":"“Then these righteous ones will reply, ‘Lord, when did we ever see you hungry and feed you?"},{"id":"mt-25-37-2","chapter":25,"verse":37,"sentence":2,"reference":"Matthew 25:37","text":"Or thirsty and give you something to drink?"}]},{"chapter":25,"verse":38,"reference":"Matthew 25:38","text":"Or a stranger and show you hospitality? Or naked and give you clothing?","sentences":[{"id":"mt-25-38-1","chapter":25,"verse":38,"sentence":1,"reference":"Matthew 25:38","text":"Or a stranger and show you hospitality?"},{"id":"mt-25-38-2","chapter":25,"verse":38,"sentence":2,"reference":"Matthew 25:38","text":"Or naked and give you clothing?"}]},{"chapter":25,"verse":39,"reference":"Matthew 25:39","text":"When did we ever see you sick or in prison and visit you?’","sentences":[{"id":"mt-25-39-1","chapter":25,"verse":39,"sentence":1,"reference":"Matthew 25:39","text":"When did we ever see you sick or in prison and visit you?’"}]},{"chapter":25,"verse":40,"reference":"Matthew 25:40","text":"“And the King will say, ‘I tell you the truth, when you did it to one of the least of these my brothers and sisters, you were doing it to me!’","sentences":[{"id":"mt-25-40-1","chapter":25,"verse":40,"sentence":1,"reference":"Matthew 25:40","text":"“And the King will say, ‘I tell you the truth, when you did it to one of the least of these my brothers and sisters, you were doing it to me!’"}]},{"chapter":25,"verse":41,"reference":"Matthew 25:41","text":"“Then the King will turn to those on the left and say, ‘Away with you, you cursed ones, into the eternal fire prepared for the devil and his demons.","sentences":[{"id":"mt-25-41-1","chapter":25,"verse":41,"sentence":1,"reference":"Matthew 25:41","text":"“Then the King will turn to those on the left and say, ‘Away with you, you cursed ones, into the eternal fire prepared for the devil and his demons."}]},{"chapter":25,"verse":42,"reference":"Matthew 25:42","text":"For I was hungry, and you didn’t feed me. I was thirsty, and you didn’t give me a drink.","sentences":[{"id":"mt-25-42-1","chapter":25,"verse":42,"sentence":1,"reference":"Matthew 25:42","text":"For I was hungry, and you didn’t feed me."},{"id":"mt-25-42-2","chapter":25,"verse":42,"sentence":2,"reference":"Matthew 25:42","text":"I was thirsty, and you didn’t give me a drink."}]},{"chapter":25,"verse":43,"reference":"Matthew 25:43","text":"I was a stranger, and you didn’t invite me into your home. I was naked, and you didn’t give me clothing. I was sick and in prison, and you didn’t visit me.’","sentences":[{"id":"mt-25-43-1","chapter":25,"verse":43,"sentence":1,"reference":"Matthew 25:43","text":"I was a stranger, and you didn’t invite me into your home."},{"id":"mt-25-43-2","chapter":25,"verse":43,"sentence":2,"reference":"Matthew 25:43","text":"I was naked, and you didn’t give me clothing."},{"id":"mt-25-43-3","chapter":25,"verse":43,"sentence":3,"reference":"Matthew 25:43","text":"I was sick and in prison, and you didn’t visit me.’"}]},{"chapter":25,"verse":44,"reference":"Matthew 25:44","text":"“Then they will reply, ‘Lord, when did we ever see you hungry or thirsty or a stranger or naked or sick or in prison, and not help you?’","sentences":[{"id":"mt-25-44-1","chapter":25,"verse":44,"sentence":1,"reference":"Matthew 25:44","text":"“Then they will reply, ‘Lord, when did we ever see you hungry or thirsty or a stranger or naked or sick or in prison, and not help you?’"}]},{"chapter":25,"verse":45,"reference":"Matthew 25:45","text":"“And he will answer, ‘I tell you the truth, when you refused to help the least of these my brothers and sisters, you were refusing to help me.’","sentences":[{"id":"mt-25-45-1","chapter":25,"verse":45,"sentence":1,"reference":"Matthew 25:45","text":"“And he will answer, ‘I tell you the truth, when you refused to help the least of these my brothers and sisters, you were refusing to help me.’"}]},{"chapter":25,"verse":46,"reference":"Matthew 25:46","text":"“And they will go away into eternal punishment, but the righteous will go into eternal life.”","sentences":[{"id":"mt-25-46-1","chapter":25,"verse":46,"sentence":1,"reference":"Matthew 25:46","text":"“And they will go away into eternal punishment, but the righteous will go into eternal life.”"}]}]},{"chapter":26,"verses":[{"chapter":26,"verse":1,"reference":"Matthew 26:1","text":"When Jesus had finished saying all these things, he said to his disciples,","sentences":[{"id":"mt-26-1-1","chapter":26,"verse":1,"sentence":1,"reference":"Matthew 26:1","text":"When Jesus had finished saying all these things, he said to his disciples,"}]},{"chapter":26,"verse":2,"reference":"Matthew 26:2","text":"“As you know, Passover begins in two days, and the Son of Man will be handed over to be crucified.”","sentences":[{"id":"mt-26-2-1","chapter":26,"verse":2,"sentence":1,"reference":"Matthew 26:2","text":"“As you know, Passover begins in two days, and the Son of Man will be handed over to be crucified.”"}]},{"chapter":26,"verse":3,"reference":"Matthew 26:3","text":"At that same time the leading priests and elders were meeting at the residence of Caiaphas, the high priest,","sentences":[{"id":"mt-26-3-1","chapter":26,"verse":3,"sentence":1,"reference":"Matthew 26:3","text":"At that same time the leading priests and elders were meeting at the residence of Caiaphas, the high priest,"}]},{"chapter":26,"verse":4,"reference":"Matthew 26:4","text":"plotting how to capture Jesus secretly and kill him.","sentences":[{"id":"mt-26-4-1","chapter":26,"verse":4,"sentence":1,"reference":"Matthew 26:4","text":"plotting how to capture Jesus secretly and kill him."}]},{"chapter":26,"verse":5,"reference":"Matthew 26:5","text":"“But not during the Passover celebration,” they agreed, “or the people may riot.”","sentences":[{"id":"mt-26-5-1","chapter":26,"verse":5,"sentence":1,"reference":"Matthew 26:5","text":"“But not during the Passover celebration,” they agreed, “or the people may riot.”"}]},{"chapter":26,"verse":6,"reference":"Matthew 26:6","text":"Meanwhile, Jesus was in Bethany at the home of Simon, a man who had previously had leprosy.","sentences":[{"id":"mt-26-6-1","chapter":26,"verse":6,"sentence":1,"reference":"Matthew 26:6","text":"Meanwhile, Jesus was in Bethany at the home of Simon, a man who had previously had leprosy."}]},{"chapter":26,"verse":7,"reference":"Matthew 26:7","text":"While he was eating, a woman came in with a beautiful alabaster jar of expensive perfume and poured it over his head.","sentences":[{"id":"mt-26-7-1","chapter":26,"verse":7,"sentence":1,"reference":"Matthew 26:7","text":"While he was eating, a woman came in with a beautiful alabaster jar of expensive perfume and poured it over his head."}]},{"chapter":26,"verse":8,"reference":"Matthew 26:8","text":"The disciples were indignant when they saw this. “What a waste!” they said.","sentences":[{"id":"mt-26-8-1","chapter":26,"verse":8,"sentence":1,"reference":"Matthew 26:8","text":"The disciples were indignant when they saw this."},{"id":"mt-26-8-2","chapter":26,"verse":8,"sentence":2,"reference":"Matthew 26:8","text":"“What a waste!”"},{"id":"mt-26-8-3","chapter":26,"verse":8,"sentence":3,"reference":"Matthew 26:8","text":"they said."}]},{"chapter":26,"verse":9,"reference":"Matthew 26:9","text":"“It could have been sold for a high price and the money given to the poor.”","sentences":[{"id":"mt-26-9-1","chapter":26,"verse":9,"sentence":1,"reference":"Matthew 26:9","text":"“It could have been sold for a high price and the money given to the poor.”"}]},{"chapter":26,"verse":10,"reference":"Matthew 26:10","text":"But Jesus, aware of this, replied, “Why criticize this woman for doing such a good thing to me?","sentences":[{"id":"mt-26-10-1","chapter":26,"verse":10,"sentence":1,"reference":"Matthew 26:10","text":"But Jesus, aware of this, replied, “Why criticize this woman for doing such a good thing to me?"}]},{"chapter":26,"verse":11,"reference":"Matthew 26:11","text":"You will always have the poor among you, but you will not always have me.","sentences":[{"id":"mt-26-11-1","chapter":26,"verse":11,"sentence":1,"reference":"Matthew 26:11","text":"You will always have the poor among you, but you will not always have me."}]},{"chapter":26,"verse":12,"reference":"Matthew 26:12","text":"She has poured this perfume on me to prepare my body for burial.","sentences":[{"id":"mt-26-12-1","chapter":26,"verse":12,"sentence":1,"reference":"Matthew 26:12","text":"She has poured this perfume on me to prepare my body for burial."}]},{"chapter":26,"verse":13,"reference":"Matthew 26:13","text":"I tell you the truth, wherever the Good News is preached throughout the world, this woman’s deed will be remembered and discussed.”","sentences":[{"id":"mt-26-13-1","chapter":26,"verse":13,"sentence":1,"reference":"Matthew 26:13","text":"I tell you the truth, wherever the Good News is preached throughout the world, this woman’s deed will be remembered and discussed.”"}]},{"chapter":26,"verse":14,"reference":"Matthew 26:14","text":"Then Judas Iscariot, one of the twelve disciples, went to the leading priests","sentences":[{"id":"mt-26-14-1","chapter":26,"verse":14,"sentence":1,"reference":"Matthew 26:14","text":"Then Judas Iscariot, one of the twelve disciples, went to the leading priests"}]},{"chapter":26,"verse":15,"reference":"Matthew 26:15","text":"and asked, “How much will you pay me to betray Jesus to you?” And they gave him thirty pieces of silver.","sentences":[{"id":"mt-26-15-1","chapter":26,"verse":15,"sentence":1,"reference":"Matthew 26:15","text":"and asked, “How much will you pay me to betray Jesus to you?”"},{"id":"mt-26-15-2","chapter":26,"verse":15,"sentence":2,"reference":"Matthew 26:15","text":"And they gave him thirty pieces of silver."}]},{"chapter":26,"verse":16,"reference":"Matthew 26:16","text":"From that time on, Judas began looking for an opportunity to betray Jesus.","sentences":[{"id":"mt-26-16-1","chapter":26,"verse":16,"sentence":1,"reference":"Matthew 26:16","text":"From that time on, Judas began looking for an opportunity to betray Jesus."}]},{"chapter":26,"verse":17,"reference":"Matthew 26:17","text":"On the first day of the Festival of Unleavened Bread, the disciples came to Jesus and asked, “Where do you want us to prepare the Passover meal for you?”","sentences":[{"id":"mt-26-17-1","chapter":26,"verse":17,"sentence":1,"reference":"Matthew 26:17","text":"On the first day of the Festival of Unleavened Bread, the disciples came to Jesus and asked, “Where do you want us to prepare the Passover meal for you?”"}]},{"chapter":26,"verse":18,"reference":"Matthew 26:18","text":"“As you go into the city,” he told them, “you will see a certain man. Tell him, ‘The Teacher says: My time has come, and I will eat the Passover meal with my disciples at your house.’”","sentences":[{"id":"mt-26-18-1","chapter":26,"verse":18,"sentence":1,"reference":"Matthew 26:18","text":"“As you go into the city,” he told them, “you will see a certain man."},{"id":"mt-26-18-2","chapter":26,"verse":18,"sentence":2,"reference":"Matthew 26:18","text":"Tell him, ‘The Teacher says: My time has come, and I will eat the Passover meal with my disciples at your house.’”"}]},{"chapter":26,"verse":19,"reference":"Matthew 26:19","text":"So the disciples did as Jesus told them and prepared the Passover meal there.","sentences":[{"id":"mt-26-19-1","chapter":26,"verse":19,"sentence":1,"reference":"Matthew 26:19","text":"So the disciples did as Jesus told them and prepared the Passover meal there."}]},{"chapter":26,"verse":20,"reference":"Matthew 26:20","text":"When it was evening, Jesus sat down at the table with the Twelve.","sentences":[{"id":"mt-26-20-1","chapter":26,"verse":20,"sentence":1,"reference":"Matthew 26:20","text":"When it was evening, Jesus sat down at the table with the Twelve."}]},{"chapter":26,"verse":21,"reference":"Matthew 26:21","text":"While they were eating, he said, “I tell you the truth, one of you will betray me.”","sentences":[{"id":"mt-26-21-1","chapter":26,"verse":21,"sentence":1,"reference":"Matthew 26:21","text":"While they were eating, he said, “I tell you the truth, one of you will betray me.”"}]},{"chapter":26,"verse":22,"reference":"Matthew 26:22","text":"Greatly distressed, each one asked in turn, “Am I the one, Lord?”","sentences":[{"id":"mt-26-22-1","chapter":26,"verse":22,"sentence":1,"reference":"Matthew 26:22","text":"Greatly distressed, each one asked in turn, “Am I the one, Lord?”"}]},{"chapter":26,"verse":23,"reference":"Matthew 26:23","text":"He replied, “One of you who has just eaten from this bowl with me will betray me.","sentences":[{"id":"mt-26-23-1","chapter":26,"verse":23,"sentence":1,"reference":"Matthew 26:23","text":"He replied, “One of you who has just eaten from this bowl with me will betray me."}]},{"chapter":26,"verse":24,"reference":"Matthew 26:24","text":"For the Son of Man must die, as the Scriptures declared long ago. But how terrible it will be for the one who betrays him. It would be far better for that man if he had never been born!”","sentences":[{"id":"mt-26-24-1","chapter":26,"verse":24,"sentence":1,"reference":"Matthew 26:24","text":"For the Son of Man must die, as the Scriptures declared long ago."},{"id":"mt-26-24-2","chapter":26,"verse":24,"sentence":2,"reference":"Matthew 26:24","text":"But how terrible it will be for the one who betrays him."},{"id":"mt-26-24-3","chapter":26,"verse":24,"sentence":3,"reference":"Matthew 26:24","text":"It would be far better for that man if he had never been born!”"}]},{"chapter":26,"verse":25,"reference":"Matthew 26:25","text":"Judas, the one who would betray him, also asked, “Rabbi, am I the one?” And Jesus told him, “You have said it.”","sentences":[{"id":"mt-26-25-1","chapter":26,"verse":25,"sentence":1,"reference":"Matthew 26:25","text":"Judas, the one who would betray him, also asked, “Rabbi, am I the one?”"},{"id":"mt-26-25-2","chapter":26,"verse":25,"sentence":2,"reference":"Matthew 26:25","text":"And Jesus told him, “You have said it.”"}]},{"chapter":26,"verse":26,"reference":"Matthew 26:26","text":"As they were eating, Jesus took some bread and blessed it. Then he broke it in pieces and gave it to the disciples, saying, “Take this and eat it, for this is my body.”","sentences":[{"id":"mt-26-26-1","chapter":26,"verse":26,"sentence":1,"reference":"Matthew 26:26","text":"As they were eating, Jesus took some bread and blessed it."},{"id":"mt-26-26-2","chapter":26,"verse":26,"sentence":2,"reference":"Matthew 26:26","text":"Then he broke it in pieces and gave it to the disciples, saying, “Take this and eat it, for this is my body.”"}]},{"chapter":26,"verse":27,"reference":"Matthew 26:27","text":"And he took a cup of wine and gave thanks to God for it. He gave it to them and said, “Each of you drink from it,","sentences":[{"id":"mt-26-27-1","chapter":26,"verse":27,"sentence":1,"reference":"Matthew 26:27","text":"And he took a cup of wine and gave thanks to God for it."},{"id":"mt-26-27-2","chapter":26,"verse":27,"sentence":2,"reference":"Matthew 26:27","text":"He gave it to them and said, “Each of you drink from it,"}]},{"chapter":26,"verse":28,"reference":"Matthew 26:28","text":"for this is my blood, which confirms the covenant between God and his people. It is poured out as a sacrifice to forgive the sins of many.","sentences":[{"id":"mt-26-28-1","chapter":26,"verse":28,"sentence":1,"reference":"Matthew 26:28","text":"for this is my blood, which confirms the covenant between God and his people."},{"id":"mt-26-28-2","chapter":26,"verse":28,"sentence":2,"reference":"Matthew 26:28","text":"It is poured out as a sacrifice to forgive the sins of many."}]},{"chapter":26,"verse":29,"reference":"Matthew 26:29","text":"Mark my words—I will not drink wine again until the day I drink it new with you in my Father’s Kingdom.”","sentences":[{"id":"mt-26-29-1","chapter":26,"verse":29,"sentence":1,"reference":"Matthew 26:29","text":"Mark my words—I will not drink wine again until the day I drink it new with you in my Father’s Kingdom.”"}]},{"chapter":26,"verse":30,"reference":"Matthew 26:30","text":"Then they sang a hymn and went out to the Mount of Olives.","sentences":[{"id":"mt-26-30-1","chapter":26,"verse":30,"sentence":1,"reference":"Matthew 26:30","text":"Then they sang a hymn and went out to the Mount of Olives."}]},{"chapter":26,"verse":31,"reference":"Matthew 26:31","text":"On the way, Jesus told them, “Tonight all of you will desert me. For the Scriptures say, ‘God will strike the Shepherd, and the sheep of the flock will be scattered.’","sentences":[{"id":"mt-26-31-1","chapter":26,"verse":31,"sentence":1,"reference":"Matthew 26:31","text":"On the way, Jesus told them, “Tonight all of you will desert me."},{"id":"mt-26-31-2","chapter":26,"verse":31,"sentence":2,"reference":"Matthew 26:31","text":"For the Scriptures say, ‘God will strike the Shepherd, and the sheep of the flock will be scattered.’"}]},{"chapter":26,"verse":32,"reference":"Matthew 26:32","text":"But after I have been raised from the dead, I will go ahead of you to Galilee and meet you there.”","sentences":[{"id":"mt-26-32-1","chapter":26,"verse":32,"sentence":1,"reference":"Matthew 26:32","text":"But after I have been raised from the dead, I will go ahead of you to Galilee and meet you there.”"}]},{"chapter":26,"verse":33,"reference":"Matthew 26:33","text":"Peter declared, “Even if everyone else deserts you, I will never desert you.”","sentences":[{"id":"mt-26-33-1","chapter":26,"verse":33,"sentence":1,"reference":"Matthew 26:33","text":"Peter declared, “Even if everyone else deserts you, I will never desert you.”"}]},{"chapter":26,"verse":34,"reference":"Matthew 26:34","text":"Jesus replied, “I tell you the truth, Peter—this very night, before the rooster crows, you will deny three times that you even know me.”","sentences":[{"id":"mt-26-34-1","chapter":26,"verse":34,"sentence":1,"reference":"Matthew 26:34","text":"Jesus replied, “I tell you the truth, Peter—this very night, before the rooster crows, you will deny three times that you even know me.”"}]},{"chapter":26,"verse":35,"reference":"Matthew 26:35","text":"“No!” Peter insisted. “Even if I have to die with you, I will never deny you!” And all the other disciples vowed the same.","sentences":[{"id":"mt-26-35-1","chapter":26,"verse":35,"sentence":1,"reference":"Matthew 26:35","text":"“No!”"},{"id":"mt-26-35-2","chapter":26,"verse":35,"sentence":2,"reference":"Matthew 26:35","text":"Peter insisted."},{"id":"mt-26-35-3","chapter":26,"verse":35,"sentence":3,"reference":"Matthew 26:35","text":"“Even if I have to die with you, I will never deny you!”"},{"id":"mt-26-35-4","chapter":26,"verse":35,"sentence":4,"reference":"Matthew 26:35","text":"And all the other disciples vowed the same."}]},{"chapter":26,"verse":36,"reference":"Matthew 26:36","text":"Then Jesus went with them to the olive grove called Gethsemane, and he said, “Sit here while I go over there to pray.”","sentences":[{"id":"mt-26-36-1","chapter":26,"verse":36,"sentence":1,"reference":"Matthew 26:36","text":"Then Jesus went with them to the olive grove called Gethsemane, and he said, “Sit here while I go over there to pray.”"}]},{"chapter":26,"verse":37,"reference":"Matthew 26:37","text":"He took Peter and Zebedee’s two sons, James and John, and he became anguished and distressed.","sentences":[{"id":"mt-26-37-1","chapter":26,"verse":37,"sentence":1,"reference":"Matthew 26:37","text":"He took Peter and Zebedee’s two sons, James and John, and he became anguished and distressed."}]},{"chapter":26,"verse":38,"reference":"Matthew 26:38","text":"He told them, “My soul is crushed with grief to the point of death. Stay here and keep watch with me.”","sentences":[{"id":"mt-26-38-1","chapter":26,"verse":38,"sentence":1,"reference":"Matthew 26:38","text":"He told them, “My soul is crushed with grief to the point of death."},{"id":"mt-26-38-2","chapter":26,"verse":38,"sentence":2,"reference":"Matthew 26:38","text":"Stay here and keep watch with me.”"}]},{"chapter":26,"verse":39,"reference":"Matthew 26:39","text":"He went on a little farther and bowed with his face to the ground, praying, “My Father! If it is possible, let this cup of suffering be taken away from me. Yet I want your will to be done, not mine.”","sentences":[{"id":"mt-26-39-1","chapter":26,"verse":39,"sentence":1,"reference":"Matthew 26:39","text":"He went on a little farther and bowed with his face to the ground, praying, “My Father!"},{"id":"mt-26-39-2","chapter":26,"verse":39,"sentence":2,"reference":"Matthew 26:39","text":"If it is possible, let this cup of suffering be taken away from me."},{"id":"mt-26-39-3","chapter":26,"verse":39,"sentence":3,"reference":"Matthew 26:39","text":"Yet I want your will to be done, not mine.”"}]},{"chapter":26,"verse":40,"reference":"Matthew 26:40","text":"Then he returned to the disciples and found them asleep. He said to Peter, “Couldn’t you watch with me even one hour?","sentences":[{"id":"mt-26-40-1","chapter":26,"verse":40,"sentence":1,"reference":"Matthew 26:40","text":"Then he returned to the disciples and found them asleep."},{"id":"mt-26-40-2","chapter":26,"verse":40,"sentence":2,"reference":"Matthew 26:40","text":"He said to Peter, “Couldn’t you watch with me even one hour?"}]},{"chapter":26,"verse":41,"reference":"Matthew 26:41","text":"Keep watch and pray, so that you will not give in to temptation. For the spirit is willing, but the body is weak!”","sentences":[{"id":"mt-26-41-1","chapter":26,"verse":41,"sentence":1,"reference":"Matthew 26:41","text":"Keep watch and pray, so that you will not give in to temptation."},{"id":"mt-26-41-2","chapter":26,"verse":41,"sentence":2,"reference":"Matthew 26:41","text":"For the spirit is willing, but the body is weak!”"}]},{"chapter":26,"verse":42,"reference":"Matthew 26:42","text":"Then Jesus left them a second time and prayed, “My Father! If this cup cannot be taken away unless I drink it, your will be done.”","sentences":[{"id":"mt-26-42-1","chapter":26,"verse":42,"sentence":1,"reference":"Matthew 26:42","text":"Then Jesus left them a second time and prayed, “My Father!"},{"id":"mt-26-42-2","chapter":26,"verse":42,"sentence":2,"reference":"Matthew 26:42","text":"If this cup cannot be taken away unless I drink it, your will be done.”"}]},{"chapter":26,"verse":43,"reference":"Matthew 26:43","text":"When he returned to them again, he found them sleeping, for they couldn’t keep their eyes open.","sentences":[{"id":"mt-26-43-1","chapter":26,"verse":43,"sentence":1,"reference":"Matthew 26:43","text":"When he returned to them again, he found them sleeping, for they couldn’t keep their eyes open."}]},{"chapter":26,"verse":44,"reference":"Matthew 26:44","text":"So he went to pray a third time, saying the same things again.","sentences":[{"id":"mt-26-44-1","chapter":26,"verse":44,"sentence":1,"reference":"Matthew 26:44","text":"So he went to pray a third time, saying the same things again."}]},{"chapter":26,"verse":45,"reference":"Matthew 26:45","text":"Then he came to the disciples and said, “Go ahead and sleep. Have your rest. But look—the time has come. The Son of Man is betrayed into the hands of sinners.","sentences":[{"id":"mt-26-45-1","chapter":26,"verse":45,"sentence":1,"reference":"Matthew 26:45","text":"Then he came to the disciples and said, “Go ahead and sleep."},{"id":"mt-26-45-2","chapter":26,"verse":45,"sentence":2,"reference":"Matthew 26:45","text":"Have your rest."},{"id":"mt-26-45-3","chapter":26,"verse":45,"sentence":3,"reference":"Matthew 26:45","text":"But look—the time has come."},{"id":"mt-26-45-4","chapter":26,"verse":45,"sentence":4,"reference":"Matthew 26:45","text":"The Son of Man is betrayed into the hands of sinners."}]},{"chapter":26,"verse":46,"reference":"Matthew 26:46","text":"Up, let’s be going. Look, my betrayer is here!”","sentences":[{"id":"mt-26-46-1","chapter":26,"verse":46,"sentence":1,"reference":"Matthew 26:46","text":"Up, let’s be going."},{"id":"mt-26-46-2","chapter":26,"verse":46,"sentence":2,"reference":"Matthew 26:46","text":"Look, my betrayer is here!”"}]},{"chapter":26,"verse":47,"reference":"Matthew 26:47","text":"And even as Jesus said this, Judas, one of the twelve disciples, arrived with a crowd of men armed with swords and clubs. They had been sent by the leading priests and elders of the people.","sentences":[{"id":"mt-26-47-1","chapter":26,"verse":47,"sentence":1,"reference":"Matthew 26:47","text":"And even as Jesus said this, Judas, one of the twelve disciples, arrived with a crowd of men armed with swords and clubs."},{"id":"mt-26-47-2","chapter":26,"verse":47,"sentence":2,"reference":"Matthew 26:47","text":"They had been sent by the leading priests and elders of the people."}]},{"chapter":26,"verse":48,"reference":"Matthew 26:48","text":"The traitor, Judas, had given them a prearranged signal: “You will know which one to arrest when I greet him with a kiss.”","sentences":[{"id":"mt-26-48-1","chapter":26,"verse":48,"sentence":1,"reference":"Matthew 26:48","text":"The traitor, Judas, had given them a prearranged signal: “You will know which one to arrest when I greet him with a kiss.”"}]},{"chapter":26,"verse":49,"reference":"Matthew 26:49","text":"So Judas came straight to Jesus. “Greetings, Rabbi!” he exclaimed and gave him the kiss.","sentences":[{"id":"mt-26-49-1","chapter":26,"verse":49,"sentence":1,"reference":"Matthew 26:49","text":"So Judas came straight to Jesus."},{"id":"mt-26-49-2","chapter":26,"verse":49,"sentence":2,"reference":"Matthew 26:49","text":"“Greetings, Rabbi!”"},{"id":"mt-26-49-3","chapter":26,"verse":49,"sentence":3,"reference":"Matthew 26:49","text":"he exclaimed and gave him the kiss."}]},{"chapter":26,"verse":50,"reference":"Matthew 26:50","text":"Jesus said, “My friend, go ahead and do what you have come for.” Then the others grabbed Jesus and arrested him.","sentences":[{"id":"mt-26-50-1","chapter":26,"verse":50,"sentence":1,"reference":"Matthew 26:50","text":"Jesus said, “My friend, go ahead and do what you have come for.”"},{"id":"mt-26-50-2","chapter":26,"verse":50,"sentence":2,"reference":"Matthew 26:50","text":"Then the others grabbed Jesus and arrested him."}]},{"chapter":26,"verse":51,"reference":"Matthew 26:51","text":"But one of the men with Jesus pulled out his sword and struck the high priest’s slave, slashing off his ear.","sentences":[{"id":"mt-26-51-1","chapter":26,"verse":51,"sentence":1,"reference":"Matthew 26:51","text":"But one of the men with Jesus pulled out his sword and struck the high priest’s slave, slashing off his ear."}]},{"chapter":26,"verse":52,"reference":"Matthew 26:52","text":"“Put away your sword,” Jesus told him. “Those who use the sword will die by the sword.","sentences":[{"id":"mt-26-52-1","chapter":26,"verse":52,"sentence":1,"reference":"Matthew 26:52","text":"“Put away your sword,” Jesus told him."},{"id":"mt-26-52-2","chapter":26,"verse":52,"sentence":2,"reference":"Matthew 26:52","text":"“Those who use the sword will die by the sword."}]},{"chapter":26,"verse":53,"reference":"Matthew 26:53","text":"Don’t you realize that I could ask my Father for thousands of angels to protect us, and he would send them instantly?","sentences":[{"id":"mt-26-53-1","chapter":26,"verse":53,"sentence":1,"reference":"Matthew 26:53","text":"Don’t you realize that I could ask my Father for thousands of angels to protect us, and he would send them instantly?"}]},{"chapter":26,"verse":54,"reference":"Matthew 26:54","text":"But if I did, how would the Scriptures be fulfilled that describe what must happen now?”","sentences":[{"id":"mt-26-54-1","chapter":26,"verse":54,"sentence":1,"reference":"Matthew 26:54","text":"But if I did, how would the Scriptures be fulfilled that describe what must happen now?”"}]},{"chapter":26,"verse":55,"reference":"Matthew 26:55","text":"Then Jesus said to the crowd, “Am I some dangerous revolutionary, that you come with swords and clubs to arrest me? Why didn’t you arrest me in the Temple? I was there teaching every day.","sentences":[{"id":"mt-26-55-1","chapter":26,"verse":55,"sentence":1,"reference":"Matthew 26:55","text":"Then Jesus said to the crowd, “Am I some dangerous revolutionary, that you come with swords and clubs to arrest me?"},{"id":"mt-26-55-2","chapter":26,"verse":55,"sentence":2,"reference":"Matthew 26:55","text":"Why didn’t you arrest me in the Temple?"},{"id":"mt-26-55-3","chapter":26,"verse":55,"sentence":3,"reference":"Matthew 26:55","text":"I was there teaching every day."}]},{"chapter":26,"verse":56,"reference":"Matthew 26:56","text":"But this is all happening to fulfill the words of the prophets as recorded in the Scriptures.” At that point, all the disciples deserted him and fled.","sentences":[{"id":"mt-26-56-1","chapter":26,"verse":56,"sentence":1,"reference":"Matthew 26:56","text":"But this is all happening to fulfill the words of the prophets as recorded in the Scriptures.”"},{"id":"mt-26-56-2","chapter":26,"verse":56,"sentence":2,"reference":"Matthew 26:56","text":"At that point, all the disciples deserted him and fled."}]},{"chapter":26,"verse":57,"reference":"Matthew 26:57","text":"Then the people who had arrested Jesus led him to the home of Caiaphas, the high priest, where the teachers of religious law and the elders had gathered.","sentences":[{"id":"mt-26-57-1","chapter":26,"verse":57,"sentence":1,"reference":"Matthew 26:57","text":"Then the people who had arrested Jesus led him to the home of Caiaphas, the high priest, where the teachers of religious law and the elders had gathered."}]},{"chapter":26,"verse":58,"reference":"Matthew 26:58","text":"Meanwhile, Peter followed him at a distance and came to the high priest’s courtyard. He went in and sat with the guards and waited to see how it would all end.","sentences":[{"id":"mt-26-58-1","chapter":26,"verse":58,"sentence":1,"reference":"Matthew 26:58","text":"Meanwhile, Peter followed him at a distance and came to the high priest’s courtyard."},{"id":"mt-26-58-2","chapter":26,"verse":58,"sentence":2,"reference":"Matthew 26:58","text":"He went in and sat with the guards and waited to see how it would all end."}]},{"chapter":26,"verse":59,"reference":"Matthew 26:59","text":"Inside, the leading priests and the entire high council were trying to find witnesses who would lie about Jesus, so they could put him to death.","sentences":[{"id":"mt-26-59-1","chapter":26,"verse":59,"sentence":1,"reference":"Matthew 26:59","text":"Inside, the leading priests and the entire high council were trying to find witnesses who would lie about Jesus, so they could put him to death."}]},{"chapter":26,"verse":60,"reference":"Matthew 26:60","text":"But even though they found many who agreed to give false witness, they could not use anyone’s testimony. Finally, two men came forward","sentences":[{"id":"mt-26-60-1","chapter":26,"verse":60,"sentence":1,"reference":"Matthew 26:60","text":"But even though they found many who agreed to give false witness, they could not use anyone’s testimony."},{"id":"mt-26-60-2","chapter":26,"verse":60,"sentence":2,"reference":"Matthew 26:60","text":"Finally, two men came forward"}]},{"chapter":26,"verse":61,"reference":"Matthew 26:61","text":"who declared, “This man said, ‘I am able to destroy the Temple of God and rebuild it in three days.’”","sentences":[{"id":"mt-26-61-1","chapter":26,"verse":61,"sentence":1,"reference":"Matthew 26:61","text":"who declared, “This man said, ‘I am able to destroy the Temple of God and rebuild it in three days.’”"}]},{"chapter":26,"verse":62,"reference":"Matthew 26:62","text":"Then the high priest stood up and said to Jesus, “Well, aren’t you going to answer these charges? What do you have to say for yourself?”","sentences":[{"id":"mt-26-62-1","chapter":26,"verse":62,"sentence":1,"reference":"Matthew 26:62","text":"Then the high priest stood up and said to Jesus, “Well, aren’t you going to answer these charges?"},{"id":"mt-26-62-2","chapter":26,"verse":62,"sentence":2,"reference":"Matthew 26:62","text":"What do you have to say for yourself?”"}]},{"chapter":26,"verse":63,"reference":"Matthew 26:63","text":"But Jesus remained silent. Then the high priest said to him, “I demand in the name of the living God—tell us if you are the Messiah, the Son of God.”","sentences":[{"id":"mt-26-63-1","chapter":26,"verse":63,"sentence":1,"reference":"Matthew 26:63","text":"But Jesus remained silent."},{"id":"mt-26-63-2","chapter":26,"verse":63,"sentence":2,"reference":"Matthew 26:63","text":"Then the high priest said to him, “I demand in the name of the living God—tell us if you are the Messiah, the Son of God.”"}]},{"chapter":26,"verse":64,"reference":"Matthew 26:64","text":"Jesus replied, “You have said it. And in the future you will see the Son of Man seated in the place of power at God’s right hand and coming on the clouds of heaven.”","sentences":[{"id":"mt-26-64-1","chapter":26,"verse":64,"sentence":1,"reference":"Matthew 26:64","text":"Jesus replied, “You have said it."},{"id":"mt-26-64-2","chapter":26,"verse":64,"sentence":2,"reference":"Matthew 26:64","text":"And in the future you will see the Son of Man seated in the place of power at God’s right hand and coming on the clouds of heaven.”"}]},{"chapter":26,"verse":65,"reference":"Matthew 26:65","text":"Then the high priest tore his clothing to show his horror and said, “Blasphemy! Why do we need other witnesses? You have all heard his blasphemy.","sentences":[{"id":"mt-26-65-1","chapter":26,"verse":65,"sentence":1,"reference":"Matthew 26:65","text":"Then the high priest tore his clothing to show his horror and said, “Blasphemy!"},{"id":"mt-26-65-2","chapter":26,"verse":65,"sentence":2,"reference":"Matthew 26:65","text":"Why do we need other witnesses?"},{"id":"mt-26-65-3","chapter":26,"verse":65,"sentence":3,"reference":"Matthew 26:65","text":"You have all heard his blasphemy."}]},{"chapter":26,"verse":66,"reference":"Matthew 26:66","text":"What is your verdict?” “Guilty!” they shouted. “He deserves to die!”","sentences":[{"id":"mt-26-66-1","chapter":26,"verse":66,"sentence":1,"reference":"Matthew 26:66","text":"What is your verdict?”"},{"id":"mt-26-66-2","chapter":26,"verse":66,"sentence":2,"reference":"Matthew 26:66","text":"“Guilty!”"},{"id":"mt-26-66-3","chapter":26,"verse":66,"sentence":3,"reference":"Matthew 26:66","text":"they shouted."},{"id":"mt-26-66-4","chapter":26,"verse":66,"sentence":4,"reference":"Matthew 26:66","text":"“He deserves to die!”"}]},{"chapter":26,"verse":67,"reference":"Matthew 26:67","text":"Then they began to spit in Jesus’ face and beat him with their fists. And some slapped him,","sentences":[{"id":"mt-26-67-1","chapter":26,"verse":67,"sentence":1,"reference":"Matthew 26:67","text":"Then they began to spit in Jesus’ face and beat him with their fists."},{"id":"mt-26-67-2","chapter":26,"verse":67,"sentence":2,"reference":"Matthew 26:67","text":"And some slapped him,"}]},{"chapter":26,"verse":68,"reference":"Matthew 26:68","text":"jeering, “Prophesy to us, you Messiah! Who hit you that time?”","sentences":[{"id":"mt-26-68-1","chapter":26,"verse":68,"sentence":1,"reference":"Matthew 26:68","text":"jeering, “Prophesy to us, you Messiah!"},{"id":"mt-26-68-2","chapter":26,"verse":68,"sentence":2,"reference":"Matthew 26:68","text":"Who hit you that time?”"}]},{"chapter":26,"verse":69,"reference":"Matthew 26:69","text":"Meanwhile, Peter was sitting outside in the courtyard. A servant girl came over and said to him, “You were one of those with Jesus the Galilean.”","sentences":[{"id":"mt-26-69-1","chapter":26,"verse":69,"sentence":1,"reference":"Matthew 26:69","text":"Meanwhile, Peter was sitting outside in the courtyard."},{"id":"mt-26-69-2","chapter":26,"verse":69,"sentence":2,"reference":"Matthew 26:69","text":"A servant girl came over and said to him, “You were one of those with Jesus the Galilean.”"}]},{"chapter":26,"verse":70,"reference":"Matthew 26:70","text":"But Peter denied it in front of everyone. “I don’t know what you’re talking about,” he said.","sentences":[{"id":"mt-26-70-1","chapter":26,"verse":70,"sentence":1,"reference":"Matthew 26:70","text":"But Peter denied it in front of everyone."},{"id":"mt-26-70-2","chapter":26,"verse":70,"sentence":2,"reference":"Matthew 26:70","text":"“I don’t know what you’re talking about,” he said."}]},{"chapter":26,"verse":71,"reference":"Matthew 26:71","text":"Later, out by the gate, another servant girl noticed him and said to those standing around, “This man was with Jesus of Nazareth.”","sentences":[{"id":"mt-26-71-1","chapter":26,"verse":71,"sentence":1,"reference":"Matthew 26:71","text":"Later, out by the gate, another servant girl noticed him and said to those standing around, “This man was with Jesus of Nazareth.”"}]},{"chapter":26,"verse":72,"reference":"Matthew 26:72","text":"Again Peter denied it, this time with an oath. “I don’t even know the man,” he said.","sentences":[{"id":"mt-26-72-1","chapter":26,"verse":72,"sentence":1,"reference":"Matthew 26:72","text":"Again Peter denied it, this time with an oath."},{"id":"mt-26-72-2","chapter":26,"verse":72,"sentence":2,"reference":"Matthew 26:72","text":"“I don’t even know the man,” he said."}]},{"chapter":26,"verse":73,"reference":"Matthew 26:73","text":"A little later some of the other bystanders came over to Peter and said, “You must be one of them; we can tell by your Galilean accent.”","sentences":[{"id":"mt-26-73-1","chapter":26,"verse":73,"sentence":1,"reference":"Matthew 26:73","text":"A little later some of the other bystanders came over to Peter and said, “You must be one of them; we can tell by your Galilean accent.”"}]},{"chapter":26,"verse":74,"reference":"Matthew 26:74","text":"Peter swore, “A curse on me if I’m lying—I don’t know the man!” And immediately the rooster crowed.","sentences":[{"id":"mt-26-74-1","chapter":26,"verse":74,"sentence":1,"reference":"Matthew 26:74","text":"Peter swore, “A curse on me if I’m lying—I don’t know the man!”"},{"id":"mt-26-74-2","chapter":26,"verse":74,"sentence":2,"reference":"Matthew 26:74","text":"And immediately the rooster crowed."}]},{"chapter":26,"verse":75,"reference":"Matthew 26:75","text":"Suddenly, Jesus’ words flashed through Peter’s mind: “Before the rooster crows, you will deny three times that you even know me.” And he went away, weeping bitterly.","sentences":[{"id":"mt-26-75-1","chapter":26,"verse":75,"sentence":1,"reference":"Matthew 26:75","text":"Suddenly, Jesus’ words flashed through Peter’s mind: “Before the rooster crows, you will deny three times that you even know me.”"},{"id":"mt-26-75-2","chapter":26,"verse":75,"sentence":2,"reference":"Matthew 26:75","text":"And he went away, weeping bitterly."}]}]},{"chapter":27,"verses":[{"chapter":27,"verse":1,"reference":"Matthew 27:1","text":"Very early in the morning the leading priests and the elders of the people met again to lay plans for putting Jesus to death.","sentences":[{"id":"mt-27-1-1","chapter":27,"verse":1,"sentence":1,"reference":"Matthew 27:1","text":"Very early in the morning the leading priests and the elders of the people met again to lay plans for putting Jesus to death."}]},{"chapter":27,"verse":2,"reference":"Matthew 27:2","text":"Then they bound him, led him away, and took him to Pilate, the Roman governor.","sentences":[{"id":"mt-27-2-1","chapter":27,"verse":2,"sentence":1,"reference":"Matthew 27:2","text":"Then they bound him, led him away, and took him to Pilate, the Roman governor."}]},{"chapter":27,"verse":3,"reference":"Matthew 27:3","text":"When Judas, who had betrayed him, realized that Jesus had been condemned to die, he was filled with remorse. So he took the thirty pieces of silver back to the leading priests and the elders.","sentences":[{"id":"mt-27-3-1","chapter":27,"verse":3,"sentence":1,"reference":"Matthew 27:3","text":"When Judas, who had betrayed him, realized that Jesus had been condemned to die, he was filled with remorse."},{"id":"mt-27-3-2","chapter":27,"verse":3,"sentence":2,"reference":"Matthew 27:3","text":"So he took the thirty pieces of silver back to the leading priests and the elders."}]},{"chapter":27,"verse":4,"reference":"Matthew 27:4","text":"“I have sinned,” he declared, “for I have betrayed an innocent man.” “What do we care?” they retorted. “That’s your problem.”","sentences":[{"id":"mt-27-4-1","chapter":27,"verse":4,"sentence":1,"reference":"Matthew 27:4","text":"“I have sinned,” he declared, “for I have betrayed an innocent man.”"},{"id":"mt-27-4-2","chapter":27,"verse":4,"sentence":2,"reference":"Matthew 27:4","text":"“What do we care?”"},{"id":"mt-27-4-3","chapter":27,"verse":4,"sentence":3,"reference":"Matthew 27:4","text":"they retorted."},{"id":"mt-27-4-4","chapter":27,"verse":4,"sentence":4,"reference":"Matthew 27:4","text":"“That’s your problem.”"}]},{"chapter":27,"verse":5,"reference":"Matthew 27:5","text":"Then Judas threw the silver coins down in the Temple and went out and hanged himself.","sentences":[{"id":"mt-27-5-1","chapter":27,"verse":5,"sentence":1,"reference":"Matthew 27:5","text":"Then Judas threw the silver coins down in the Temple and went out and hanged himself."}]},{"chapter":27,"verse":6,"reference":"Matthew 27:6","text":"The leading priests picked up the coins. “It wouldn’t be right to put this money in the Temple treasury,” they said, “since it was payment for murder.”","sentences":[{"id":"mt-27-6-1","chapter":27,"verse":6,"sentence":1,"reference":"Matthew 27:6","text":"The leading priests picked up the coins."},{"id":"mt-27-6-2","chapter":27,"verse":6,"sentence":2,"reference":"Matthew 27:6","text":"“It wouldn’t be right to put this money in the Temple treasury,” they said, “since it was payment for murder.”"}]},{"chapter":27,"verse":7,"reference":"Matthew 27:7","text":"After some discussion they finally decided to buy the potter’s field, and they made it into a cemetery for foreigners.","sentences":[{"id":"mt-27-7-1","chapter":27,"verse":7,"sentence":1,"reference":"Matthew 27:7","text":"After some discussion they finally decided to buy the potter’s field, and they made it into a cemetery for foreigners."}]},{"chapter":27,"verse":8,"reference":"Matthew 27:8","text":"That is why the field is still called the Field of Blood.","sentences":[{"id":"mt-27-8-1","chapter":27,"verse":8,"sentence":1,"reference":"Matthew 27:8","text":"That is why the field is still called the Field of Blood."}]},{"chapter":27,"verse":9,"reference":"Matthew 27:9","text":"This fulfilled the prophecy of Jeremiah that says, “They took the thirty pieces of silver— the price at which he was valued by the people of Israel,","sentences":[{"id":"mt-27-9-1","chapter":27,"verse":9,"sentence":1,"reference":"Matthew 27:9","text":"This fulfilled the prophecy of Jeremiah that says, “They took the thirty pieces of silver— the price at which he was valued by the people of Israel,"}]},{"chapter":27,"verse":10,"reference":"Matthew 27:10","text":"and purchased the potter’s field, as the Lord directed.”","sentences":[{"id":"mt-27-10-1","chapter":27,"verse":10,"sentence":1,"reference":"Matthew 27:10","text":"and purchased the potter’s field, as the Lord directed.”"}]},{"chapter":27,"verse":11,"reference":"Matthew 27:11","text":"Now Jesus was standing before Pilate, the Roman governor. “Are you the king of the Jews?” the governor asked him. Jesus replied, “You have said it.”","sentences":[{"id":"mt-27-11-1","chapter":27,"verse":11,"sentence":1,"reference":"Matthew 27:11","text":"Now Jesus was standing before Pilate, the Roman governor."},{"id":"mt-27-11-2","chapter":27,"verse":11,"sentence":2,"reference":"Matthew 27:11","text":"“Are you the king of the Jews?”"},{"id":"mt-27-11-3","chapter":27,"verse":11,"sentence":3,"reference":"Matthew 27:11","text":"the governor asked him."},{"id":"mt-27-11-4","chapter":27,"verse":11,"sentence":4,"reference":"Matthew 27:11","text":"Jesus replied, “You have said it.”"}]},{"chapter":27,"verse":12,"reference":"Matthew 27:12","text":"But when the leading priests and the elders made their accusations against him, Jesus remained silent.","sentences":[{"id":"mt-27-12-1","chapter":27,"verse":12,"sentence":1,"reference":"Matthew 27:12","text":"But when the leading priests and the elders made their accusations against him, Jesus remained silent."}]},{"chapter":27,"verse":13,"reference":"Matthew 27:13","text":"“Don’t you hear all these charges they are bringing against you?” Pilate demanded.","sentences":[{"id":"mt-27-13-1","chapter":27,"verse":13,"sentence":1,"reference":"Matthew 27:13","text":"“Don’t you hear all these charges they are bringing against you?”"},{"id":"mt-27-13-2","chapter":27,"verse":13,"sentence":2,"reference":"Matthew 27:13","text":"Pilate demanded."}]},{"chapter":27,"verse":14,"reference":"Matthew 27:14","text":"But Jesus made no response to any of the charges, much to the governor’s surprise.","sentences":[{"id":"mt-27-14-1","chapter":27,"verse":14,"sentence":1,"reference":"Matthew 27:14","text":"But Jesus made no response to any of the charges, much to the governor’s surprise."}]},{"chapter":27,"verse":15,"reference":"Matthew 27:15","text":"Now it was the governor’s custom each year during the Passover celebration to release one prisoner to the crowd—anyone they wanted.","sentences":[{"id":"mt-27-15-1","chapter":27,"verse":15,"sentence":1,"reference":"Matthew 27:15","text":"Now it was the governor’s custom each year during the Passover celebration to release one prisoner to the crowd—anyone they wanted."}]},{"chapter":27,"verse":16,"reference":"Matthew 27:16","text":"This year there was a notorious prisoner, a man named Barabbas.","sentences":[{"id":"mt-27-16-1","chapter":27,"verse":16,"sentence":1,"reference":"Matthew 27:16","text":"This year there was a notorious prisoner, a man named Barabbas."}]},{"chapter":27,"verse":17,"reference":"Matthew 27:17","text":"As the crowds gathered before Pilate’s house that morning, he asked them, “Which one do you want me to release to you—Barabbas, or Jesus who is called the Messiah?” 18(He knew very well that the religious leaders had arrested Jesus out of envy.)","sentences":[{"id":"mt-27-17-1","chapter":27,"verse":17,"sentence":1,"reference":"Matthew 27:17","text":"As the crowds gathered before Pilate’s house that morning, he asked them, “Which one do you want me to release to you—Barabbas, or Jesus who is called the Messiah?”"},{"id":"mt-27-17-2","chapter":27,"verse":17,"sentence":2,"reference":"Matthew 27:17","text":"18(He knew very well that the religious leaders had arrested Jesus out of envy.)"}]},{"chapter":27,"verse":19,"reference":"Matthew 27:19","text":"Just then, as Pilate was sitting on the judgment seat, his wife sent him this message: “Leave that innocent man alone. I suffered through a terrible nightmare about him last night.”","sentences":[{"id":"mt-27-19-1","chapter":27,"verse":19,"sentence":1,"reference":"Matthew 27:19","text":"Just then, as Pilate was sitting on the judgment seat, his wife sent him this message: “Leave that innocent man alone."},{"id":"mt-27-19-2","chapter":27,"verse":19,"sentence":2,"reference":"Matthew 27:19","text":"I suffered through a terrible nightmare about him last night.”"}]},{"chapter":27,"verse":20,"reference":"Matthew 27:20","text":"Meanwhile, the leading priests and the elders persuaded the crowd to ask for Barabbas to be released and for Jesus to be put to death.","sentences":[{"id":"mt-27-20-1","chapter":27,"verse":20,"sentence":1,"reference":"Matthew 27:20","text":"Meanwhile, the leading priests and the elders persuaded the crowd to ask for Barabbas to be released and for Jesus to be put to death."}]},{"chapter":27,"verse":21,"reference":"Matthew 27:21","text":"So the governor asked again, “Which of these two do you want me to release to you?” The crowd shouted back, “Barabbas!”","sentences":[{"id":"mt-27-21-1","chapter":27,"verse":21,"sentence":1,"reference":"Matthew 27:21","text":"So the governor asked again, “Which of these two do you want me to release to you?”"},{"id":"mt-27-21-2","chapter":27,"verse":21,"sentence":2,"reference":"Matthew 27:21","text":"The crowd shouted back, “Barabbas!”"}]},{"chapter":27,"verse":22,"reference":"Matthew 27:22","text":"Pilate responded, “Then what should I do with Jesus who is called the Messiah?” They shouted back, “Crucify him!”","sentences":[{"id":"mt-27-22-1","chapter":27,"verse":22,"sentence":1,"reference":"Matthew 27:22","text":"Pilate responded, “Then what should I do with Jesus who is called the Messiah?”"},{"id":"mt-27-22-2","chapter":27,"verse":22,"sentence":2,"reference":"Matthew 27:22","text":"They shouted back, “Crucify him!”"}]},{"chapter":27,"verse":23,"reference":"Matthew 27:23","text":"“Why?” Pilate demanded. “What crime has he committed?” But the mob roared even louder, “Crucify him!”","sentences":[{"id":"mt-27-23-1","chapter":27,"verse":23,"sentence":1,"reference":"Matthew 27:23","text":"“Why?”"},{"id":"mt-27-23-2","chapter":27,"verse":23,"sentence":2,"reference":"Matthew 27:23","text":"Pilate demanded."},{"id":"mt-27-23-3","chapter":27,"verse":23,"sentence":3,"reference":"Matthew 27:23","text":"“What crime has he committed?”"},{"id":"mt-27-23-4","chapter":27,"verse":23,"sentence":4,"reference":"Matthew 27:23","text":"But the mob roared even louder, “Crucify him!”"}]},{"chapter":27,"verse":24,"reference":"Matthew 27:24","text":"Pilate saw that he wasn’t getting anywhere and that a riot was developing. So he sent for a bowl of water and washed his hands before the crowd, saying, “I am innocent of this man’s blood. The responsibility is yours!”","sentences":[{"id":"mt-27-24-1","chapter":27,"verse":24,"sentence":1,"reference":"Matthew 27:24","text":"Pilate saw that he wasn’t getting anywhere and that a riot was developing."},{"id":"mt-27-24-2","chapter":27,"verse":24,"sentence":2,"reference":"Matthew 27:24","text":"So he sent for a bowl of water and washed his hands before the crowd, saying, “I am innocent of this man’s blood."},{"id":"mt-27-24-3","chapter":27,"verse":24,"sentence":3,"reference":"Matthew 27:24","text":"The responsibility is yours!”"}]},{"chapter":27,"verse":25,"reference":"Matthew 27:25","text":"And all the people yelled back, “We will take responsibility for his death—we and our children!”","sentences":[{"id":"mt-27-25-1","chapter":27,"verse":25,"sentence":1,"reference":"Matthew 27:25","text":"And all the people yelled back, “We will take responsibility for his death—we and our children!”"}]},{"chapter":27,"verse":26,"reference":"Matthew 27:26","text":"So Pilate released Barabbas to them. He ordered Jesus flogged with a lead-tipped whip, then turned him over to the Roman soldiers to be crucified.","sentences":[{"id":"mt-27-26-1","chapter":27,"verse":26,"sentence":1,"reference":"Matthew 27:26","text":"So Pilate released Barabbas to them."},{"id":"mt-27-26-2","chapter":27,"verse":26,"sentence":2,"reference":"Matthew 27:26","text":"He ordered Jesus flogged with a lead-tipped whip, then turned him over to the Roman soldiers to be crucified."}]},{"chapter":27,"verse":27,"reference":"Matthew 27:27","text":"Some of the governor’s soldiers took Jesus into their headquarters and called out the entire regiment.","sentences":[{"id":"mt-27-27-1","chapter":27,"verse":27,"sentence":1,"reference":"Matthew 27:27","text":"Some of the governor’s soldiers took Jesus into their headquarters and called out the entire regiment."}]},{"chapter":27,"verse":28,"reference":"Matthew 27:28","text":"They stripped him and put a scarlet robe on him.","sentences":[{"id":"mt-27-28-1","chapter":27,"verse":28,"sentence":1,"reference":"Matthew 27:28","text":"They stripped him and put a scarlet robe on him."}]},{"chapter":27,"verse":29,"reference":"Matthew 27:29","text":"They wove thorn branches into a crown and put it on his head, and they placed a reed stick in his right hand as a scepter. Then they knelt before him in mockery and taunted, “Hail! King of the Jews!”","sentences":[{"id":"mt-27-29-1","chapter":27,"verse":29,"sentence":1,"reference":"Matthew 27:29","text":"They wove thorn branches into a crown and put it on his head, and they placed a reed stick in his right hand as a scepter."},{"id":"mt-27-29-2","chapter":27,"verse":29,"sentence":2,"reference":"Matthew 27:29","text":"Then they knelt before him in mockery and taunted, “Hail!"},{"id":"mt-27-29-3","chapter":27,"verse":29,"sentence":3,"reference":"Matthew 27:29","text":"King of the Jews!”"}]},{"chapter":27,"verse":30,"reference":"Matthew 27:30","text":"And they spit on him and grabbed the stick and struck him on the head with it.","sentences":[{"id":"mt-27-30-1","chapter":27,"verse":30,"sentence":1,"reference":"Matthew 27:30","text":"And they spit on him and grabbed the stick and struck him on the head with it."}]},{"chapter":27,"verse":31,"reference":"Matthew 27:31","text":"When they were finally tired of mocking him, they took off the robe and put his own clothes on him again. Then they led him away to be crucified.","sentences":[{"id":"mt-27-31-1","chapter":27,"verse":31,"sentence":1,"reference":"Matthew 27:31","text":"When they were finally tired of mocking him, they took off the robe and put his own clothes on him again."},{"id":"mt-27-31-2","chapter":27,"verse":31,"sentence":2,"reference":"Matthew 27:31","text":"Then they led him away to be crucified."}]},{"chapter":27,"verse":32,"reference":"Matthew 27:32","text":"Along the way, they came across a man named Simon, who was from Cyrene, and the soldiers forced him to carry Jesus’ cross.","sentences":[{"id":"mt-27-32-1","chapter":27,"verse":32,"sentence":1,"reference":"Matthew 27:32","text":"Along the way, they came across a man named Simon, who was from Cyrene, and the soldiers forced him to carry Jesus’ cross."}]},{"chapter":27,"verse":33,"reference":"Matthew 27:33","text":"And they went out to a place called Golgotha (which means “Place of the Skull”).","sentences":[{"id":"mt-27-33-1","chapter":27,"verse":33,"sentence":1,"reference":"Matthew 27:33","text":"And they went out to a place called Golgotha (which means “Place of the Skull”)."}]},{"chapter":27,"verse":34,"reference":"Matthew 27:34","text":"The soldiers gave Jesus wine mixed with bitter gall, but when he had tasted it, he refused to drink it.","sentences":[{"id":"mt-27-34-1","chapter":27,"verse":34,"sentence":1,"reference":"Matthew 27:34","text":"The soldiers gave Jesus wine mixed with bitter gall, but when he had tasted it, he refused to drink it."}]},{"chapter":27,"verse":35,"reference":"Matthew 27:35","text":"After they had nailed him to the cross, the soldiers gambled for his clothes by throwing dice.","sentences":[{"id":"mt-27-35-1","chapter":27,"verse":35,"sentence":1,"reference":"Matthew 27:35","text":"After they had nailed him to the cross, the soldiers gambled for his clothes by throwing dice."}]},{"chapter":27,"verse":36,"reference":"Matthew 27:36","text":"Then they sat around and kept guard as he hung there.","sentences":[{"id":"mt-27-36-1","chapter":27,"verse":36,"sentence":1,"reference":"Matthew 27:36","text":"Then they sat around and kept guard as he hung there."}]},{"chapter":27,"verse":37,"reference":"Matthew 27:37","text":"A sign was fastened above Jesus’ head, announcing the charge against him. It read: “This is Jesus, the King of the Jews.”","sentences":[{"id":"mt-27-37-1","chapter":27,"verse":37,"sentence":1,"reference":"Matthew 27:37","text":"A sign was fastened above Jesus’ head, announcing the charge against him."},{"id":"mt-27-37-2","chapter":27,"verse":37,"sentence":2,"reference":"Matthew 27:37","text":"It read: “This is Jesus, the King of the Jews.”"}]},{"chapter":27,"verse":38,"reference":"Matthew 27:38","text":"Two revolutionaries were crucified with him, one on his right and one on his left.","sentences":[{"id":"mt-27-38-1","chapter":27,"verse":38,"sentence":1,"reference":"Matthew 27:38","text":"Two revolutionaries were crucified with him, one on his right and one on his left."}]},{"chapter":27,"verse":39,"reference":"Matthew 27:39","text":"The people passing by shouted abuse, shaking their heads in mockery.","sentences":[{"id":"mt-27-39-1","chapter":27,"verse":39,"sentence":1,"reference":"Matthew 27:39","text":"The people passing by shouted abuse, shaking their heads in mockery."}]},{"chapter":27,"verse":40,"reference":"Matthew 27:40","text":"“Look at you now!” they yelled at him. “You said you were going to destroy the Temple and rebuild it in three days. Well then, if you are the Son of God, save yourself and come down from the cross!”","sentences":[{"id":"mt-27-40-1","chapter":27,"verse":40,"sentence":1,"reference":"Matthew 27:40","text":"“Look at you now!”"},{"id":"mt-27-40-2","chapter":27,"verse":40,"sentence":2,"reference":"Matthew 27:40","text":"they yelled at him."},{"id":"mt-27-40-3","chapter":27,"verse":40,"sentence":3,"reference":"Matthew 27:40","text":"“You said you were going to destroy the Temple and rebuild it in three days."},{"id":"mt-27-40-4","chapter":27,"verse":40,"sentence":4,"reference":"Matthew 27:40","text":"Well then, if you are the Son of God, save yourself and come down from the cross!”"}]},{"chapter":27,"verse":41,"reference":"Matthew 27:41","text":"The leading priests, the teachers of religious law, and the elders also mocked Jesus.","sentences":[{"id":"mt-27-41-1","chapter":27,"verse":41,"sentence":1,"reference":"Matthew 27:41","text":"The leading priests, the teachers of religious law, and the elders also mocked Jesus."}]},{"chapter":27,"verse":42,"reference":"Matthew 27:42","text":"“He saved others,” they scoffed, “but he can’t save himself! So he is the King of Israel, is he? Let him come down from the cross right now, and we will believe in him!","sentences":[{"id":"mt-27-42-1","chapter":27,"verse":42,"sentence":1,"reference":"Matthew 27:42","text":"“He saved others,” they scoffed, “but he can’t save himself!"},{"id":"mt-27-42-2","chapter":27,"verse":42,"sentence":2,"reference":"Matthew 27:42","text":"So he is the King of Israel, is he?"},{"id":"mt-27-42-3","chapter":27,"verse":42,"sentence":3,"reference":"Matthew 27:42","text":"Let him come down from the cross right now, and we will believe in him!"}]},{"chapter":27,"verse":43,"reference":"Matthew 27:43","text":"He trusted God, so let God rescue him now if he wants him! For he said, ‘I am the Son of God.’”","sentences":[{"id":"mt-27-43-1","chapter":27,"verse":43,"sentence":1,"reference":"Matthew 27:43","text":"He trusted God, so let God rescue him now if he wants him!"},{"id":"mt-27-43-2","chapter":27,"verse":43,"sentence":2,"reference":"Matthew 27:43","text":"For he said, ‘I am the Son of God.’”"}]},{"chapter":27,"verse":44,"reference":"Matthew 27:44","text":"Even the revolutionaries who were crucified with him ridiculed him in the same way.","sentences":[{"id":"mt-27-44-1","chapter":27,"verse":44,"sentence":1,"reference":"Matthew 27:44","text":"Even the revolutionaries who were crucified with him ridiculed him in the same way."}]},{"chapter":27,"verse":45,"reference":"Matthew 27:45","text":"At noon, darkness fell across the whole land until three o’clock.","sentences":[{"id":"mt-27-45-1","chapter":27,"verse":45,"sentence":1,"reference":"Matthew 27:45","text":"At noon, darkness fell across the whole land until three o’clock."}]},{"chapter":27,"verse":46,"reference":"Matthew 27:46","text":"At about three o’clock, Jesus called out with a loud voice, *“Eli, Eli,* *lema sabachthani?”* which means “My God, my God, why have you abandoned me?”","sentences":[{"id":"mt-27-46-1","chapter":27,"verse":46,"sentence":1,"reference":"Matthew 27:46","text":"At about three o’clock, Jesus called out with a loud voice, *“Eli, Eli,* *lema sabachthani?”"},{"id":"mt-27-46-2","chapter":27,"verse":46,"sentence":2,"reference":"Matthew 27:46","text":"* which means “My God, my God, why have you abandoned me?”"}]},{"chapter":27,"verse":47,"reference":"Matthew 27:47","text":"Some of the bystanders misunderstood and thought he was calling for the prophet Elijah.","sentences":[{"id":"mt-27-47-1","chapter":27,"verse":47,"sentence":1,"reference":"Matthew 27:47","text":"Some of the bystanders misunderstood and thought he was calling for the prophet Elijah."}]},{"chapter":27,"verse":48,"reference":"Matthew 27:48","text":"One of them ran and filled a sponge with sour wine, holding it up to him on a reed stick so he could drink.","sentences":[{"id":"mt-27-48-1","chapter":27,"verse":48,"sentence":1,"reference":"Matthew 27:48","text":"One of them ran and filled a sponge with sour wine, holding it up to him on a reed stick so he could drink."}]},{"chapter":27,"verse":49,"reference":"Matthew 27:49","text":"But the rest said, “Wait! Let’s see whether Elijah comes to save him.”","sentences":[{"id":"mt-27-49-1","chapter":27,"verse":49,"sentence":1,"reference":"Matthew 27:49","text":"But the rest said, “Wait!"},{"id":"mt-27-49-2","chapter":27,"verse":49,"sentence":2,"reference":"Matthew 27:49","text":"Let’s see whether Elijah comes to save him.”"}]},{"chapter":27,"verse":50,"reference":"Matthew 27:50","text":"Then Jesus shouted out again, and he released his spirit.","sentences":[{"id":"mt-27-50-1","chapter":27,"verse":50,"sentence":1,"reference":"Matthew 27:50","text":"Then Jesus shouted out again, and he released his spirit."}]},{"chapter":27,"verse":51,"reference":"Matthew 27:51","text":"At that moment the curtain in the sanctuary of the Temple was torn in two, from top to bottom. The earth shook, rocks split apart,","sentences":[{"id":"mt-27-51-1","chapter":27,"verse":51,"sentence":1,"reference":"Matthew 27:51","text":"At that moment the curtain in the sanctuary of the Temple was torn in two, from top to bottom."},{"id":"mt-27-51-2","chapter":27,"verse":51,"sentence":2,"reference":"Matthew 27:51","text":"The earth shook, rocks split apart,"}]},{"chapter":27,"verse":52,"reference":"Matthew 27:52","text":"and tombs opened. The bodies of many godly men and women who had died were raised from the dead.","sentences":[{"id":"mt-27-52-1","chapter":27,"verse":52,"sentence":1,"reference":"Matthew 27:52","text":"and tombs opened."},{"id":"mt-27-52-2","chapter":27,"verse":52,"sentence":2,"reference":"Matthew 27:52","text":"The bodies of many godly men and women who had died were raised from the dead."}]},{"chapter":27,"verse":53,"reference":"Matthew 27:53","text":"They left the cemetery after Jesus’ resurrection, went into the holy city of Jerusalem, and appeared to many people.","sentences":[{"id":"mt-27-53-1","chapter":27,"verse":53,"sentence":1,"reference":"Matthew 27:53","text":"They left the cemetery after Jesus’ resurrection, went into the holy city of Jerusalem, and appeared to many people."}]},{"chapter":27,"verse":54,"reference":"Matthew 27:54","text":"The Roman officer and the other soldiers at the crucifixion were terrified by the earthquake and all that had happened. They said, “This man truly was the Son of God!”","sentences":[{"id":"mt-27-54-1","chapter":27,"verse":54,"sentence":1,"reference":"Matthew 27:54","text":"The Roman officer and the other soldiers at the crucifixion were terrified by the earthquake and all that had happened."},{"id":"mt-27-54-2","chapter":27,"verse":54,"sentence":2,"reference":"Matthew 27:54","text":"They said, “This man truly was the Son of God!”"}]},{"chapter":27,"verse":55,"reference":"Matthew 27:55","text":"And many women who had come from Galilee with Jesus to care for him were watching from a distance.","sentences":[{"id":"mt-27-55-1","chapter":27,"verse":55,"sentence":1,"reference":"Matthew 27:55","text":"And many women who had come from Galilee with Jesus to care for him were watching from a distance."}]},{"chapter":27,"verse":56,"reference":"Matthew 27:56","text":"Among them were Mary Magdalene, Mary (the mother of James and Joseph), and the mother of James and John, the sons of Zebedee.","sentences":[{"id":"mt-27-56-1","chapter":27,"verse":56,"sentence":1,"reference":"Matthew 27:56","text":"Among them were Mary Magdalene, Mary (the mother of James and Joseph), and the mother of James and John, the sons of Zebedee."}]},{"chapter":27,"verse":57,"reference":"Matthew 27:57","text":"As evening approached, Joseph, a rich man from Arimathea who had become a follower of Jesus,","sentences":[{"id":"mt-27-57-1","chapter":27,"verse":57,"sentence":1,"reference":"Matthew 27:57","text":"As evening approached, Joseph, a rich man from Arimathea who had become a follower of Jesus,"}]},{"chapter":27,"verse":58,"reference":"Matthew 27:58","text":"went to Pilate and asked for Jesus’ body. And Pilate issued an order to release it to him.","sentences":[{"id":"mt-27-58-1","chapter":27,"verse":58,"sentence":1,"reference":"Matthew 27:58","text":"went to Pilate and asked for Jesus’ body."},{"id":"mt-27-58-2","chapter":27,"verse":58,"sentence":2,"reference":"Matthew 27:58","text":"And Pilate issued an order to release it to him."}]},{"chapter":27,"verse":59,"reference":"Matthew 27:59","text":"Joseph took the body and wrapped it in a long sheet of clean linen cloth.","sentences":[{"id":"mt-27-59-1","chapter":27,"verse":59,"sentence":1,"reference":"Matthew 27:59","text":"Joseph took the body and wrapped it in a long sheet of clean linen cloth."}]},{"chapter":27,"verse":60,"reference":"Matthew 27:60","text":"He placed it in his own new tomb, which had been carved out of the rock. Then he rolled a great stone across the entrance and left.","sentences":[{"id":"mt-27-60-1","chapter":27,"verse":60,"sentence":1,"reference":"Matthew 27:60","text":"He placed it in his own new tomb, which had been carved out of the rock."},{"id":"mt-27-60-2","chapter":27,"verse":60,"sentence":2,"reference":"Matthew 27:60","text":"Then he rolled a great stone across the entrance and left."}]},{"chapter":27,"verse":61,"reference":"Matthew 27:61","text":"Both Mary Magdalene and the other Mary were sitting across from the tomb and watching.","sentences":[{"id":"mt-27-61-1","chapter":27,"verse":61,"sentence":1,"reference":"Matthew 27:61","text":"Both Mary Magdalene and the other Mary were sitting across from the tomb and watching."}]},{"chapter":27,"verse":62,"reference":"Matthew 27:62","text":"The next day, on the Sabbath, the leading priests and Pharisees went to see Pilate.","sentences":[{"id":"mt-27-62-1","chapter":27,"verse":62,"sentence":1,"reference":"Matthew 27:62","text":"The next day, on the Sabbath, the leading priests and Pharisees went to see Pilate."}]},{"chapter":27,"verse":63,"reference":"Matthew 27:63","text":"They told him, “Sir, we remember what that deceiver once said while he was still alive: ‘After three days I will rise from the dead.’","sentences":[{"id":"mt-27-63-1","chapter":27,"verse":63,"sentence":1,"reference":"Matthew 27:63","text":"They told him, “Sir, we remember what that deceiver once said while he was still alive: ‘After three days I will rise from the dead.’"}]},{"chapter":27,"verse":64,"reference":"Matthew 27:64","text":"So we request that you seal the tomb until the third day. This will prevent his disciples from coming and stealing his body and then telling everyone he was raised from the dead! If that happens, we’ll be worse off than we were at first.”","sentences":[{"id":"mt-27-64-1","chapter":27,"verse":64,"sentence":1,"reference":"Matthew 27:64","text":"So we request that you seal the tomb until the third day."},{"id":"mt-27-64-2","chapter":27,"verse":64,"sentence":2,"reference":"Matthew 27:64","text":"This will prevent his disciples from coming and stealing his body and then telling everyone he was raised from the dead!"},{"id":"mt-27-64-3","chapter":27,"verse":64,"sentence":3,"reference":"Matthew 27:64","text":"If that happens, we’ll be worse off than we were at first.”"}]},{"chapter":27,"verse":65,"reference":"Matthew 27:65","text":"Pilate replied, “Take guards and secure it the best you can.”","sentences":[{"id":"mt-27-65-1","chapter":27,"verse":65,"sentence":1,"reference":"Matthew 27:65","text":"Pilate replied, “Take guards and secure it the best you can.”"}]},{"chapter":27,"verse":66,"reference":"Matthew 27:66","text":"So they sealed the tomb and posted guards to protect it.","sentences":[{"id":"mt-27-66-1","chapter":27,"verse":66,"sentence":1,"reference":"Matthew 27:66","text":"So they sealed the tomb and posted guards to protect it."}]}]},{"chapter":28,"verses":[{"chapter":28,"verse":1,"reference":"Matthew 28:1","text":"Early on Sunday morning, as the new day was dawning, Mary Magdalene and the other Mary went out to visit the tomb.","sentences":[{"id":"mt-28-1-1","chapter":28,"verse":1,"sentence":1,"reference":"Matthew 28:1","text":"Early on Sunday morning, as the new day was dawning, Mary Magdalene and the other Mary went out to visit the tomb."}]},{"chapter":28,"verse":2,"reference":"Matthew 28:2","text":"Suddenly there was a great earthquake! For an angel of the Lord came down from heaven, rolled aside the stone, and sat on it.","sentences":[{"id":"mt-28-2-1","chapter":28,"verse":2,"sentence":1,"reference":"Matthew 28:2","text":"Suddenly there was a great earthquake!"},{"id":"mt-28-2-2","chapter":28,"verse":2,"sentence":2,"reference":"Matthew 28:2","text":"For an angel of the Lord came down from heaven, rolled aside the stone, and sat on it."}]},{"chapter":28,"verse":3,"reference":"Matthew 28:3","text":"His face shone like lightning, and his clothing was as white as snow.","sentences":[{"id":"mt-28-3-1","chapter":28,"verse":3,"sentence":1,"reference":"Matthew 28:3","text":"His face shone like lightning, and his clothing was as white as snow."}]},{"chapter":28,"verse":4,"reference":"Matthew 28:4","text":"The guards shook with fear when they saw him, and they fell into a dead faint.","sentences":[{"id":"mt-28-4-1","chapter":28,"verse":4,"sentence":1,"reference":"Matthew 28:4","text":"The guards shook with fear when they saw him, and they fell into a dead faint."}]},{"chapter":28,"verse":5,"reference":"Matthew 28:5","text":"Then the angel spoke to the women. “Don’t be afraid!” he said. “I know you are looking for Jesus, who was crucified.","sentences":[{"id":"mt-28-5-1","chapter":28,"verse":5,"sentence":1,"reference":"Matthew 28:5","text":"Then the angel spoke to the women."},{"id":"mt-28-5-2","chapter":28,"verse":5,"sentence":2,"reference":"Matthew 28:5","text":"“Don’t be afraid!”"},{"id":"mt-28-5-3","chapter":28,"verse":5,"sentence":3,"reference":"Matthew 28:5","text":"he said."},{"id":"mt-28-5-4","chapter":28,"verse":5,"sentence":4,"reference":"Matthew 28:5","text":"“I know you are looking for Jesus, who was crucified."}]},{"chapter":28,"verse":6,"reference":"Matthew 28:6","text":"He isn’t here! He is risen from the dead, just as he said would happen. Come, see where his body was lying.","sentences":[{"id":"mt-28-6-1","chapter":28,"verse":6,"sentence":1,"reference":"Matthew 28:6","text":"He isn’t here!"},{"id":"mt-28-6-2","chapter":28,"verse":6,"sentence":2,"reference":"Matthew 28:6","text":"He is risen from the dead, just as he said would happen."},{"id":"mt-28-6-3","chapter":28,"verse":6,"sentence":3,"reference":"Matthew 28:6","text":"Come, see where his body was lying."}]},{"chapter":28,"verse":7,"reference":"Matthew 28:7","text":"And now, go quickly and tell his disciples that he has risen from the dead, and he is going ahead of you to Galilee. You will see him there. Remember what I have told you.”","sentences":[{"id":"mt-28-7-1","chapter":28,"verse":7,"sentence":1,"reference":"Matthew 28:7","text":"And now, go quickly and tell his disciples that he has risen from the dead, and he is going ahead of you to Galilee."},{"id":"mt-28-7-2","chapter":28,"verse":7,"sentence":2,"reference":"Matthew 28:7","text":"You will see him there."},{"id":"mt-28-7-3","chapter":28,"verse":7,"sentence":3,"reference":"Matthew 28:7","text":"Remember what I have told you.”"}]},{"chapter":28,"verse":8,"reference":"Matthew 28:8","text":"The women ran quickly from the tomb. They were very frightened but also filled with great joy, and they rushed to give the disciples the angel’s message.","sentences":[{"id":"mt-28-8-1","chapter":28,"verse":8,"sentence":1,"reference":"Matthew 28:8","text":"The women ran quickly from the tomb."},{"id":"mt-28-8-2","chapter":28,"verse":8,"sentence":2,"reference":"Matthew 28:8","text":"They were very frightened but also filled with great joy, and they rushed to give the disciples the angel’s message."}]},{"chapter":28,"verse":9,"reference":"Matthew 28:9","text":"And as they went, Jesus met them and greeted them. And they ran to him, grasped his feet, and worshiped him.","sentences":[{"id":"mt-28-9-1","chapter":28,"verse":9,"sentence":1,"reference":"Matthew 28:9","text":"And as they went, Jesus met them and greeted them."},{"id":"mt-28-9-2","chapter":28,"verse":9,"sentence":2,"reference":"Matthew 28:9","text":"And they ran to him, grasped his feet, and worshiped him."}]},{"chapter":28,"verse":10,"reference":"Matthew 28:10","text":"Then Jesus said to them, “Don’t be afraid! Go tell my brothers to leave for Galilee, and they will see me there.”","sentences":[{"id":"mt-28-10-1","chapter":28,"verse":10,"sentence":1,"reference":"Matthew 28:10","text":"Then Jesus said to them, “Don’t be afraid!"},{"id":"mt-28-10-2","chapter":28,"verse":10,"sentence":2,"reference":"Matthew 28:10","text":"Go tell my brothers to leave for Galilee, and they will see me there.”"}]},{"chapter":28,"verse":11,"reference":"Matthew 28:11","text":"As the women were on their way, some of the guards went into the city and told the leading priests what had happened.","sentences":[{"id":"mt-28-11-1","chapter":28,"verse":11,"sentence":1,"reference":"Matthew 28:11","text":"As the women were on their way, some of the guards went into the city and told the leading priests what had happened."}]},{"chapter":28,"verse":12,"reference":"Matthew 28:12","text":"A meeting with the elders was called, and they decided to give the soldiers a large bribe.","sentences":[{"id":"mt-28-12-1","chapter":28,"verse":12,"sentence":1,"reference":"Matthew 28:12","text":"A meeting with the elders was called, and they decided to give the soldiers a large bribe."}]},{"chapter":28,"verse":13,"reference":"Matthew 28:13","text":"They told the soldiers, “You must say, ‘Jesus’ disciples came during the night while we were sleeping, and they stole his body.’","sentences":[{"id":"mt-28-13-1","chapter":28,"verse":13,"sentence":1,"reference":"Matthew 28:13","text":"They told the soldiers, “You must say, ‘Jesus’ disciples came during the night while we were sleeping, and they stole his body.’"}]},{"chapter":28,"verse":14,"reference":"Matthew 28:14","text":"If the governor hears about it, we’ll stand up for you so you won’t get in trouble.”","sentences":[{"id":"mt-28-14-1","chapter":28,"verse":14,"sentence":1,"reference":"Matthew 28:14","text":"If the governor hears about it, we’ll stand up for you so you won’t get in trouble.”"}]},{"chapter":28,"verse":15,"reference":"Matthew 28:15","text":"So the guards accepted the bribe and said what they were told to say. Their story spread widely among the Jews, and they still tell it today.","sentences":[{"id":"mt-28-15-1","chapter":28,"verse":15,"sentence":1,"reference":"Matthew 28:15","text":"So the guards accepted the bribe and said what they were told to say."},{"id":"mt-28-15-2","chapter":28,"verse":15,"sentence":2,"reference":"Matthew 28:15","text":"Their story spread widely among the Jews, and they still tell it today."}]},{"chapter":28,"verse":16,"reference":"Matthew 28:16","text":"Then the eleven disciples left for Galilee, going to the mountain where Jesus had told them to go.","sentences":[{"id":"mt-28-16-1","chapter":28,"verse":16,"sentence":1,"reference":"Matthew 28:16","text":"Then the eleven disciples left for Galilee, going to the mountain where Jesus had told them to go."}]},{"chapter":28,"verse":17,"reference":"Matthew 28:17","text":"When they saw him, they worshiped him—but some of them doubted!","sentences":[{"id":"mt-28-17-1","chapter":28,"verse":17,"sentence":1,"reference":"Matthew 28:17","text":"When they saw him, they worshiped him—but some of them doubted!"}]},{"chapter":28,"verse":18,"reference":"Matthew 28:18","text":"Jesus came and told his disciples, “I have been given all authority in heaven and on earth.","sentences":[{"id":"mt-28-18-1","chapter":28,"verse":18,"sentence":1,"reference":"Matthew 28:18","text":"Jesus came and told his disciples, “I have been given all authority in heaven and on earth."}]},{"chapter":28,"verse":19,"reference":"Matthew 28:19","text":"Therefore, go and make disciples of all the nations, baptizing them in the name of the Father and the Son and the Holy Spirit.","sentences":[{"id":"mt-28-19-1","chapter":28,"verse":19,"sentence":1,"reference":"Matthew 28:19","text":"Therefore, go and make disciples of all the nations, baptizing them in the name of the Father and the Son and the Holy Spirit."}]},{"chapter":28,"verse":20,"reference":"Matthew 28:20","text":"Teach these new disciples to obey all the commands I have given you. And be sure of this: I am with you always, even to the end of the age.”","sentences":[{"id":"mt-28-20-1","chapter":28,"verse":20,"sentence":1,"reference":"Matthew 28:20","text":"Teach these new disciples to obey all the commands I have given you."},{"id":"mt-28-20-2","chapter":28,"verse":20,"sentence":2,"reference":"Matthew 28:20","text":"And be sure of this: I am with you always, even to the end of the age.”"}]}]}]};
